local function _fatal(msg)
    pcall(function() _gatePlayers.LocalPlayer:Kick("[LYNX] " .. tostring(msg)) end)
end
local function _httpGetRetry(url, tries)
    local lastErr
    for i = 1, tries do
        local ok, body = pcall(function() return game:HttpGet(url) end)
        if ok and type(body) == "string" and #body > 0 then return body end
        lastErr = body
        if i < tries then task.wait(1.5 * i) end
    end
    return nil, lastErr
end
