    if _coreGuiHideRefs[key] == 1 then
        pcall(function() game:GetService("StarterGui"):SetCoreGuiEnabled(guiType, false) end)
    end
end
local function _popCoreGuiHide(guiType)
    local key = tostring(guiType)
    _coreGuiHideRefs[key] = math.max(0, (_coreGuiHideRefs[key] or 1) - 1)
    if _coreGuiHideRefs[key] == 0 then
        pcall(function() game:GetService("StarterGui"):SetCoreGuiEnabled(guiType, true) end)
    end
end
local _fishingActive = false
local _mainFishingToggles = {}
local function regFishToggle(name, section, opts)
    local userCallback = opts.Callback
    local entry = { name = name, active = opts.Default == true }
    opts.Callback = function(on, ...)
        entry.active = on and true or false
        if userCallback then return userCallback(on, ...) end
    end
    entry.ref = section:AddToggle(opts)
    _mainFishingToggles[#_mainFishingToggles + 1] = entry
    return entry.ref
end
_G.AutoMineActive    = false
_G.OrbThrowing       = false
_G._treasureHuntBusy = false
_G.AutoIndexActive    = false -- Auto Complete Fish Index owns the rod; other fishing loops wait
_G._blockFlags = { epoch = {}, maxSeconds = 300, pollInterval = 1 }
function _G.SetBlockFlag(name, state)
    local reg  = _G._blockFlags
    local mine = (reg.epoch[name] or 0) + 1
    reg.epoch[name] = mine
    _G[name] = state and true or false
    if not state then return end
    local owner    = coroutine.running()
    local deadline = os.clock() + reg.maxSeconds
    task.spawn(function()
        while reg.epoch[name] == mine and _G[name] do
            if coroutine.status(owner) == "dead" or os.clock() > deadline then
                if reg.epoch[name] == mine then _G[name] = false end
                return
            end
            task.wait(reg.pollInterval)
        end
    end)
end
function _G.SetOrbThrowing(state)  _G.SetBlockFlag("OrbThrowing", state) end
function _G.SetMining(state)       _G.SetBlockFlag("AutoMineActive", state) end
function _G.SetTreasureBusy(state) _G.SetBlockFlag("_treasureHuntBusy", state) end
local _moduleCache = {}
local function cachedRequire(moduleInstance)
    if not moduleInstance then return nil end
    local hit = _moduleCache[moduleInstance]
    if hit ~= nil then return hit end
    local ok, result = pcall(require, moduleInstance)
    if not ok then return nil end
    if result ~= nil then _moduleCache[moduleInstance] = result end
    return result
end
local _cachedReplionModule
local function getCachedReplion()
    if not _cachedReplionModule then
        local packages = ReplicatedStorage:FindFirstChild("Packages")
        _cachedReplionModule = cachedRequire(packages and packages:FindFirstChild("Replion"))
    end
    return _cachedReplionModule
end
local _cachedReplionData
local _replionHookInstalled = false
local function getCachedReplionData(timeout)
    if _cachedReplionData and not _cachedReplionData.Destroyed then return _cachedReplionData end
    _cachedReplionData = nil
    local rep = getCachedReplion()
    if not (rep and rep.Client) then return nil end
    if not _replionHookInstalled then
        _replionHookInstalled = true
        pcall(function()
            rep.Client:OnReplionRemoved("Data", function() _cachedReplionData = nil end)
        end)
    end
    local ok, data = pcall(function()
        return rep.Client:GetReplion("Data") or rep.Client:WaitReplion("Data", timeout or 5)
    end)
    if ok and data then _cachedReplionData = data end
    return _cachedReplionData
end
