local NetEvents = setmetatable({}, {
    __index = function(t, key)
        local resolver = NET_RESOLVERS[key]
        if not resolver then return nil end
        local value = resolver()
        if value ~= nil and key ~= "IsInitialized" and key ~= "netFolder" then
            rawset(t, key, value)
        end
        return value
    end,
})
clearNetEventsCache = function()
    for k in pairs(NetEvents) do
        rawset(NetEvents, k, nil)
    end
end
do
    local genv = getgenv()
    if genv._fishNotifConn then pcall(function() genv._fishNotifConn:Disconnect() end) end
    if genv._fishNotifThread then pcall(task.cancel, genv._fishNotifThread) end
    genv._fishNotifConn, genv._fishNotifThread = nil, nil
    local Notifications = cachedRequire(ReplicatedStorage.Controllers.TextNotificationController)
    local ItemUtility   = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
    if Notifications and ItemUtility then
        local QUEUE_LIMIT, MAX_AGE = 32, 8
        local queue, head, tail, running = {}, 1, 0, false
        local stackTable
        local function findStackTable(fn, depth, seen)
            if type(fn) ~= "function" or depth > 3 or seen[fn] then return nil end
            seen[fn] = true
            local ok, ups = pcall(debug.getupvalues, fn)
            if not ok or type(ups) ~= "table" then return nil end
            for i = 1, #ups - 1 do
                local nxt = ups[i + 1]
                if type(ups[i]) == "table" and typeof(nxt) == "Instance" and nxt.Name == "Frame"
                    and nxt.Parent and nxt.Parent.Name == "Text Notifications"
                then
                    return ups[i]
                end
            end
            for _, v in pairs(ups) do
                if type(v) == "function" then
                    local found = findStackTable(v, depth + 1, seen)
                    if found then return found end
                elseif type(v) == "table" and depth == 0 then
                    for _, inner in pairs(v) do
                        local found = type(inner) == "function" and findStackTable(inner, depth + 1, seen)
                        if found then return found end
                    end
                end
            end
            return nil
        end
        local function getStackTable()
            if not stackTable then
                pcall(function() stackTable = findStackTable(Notifications.DeliverNotification, 0, {}) end)
            end
            return stackTable
        end
        getStackTable()
        local function itemTypeOf(itemId)
            if not ItemUtility.GetItemDataFromItemType("Items", itemId)
                and ItemUtility.GetItemDataFromItemType("Fishing Rods", itemId)
            then
                return "Fishing Rods"
            end
            return "Items"
        end
        local function flush()
            if running then return end
            running = true
            genv._fishNotifThread = task.spawn(function()
                while head <= tail do
                    local entry = queue[head]
                    queue[head] = nil
                    head += 1
                    if os.clock() - entry.queuedAt <= MAX_AGE then
                        pcall(function()
                            local stacks = getStackTable()
                            if stacks then stacks[("Item:%s:%s"):format(entry.itemType, tostring(entry.itemId))] = nil end
                            Notifications:DeliverNotification({
                                Type           = "Item",
                                ItemType       = entry.itemType,
                                ItemId         = entry.itemId,
                                InventoryItem  = entry.inventoryItem,
                                Quantity       = 1,
                                CustomDuration = 5,
                            })
                        end)
                        task.wait(0.6)
                    end
                end
                table.clear(queue)
                head, tail, running = 1, 0, false
                genv._fishNotifThread = nil
            end)
        end
        genv._fishNotifConn = NetEvents.RE_ObtainedNewFishNotification.OnClientEvent:Connect(function(itemId, inventoryItem)
            if not itemId then return end
            if tail - head + 1 >= QUEUE_LIMIT then
                queue[head] = nil
                head += 1
            end
            tail += 1
            queue[tail] = {
                itemId        = itemId,
                inventoryItem = inventoryItem,
                itemType      = itemTypeOf(itemId),
                queuedAt      = os.clock(),
            }
            flush()
        end)
    end
end
local function isRodEquipped()
    local data = getCachedReplionData(2)
    if not data then return nil end
    local ok, equippedType = pcall(data.Get, data, "EquippedType")
    if not ok then return nil end
    return equippedType == "Fishing Rods"
end
local function forceEquipRod(maxTries)
    for _ = 1, maxTries or 12 do
        if isRodEquipped() then return true end
        pcall(function() NetEvents.RF_CancelFishingInputs:InvokeServer() end)
        pcall(function() NetEvents.RF_EquipToolFromHotbar:FireServer(1) end)
        task.wait(0.15)
    end
    return isRodEquipped() == true
end
local function autoEquipRod()
    if LocalPlayer.Character and not isRodEquipped() then forceEquipRod(12) end
end
local function getQueueFn()
    local genv = getgenv and getgenv() or {}
    for _, fn in ipairs({ rawget(genv, "queue_on_teleport"), rawget(genv, "queueonteleport"),
                          queue_on_teleport, queueonteleport }) do
        if typeof(fn) == "function" then return fn end
    end
    for _, lib in ipairs({ syn, fluxus, solara, Delta }) do
        if type(lib) == "table" and typeof(lib.queue_on_teleport) == "function" then return lib.queue_on_teleport end
    end
    return nil
end
local function sharedQueueAutoExecute(enableTreasureJoin)
    local queueFn = getQueueFn()
    if not queueFn then
        Library:MakeNotify({ Title = "Auto Execute", Description = "Executor ini tidak support auto execute setelah teleport (queue_on_teleport).", Delay = 5 })
        return false
    end
    local loaderUrl = ("https://raw.githubusercontent.com/abe11075/testing/refs/heads/main/join.lua?nocache=%d&r=%d")
        :format(os.time(), math.random(1, 9999999))
    local payload = ([[
        if not game:IsLoaded() then game.Loaded:Wait() end
        if getgenv().__lynxAutoExec == game.JobId then return end
        getgenv().__lynxAutoExec = game.JobId
        local LocalPlayer = game:GetService("Players").LocalPlayer
        local deadline = os.clock() + 60
        repeat task.wait(0.5)
            local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
        until (hum and hum.Health > 0) or os.clock() > deadline
        task.wait(1.5)
        %s
        local ok, err = pcall(function() loadstring(game:HttpGet("%s", true))() end)
        if not ok then warn("[AutoExec] Error:", err) end
    ]]):format(enableTreasureJoin and "getgenv().__autoTreasureJoin = true" or "", loaderUrl)
    return (pcall(queueFn, payload))
end
getgenv().sharedQueueAutoExecute = sharedQueueAutoExecute
local function safeFire(fn) return pcall(fn) end
local CAST_POWER_NORMAL  = 0
local CAST_POWER_PERFECT = 0.95
local function setAutoFishing(state, data, wanted)
    local remote = NetEvents.RF_UpdateAutoFishingState
    if not (remote and pcall(remote.InvokeServer, remote, state)) then return nil end
    if not (state and data and wanted) then return true end
    return data:OnChange("AutoFishing", inScriptContext(function(on)
        if on or not wanted() then return end
        task.delay(1, function()
            while _G.OrbThrowing do task.wait(0.5) end
            if wanted() and not data:Get("AutoFishing") then pcall(remote.InvokeServer, remote, true) end
        end)
    end))
end
