local _finisherScene = nil   -- the scene Custom Cutscenes is starting right now; Disable Cutscenes lets it through
local onCatchShared -- the auto fishing catch animation, set where it's defined so later tabs can hook it too
local _tpPriority = { mode = "Elemental Zone", eventActive = nil, elementalActive = nil }
function _tpPriority.yields(who)
    local mode = _tpPriority.mode
    if mode ~= "Elemental Zone" and mode ~= "Event Teleport" then return false end
    local winner = mode == "Elemental Zone" and "elemental" or "event"
    if who == winner then return false end
    local probe = winner == "elemental" and _tpPriority.elementalActive or _tpPriority.eventActive
    if type(probe) ~= "function" then return false end
    local ok, active = pcall(probe)
    return ok and active == true
end
local _httpFnCache
local function getHTTP()
    if _httpFnCache then return _httpFnCache end
    local env, genv = getfenv and getfenv(0) or _G, getgenv and getgenv() or {}
    for _, name in ipairs({ "request", "http_request" }) do
        local f = rawget(env, name) or rawget(genv, name)
        if type(f) == "function" then _httpFnCache = f; return f end
    end
    local libs = { syn, fluxus, solara, rawget(_G, "http") }
    for i = 1, 4 do
        local lib = libs[i]
        if type(lib) == "table" and type(lib.request) == "function" then
            _httpFnCache = lib.request
            return lib.request
        end
    end
    return nil
end
local _islandCoordsCache, _islandCoordsFetching = nil, false
local function fetchIslandCoords()
    if _islandCoordsCache then return _islandCoordsCache end
    while _islandCoordsFetching do task.wait(0.1) end
    if _islandCoordsCache then return _islandCoordsCache end
    _islandCoordsFetching = true
    local url       = "https://raw.githubusercontent.com/4LynxX/Coords/refs/heads/main/coords.json"
    local cacheDir  = "LynxGUI_Configs"
    local cacheFile = cacheDir .. "/island_coords.json"
    local raw
    for attempt = 1, 3 do
        local ok, body = pcall(function()
            local httpFn = getHTTP()
            if httpFn then
                local res = httpFn({ Url = url, Method = "GET" })
                return res and res.Body
            end
            return game:HttpGet(url)
        end)
        if ok and type(body) == "string" and #body > 10 then raw = body; break end
        warn(("[IslandCoords] gagal ambil coords (%d/3): %s"):format(attempt, tostring(body)))
        if attempt < 3 then task.wait(2) end
    end
    if raw then
        pcall(function()
            if isfolder and makefolder and not isfolder(cacheDir) then makefolder(cacheDir) end
            if writefile then writefile(cacheFile, raw) end
        end)
    elseif isfile and readfile and isfile(cacheFile) then
        local okRead, body = pcall(readfile, cacheFile)
        if okRead then raw = body end
    end
    local coords
    if raw then
        local okDecode, parsed = pcall(function() return game:GetService("HttpService"):JSONDecode(raw) end)
        if okDecode and type(parsed) == "table" then
            coords = {}
            for name, d in pairs(parsed) do
                if type(d) == "table" and d.pos and d.look then
                    coords[name] = {
                        pos  = Vector3.new(d.pos[1],  d.pos[2],  d.pos[3]),
                        look = Vector3.new(d.look[1], d.look[2], d.look[3]),
                    }
                end
            end
        end
    end
    _islandCoordsCache    = coords
    _islandCoordsFetching = false
    return coords
end
local Webhook = {}
do
    local HttpService = game:GetService("HttpService")
    local MIN_INTERVAL = 1.5
    local queue, processing, imageCache = {}, false, {}
    Webhook.AvatarUrl  = "https://raw.githubusercontent.com/habibrodriguez7-art/kontol/refs/heads/main/majesticons--planet-ring-2.png"
    Webhook.TierNames  = { [1]="Common",[2]="Uncommon",[3]="Rare",[4]="Epic",[5]="Legendary",[6]="Mythic",[7]="SECRET",[8]="FORGOTTEN" }
    Webhook.TierColors = { [1]=9807270,[2]=3066993,[3]=3447003,[4]=10181046,[5]=15844367,[6]=16711680,[7]=65535,[8]=8355711 }
    function Webhook.cleanStr(v)
        return tostring(v):gsub("^%s*(.-)%s*$", "%1")
    end
    function Webhook.cleanId(v)
        if type(v) == "number" then return string.format("%.0f", v) end
        return tostring(v):gsub("%D", ""):gsub("^%s*(.-)%s*$", "%1")
    end
    function Webhook.formatPrice(n)
        return tostring(math.floor(n)):reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
    end
    local function post(httpFn, url, payload)
        httpFn({
            Url     = url,
            Method  = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body    = HttpService:JSONEncode(payload),
        })
    end
    local function drain()
        if processing then return end
        processing = true
        task.spawn(function()
            while #queue > 0 do
                local entry = table.remove(queue, 1)
                pcall(function()
                    local httpFn = getHTTP()
                    if httpFn and entry.url ~= "" then post(httpFn, entry.url, entry.payload) end
                end)
                if #queue > 0 then task.wait(MIN_INTERVAL) end
            end
            processing = false
        end)
    end
    function Webhook.queue(url, payload)
        if not url or url == "" or not getHTTP() then return false end
        table.insert(queue, { url = url, payload = payload })
        drain()
        return true
    end
    function Webhook.send(url, payload)
        local httpFn = getHTTP()
        if not httpFn or not url or url == "" then return false end
        return (pcall(post, httpFn, url, payload))
    end
    function Webhook.assetId(value)
        local s = value and tostring(value):match("%d+")
        return (s and s ~= "") and s or nil
    end
    function Webhook.imageUrl(assetId)
        if not assetId then return nil end
        local key = tostring(assetId)
        if imageCache[key] ~= nil then return imageCache[key] or nil end
        local httpFn = getHTTP()
        if not httpFn then return nil end
        local ok, url = pcall(function()
            local res = httpFn({
                Url    = ("https://thumbnails.roblox.com/v1/assets?assetIds=%s&returnPolicy=PlaceHolder&size=420x420&format=Png&isCircular=false"):format(key),
                Method = "GET",
            })
            local data = res and res.Body and HttpService:JSONDecode(res.Body)
            return data and data.data and data.data[1] and data.data[1].imageUrl
        end)
        url = ok and url or nil
        imageCache[key] = url or false
        return url
    end
    function Webhook.payload(opts)
        local bot = opts.botName or "Lynx"
        local embed = {
            author      = { name = opts.authorName or bot, icon_url = Webhook.AvatarUrl },
            title       = opts.title,
            description = opts.bodyText or "",
            color       = opts.color or 3447003,
            fields      = opts.fields or {},
            footer      = { text = (opts.footerName or bot) .. " • " .. os.date("%m/%d/%Y %I:%M"), icon_url = Webhook.AvatarUrl },
            timestamp   = os.date("!%Y-%m-%dT%H:%M:%SZ"),
            image       = opts.imageUrl and { url = opts.imageUrl } or nil,
            thumbnail   = opts.thumbnailUrl and { url = opts.thumbnailUrl } or nil,
        }
        return {
            content          = opts.content,
            username         = bot,
            avatar_url       = Webhook.AvatarUrl,
            allowed_mentions = (opts.mention and opts.mention ~= "") and { parse = { "users" } } or nil,
            embeds           = { embed },
        }
    end
end
