do
    local FishingTab = MainWindow:AddTab({ Name = "Main", Icon = "home" })
    do
        local _sup = {
            AnimEnabled = false, AnimConns = {},
            RodThread  = nil, RodEnabled  = false, RodEquipBusy = false,
            LockConn   = nil, LockEnabled = false, LockedCFrame = nil,
            RadarOn    = false,
            NotifConn  = nil,
            VFXDisabled     = false,
            VFXController   = nil,
            VFXOrigHandle   = nil, VFXOrigAtPoint = nil, VFXOrigInstance = nil,
            VFXSupported    = false,
            CutsceneHooked  = false, CutsceneDisabled = false,
            WaterEnabled    = false, WaterPlatform = nil,
            WaterConn       = nil,   WaterSurfaceY = nil, WaterCharConn = nil,
            MonitorState = nil,
            AbilityVFXEnabled = false, AbilityVFXLoop = nil, AbilityVFXSweep = nil,
            DivingEnabled = false, DivingConn = nil, DivingThread = nil,
            DailyEnabled = false, DailyGuiControl = nil, DailyOrigOpen = nil, DailyThread = nil,
        }
        local function buildPillPanel(guiName, yOffset, placeholder)
            local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")
            local oldGui    = PlayerGui:FindFirstChild(guiName)
            if oldGui then oldGui:Destroy() end
            local screenGui = Instance.new("ScreenGui")
            screenGui.Name           = guiName
            screenGui.ResetOnSpawn   = false
            screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
            screenGui.DisplayOrder   = 999999
            screenGui.IgnoreGuiInset = true
            screenGui.Parent         = PlayerGui
            local container = Instance.new("Frame")
            container.Size                   = UDim2.new(0, 0, 0, 30)
            container.Position               = UDim2.new(0.5, 0, 0, yOffset)
            container.AnchorPoint            = Vector2.new(0.5, 0)
            container.AutomaticSize          = Enum.AutomaticSize.X
            container.BackgroundColor3       = Color3.fromRGB(18, 8, 2)
            container.BackgroundTransparency = 0.45
            container.BorderSizePixel        = 0
            container.Parent                 = screenGui
            Instance.new("UICorner", container).CornerRadius = UDim.new(1, 0)
            local grad = Instance.new("UIGradient")
            grad.Color = ColorSequence.new{
                ColorSequenceKeypoint.new(0,    Color3.fromRGB(8,  4,  1)),
                ColorSequenceKeypoint.new(0.25, Color3.fromRGB(30, 12, 2)),
                ColorSequenceKeypoint.new(0.5,  Color3.fromRGB(70, 28, 4)),
                ColorSequenceKeypoint.new(0.75, Color3.fromRGB(30, 12, 2)),
                ColorSequenceKeypoint.new(1,    Color3.fromRGB(8,  4,  1)),
            }
            grad.Rotation = 0
            grad.Parent   = container
            local padding = Instance.new("UIPadding")
            padding.PaddingLeft   = UDim.new(0, 14)
            padding.PaddingRight  = UDim.new(0, 14)
            padding.Parent        = container
            local shine = Instance.new("Frame")
            shine.Size                   = UDim2.new(0.7, 0, 0, 1)
            shine.Position               = UDim2.new(0.15, 0, 0, 1)
            shine.BackgroundColor3       = Color3.fromRGB(255, 160, 60)
            shine.BackgroundTransparency = 0.5
            shine.BorderSizePixel        = 0
            shine.Parent                 = container
            Instance.new("UICorner", shine).CornerRadius = UDim.new(1, 0)
            local shineGrad = Instance.new("UIGradient")
            shineGrad.Transparency = NumberSequence.new{
                NumberSequenceKeypoint.new(0,   1),
                NumberSequenceKeypoint.new(0.2, 0.3),
                NumberSequenceKeypoint.new(0.5, 0.2),
                NumberSequenceKeypoint.new(0.8, 0.3),
                NumberSequenceKeypoint.new(1,   1),
            }
            shineGrad.Parent = shine
            local label = Instance.new("TextLabel")
            label.Size                   = UDim2.new(0, 0, 1, 0)
            label.AutomaticSize          = Enum.AutomaticSize.X
            label.BackgroundTransparency = 1
            label.Text                   = placeholder
            label.TextColor3             = Color3.fromRGB(210, 150, 80)
            label.TextSize               = 11
            label.Font                   = Enum.Font.GothamBold
            label.TextXAlignment         = Enum.TextXAlignment.Center
            label.RichText               = true
            label.Parent                 = container
            local _drag = { active = false, input = nil, startPos = nil, startCont = nil, changedConn = nil }
            container.InputBegan:Connect(function(input)
                if input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
                _drag.active    = true
                _drag.startPos  = input.Position
                _drag.startCont = container.Position
                if _drag.changedConn then _drag.changedConn:Disconnect() end
                _drag.changedConn = input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        _drag.active = false
                        if _drag.changedConn then _drag.changedConn:Disconnect(); _drag.changedConn = nil end
                    end
                end)
            end)
            container.InputChanged:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch then
                    _drag.input = input
                end
            end)
            local inputConn = UIS.InputChanged:Connect(function(input)
                if input == _drag.input and _drag.active then
                    local delta = input.Position - _drag.startPos
                    container.Position = UDim2.new(
                        _drag.startCont.X.Scale, _drag.startCont.X.Offset + delta.X,
                        _drag.startCont.Y.Scale, _drag.startCont.Y.Offset + delta.Y
                    )
                end
            end)
            return screenGui, label, inputConn
        end
        local SupportSection = FishingTab:AddSection("Support Features")
        do
            local FISHING_KINDS = {
                AnimationOverride = true, EquipIdle = true, EquipIdleFake = true, FishCaught = true,
                FishingFailure = true, LoopedRodCharge = true, ReelIntermission = true, ReelStart = true,
                ReelingHold = true, ReelingIdle = true, RodThrow = true, StartRodCharge = true,
                HoldFish1 = true, HoldFish2 = true, HoldFish3 = true,
            }
            local fishingIds
            local function isFishing(track)
                if not fishingIds then
                    fishingIds = {}
                    for key, d in pairs(cachedRequire(ReplicatedStorage.Modules.Animations) or {}) do
                        local kind = type(key) == "string" and (key:match("%s%-%s(.+)$") or key)
                        local id = type(d) == "table" and (d.Animation and d.Animation.AnimationId or d.AnimationId)
                        if kind and FISHING_KINDS[kind] and id then fishingIds[id] = true end
                    end
                end
                return track.Animation ~= nil and fishingIds[track.Animation.AnimationId] == true
            end
            local function stopIfFishing(track)
                if _sup.AnimEnabled and isFishing(track) then pcall(function() track:Stop(0) end) end
            end
            local function hookCharacter(char)
                local hum = char and char:WaitForChild("Humanoid", 10)
                local animator = hum and hum:WaitForChild("Animator", 10)
                if not (animator and _sup.AnimEnabled) then return end
                for _, track in ipairs(animator:GetPlayingAnimationTracks()) do stopIfFishing(track) end
                _sup.AnimConns[#_sup.AnimConns + 1] = animator.AnimationPlayed:Connect(function(track)
                    task.defer(stopIfFishing, track)
                end)
            end
            SupportSection:AddToggle({
                Title   = "No Fishing Animation",
                Default = false,
                Callback = function(on)
                    _sup.AnimEnabled = on
                    for _, c in ipairs(_sup.AnimConns) do c:Disconnect() end
                    table.clear(_sup.AnimConns)
                    if not on then return end
                    _sup.AnimConns[1] = LocalPlayer.CharacterAdded:Connect(hookCharacter)
                    if LocalPlayer.Character then hookCharacter(LocalPlayer.Character) end
                end,
            })
        end
        _G._autoEquipRodToggleRef = SupportSection:AddToggle({
            Title    = "Auto Equip Rod",
            Default  = false,
            Callback = function(on)
                if on then
                    if _sup.RodEnabled then return end
                    _sup.RodEnabled = true
                    _sup.RodThread  = task.spawn(function()
                        while _sup.RodEnabled do
                            if not _G.AutoMineActive and not _G.OrbThrowing and not _G.CosmicTrading and not _G.AutoIndexActive
                                and not _sup.RodEquipBusy and isRodEquipped() == false
