        SupportSection:AddToggle({
            Title    = "Show Real Ping Panel",
            Default  = false,
            Callback = function(on)
                local _monitor = _sup.MonitorState
                if not _monitor then
                    _monitor = { enabled = false, conn = nil, inputConn = nil, updateThread = nil, gui = nil, gen = 0 }
                    _sup.MonitorState = _monitor
                end
                _monitor.enabled = on
                _monitor.gen = (_monitor.gen or 0) + 1
                if _monitor.conn      then _monitor.conn:Disconnect();      _monitor.conn      = nil end
                if _monitor.inputConn then _monitor.inputConn:Disconnect(); _monitor.inputConn = nil end
                if _monitor.updateThread then
                    pcall(task.cancel, _monitor.updateThread)
                    _monitor.updateThread = nil
                end
                if _monitor.gui       then _monitor.gui:Destroy();          _monitor.gui       = nil end
                if not on then return end
                local Stats  = game:GetService("Stats")
                local _theme = {
                    Good = Color3.fromRGB(80,  255, 140),
                    Warn = Color3.fromRGB(255, 220, 90),
                    Bad  = Color3.fromRGB(255, 90,  90),
                }
                local statsLabel
                _monitor.gui, statsLabel, _monitor.inputConn =
                    buildPillPanel("LynxPanelMonitor", 14, "-- ms  ·  CPU --  ·  -- fps")
                local perfStats = Stats:FindFirstChild("PerformanceStats")
                local pingItem  = perfStats and perfStats:FindFirstChild("Ping")
                local cpuItem   = perfStats and perfStats:FindFirstChild("CPU")
                local _acc = {
                    frames       = 0,
                    fpsAccum     = 0,
                    currentCpuMs = 0,
                    lastText     = nil,
                }
                local function colorTag(val, good, warn, rev)
                    local c = rev
                        and ((val >= good and _theme.Good) or (val >= warn and _theme.Warn) or _theme.Bad)
                        or  ((val <= good and _theme.Good) or (val <= warn and _theme.Warn) or _theme.Bad)
                    return string.format('<font color="rgb(%d,%d,%d)">', math.floor(c.R*255), math.floor(c.G*255), math.floor(c.B*255))
                end
                if cpuItem then
                    _monitor.conn = RunService.Heartbeat:Connect((function(dt)
                        _acc.frames   += 1
                        _acc.fpsAccum += dt
                    end))
                else
                    _monitor.conn = RunService.Heartbeat:Connect((function(dt)
                        _acc.frames   += 1
                        _acc.fpsAccum += dt
                        _acc.currentCpuMs = _acc.currentCpuMs * 0.8 + (dt * 1000) * 0.2
                    end))
                end
                local myGen = _monitor.gen
                _monitor.updateThread = task.spawn(function()
                    while true do
                        task.wait(1)
                        if not _monitor.enabled or _monitor.gen ~= myGen then break end
                        if not statsLabel.Parent then break end
                        local fps = _acc.fpsAccum > 0 and math.floor(_acc.frames / _acc.fpsAccum) or 0
                        _acc.frames   = 0
                        _acc.fpsAccum = 0
                        local ping = 0
                        if pingItem then
                            ping = math.floor(pingItem:GetValue())
                        else
                            local ok, v = pcall(function() return LocalPlayer:GetNetworkPing() * 1000 end)
                            if ok and v then ping = math.floor(v) end
                        end
                        if ping < 0 then ping = 0 end
                        local cpuDisplay = math.floor(math.clamp(
                            cpuItem and cpuItem:GetValue() or _acc.currentCpuMs, 0, 999))
                        local sep = '<font color="rgb(90,40,10)"> · </font>'
                        local text = string.format(
                            "%s%d ms</font>%sCPU %s%d ms</font>%s%s%d fps</font>",
                            colorTag(ping, 50, 100, false), ping, sep,
                            colorTag(cpuDisplay, 33, 50, false), cpuDisplay, sep,
                            colorTag(fps, 50, 30, true), fps
                        )
                        if text ~= _acc.lastText then
                            _acc.lastText   = text
                            statsLabel.Text = text
                        end
                    end
                    _monitor.updateThread = nil
                end)
            end,
        })
        SupportSection:AddToggle({
            Title    = "Show Stats Monitor",
            Default  = false,
            Callback = function(on)
                local st = _sup.StatsMonitor
                if not st then st = { gen = 0 }; _sup.StatsMonitor = st end
                st.gen += 1
                if st.inputConn then st.inputConn:Disconnect(); st.inputConn = nil end
                if st.gui then st.gui:Destroy(); st.gui = nil end
                if not on then return end
                local label
                st.gui, label, st.inputConn =
                    buildPillPanel("LynxStatsMonitor", 50, "Luck --  ·  Mutation --  ·  Shiny --")
                local function findUpdateStats()
                    if not getconnections then return nil end
                    for _, c in ipairs(getconnections(LocalPlayer:GetAttributeChangedSignal("LocationName"))) do
                        local fn = c.Function
                        if fn and (debug.info(fn, "s") or ""):find("SettingsController") then return fn end
                    end
                end
                local function statTile()
                    local node = LocalPlayer.PlayerGui:FindFirstChild("Settings")
                    for _, name in ipairs({ "Main", "Bottom", "ScrollingFrame", "StatTile" }) do
                        node = node and node:FindFirstChild(name)
                    end
                    return node
                end
                local function readStat(tile, prefix)
                    for _, s in ipairs(tile:GetChildren()) do
                        local l = s:FindFirstChild("Label")
                        if l and l.Text:sub(1, #prefix) == prefix then return l.Text:sub(#prefix + 1) end
                    end
                    return "--"
                end
                local myGen = st.gen
                task.spawn(function()
                    local okFind, updateStats = pcall(findUpdateStats)
                    if not okFind then updateStats = nil end
                    local val  = '<font color="rgb(255,200,120)">%s</font>'
                    local luck = '<font color="rgb(80,255,140)">Luck %s</font>'
                    local sep  = '<font color="rgb(90,40,10)"> · </font>'
                    while st.gen == myGen and label.Parent do
                        if updateStats then pcall(updateStats) end
                        local tile = statTile()
                        if tile then
                            label.Text = luck:format(readStat(tile, "Bonus Luck: "))
                                .. sep .. "Mutation " .. val:format(readStat(tile, "Mutation Chance: "))
                                .. sep .. "Shiny " .. val:format(readStat(tile, "Shiny Chance: "))
                        end
                        task.wait(5)
                    end
                end)
            end,
        })
        SupportSection:AddToggle({
            Title    = "Disable Cutscenes",
            Default  = false,
            Callback = function(on)
                _sup.CutsceneDisabled = on
                if not on or _sup.CutsceneHooked then return end
                local ctrl = cachedRequire(ReplicatedStorage.Controllers:FindFirstChild("CutsceneController"))
                if not (ctrl and ctrl.Play) then return end
                local origPlay = ctrl.Play
                ctrl.Play = function(selfArg, scene, character, ...)
                    local finisher = scene == _finisherScene
                        or (_finisherTiers and _finisherTiers[scene] and character == LocalPlayer.Character
                            and not (_animationsOff or _worldStripped))
                    if _sup.CutsceneDisabled and not finisher then return end
                    return origPlay(selfArg, scene, character, ...)
                end
                _sup.CutsceneHooked = true
            end,
        })
        SupportSection:AddToggle({
            Title    = "Disable Obtained Fish Notification",
