                    _sup.VFXDisabled = true
                    _sup.VFXController.Handle         = function() end
                    _sup.VFXController.RenderAtPoint  = function() end
                    _sup.VFXController.RenderInstance = function() end
                else
                    _sup.VFXDisabled = false
                    if _sup.VFXController then
                        _sup.VFXController.Handle         = _sup.VFXOrigHandle
                        _sup.VFXController.RenderAtPoint  = _sup.VFXOrigAtPoint
                        _sup.VFXController.RenderInstance = _sup.VFXOrigInstance
                    end
                end
            end,
        })
        do
            local RAY_EVERY, PARKED = 10, CFrame.new(0, -10000, 0)
            local function stopPlatform()
                if _sup.WaterConn then _sup.WaterConn:Disconnect(); _sup.WaterConn = nil end
                local part = workspace:FindFirstChild("WW_Part")
                if part then part:Destroy() end
                _sup.WaterPlatform, _sup.WaterSurfaceY = nil, nil
            end
            local function disable()
                stopPlatform()
                if _sup.WaterCharConn then _sup.WaterCharConn:Disconnect(); _sup.WaterCharConn = nil end
            end
            local function setupForCharacter(char)
                stopPlatform()
                if not _sup.WaterEnabled then return end
                local root = char:WaitForChild("HumanoidRootPart", 5)
                if not root or not _sup.WaterEnabled then return end
                local platform        = Instance.new("Part")
                platform.Name         = "WW_Part"
                platform.Size         = Vector3.new(20, 1, 20)
                platform.Anchored     = true
                platform.CanCollide   = true
                platform.Transparency = 1
                platform.CastShadow   = false
                platform.CanQuery     = false
                platform.CanTouch     = false
                platform.Parent       = workspace
                _sup.WaterPlatform    = platform
                local hum = char:FindFirstChildOfClass("Humanoid")
                local rayParams = RaycastParams.new()
                rayParams.FilterType = Enum.RaycastFilterType.Include
                rayParams.FilterDescendantsInstances = { workspace.Terrain }
                rayParams.IgnoreWater = false
                local frame = 0
                _sup.WaterConn = RunService.Heartbeat:Connect((function()
                    if not _sup.WaterEnabled then return end
                    if not root.Parent then stopPlatform(); return end
                    frame += 1
                    if frame >= RAY_EVERY then
                        frame = 0
                        local hit = workspace:Raycast(root.Position + Vector3.new(0, 40, 0), Vector3.new(0, -200, 0), rayParams)
                        local y = hit and hit.Material == Enum.Material.Water and hit.Position.Y or nil
                        _sup.WaterSurfaceY = y
                        local state = hum and hum:GetState()
                        if y and not (root.Anchored or _totemSpawning)
                            and (state == Enum.HumanoidStateType.Swimming or state == Enum.HumanoidStateType.Freefall)
                            and root.Position.Y < y + 2 and root.Position.Y > y - 40 then
                            root.CFrame += Vector3.new(0, y + 3.5 - root.Position.Y, 0) -- sank already: back on top
                            root.AssemblyLinearVelocity = Vector3.zero
                        end
                    end
                    local y = _sup.WaterSurfaceY
                    platform.CFrame = y and CFrame.new(root.Position.X, y, root.Position.Z) or PARKED
                end))
            end
            _G._wowToggleRef = SupportSection:AddToggle({
                Title    = "Walk On Water",
                Default  = false,
                Callback = function(on)
                    _sup.WaterEnabled = on
                    disable()
                    if not on then return end
                    _sup.WaterCharConn = LocalPlayer.CharacterAdded:Connect(function(newChar)
                        if _sup.WaterEnabled then task.spawn(setupForCharacter, newChar) end
                    end)
                    if LocalPlayer.Character then
                        task.spawn(setupForCharacter, LocalPlayer.Character)
                    end
                end,
            })
        end
        do
            local DAILY_GUI = "!!! Daily Login"
            local function claimIfDue()
                pcall(function()
                    local data = getCachedReplionData()
                    if not data then return end
                    local lastLogin = data:Get("LastLogin")
                    if not lastLogin then return end
                    if workspace:GetServerTimeNow() < lastLogin + 86400 then return end
                    local claim = NetEvents.RF_ClaimDailyLogin
                    if claim then claim:InvokeServer() end
                end)
            end
            SupportSection:AddToggle({
                Title    = "Auto Claim Daily Login",
                Default  = false,
                Callback = function(on)
                    _sup.DailyEnabled = on
                    if not _sup.DailyOrigOpen then
                        pcall(function()
                            _sup.DailyGuiControl = require(ReplicatedStorage.Modules.GuiControl)
                            _sup.DailyOrigOpen   = _sup.DailyGuiControl.Open
                            _sup.DailyGuiControl.Open = function(selfArg, guiName, ...)
                                if _sup.DailyEnabled and guiName == DAILY_GUI then
                                    pcall(function() _sup.DailyGuiControl:Unlock() end)
                                    return
                                end
                                return _sup.DailyOrigOpen(selfArg, guiName, ...)
                            end
                        end)
                    end
                    if _sup.DailyThread then pcall(task.cancel, _sup.DailyThread); _sup.DailyThread = nil end
                    if not on then return end
                    pcall(function()
                        if _sup.DailyGuiControl and _sup.DailyGuiControl:IsOpen(DAILY_GUI) then
                            _sup.DailyGuiControl:Close(true)
                            _sup.DailyGuiControl:Unlock()
                        end
                    end)
                    _sup.DailyThread = task.spawn(function()
                        while _sup.DailyEnabled do
                            claimIfDue()
                            task.wait(60)
                        end
                    end)
                end,
            })
        end
        do
            local DIVING_GEAR_ID = 105
            local function isEquipped(data)
                return data ~= nil and data:Get("EquippedOxygenTankId") == DIVING_GEAR_ID
            end
            local function tryEquip()
                local data = getCachedReplionData()
                if not data or isEquipped(data) then return end
                pcall(function()
                    if NetEvents.RF_EquipOxygenTank:InvokeServer(DIVING_GEAR_ID) then return end
                    local purchase = NetEvents.RF_PurchaseGear
                    if purchase and purchase:InvokeServer(DIVING_GEAR_ID) then
                        NetEvents.RF_EquipOxygenTank:InvokeServer(DIVING_GEAR_ID)
                    end
                end)
            end
            _G._divingGearToggleRef = SupportSection:AddToggle({
                Title    = "Auto Equip Diving Gear",
                Default  = false,
                Callback = function(on)
                    local wasOn = _sup.DivingEnabled
                    _sup.DivingEnabled = on
                    if _sup.DivingConn then
                        pcall(function() _sup.DivingConn:Disconnect() end)
                        _sup.DivingConn = nil
                    end
                    if _sup.DivingThread then
                        pcall(task.cancel, _sup.DivingThread)
                        _sup.DivingThread = nil
                    end
                    local data = getCachedReplionData()
                    if not on then
                        if wasOn and isEquipped(data) then
                            pcall(function() NetEvents.RF_UnequipOxygenTank:InvokeServer() end)
                        end
                        return
                    end
                    if not data then return end
                    tryEquip()
                    _sup.DivingConn = data:OnChange("EquippedOxygenTankId", inScriptContext(function(newValue)
                        if not _sup.DivingEnabled or newValue == DIVING_GEAR_ID then return end
                        if _sup.DivingThread then pcall(task.cancel, _sup.DivingThread) end
                        _sup.DivingThread = task.spawn(function()
                            task.wait(0.5)
                            if _sup.DivingEnabled then tryEquip() end
                        end)
                    end))
                end,
            })
        end
        do
            local V3ZERO = Vector3.zero
            local enabled = false
            local hidden, descConns, removeConns, spawnConns, rosterConns = {}, {}, {}, {}, {}
            local function hideObject(store, obj)
                if store[obj] then return end
                if obj:IsA("BasePart") then
                    store[obj] = { obj.Transparency, obj.LocalTransparencyModifier }
                    obj.Transparency, obj.LocalTransparencyModifier = 1, 1
                elseif obj:IsA("Decal") then
                    store[obj] = { obj.Transparency }
                    obj.Transparency = 1
                elseif obj:IsA("SpecialMesh") then
                    store[obj] = { obj.Scale }
                    obj.Scale = V3ZERO
                elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
                    or obj:IsA("BillboardGui") or obj:IsA("SurfaceGui") then
                    store[obj] = { obj.Enabled }
                    obj.Enabled = false
                end
            end
            local function restoreObject(obj, props)
                if not obj or not obj.Parent then return end
                if obj:IsA("BasePart") then
                    obj.Transparency, obj.LocalTransparencyModifier = props[1], props[2]
                elseif obj:IsA("Decal") then
                    obj.Transparency = props[1]
                elseif obj:IsA("SpecialMesh") then
                    obj.Scale = props[1]
                else
                    obj.Enabled = props[1]
                end
            end
            local function forgetCharacter(player)
                local store = hidden[player]
                hidden[player] = nil
                if descConns[player] then descConns[player]:Disconnect(); descConns[player] = nil end
                if removeConns[player] then removeConns[player]:Disconnect(); removeConns[player] = nil end
                return store
            end
            local function hideCharacter(player)
                local char = player.Character
                if player == LocalPlayer or not char or hidden[player] then return end
                local store = setmetatable({}, { __mode = "k" })
                hidden[player] = store
                for _, obj in ipairs(char:GetDescendants()) do hideObject(store, obj) end
                descConns[player] = char.DescendantAdded:Connect(function(obj)
                    local current = hidden[player]
                    if enabled and current then hideObject(current, obj) end
                end)
                removeConns[player] = char.DescendantRemoving:Connect(function(obj)
                    local current = hidden[player]
                    local props = current and current[obj]
                    if props then
                        current[obj] = nil
                        pcall(restoreObject, obj, props)
                    end
                end)
            end
            local function restoreCharacter(player)
                local store = forgetCharacter(player)
                if not store then return end
                for obj, props in pairs(store) do restoreObject(obj, props) end
            end
            local function watchPlayer(player)
                if player == LocalPlayer or spawnConns[player] then return end
                spawnConns[player] = player.CharacterAdded:Connect(function()
                    task.defer(function()
                        if not enabled then return end
                        forgetCharacter(player)   
                        hideCharacter(player)
                    end)
                end)
            end
            local function forgetPlayer(player)
                forgetCharacter(player)
                if spawnConns[player] then spawnConns[player]:Disconnect(); spawnConns[player] = nil end
            end
            SupportSection:AddToggle({
                Title   = "Hide Other Players",
                Default = false,
                NoSave  = true,
                Callback = function(on)
                    if enabled == on then return end
                    enabled = on
                    if on then
                        for _, player in ipairs(Players:GetPlayers()) do
                            watchPlayer(player)
                            hideCharacter(player)
                        end
                        rosterConns[#rosterConns + 1] = Players.PlayerAdded:Connect(function(player)
                            watchPlayer(player)
                            task.defer(function()
                                if enabled then hideCharacter(player) end
                            end)
                        end)
                        rosterConns[#rosterConns + 1] = Players.PlayerRemoving:Connect(forgetPlayer)
                        Library:MakeNotify({ Title = "Remove Players", Description = "Player lain disembunyikan.", Delay = 2 })
                    else
                        for _, conn in ipairs(rosterConns) do pcall(function() conn:Disconnect() end) end
                        table.clear(rosterConns)
                        for _, player in ipairs(Players:GetPlayers()) do restoreCharacter(player) end
                        for player in pairs(hidden) do restoreCharacter(player) end
                        for player, conn in pairs(spawnConns) do
                            conn:Disconnect()
                            spawnConns[player] = nil
                        end
                        Library:MakeNotify({ Title = "Remove Players", Description = "Player lain ditampilkan kembali.", Delay = 2 })
                    end
                end,
            })
        end
        do
            local function destroyIfVFX(obj)
                if obj and obj.Parent and obj:GetAttribute("AbilityVFX") == true then
                    pcall(function() obj:Destroy() end)
                end
            end
            SupportSection:AddToggle({
                Title    = "Disable Ability VFX",
                Default  = false,
                Callback = function(on)
                    _sup.AbilityVFXEnabled = on
                    if _sup.AbilityVFXLoop then _sup.AbilityVFXLoop:Disconnect(); _sup.AbilityVFXLoop = nil end
                    if _sup.AbilityVFXSweep then
                        pcall(task.cancel, _sup.AbilityVFXSweep)
                        _sup.AbilityVFXSweep = nil
                    end
                    if not on then return end
                    _sup.AbilityVFXSweep = task.spawn(function()
                        local stack = { workspace }
                        while #stack > 0 and _sup.AbilityVFXEnabled do
                            local deadline = os.clock() + 0.002
                            while #stack > 0 and os.clock() < deadline do
                                local obj = table.remove(stack)
                                for _, child in ipairs(obj:GetChildren()) do
                                    stack[#stack + 1] = child
                                end
                                destroyIfVFX(obj)
                            end
                            task.wait()
                        end
                        _sup.AbilityVFXSweep = nil
                    end)
                    _sup.AbilityVFXLoop = workspace.DescendantAdded:Connect(function(obj)
                        if not _sup.AbilityVFXEnabled then return end
                        task.defer(destroyIfVFX, obj)
                    end)
                end,
            })
        end
    end
    do
        local _stuck = {
            enabled    = false,
            conn       = nil,
            busy       = false,
            lastCatch  = 0,
            lastSave   = 0,
            savedPos   = nil,
            savedLook  = nil,
            fishCount  = 0,
            threshold  = 15,
            replion    = nil,
        }
        local StuckSection = FishingTab:AddSection("Stuck Detector", false)
        task.spawn(function()
            local ok, rep = pcall(function()
                return require(ReplicatedStorage.Packages.Replion).Client:WaitReplion("Data")
            end)
            if ok and rep then
                _stuck.replion = rep
            end
        end)
        StuckSection:AddInput({
            Title    = "Threshold (seconds)",
            Default  = "15",
            NoSave   = false,
            Callback = function(v)
                _stuck.threshold = tonumber(v) or 15
            end,
        })
        local function savePosition()
            if _stuck.busy then return end
            local char = LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            local ok, cf = pcall(function() return hrp.CFrame end)
            if ok then
                _stuck.savedPos  = cf.Position
                _stuck.savedLook = cf.LookVector
            end
        end
        local function doRespawn()
            if not _stuck.savedPos then return end
            if _stuck.busy then return end
            _stuck.busy = true
            local targetCF = CFrame.new(_stuck.savedPos, _stuck.savedPos + _stuck.savedLook)
            local oldChar  = LocalPlayer.Character
            Library:MakeNotify({ Title = "Stuck Detector", Description = "Stuck! Respawning...", Delay = 3 })
            pcall(function()
                if oldChar then
                    local hum = oldChar:FindFirstChild("Humanoid")
                    if hum then hum.Health = 0 end
                end
            end)
            task.spawn(function()
                local newChar = LocalPlayer.CharacterAdded:Wait()
                local hrp = newChar:WaitForChild("HumanoidRootPart", 10)
                local hum = newChar:WaitForChild("Humanoid", 10)
                if not hrp or not hum or hum.Health <= 0 then
                    _stuck.busy      = false
                    _stuck.lastCatch = tick()
                    return
                end
                task.wait(1)
                for _ = 1, 8 do
                    pcall(function() hrp.CFrame = targetCF end)
                    task.wait(0.15)
                end
                pcall(function()
                    NetEvents.RF_EquipToolFromHotbar:FireServer(1)
                end)
                task.wait(0.3)
                _stuck.busy      = false
                _stuck.lastCatch = tick()
                Library:MakeNotify({ Title = "Stuck Detector", Description = "Respawned!", Delay = 2 })
            end)
        end
        StuckSection:AddToggle({
            Title    = "Stuck Detector",
            Default  = false,
            Callback = function(on)
                _stuck.enabled = on
                if _stuck.conn then
                    _stuck.conn:Disconnect()
                    _stuck.conn = nil
                end
                if not on then
                    _stuck.busy = false
                    Library:MakeNotify({ Title = "Stuck Detector", Description = "Stopped.", Delay = 2 })
                    return
                end
                _stuck.busy      = false
                _stuck.savedPos  = nil
                _stuck.savedLook = nil
                local now        = tick()
                _stuck.lastSave  = now
                _stuck.lastCatch = now
                if _stuck.replion then
                    pcall(function()
                        _stuck.fishCount = _stuck.replion:Get({ "Statistics", "FishCaught" }) or 0
                    end)
                end
                savePosition()
                Library:MakeNotify({ Title = "Stuck Detector", Description = "Active!", Delay = 2 })
                _stuck.conn = RunService.Heartbeat:Connect((function()
                    if not _stuck.enabled then
                        if _stuck.conn then
                            _stuck.conn:Disconnect()
                            _stuck.conn = nil
                        end
                        return
                    end
                    if _stuck.busy then return end
                    local now2 = tick()
                    if now2 - _stuck.lastSave >= 1 then
                        _stuck.lastSave = now2
                        savePosition()
                        if _stuck.replion then
                            pcall(function()
                                local cur = _stuck.replion:Get({ "Statistics", "FishCaught" }) or 0
                                if cur > _stuck.fishCount then
                                    _stuck.fishCount  = cur
                                    _stuck.lastCatch  = now2
                                end
                            end)
                        end
                    end
                    if now2 - _stuck.lastCatch >= _stuck.threshold then
                        _stuck.lastCatch = now2
                        doRespawn()
                    end
                end))
            end,
        })
    end
    do
        local _stable = { enabled = false, conn = nil }
        FishingTab:AddSection("Stable Result"):AddToggle({
            Title    = "Stable Result Good/Perfection",
            Default  = false,
            Callback = function(on)
                if on == _stable.enabled then return end
                _stable.enabled = on
                if _stable.conn then _stable.conn:Disconnect(); _stable.conn = nil end
                if not on then
                    setAutoFishing(false)
                    pcall(function() LocalPlayer:SetAttribute("Loading", false) end)
                    return
                end
                task.spawn(function()
                    local data = getCachedReplionData(10)
                    if not (data and _stable.enabled) then return end
                    _stable.conn = setAutoFishing(true, data, function() return _stable.enabled end)
                    if _stable.conn then pcall(function() LocalPlayer:SetAttribute("Loading", nil) end) end
                end)
            end,
        })
    end
    do
        local FishingSection = FishingTab:AddSection("Skip Rarity", false)
        local skipRarityState = {
            enabled = false,
            targetRarity = "None",
            connection = nil
        }
        getgenv()._shouldSkipRarity = function(minigameData)
            if not skipRarityState.enabled or not minigameData or type(minigameData) ~= "table" or not minigameData.SelectedRarity then
                return false
            end
            local TierUtility = cachedRequire(ReplicatedStorage.Shared.TierUtility)
            if not TierUtility then return false end
            local tier = TierUtility:GetTierFromRarity(minigameData.SelectedRarity)
            if not tier or not tier.Tier then return false end
            local TIER_FISH = {
                [1]="Common",[2]="Uncommon",[3]="Rare",
                [4]="Epic",[5]="Legendary",[6]="Mythic",[7]="Secret",[8]="Forgotten",
            }
            local tierName = TIER_FISH[tier.Tier]
            if not tierName then return false end
            local targets = skipRarityState.targetRarity
            if type(targets) == "table" then
                local found = false
                local hasNone = false
                local count = 0
                for k, targetV in pairs(targets) do
                    local r = type(k) == "number" and targetV or k
                    local isSelected = type(k) == "number" or targetV == true
                    if isSelected and type(r) == "string" then
                        count = count + 1
                        if r:lower() == tierName:lower() then found = true end
                        if r:lower() == "none" then hasNone = true end
                    end
                end
                if not found and not hasNone and count > 0 then return true end
            elseif type(targets) == "string" and targets:lower() ~= "none" then
                if targets:lower() ~= tierName:lower() then return true end
            end
            return false
        end
        FishingSection:AddParagraph({
            Title = "Note",
            Content = "This Skip Rarity feature only works for the Legit Fishing, Instant Fishing, and Instant Fast Reel features."
        })
        FishingSection:AddDropdown({
            Title = "Target Rarity",
            Options = {"None", "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Secret", "Forgotten"},
            Multi = true,
            Default = "None",
            Callback = function(val)
                skipRarityState.targetRarity = val
            end
        })
        FishingSection:AddToggle({
            Title = "Enable Skip Rarity",
            Default = false,
            Callback = function(v)
                skipRarityState.enabled = v
                if v and not getgenv()._skipRarityHooked_V8 then
                    getgenv()._skipRarityHooked_V8 = true
                    local runtime = ReplicatedStorage.Modules:FindFirstChild("FishingRuntime")
                    local Network = runtime and runtime:FindFirstChild("Network") and cachedRequire(runtime.Network)
                    if type(Network) == "table" and Network.Cast then
                        local cast = Network.Cast
                        Network.Cast = function(...)
                            local ok, state = cast(...)
                            if ok and getgenv()._shouldSkipRarity(state) then
                                getgenv()._skipRarityAt = os.clock()
                                return false
                            end
                            return ok, state
                        end
                        LocalPlayer:GetAttributeChangedSignal("FishingCooldownTime"):Connect(function()
                            if os.clock() - (getgenv()._skipRarityAt or 0) < 3 and LocalPlayer:GetAttribute("FishingCooldownTime") ~= nil then
                                LocalPlayer:SetAttribute("FishingCooldownTime", nil)
                            end
                        end)
                    end
                    local FishingController = cachedRequire(ReplicatedStorage.Controllers.FishingController)
                    if type(FishingController) == "table" and FishingController.SendFishingRequestToServer then
                        local send = FishingController.SendFishingRequestToServer
                        FishingController.SendFishingRequestToServer = function(self, ...)
                            local res = send(self, ...)
                            if type(res) == "table" and res.Success and getgenv()._shouldSkipRarity(res.State) then
                                task.spawn(pcall, function() NetEvents.RF_CancelFishingInputs:InvokeServer() end)
                                return { Success = false, Message = "Canceled" }
                            end
                            return res
                        end
                    end
                end
            end
        })
    end
    do
        local _legit = {
            active        = false,
            autoShaking   = false,
            settings      = { clickWait = 0.05, shakeDelay = 0.05 },
            fishThread    = nil,
            shakeThread   = nil,
            watchConn     = nil,
            respawnConn   = nil,
        }
        local function _getController()
            local controllers = ReplicatedStorage:FindFirstChild("Controllers")
            return cachedRequire(controllers and controllers:FindFirstChild("FishingController"))
        end
        local LegitSection = FishingTab:AddSection("Legit Fishing", false)
        LegitSection:AddInput({
            Title    = "Shake Delay",
            Default  = "0.05",
            Callback = function(value)
                local num = tonumber(value)
                if num and num >= 0 then
                    _legit.settings.clickWait  = num
                    _legit.settings.shakeDelay = num
                end
            end,
        })
        regFishToggle("Legit Fishing", LegitSection, {
            Title    = "Enable Legit Fishing",
            Default  = false,
            Callback = function(on)
                if on then
                    if _legit.active or _fishingActive then return end
                    local ctrl, replionData = _getController(), getCachedReplionData()
                    if not (ctrl and replionData) then return end
                    _legit.watchConn = setAutoFishing(true, replionData, function() return _legit.active end)
                    if not _legit.watchConn then return end
                    _fishingActive = true
                    _legit.active  = true
                    _legit.respawnConn = LocalPlayer.CharacterAdded:Connect(function(char)
                        if not _legit.active then return end
                        local hum = char:WaitForChild("Humanoid", 10)
                        if hum then repeat task.wait(0.3) until hum.Health > 0 end
                        task.wait(1)
                        if _legit.active then
                            autoEquipRod()
                        end
                    end)
                    _legit.fishThread = task.spawn(function()
                        autoEquipRod()
