    local function playCatch(name, data, _, _, info)
        local FR, FC = ReplicatedStorage.Modules.FishingRuntime, ReplicatedStorage.Controllers.FishingController
        if require(FR.Core):GetSnapshot().Phase ~= "Idle" then return end
        if name and info and info.origin then
            task.delay(info.delayTime or 0, require(FC.FishCaughtVisual).playCaughtFishVisual, LocalPlayer, info.origin, name, data)
        end
        local item = name and require(ReplicatedStorage.Shared.ItemUtility):GetItemData(name)
        local prob = item and (item.Probability or item.ForcedProbability)
        local sound = prob and require(ReplicatedStorage.Shared.Soundbook).Sounds[prob.Chance <= 0.0005 and "SuperRareCatch" or prob.Chance <= 0.004 and "RareCatch" or "Catch"]
        if sound then sound:Play() end
        if _animationsOff then return end
        local Anim, char = require(ReplicatedStorage.Controllers.AnimationController), LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        Anim:DestroyActiveAnimationTracks()
        local track = not Anim:IsDisabled("FishCaught") and not (hum and hum:GetState() == Enum.HumanoidStateType.Swimming)
            and Anim:PlayAnimation("FishCaught")
        if track then require(FC.RodEffectCallbacks).FireAndReplicate("FishCaught", char) end
        local function reset()
            Anim:DestroyActiveAnimationTracks({ "EquipIdle" })
            require(FR.Equipment).RefreshIdle()
        end
        if track then track.Stopped:Once(reset) else reset() end
    end
    local function onCatch() return NetEvents.RE_FishCaught.OnClientEvent:Connect(function(...) pcall(playCatch, ...) end) end
