    do
        local _ub = {
            active        = false,
            completeDelay = 0.3,
            visualDelay   = 0.3,
            spamDelay     = 0.1,
            loopThread    = nil,
            conns         = {},
            origSet       = nil,
            hooksReady    = false,
        }
        local function track(conn) if conn then _ub.conns[#_ub.conns + 1] = conn end end
        local cachedAreas, cachedTiers, cachedItems, cachedReplionData
        local function getAreas()
            if not cachedAreas then pcall(function() cachedAreas = cachedRequire(ReplicatedStorage.Areas) end) end
            return cachedAreas
        end
        local function getTiers()
            if not cachedTiers then pcall(function() cachedTiers = cachedRequire(ReplicatedStorage.Tiers) end) end
            return cachedTiers
        end
        local function getItems()
            if not cachedItems then pcall(function() cachedItems = cachedRequire(ReplicatedStorage.Items) end) end
            return cachedItems
        end
        local function getReplionData()
            if not cachedReplionData then cachedReplionData = getCachedReplionData() end
            return cachedReplionData
        end
        local ALLOWED_ROD_IDS = { [559] = true, [257] = true, [948] = true, [978] = true, [979] = true }
        local TIER_COLOR_SEQUENCES = {
            [1] = ColorSequence.new(Color3.fromRGB(255, 250, 246)),
            [2] = ColorSequence.new(Color3.fromRGB(195, 255, 85)),
            [3] = ColorSequence.new(Color3.fromRGB(85, 162, 255)),
            [4] = ColorSequence.new(Color3.fromRGB(178, 114, 247)),
            [5] = ColorSequence.new({
                ColorSequenceKeypoint.new(0,   Color3.fromRGB(255, 184, 42)),
                ColorSequenceKeypoint.new(0.6, Color3.fromRGB(255, 184, 42)),
                ColorSequenceKeypoint.new(1,   Color3.fromRGB(255, 232, 142)),
            }),
            [6] = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 24, 24)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(102, 0,  0)),
            }),
            [7] = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(23,  255, 151)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(11,  149, 255)),
            }),
        }
        local fishIndex, rodTierById
        local function getTierFromChance(chance)
            local tiers = getTiers()
            if not tiers then return 1 end
            local best = 1
            for _, t in pairs(tiers) do
                if type(t) == "table" and t.Rarity and t.Tier
                    and chance <= t.Rarity and t.Tier > best and t.Tier <= 7
                then
                    best = t.Tier
                end
            end
            return best
        end
        local function buildIndex()
            if fishIndex then return true end
            local items = getItems()
            if not items then return false end
            fishIndex, rodTierById = {}, {}
            for _, entry in pairs(items) do
                local d = entry.Data
                if d and d.Name then
                    if d.Type == "Fish" then
                        fishIndex[d.Name] = {
                            Id    = d.Id or 0,
                            Tier  = (entry.Probability and entry.Probability.Chance
                                     and getTierFromChance(entry.Probability.Chance)) or d.Tier or 1,
                            Color = TIER_COLOR_SEQUENCES[d.Tier or 1] or TIER_COLOR_SEQUENCES[1],
                        }
                    elseif d.Type == "Fishing Rods" and d.Id then
                        rodTierById[tostring(d.Id)] = d.Tier
                    end
                end
            end
            return true
        end
        local function fishInfo(name)
            if not buildIndex() then return nil end
            return name and fishIndex[name] or nil
        end
        local function playerString(prop)
            local ok, v = pcall(function() return LocalPlayer[prop] end)
            return (ok and v and tostring(v) ~= "" and tostring(v)) or ""
        end
        local function getPlayerLocation()
            local name = playerString("LocationName")
            if name ~= "" then return name end
            local char = LocalPlayer.Character
            local attr = (char and char:GetAttribute("LocationName")) or LocalPlayer:GetAttribute("LocationName")
            if attr and tostring(attr) ~= "" then return tostring(attr) end
            return nil
        end
        local areaFishCache = {}
        local function fishByTierHere(tier)
            if not buildIndex() then return {} end
            local areas = getAreas()
            if not areas then return {} end
            local key  = getPlayerLocation() or "Fisherman Island"
            local area = areas[key] or areas["Fisherman Island"]
            if not area or not area.Items then return {} end
            local byTier = areaFishCache[key]
            if not byTier then
                byTier = {}
                for _, fishName in ipairs(area.Items) do
                    local info = fishIndex[fishName]
                    if info then
                        local bucket = byTier[info.Tier]
                        if not bucket then bucket = {}; byTier[info.Tier] = bucket end
                        bucket[#bucket + 1] = { Name = fishName, Id = info.Id }
                    end
                end
                areaFishCache[key] = byTier
            end
            return byTier[tier] or {}
        end
        local function pickRandom(list) return #list > 0 and list[math.random(1, #list)] or nil end
        local lastRodTier = 2
        local function equippedRod()
            local data = getReplionData()
            if not data then return nil end
            local uuid = data:Get("EquippedId")
            if not uuid or uuid == "" then return nil end
            for _, rod in ipairs(data:Get("Inventory.Fishing Rods") or {}) do
                if rod.UUID == uuid then return rod end
            end
            return nil
        end
        local function getEquippedRodTier()
            local rod = equippedRod()
            if not rod or not buildIndex() then return lastRodTier end
            return rodTierById[tostring(rod.Id)] or lastRodTier
        end
        local function isEquippedRodAllowed()
            local rod = equippedRod()
            return rod ~= nil and ALLOWED_ROD_IDS[rod.Id] == true
        end
        local spoofing, mutingNotif = false, false
        local goldCounter, rainbowCounter, bagCounter, isOurOwnSet = 0, 0, 0, false
        local function incrementCounters()
            goldCounter    = goldCounter    + 1
            rainbowCounter = rainbowCounter + 1
            bagCounter     = bagCounter     + 1
            if goldCounter    > 10 then goldCounter    = 1 end
            if rainbowCounter > 40 then rainbowCounter = 1 end
            local data = getReplionData()
            if not data then return end
            isOurOwnSet = true
            pcall(function() data:_set("Modifiers.Golden",            goldCounter) end)
            pcall(function() data:_set("Modifiers.Rainbow",           rainbowCounter) end)
            pcall(function() data:_set("InventoryNotifications.Fish", bagCounter) end)
            isOurOwnSet = false
        end
        local function calculateCastPosition()
            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not root then return Vector3.zero, Vector3.new(0, 6, 0) end
            local forward = root.CFrame.LookVector
            local target  = root.Position + forward * 10
            local params  = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = { LocalPlayer.Character }
            local hit = workspace:Raycast(target + Vector3.new(0, 50, 0), Vector3.new(0, -150, 0), params)
            local castPos = hit and (hit.Position + Vector3.new(0, 0.1, 0)) or (target + Vector3.new(0, -5, 0))
            return castPos, root.Position + forward * 5 + Vector3.new(0, 6.5, 0)
        end
        local function generateUUID()
            return (("xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx"):gsub("[xy]", function(c)
                return string.format("%x", c == "x" and math.random(0, 15) or math.random(8, 11))
            end))
        end
        local function spoofFishCaughtVisual(fish)
            if spoofing then return end
            spoofing = true
            local uuid     = generateUUID()
            local weight   = math.random(100, 2500) / 700
            local info     = fishInfo(fish.Name)
            local castPos, origin = calculateCastPosition()
            local char     = LocalPlayer.Character
            local headPart = (char and char:FindFirstChild("Head")) or char
            local item     = { Id = fish.Id, Favorited = false, UUID = uuid, Metadata = { Weight = weight } }
            pcall(function()
                firesignal(NetEvents.RE_BaitCastVisual.OnClientEvent, LocalPlayer, {
                    CastPosition       = castPos,
                    Power              = 0.86895783044309,
                    RodName            = playerString("FishingRod"),
                    CosmeticTemplateId = -1,
                    EquippedToolModel  = char and char:FindFirstChild("!!!EQUIPPED_TOOL!!!") or nil,
                    ConnectingJoint    = 0,
                    NoFishingZone      = false,
                    BaitIdentifier     = 3,
                    Origin             = origin,
                    CustomModel        = false,
                })
            end)
            pcall(function()
                firesignal(NetEvents.RE_PlayFishEffect.OnClientEvent, LocalPlayer, headPart, getEquippedRodTier())
            end)
            pcall(function()
                firesignal(NetEvents.RE_BaitSpawned.OnClientEvent, LocalPlayer, playerString("FishingRodSkin"),
                    Vector3.new(castPos.X, castPos.Y + 0.1, castPos.Z))
            end)
            task.wait(0.05)
            pcall(function()
                firesignal(NetEvents.RE_TextEffect.OnClientEvent, {
                    Channel  = "All",
                    TextData = {
                        AttachTo   = headPart,
                        Text       = "!",
                        TextColor  = (info and info.Color) or TIER_COLOR_SEQUENCES[1],
                        EffectType = "Exclaim",
                    },
                    Duration  = 0.5,
                    Container = headPart,
                })
            end)
            pcall(function()
                local data = getReplionData()
                if not data then return end
                local inventory = data:Get("Inventory.Items") or {}
                table.insert(inventory, item)
                data:_set("Inventory.Items", inventory)
            end)
            mutingNotif = true
            pcall(function()
                firesignal(NetEvents.RE_ObtainedNewFishNotification.OnClientEvent, fish.Id, { Weight = weight }, {
                    CustomDuration = 5,
                    InventoryItem  = item,
                    ItemType       = "Fish",
                    _newlyIndexed  = false,
                    Type           = "Item",
                    ItemId         = fish.Id,
                }, false)
            end)
            mutingNotif = false
            incrementCounters()
            pcall(function()
                firesignal(NetEvents.RE_FishCaught.OnClientEvent, fish.Name, { Weight = weight }, 0, 0)
            end)
            pcall(playCatch, fish.Name, { Weight = weight }, 0, 0, { origin = castPos, delayTime = 0.1 })
            spoofing = false
        end
        local function pickFakeFish(realName)
            local info = fishInfo(realName)
            local tier = (info and info.Tier) or 1
            if tier >= 4 then
                local rare, uncommon = fishByTierHere(3), fishByTierHere(2)
                if math.random(1, 10) <= 8 then return pickRandom(rare) or pickRandom(uncommon) end
                return pickRandom(uncommon) or pickRandom(rare)
            end
            local fallback = { Name = realName, Id = (info and info.Id) or 0 }
            if math.random(1, 10) <= 7 then return fallback end
            local others = {}
            for _, f in ipairs(fishByTierHere(tier)) do
                if f.Name ~= realName then others[#others + 1] = f end
            end
            return pickRandom(others) or fallback
        end
        local function setupHooks()
            if _ub.hooksReady then return end
            local data = getReplionData()
            if not data then return end
            _ub.hooksReady = true
            local modifiers = data:Get("Modifiers")
            goldCounter    = (modifiers and modifiers.Golden)  or 0
            rainbowCounter = (modifiers and modifiers.Rainbow) or 0
            local notifs   = data:Get("InventoryNotifications")
            bagCounter     = (notifs and notifs.Fish) or 0
            pcall(function()
                track(data:OnChange("InventoryNotifications.Fish", inScriptContext(function(v)
                    if v == 0 then bagCounter = 0 end
                end)))
            end)
            _ub.origSet = data._set
            data._set = function(selfArg, path, value)
                if not isOurOwnSet then
                    if path == "Modifiers.Golden"            then value = goldCounter end
                    if path == "Modifiers.Rainbow"           then value = rainbowCounter end
                    if path == "InventoryNotifications.Fish" then value = bagCounter end
                end
                return _ub.origSet(selfArg, path, value)
            end
            local playFX = NetEvents.RE_PlayFishEffect
            if playFX then
                track(playFX.OnClientEvent:Connect(function(player, _, tierValue)
                    if player == LocalPlayer and not spoofing and type(tierValue) == "number" and tierValue > 0 then
                        lastRodTier = tierValue
                    end
                end))
            end
            local notif = NetEvents.RE_ObtainedNewFishNotification
            if notif then
                track(notif.OnClientEvent:Connect(function()
                    if not mutingNotif then incrementCounters() end
                end))
            end
            local caught = NetEvents.RE_FishCaught
            if caught then
                track(caught.OnClientEvent:Connect(function(fishName)
                    if not _ub.active or spoofing or not fishName or fishName == "" then return end
                    if not isEquippedRodAllowed() then return end
                    task.spawn(function()
                        if _ub.visualDelay > 0 then task.wait(_ub.visualDelay) end
                        if not _ub.active then return end
                        local fake = pickFakeFish(fishName)
                        if fake then spoofFishCaughtVisual(fake) end
                    end)
                end))
            end
        end
        local function cleanupHooks()
            for _, conn in ipairs(_ub.conns) do pcall(function() conn:Disconnect() end) end
            table.clear(_ub.conns)
            if _ub.origSet then
                local data = getReplionData()
                if data then data._set = _ub.origSet end
                _ub.origSet = nil
            end
            _ub.hooksReady = false
        end
        local UBSection = FishingTab:AddSection("Blatant Visual", false)
        local function numberInput(title, default, apply)
            UBSection:AddInput({
                Title    = title,
                Default  = tostring(default),
                Callback = function(value)
                    local num = tonumber(value)
                    if num and num >= 0 then apply(num) end
                end,
            })
        end
        numberInput("Fishing Complete Delay", _ub.completeDelay, function(n) _ub.completeDelay = n end)
        numberInput("Visual Delay",           _ub.visualDelay,   function(n) _ub.visualDelay   = n end)
        regFishToggle("Ultra Blatant", UBSection, {
            Title    = "Enable Ultra Blatant",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                if on then
                    if not NetEvents.IsInitialized then return end
                    if _fishingActive then warn("[Module] Fishing lain sudah aktif!"); return end
                    _fishingActive = true
                    _ub.active     = true
                    setupHooks()
                    _ub.loopThread = task.spawn(function()
                        while _ub.active do
                            if _G.AutoMineActive or _G.OrbThrowing or _G.AutoIndexActive then task.wait(1); continue end
                            pcall(function() NetEvents.RF_ChargeFishingRod:InvokeServer() end)
                            pcall(function()
                                NetEvents.RF_RequestMinigame:InvokeServer(1, 0, workspace:GetServerTimeNow())
                            end)
                            task.wait(_ub.completeDelay)
                            pcall(function() NetEvents.RE_FishingCompleted:FireServer() end)
                            task.wait(_ub.spamDelay)
                        end
                    end)
                elseif _ub.active then
                    _ub.active     = false
                    _fishingActive = false
                    if _ub.loopThread then task.cancel(_ub.loopThread); _ub.loopThread = nil end
                    cleanupHooks()
                    pcall(function() NetEvents.RF_CancelFishingInputs:InvokeServer() end)
                end
            end,
        })
    end
    do
        local _bv2 = {
            active      = false,
            castMode    = "normal",
