    do
        local _autoPlace = {
            enabled     = false,
            thread      = nil,
            connection  = nil,
            cargoThread = nil,
        }
        local commandRemote           = NetEvents.RF_CommandFishing
        local updateAutoFishingRemote = NetEvents.RF_UpdateAutoFishingState
        local _islandCoords  = {}
        local _islandList    = {}
        local _islandLoaded  = false
        local _islandDropRef = nil
        local function _applyIslandOptions()
            if not _islandDropRef then return end
            local opts = #_islandList > 0 and _islandList or {"(Gagal load)"}
            local saved = Library.ConfigSystem.Get("Dropdowns.Pilih_Lokasi", nil)
            local selectVal = (type(saved) == "string" and _islandCoords[saved]) and saved or nil
            if _islandDropRef.SetOptions then
                _islandDropRef:SetOptions(opts)
            end
            if selectVal then
                local flagObj = Library.flags["Pilih_Lokasi"]
                if flagObj and flagObj.SetValues then
                    pcall(function() flagObj:SetValues(opts, selectVal) end)
                end
            end
        end
        local function _loadIslandCoords(onDone)
            if _islandLoaded then
                if onDone then onDone() end
                return
            end
            task.spawn(function()
                local coords = fetchIslandCoords()
                if coords then
                    table.clear(_islandCoords)
                    table.clear(_islandList)
                    for name, data in pairs(coords) do
                        _islandCoords[name] = data
                        table.insert(_islandList, name)
                    end
                    table.sort(_islandList)
                    _islandLoaded = true
                else
                    warn("[AutoPlace] Coords tidak bisa diload.")
                end
                _applyIslandOptions()
                if _islandLoaded and onDone then onDone() end
            end)
        end
        local AutoPlaceSection = FishingTab:AddSection("Auto Place Pet", false)
        local selectedMode   = "Karakter"
        local selectedIsland = nil
        AutoPlaceSection:AddDropdown({
            Title    = "Mode Posisi",
            Options  = { "Karakter", "Custom (Pilih Lokasi)" },
            Default  = "Karakter",
            Callback = function(selected) selectedMode = selected end,
