                if type(selected) == "string" and _islandCoords[selected] then selectedIsland = selected end
            end,
        })
        _loadIslandCoords(function()
            if #_islandList == 0 then return end
            local saved = Library.ConfigSystem.Get("Dropdowns.Pilih_Lokasi", nil)
            selectedIsland = (type(saved) == "string" and _islandCoords[saved]) and saved or _islandList[1]
        end)
        local function buildFloatCFrame(baseCFrame, heightOffset)
            return CFrame.new(baseCFrame.Position + Vector3.new(0, heightOffset, 0)) * CFrame.fromMatrix(
                Vector3.zero,
                baseCFrame.RightVector,
                baseCFrame.UpVector,
                -baseCFrame.LookVector
            )
        end
        AutoPlaceSection:AddButton({
            Title    = "Empty Now",
            Callback = function()
                local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if not root then
                    Library:MakeNotify({ Title = "Empty Now", Description = "Karakter tidak ditemukan.", Delay = 2 })
                    return
                end
                local commandMode = LocalPlayer:GetAttribute("PetCommandMode")
                if commandMode ~= "Stay" then
                    Library:MakeNotify({ Title = "Empty Now", Description = "Pet belum di-Stay.", Delay = 2 })
                    return
                end
                local cargoCount = LocalPlayer:GetAttribute("PetCargoCount")
                if typeof(cargoCount) ~= "number" or cargoCount <= 0 then
                    Library:MakeNotify({ Title = "Empty Now", Description = "Cargo sudah kosong.", Delay = 2 })
                    return
                end
                task.spawn(function()
                    local petPos             = LocalPlayer:GetAttribute("PetCommandPosition")
                    local originalCFrame     = root.CFrame
                    local needsTeleportToPet = typeof(petPos) == "Vector3"
                        and (root.Position - petPos).Magnitude > 10
                    if needsTeleportToPet then
                        root.CFrame = CFrame.new(petPos)
                        task.wait(0.8)
                    end
                    pcall(function()
                        commandRemote:InvokeServer({ Action = "EmptyCargo" })
                    end)
                    task.wait(5)
                    if needsTeleportToPet then
                        local char     = LocalPlayer.Character
                        local humanoid = char and char:FindFirstChildOfClass("Humanoid")
                        root.CFrame   = buildFloatCFrame(originalCFrame, 10)
                        root.Anchored = true
                        task.wait(5)
                        root.CFrame = buildFloatCFrame(originalCFrame, 5)
                        if humanoid then
                            pcall(function()
                                humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
                            end)
                        end
                        task.wait(0.05)
                        root.Anchored = false
                    end
                    Library:MakeNotify({ Title = "Empty Now", Description = string.format("Cargo di-empty (%d ikan).", cargoCount), Delay = 2 })
                end)
            end,
        })
        AutoPlaceSection:AddToggle({
            Title    = "Enable Auto Place & Empty Pet",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _autoPlace.enabled = on
                if _autoPlace.thread then
                    pcall(task.cancel, _autoPlace.thread)
                    _autoPlace.thread = nil
                end
                if _autoPlace.connection then
                    _autoPlace.connection:Disconnect()
                    _autoPlace.connection = nil
                end
                if _autoPlace.cargoThread then
                    pcall(task.cancel, _autoPlace.cargoThread)
                    _autoPlace.cargoThread = nil
                end
                if not on then
                    Library:MakeNotify({ Title = "Auto Place Pet", Description = "Dimatikan.", Delay = 2 })
                    return
                end
                local function getRoot()
                    local char = LocalPlayer.Character
                    if not char then return nil end
                    return char:FindFirstChild("HumanoidRootPart")
                end
                local function floatAt(root, targetCFrame, duration)
                    local char     = LocalPlayer.Character
                    local humanoid = char and char:FindFirstChildOfClass("Humanoid")
                    root.CFrame   = buildFloatCFrame(targetCFrame, 10)
                    root.Anchored = true
                    task.wait(duration or 3)
                    root.CFrame = buildFloatCFrame(targetCFrame, 5)
                    if humanoid then
                        pcall(function()
                            humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
                        end)
                    end
                    task.wait(0.05)
                    root.Anchored = false
                end
                local function getTargetPos()
                    if selectedMode == "Custom (Pilih Lokasi)" then
                        if not selectedIsland or not _islandCoords[selectedIsland] then
                            return nil
                        end
                        return _islandCoords[selectedIsland].pos
                    end
                    local root = getRoot()
                    if not root then return nil end
                    return root.Position
                end
                local _isBusy = false
                local function sendStay()
                    if _isBusy then return end
                    if not commandRemote then return end
                    _isBusy = true
                    pcall(function()
                        updateAutoFishingRemote:InvokeServer(true)
                    end)
                    local waited = 0
                    while LocalPlayer:GetAttribute("PetFishingActive") ~= true do
                        if not _autoPlace.enabled then
                            _isBusy = false
                            return
                        end
                        task.wait(0.5)
                        waited += 0.5
                        if waited >= 15 then
                            pcall(function() updateAutoFishingRemote:InvokeServer(false) end)
                            _isBusy = false
                            return
                        end
                    end
                    if not _autoPlace.enabled then
                        pcall(function() updateAutoFishingRemote:InvokeServer(false) end)
                        _isBusy = false
                        return
                    end
                    local root = getRoot()
                    if not root then
                        pcall(function() updateAutoFishingRemote:InvokeServer(false) end)
                        _isBusy = false
                        return
                    end
                    if LocalPlayer:GetAttribute("PetCommandMode") == "Stay" then
                        pcall(function()
                            commandRemote:InvokeServer({ Action = "Follow" })
                        end)
                        task.wait(0.8)
                    end
                    if not _autoPlace.enabled then
                        pcall(function() updateAutoFishingRemote:InvokeServer(false) end)
                        _isBusy = false
                        return
                    end
                    local targetPos     = getTargetPos()
                    local needsTeleport = selectedMode == "Custom (Pilih Lokasi)"
                    if not targetPos then
                        pcall(function() updateAutoFishingRemote:InvokeServer(false) end)
                        _isBusy = false
                        return
                    end
                    if needsTeleport then
                        local originalCFrame = root.CFrame
                        local lookData       = _islandCoords[selectedIsland]
                        root.CFrame          = CFrame.lookAt(targetPos, lookData.look)
                        task.wait(1.5)
                        if not _autoPlace.enabled then
                            floatAt(root, originalCFrame, 3)
                            pcall(function() updateAutoFishingRemote:InvokeServer(false) end)
                            _isBusy = false
                            return
                        end
                        local ok, result1 = pcall(function()
                            return commandRemote:InvokeServer({ Action = "Stay" })
                        end)
                        task.wait(0.5)
                        local modeNow = LocalPlayer:GetAttribute("PetCommandMode")
                        if ok and result1 == true and modeNow == "Stay" then
                            Library:MakeNotify({ Title = "Auto Place Pet", Description = "Pet berhasil ditempatkan!", Delay = 3 })
                        end
                        floatAt(root, originalCFrame, 3)
                        pcall(function() updateAutoFishingRemote:InvokeServer(false) end)
                    else
                        local ok, result1 = pcall(function()
                            return commandRemote:InvokeServer({ Action = "Stay" })
                        end)
                        task.wait(0.5)
                        local modeNow = LocalPlayer:GetAttribute("PetCommandMode")
                        if ok and result1 == true and modeNow == "Stay" then
                            Library:MakeNotify({ Title = "Auto Place Pet", Description = "Pet berhasil ditempatkan!", Delay = 3 })
                        end
                        pcall(function() updateAutoFishingRemote:InvokeServer(false) end)
                    end
                    _isBusy = false
                end
                Library:MakeNotify({ Title = "Auto Place Pet", Description = "Aktif - menunggu proses place pet.", Delay = 3 })
                _autoPlace.connection = LocalPlayer:GetAttributeChangedSignal("PetFishingActive"):Connect(function()
                    if not _autoPlace.enabled or _isBusy then return end
                    local isActive = LocalPlayer:GetAttribute("PetFishingActive")
                    if isActive == true then
                        task.wait(0.3)
                        if not _autoPlace.enabled or _isBusy then return end
                        local mode = LocalPlayer:GetAttribute("PetCommandMode")
                        if mode ~= "Stay" then
                            task.spawn(sendStay)
                        end
                    end
                end)
                _autoPlace.thread = task.spawn(function()
                    task.spawn(sendStay)
                    while _autoPlace.enabled do
                        task.wait(10)
                        if not _autoPlace.enabled or _isBusy then continue end
                        local mode = LocalPlayer:GetAttribute("PetCommandMode")
                        if mode ~= "Stay" then
                            task.spawn(sendStay)
                        end
                    end
                end)
                _autoPlace.cargoThread = task.spawn(function()
                    while _autoPlace.enabled do
                        task.wait(3)
                        if not _autoPlace.enabled then break end
                        local cargoCount    = LocalPlayer:GetAttribute("PetCargoCount")
                        local cargoCapacity = LocalPlayer:GetAttribute("PetCargoCapacity")
                        local commandMode   = LocalPlayer:GetAttribute("PetCommandMode")
                        if typeof(cargoCount) ~= "number" or typeof(cargoCapacity) ~= "number" or cargoCapacity <= 0 or commandMode ~= "Stay" then
                            continue
                        end
                        if cargoCount >= cargoCapacity then
                            local root = getRoot()
                            if not root then continue end
                            local petPos             = LocalPlayer:GetAttribute("PetCommandPosition")
                            local originalCFrame     = root.CFrame
                            local needsTeleportToPet = typeof(petPos) == "Vector3"
                                and (root.Position - petPos).Magnitude > 10
                            if needsTeleportToPet then
                                root.CFrame = CFrame.new(petPos)
                                task.wait(0.8)
                            end
                            pcall(function()
                                commandRemote:InvokeServer({ Action = "EmptyCargo" })
                            end)
                            task.wait(3)
                            if needsTeleportToPet then
                                floatAt(root, originalCFrame, 3)
                            end
                            Library:MakeNotify({ Title = "Auto Empty Cargo", Description = string.format("Cargo di-empty (%d ikan).", cargoCount), Delay = 2 })
                        end
                    end
                end)
            end,
        })
    end
    do
        local AutoCraftSection = FishingTab:AddSection("Perfect Rod/Bait Crafting", false)
        local _craftState = {
            enabled   = false,
            thread    = nil,
            eventConn = nil,
        }
        AutoCraftSection:AddParagraph({
            Title   = "Info",
            Content = "Otomatis klik di zona Perfect untuk setiap bar saat minigame crafting berlangsung.\nAktifkan lalu klik Craft secara manual di UI crafting.\n⚠️Diwajibkan untuk menyalakan fitur ini dulu sebelum memulai crafting, dan ketika crafting nya sudah di mulai tinggal tunggu saja sampai notif mendapatkan Perfect Forgotten nya muncul.",
        })
        local CraftMinigame = cachedRequire(ReplicatedStorage.Shared:FindFirstChild("RodCraftingMinigame"))
            or { MinimumClickInterval = 0.08, StartDelaySeconds = 0.35, DurationSeconds = 25 }
        local function nextPeak(bar, startedAt, notBefore)
            local from = math.max(notBefore, startedAt)
            local k = math.ceil(((from - startedAt) / bar.Speed + bar.Phase - 1) / 2)
            return startedAt + bar.Speed * (2 * k + 1 - bar.Phase)
        end
        local function waitUntilServerTime(target)
            local frame = 1 / 60
            while target - frame / 2 - workspace:GetServerTimeNow() > 0 do
                frame = math.clamp(RunService.Heartbeat:Wait(), 0.001, 0.2)
            end
        end
        local function newDelayTracker()
            local samples = { math.clamp(LocalPlayer:GetNetworkPing() / 2, 0.02, 0.3) }
            return {
                add = function(v)
                    samples[#samples + 1] = math.clamp(v, 0.01, 0.4)
                    if #samples > 5 then table.remove(samples, 1) end
                end,
                get = function()
                    local sorted = table.clone(samples)
                    table.sort(sorted)
                    return sorted[math.ceil(#sorted / 2)]
                end,
            }
        end
        local function runAutoCraft(minigameData)
            local ClickRemote  = NetEvents.RF_RodCraftingMinigameClick
            local FinishRemote = NetEvents.RF_FinishRodCraftingMinigame
            if not ClickRemote then
                warn("[AutoCraft] RF_RodCraftingMinigameClick not found")
                return
            end
            local startedAt = minigameData.StartedAt or workspace:GetServerTimeNow()
            local bars      = minigameData.Bars
            local barCount  = minigameData.BarCount or #(bars or {})
            if type(bars) ~= "table" or barCount < 1 then
                warn("[AutoCraft] data minigame tidak berisi Bars")
                return
            end
            local deadline  = workspace:GetServerTimeNow() + (minigameData.DurationSeconds or CraftMinigame.DurationSeconds or 25)
            local barIndex  = 1
            local delay     = newDelayTracker()
            local lastSent  = -math.huge
            while barIndex <= barCount and _craftState.enabled and workspace:GetServerTimeNow() < deadline do
                local barData = bars[barIndex]
                if not (barData and tonumber(barData.Speed) and tonumber(barData.Phase)) then
                    task.wait(0.1)
                    barIndex += 1
                    continue
                end
                local oneWay = delay.get()
                local notBefore = math.max(workspace:GetServerTimeNow() + 0.03,
                    lastSent + (CraftMinigame.MinimumClickInterval or 0.08) + 0.02) + oneWay
                waitUntilServerTime(nextPeak(barData, startedAt, notBefore) - oneWay)
                if not _craftState.enabled then break end
                lastSent = workspace:GetServerTimeNow()
                local sentClock = os.clock()
                local result
                local ok, err = pcall(function()
                    result = ClickRemote:InvokeServer(barIndex)
                end)
                if not ok then
                    warn("[AutoCraft] Click error:", err)
                    break
                end
                if not result then break end
                delay.add((os.clock() - sentClock) / 2)
                if result.Complete then
                    if result.Passed and FinishRemote then
                        task.wait(0.3)
                        pcall(function()
                            FinishRemote:InvokeServer()
                        end)
                    end
                    break
                end
                if result.Accepted then
                    startedAt = result.NextStartedAt or workspace:GetServerTimeNow()
                    barIndex  = result.NextBarIndex or barIndex + 1
                end
            end
        end
        local function setupHook()
            if _craftState.eventConn then
                pcall(function() _craftState.eventConn:Disconnect() end)
                _craftState.eventConn = nil
            end
            local PlayEvent = NetEvents.RE_PlayRodCraftingMinigame
            if not PlayEvent then
                warn("[AutoCraft] RE_PlayRodCraftingMinigame not found")
                return
            end
            _craftState.eventConn = PlayEvent.OnClientEvent:Connect(function(minigameData)
                if not _craftState.enabled then return end
                if not minigameData then return end
                if _craftState.thread then
                    pcall(task.cancel, _craftState.thread)
                    _craftState.thread = nil
                end
                _craftState.thread = task.spawn(function()
                    _G.SetOrbThrowing(true)
                    local ok, err = pcall(runAutoCraft, minigameData)
                    if not ok then warn("[AutoCraft] error:", err) end
                    _G.SetOrbThrowing(false)
                    _craftState.thread = nil
                end)
            end)
        end
        AutoCraftSection:AddToggle({
            Title    = "Enable Auto Perfect Crafting",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _craftState.enabled = on
                if _craftState.thread then
                    pcall(task.cancel, _craftState.thread)
                    _craftState.thread = nil
                    _G.SetOrbThrowing(false)
                end
                if on then
                    setupHook()
                    Library:MakeNotify({
                        Title       = "Auto Craft",
                        Description = "Aktif — akan auto perfect saat minigame crafting rod dimulai.",
                        Delay       = 3,
                    })
                else
                    if _craftState.eventConn then
                        pcall(function() _craftState.eventConn:Disconnect() end)
                        _craftState.eventConn = nil
                    end
                    Library:MakeNotify({
                        Title       = "Auto Craft",
                        Description = "Dinonaktifkan.",
                        Delay       = 2,
                    })
                end
            end,
        })
        local function teleportCrafting(pos, look)
            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then
                Library:MakeNotify({ Title = "Teleport", Description = "Character not found!", Delay = 2 })
                return
            end
            hrp.CFrame = CFrame.lookAt(pos, look)
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
        AutoCraftSection:AddButton({
            Title    = "Teleport to Crafting Tribunal",
            Callback = function()
                teleportCrafting(Vector3.new(-1465.234, -838.012, 5628.995), Vector3.new(-1475.069, -838.012, 5630.799))
            end,
        })
        AutoCraftSection:AddButton({
            Title    = "Teleport to Crafting Withering Core",
            Callback = function()
                teleportCrafting(Vector3.new(-4046.371, -549.875, 468.36), Vector3.new(-4036.702, -549.875, 465.806))
            end,
        })
    end
    do
        local LameCraftSection = FishingTab:AddSection("Auto Lame Craft Bait", false)
        local _lameCraftState = {
            enabled   = false,
            thread    = nil,
            eventConn = nil,
        }
        LameCraftSection:AddParagraph({
            Title   = "Info",
            Content = "For farming a high Size bonus on bait.",
        })
        local waitForLameTiming = (function(barData, startedAt)
            local RodCraftingMinigame = cachedRequire(ReplicatedStorage.Shared:FindFirstChild("RodCraftingMinigame")) or {}
            local minDelay = RodCraftingMinigame.StartDelaySeconds or 0.35
            local elapsed  = workspace:GetServerTimeNow() - (startedAt or workspace:GetServerTimeNow())
            local remaining = minDelay - elapsed
            if remaining > 0 then
                task.wait(remaining + 0.03)
            end
        end)
        local function runAutoLameCraft(minigameData)
            local ClickRemote  = NetEvents.RF_RodCraftingMinigameClick
            local FinishRemote = NetEvents.RF_FinishRodCraftingMinigame
            if not ClickRemote then
                warn("[AutoLameCraft] RF_RodCraftingMinigameClick not found")
                return
            end
            local startedAt = minigameData.StartedAt
            local bars      = minigameData.Bars
            local barCount  = minigameData.BarCount or #(bars or {}) or 4
            local barIndex  = 1
            while barIndex <= barCount and _lameCraftState.enabled do
                local barData = bars and bars[barIndex]
                if not barData then
                    task.wait(0.1)
                    barIndex += 1
                    continue
                end
                waitForLameTiming(barData, startedAt)
                if not _lameCraftState.enabled then break end
                local result
                local ok, err = pcall(function()
                    result = ClickRemote:InvokeServer(barIndex)
                end)
                if not ok then
                    warn("[AutoLameCraft] Click error:", err)
                    break
                end
                if not result then break end
                if result.Complete then
                    if FinishRemote then
                        task.wait(0.3)
                        pcall(function()
                            FinishRemote:InvokeServer()
                        end)
                    end
                    break
                end
                if result.Accepted then
                    startedAt = result.NextStartedAt or workspace:GetServerTimeNow()
                    barIndex  = result.NextBarIndex or barIndex + 1
                else
                    task.wait(0.05)
                end
            end
        end
        local function setupLameCraftHook()
            if _lameCraftState.eventConn then
                pcall(function() _lameCraftState.eventConn:Disconnect() end)
                _lameCraftState.eventConn = nil
            end
            local PlayEvent = NetEvents.RE_PlayRodCraftingMinigame
            if not PlayEvent then
                warn("[AutoLameCraft] RE_PlayRodCraftingMinigame not found")
                return
            end
            _lameCraftState.eventConn = PlayEvent.OnClientEvent:Connect(function(minigameData)
                if not _lameCraftState.enabled then return end
                if not minigameData then return end
                if _lameCraftState.thread then
                    pcall(task.cancel, _lameCraftState.thread)
                    _lameCraftState.thread = nil
                end
                _lameCraftState.thread = task.spawn(function()
                    task.wait(0.4)
                    if _lameCraftState.enabled then
                        runAutoLameCraft(minigameData)
                    end
                end)
            end)
        end
        LameCraftSection:AddToggle({
            Title    = "Enable Auto Lame Craft Bait",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _lameCraftState.enabled = on
                if _lameCraftState.thread then
                    pcall(task.cancel, _lameCraftState.thread)
                    _lameCraftState.thread = nil
                end
                if on then
                    setupLameCraftHook()
                    Library:MakeNotify({
                        Title       = "Auto Lame Craft",
                        Description = "Aktif — akan sengaja klik jelek (Lame) saat minigame crafting bait dimulai.",
                        Delay       = 3,
                    })
                else
                    if _lameCraftState.eventConn then
                        pcall(function() _lameCraftState.eventConn:Disconnect() end)
                        _lameCraftState.eventConn = nil
                    end
                    Library:MakeNotify({
                        Title       = "Auto Lame Craft",
                        Description = "Dinonaktifkan.",
                        Delay       = 2,
                    })
                end
            end,
        })
    end
end
-- [Favorite Tab]
task.wait()
local FavoriteTab = MainWindow:AddTab({ Name = "Favorite", Icon = "star" })
do
    local TIER_NAMES = {
        [1] = "Common",    [2] = "Uncommon", [3] = "Rare",
        [4] = "Epic",      [5] = "Legendary",[6] = "Mythic",
        [7] = "SECRET",    [8] = "FORGOTTEN",
        [90] = "Trophy",
    }
    local RARITY_OPTIONS = { "Common","Uncommon","Rare","Epic","Legendary","Mythic","SECRET","FORGOTTEN" }
    local RARITY_SET = {}
    for _, r in ipairs(RARITY_OPTIONS) do RARITY_SET[r] = true end
    local EQUIP_TYPES = {
        ["Gears"]          = true,
        ["Enchant Stones"] = true,
        ["Trophies"]       = true,
        ["Equipment"]      = true,
    }
    local EQUIP_RARITY_OPTIONS = { "Common","Uncommon","Rare","Epic","Legendary","Mythic","SECRET","FORGOTTEN","Trophy" }
    local EQUIP_RARITY_SET = {}
    for _, r in ipairs(EQUIP_RARITY_OPTIONS) do EQUIP_RARITY_SET[r] = true end
    local _fav = {
        itemUtility = nil,
        replion     = nil,
        fishList    = {},
        equipList   = {},
        variantList = {},
        watchConn   = nil,
        watchers    = {},
        pending     = false,
    }
    local function toSet(arr)
        local s = {}
        if type(arr) == "table" then
            for _, v in ipairs(arr) do s[v] = true end
        end
        return s
    end
    local function keepValid(list, validSet)
        local out, ready = {}, next(validSet) ~= nil
        if type(list) == "table" then
            for _, v in ipairs(list) do
                if type(v) == "string" and (validSet[v] or not ready) then out[#out + 1] = v end
            end
        end
        return out
    end
    local function notify(title, text, delay)
        Library:MakeNotify({ Title = title, Description = text, Delay = delay or 3 })
    end
    local function initRefs()
        if not _fav.itemUtility then
            pcall(function() _fav.itemUtility = cachedRequire(ReplicatedStorage.Shared.ItemUtility) end)
        end
        if not _fav.replion then _fav.replion = getCachedReplionData() end
        return _fav.replion ~= nil and _fav.itemUtility ~= nil
    end
    local function buildLists()
        _fav.fishList, _fav.equipList, _fav.variantList = {}, {}, {}
        pcall(function()
            local items = cachedRequire(ReplicatedStorage:FindFirstChild("Items"))
            if type(items) ~= "table" then return end
            local seenFish, seenEquip = {}, {}
            for _, entry in pairs(items) do
                local d = entry.Data
                if d and d.Type then
                    local name = d.DisplayName or d.Name
                    if name and d.Type == "Fish" then
                        if not seenFish[name] then
                            seenFish[name] = true
                            _fav.fishList[#_fav.fishList + 1] = name
                        end
                    elseif name and EQUIP_TYPES[d.Type] then
                        if not seenEquip[name] then
                            seenEquip[name] = true
                            _fav.equipList[#_fav.equipList + 1] = name
                        end
                    end
                end
            end
            table.sort(_fav.fishList)
            table.sort(_fav.equipList)
        end)
        pcall(function()
            local folder = ReplicatedStorage:FindFirstChild("Variants")
            if not folder then return end
            for _, m in ipairs(folder:GetChildren()) do
                if m:IsA("ModuleScript") and m.Name ~= "1x1x1x1" then
                    _fav.variantList[#_fav.variantList + 1] = m.Name
                end
            end
            table.sort(_fav.variantList)
        end)
    end
    local function variantNameOf(item)
        local md = item and item.Metadata
        if not md then return nil end
        local v = md.Variant or md.VariantName or md.MutationName or md.VariantId
        if type(v) ~= "string" then return nil end
        v = v:gsub("^%s+", ""):gsub("%s+$", "")
        if v == "" or v == "None" then return nil end
        return v
    end
    local function matches(item, data, filter)
        if filter.tier and data.Tier ~= filter.tier then return false end
        if filter.ids and not filter.ids[data.Id] then return false end
        if filter.mutated and not variantNameOf(item) then return false end
        if filter.names and next(filter.names) then
            local name = data.DisplayName or data.Name
            if not name or not filter.names[name] then return false end
        end
        if filter.rarities and next(filter.rarities) then
            local tierName = TIER_NAMES[data.Tier]
            if not tierName or not filter.rarities[tierName] then return false end
        end
        if filter.variants and next(filter.variants) then
            local variant = variantNameOf(item)
            if not variant or not filter.variants[variant] then return false end
        end
        return true
    end
    local function hasAnyFilter(filter)
        return (filter.tier ~= nil)
            or (filter.ids and next(filter.ids) ~= nil)
            or (filter.mutated == true)
            or (filter.names and next(filter.names) ~= nil)
            or (filter.rarities and next(filter.rarities) ~= nil)
            or (filter.variants and next(filter.variants) ~= nil)
    end
    local function favoritedNow(uuid)
        local inv = _fav.replion:Get({ "Inventory", "Items" })
        if type(inv) ~= "table" then return nil end
        for _, it in ipairs(inv) do
            if it.UUID == uuid then return it.Favorited == true end
        end
        return nil
    end
    local function setFavorited(uuid, target)
        local current = favoritedNow(uuid)
        if current == nil then return false end
        if current == target then return true end
        pcall(function() NetEvents.RE_FavoriteItem:FireServer(uuid) end)
        local deadline = os.clock() + 2
        repeat
            task.wait(0.05)
            current = favoritedNow(uuid)
        until current == target or current == nil or os.clock() > deadline
        return current == target
    end
    local function scan(state, filter, target)
        if state.busy or not state.enabled then return end
        if not initRefs() then return end
        if not hasAnyFilter(filter) then return end
        state.busy = true
        local matched, done = 0, 0
        pcall(function()
            local inv = _fav.replion:Get({ "Inventory", "Items" })
            if type(inv) ~= "table" then return end
            for _, item in ipairs(inv) do
                if not state.enabled then break end
                if (item.Favorited == true) ~= target then
                    local data = _fav.itemUtility:GetItemData(item.Id)
                    data = data and data.Data
                    local typeOk = data and (
                        filter.types and filter.types[data.Type] == true
                        or (not filter.types and data.Type == "Fish")
                    )
                    if typeOk and matches(item, data, filter) then
                        matched = matched + 1
                        if setFavorited(item.UUID, target) then done = done + 1 end
                    end
                end
            end
        end)
        state.busy = false
        return matched, done
    end
    local function syncWatcher()
        local anyActive = false
        for _, w in ipairs(_fav.watchers) do
            if w.state.enabled then anyActive = true; break end
        end
        if anyActive and not _fav.watchConn and _fav.replion then
            _fav.watchConn = _fav.replion:OnChange({ "Inventory", "Items" }, inScriptContext(function()
                if _fav.pending then return end
                _fav.pending = true
                task.delay(0.5, function()
                    _fav.pending = false
                    for _, w in ipairs(_fav.watchers) do
                        if w.state.enabled then (w.scan or scan)(w.state, w.filter(), true) end
                    end
                end)
            end))
        elseif not anyActive and _fav.watchConn then
            pcall(function() _fav.watchConn:Disconnect() end)
            _fav.watchConn = nil
        end
    end
    local function addWatcher(state, filter, scanFn)
        _fav.watchers[#_fav.watchers + 1] = { state = state, filter = filter, scan = scanFn }
    end
    local AutoFavSection = FavoriteTab:AddSection("Auto Favorite")
    local _auto = { enabled = false, busy = false, names = {}, rarities = {}, variants = {} }
    local function autoFilter()
        return { names = _auto.names, rarities = _auto.rarities, variants = _auto.variants }
    end
    addWatcher(_auto, autoFilter)
    AutoFavSection:AddParagraph({
        Title   = "Filter Logic (AND)",
        Content = "Semua filter aktif bekerja sebagai AND.\n\n"
               .. "• Name saja    → ikan cocok name\n"
               .. "• Rarity saja  → ikan cocok rarity\n"
               .. "• Variant saja → ikan cocok variant\n"
               .. "• Gabungan     → harus cocok semuanya\n\n"
               .. "Filter kosong diabaikan.\n"
               .. "Contoh: Mythic + Corrupt → hanya ikan Mythic ber-variant Corrupt.",
    })
    local function rescanAuto()
        if _auto.enabled then task.spawn(function() scan(_auto, autoFilter(), true) end) end
    end
    AutoFavSection:AddDropdown({
        Title    = "Name",
        Multi    = true,
        Options  = { "Loading..." },
        Default  = {},
        Callback = function(selected) _auto.names = toSet(selected); rescanAuto() end,
    })
    AutoFavSection:AddDropdown({
        Title    = "Variant",
        Multi    = true,
        Options  = { "Loading..." },
        Default  = {},
        Callback = function(selected) _auto.variants = toSet(selected); rescanAuto() end,
    })
    AutoFavSection:AddDropdown({
        Title    = "Rarity",
        Multi    = true,
        Options  = RARITY_OPTIONS,
        Default  = {},
        Callback = function(selected)
            _auto.rarities = toSet(keepValid(selected, RARITY_SET))
            rescanAuto()
        end,
    })
    local autoToggleRef
    autoToggleRef = AutoFavSection:AddToggle({
        Title    = "Auto Favorite",
        Default  = false,
        Callback = function(on)
            if on and not initRefs() then
                notify("Auto Favorite", "Gagal inisialisasi data.", 3)
                pcall(function() autoToggleRef:SetValue(false) end)
                return
            end
            _auto.enabled = on
            syncWatcher()
            if on then task.spawn(function() scan(_auto, autoFilter(), true) end) end
            notify("Auto Favorite", on and "Started" or "Stopped", 2)
        end,
    })
    local MaxtonSection = FavoriteTab:AddSection("Auto Favorite Maxton", false)
    local _maxton = { enabled = false, busy = false, names = {}, rarities = {}, variants = {} }
    local function maxtonFilter()
        return { names = _maxton.names, rarities = _maxton.rarities, variants = _maxton.variants }
    end
    local function isMaxTon(info, item)
        local weight = item and item.Metadata and tonumber(item.Metadata.Weight)
        local big    = info and info.Weight and info.Weight.Big
        local max    = big and tonumber(big.Max)
        return weight ~= nil and max ~= nil and weight >= max
    end
    local function maxtonScan(state, filter, target)
        if target == false then return 0, 0 end
        if state.busy or not state.enabled then return 0, 0 end
        if not initRefs() then return 0, 0 end
        state.busy = true
        local matched, done = 0, 0
        pcall(function()
            local inv = _fav.replion:Get({ "Inventory", "Items" })
            if type(inv) ~= "table" then return end
            for _, item in ipairs(inv) do
                if not state.enabled then break end
                local info = _fav.itemUtility:GetItemData(item.Id)
                local data = info and info.Data
                if data and data.Type == "Fish" and isMaxTon(info, item) and matches(item, data, filter) then
                    matched += 1
                    if item.Favorited ~= true and setFavorited(item.UUID, true) then done += 1 end
                end
            end
        end)
        state.busy = false
        return matched, done
    end
    addWatcher(_maxton, maxtonFilter, maxtonScan)
    MaxtonSection:AddParagraph({
