    local function elementalIslandFishIds()
        local ids = {}
        pcall(function()
            local areas = cachedRequire(ReplicatedStorage:FindFirstChild("Areas"))
            local items = cachedRequire(ReplicatedStorage:FindFirstChild("Items"))
            local names = {}
            for areaName, area in pairs(areas) do
                if type(areaName) == "string" and areaName:find("^Elemental Island")
                    and type(area) == "table" and type(area.Items) == "table"
                then
                    for _, fishName in ipairs(area.Items) do names[fishName] = true end
                end
            end
            for _, entry in pairs(items) do
                local d = type(entry) == "table" and entry.Data
                if d and d.Type == "Fish" and d.Id and (names[d.Name] or names[d.DisplayName]) then
                    ids[d.Id] = true
                end
            end
        end)
        if next(ids) == nil then
            for _, id in ipairs({ 1186, 1187, 1188, 1189, 1201 }) do ids[id] = true end
        end
        return ids
    end
    addPreset("Favorite Legendary Elemental (Any Mutation)",
        "Favorite Legendary Elemental Island (Any Mutation)",
        { tier = 5, mutated = true, ids = elementalIslandFishIds() })
    addPreset("Favorite Legendary (Lightning / Corrupt / Stone)",
        "Favorite Legendary (Lightning / Corrupt / Stone)",
        { tier = 5, variants = { Lightning = true, Corrupt = true, Stone = true } })
    local EquipSection = FavoriteTab:AddSection("Auto Favorite Equipment", false)
    local _equip = { enabled = false, busy = false, names = {}, rarities = {}, variants = {} }
    local function equipFilter()
        return {
            names    = _equip.names,
            rarities = _equip.rarities,
            variants = _equip.variants,
            types    = EQUIP_TYPES,
        }
    end
    addWatcher(_equip, equipFilter)
    EquipSection:AddParagraph({
        Title   = "Info",
        Content = "Auto favorite Gears, Enchant Stones, Trophies & Equipment (bukan ikan/rod).\n"
               .. "Filter = AND, yang kosong diabaikan.",
    })
    local function rescanEquip()
        if _equip.enabled then task.spawn(function() scan(_equip, equipFilter(), true) end) end
    end
    EquipSection:AddDropdown({
        Title    = "Equip Name",
        Multi    = true,
        Options  = { "Loading..." },
        Default  = {},
        Callback = function(selected) _equip.names = toSet(selected); rescanEquip() end,
    })
    EquipSection:AddDropdown({
        Title    = "Equip Variant",
        Multi    = true,
        Options  = { "Loading..." },
        Default  = {},
        Callback = function(selected) _equip.variants = toSet(selected); rescanEquip() end,
    })
    EquipSection:AddDropdown({
        Title    = "Equip Rarity",
        Multi    = true,
        Options  = EQUIP_RARITY_OPTIONS,
        Default  = {},
        Callback = function(selected)
            _equip.rarities = toSet(keepValid(selected, EQUIP_RARITY_SET))
            rescanEquip()
        end,
    })
    local equipToggleRef
    equipToggleRef = EquipSection:AddToggle({
        Title    = "Auto Favorite Equipment",
        Default  = false,
        Callback = function(on)
            if on and not initRefs() then
                notify("Auto Favorite Equipment", "Gagal inisialisasi data.", 3)
                pcall(function() equipToggleRef:SetValue(false) end)
                return
            end
            _equip.enabled = on
            syncWatcher()
            if on then
                task.spawn(function()
                    local matched, doneCount = scan(_equip, equipFilter(), true)
                    if matched and matched > 0 then
                        notify("Auto Favorite Equipment",
                            ("%d cocok, %d berhasil di-favorite."):format(matched, doneCount or 0), 3)
                    end
                end)
            end
            notify("Auto Favorite Equipment", on and "Started" or "Stopped", 2)
        end,
    })
    local NAME_FLAG, VARIANT_FLAG, RARITY_FLAG = "Name", "Variant", "Rarity"
    local MAXTON_NAME_FLAG, MAXTON_VARIANT_FLAG, MAXTON_RARITY_FLAG = "Maxton_Name", "Maxton_Variant", "Maxton_Rarity"
    local EQUIP_NAME_FLAG, EQUIP_VARIANT_FLAG, EQUIP_RARITY_FLAG = "Equip_Name", "Equip_Variant", "Equip_Rarity"
    local UNFAV_NAME_FLAG, UNFAV_VARIANT_FLAG  = "Unfav_Name", "Unfav_Variant"
    local function setFlagValues(flagKey, options, selected)
        local flag = Library.flags and Library.flags[flagKey]
        if not flag or not flag.SetValues then return end
        pcall(function() flag:SetValues(options, selected or {}) end)
    end
    local function picked(set, valid)
        local out, ok = {}, toSet(valid)
        local ready = next(ok) ~= nil
        for name in pairs(set or {}) do
            if ok[name] or not ready then out[#out + 1] = name end
        end
        table.sort(out)
        return out
    end
    local function optionsFor(list, saved, placeholder)
        if #list > 0 then return list end
        if #saved > 0 then return saved end
        return { placeholder }
    end
    local function savedPicks(flagKey, list)
        return keepValid(Library.ConfigSystem.Get("MultiDropdowns." .. flagKey, {}), toSet(list))
    end
    local function setRarity(flagKey, list)
        if #list == 0 then return end
        local flag = Library.flags and Library.flags[flagKey]
        if flag and flag.Set then pcall(function() flag:Set(list) end) end
    end
    local function applyGroup(loadSaved, state, nameFlag, nameList, namePlaceholder, variantFlag, rarityFlag, raritySet)
        local names, variants
        if loadSaved then
            names, variants = savedPicks(nameFlag, nameList), savedPicks(variantFlag, _fav.variantList)
            local rarities = keepValid(Library.ConfigSystem.Get("MultiDropdowns." .. rarityFlag, {}), raritySet)
            state.names, state.variants, state.rarities = toSet(names), toSet(variants), toSet(rarities)
            setRarity(rarityFlag, rarities)
        else
            names, variants = picked(state.names, nameList), picked(state.variants, _fav.variantList)
        end
        setFlagValues(nameFlag,    optionsFor(nameList, names, namePlaceholder), names)
        setFlagValues(variantFlag, optionsFor(_fav.variantList, variants, "No Variants Found"), variants)
    end
    local function applyLists(loadSaved)
        applyGroup(loadSaved, _auto,   NAME_FLAG,        _fav.fishList,  "No Fish Found",      VARIANT_FLAG,        RARITY_FLAG,        RARITY_SET)
        applyGroup(loadSaved, _maxton, MAXTON_NAME_FLAG, _fav.fishList,  "No Fish Found",      MAXTON_VARIANT_FLAG, MAXTON_RARITY_FLAG, RARITY_SET)
        applyGroup(loadSaved, _equip,  EQUIP_NAME_FLAG,  _fav.equipList, "No Equipment Found", EQUIP_VARIANT_FLAG,  EQUIP_RARITY_FLAG,  EQUIP_RARITY_SET)
        setFlagValues(UNFAV_NAME_FLAG,    optionsFor(_fav.fishList,    {}, "No Fish Found"),     {})
        setFlagValues(UNFAV_VARIANT_FLAG, optionsFor(_fav.variantList, {}, "No Variants Found"), {})
    end
    local function listsReady()
        return #_fav.fishList > 0 and #_fav.variantList > 0 and #_fav.equipList > 0
    end
    local function refreshLists(loadSaved)
        buildLists()
        applyLists(loadSaved)
        return #_fav.fishList, #_fav.variantList, #_fav.equipList
    end
    AutoFavSection:AddButton({
        Title    = "Refresh Lists",
        Callback = function()
            local fish, variant, equip = refreshLists(false)
            notify("Refresh", ("Fish: %d | Variant: %d | Equipment: %d"):format(fish, variant, equip), 3)
        end,
    })
    UnfavSection:AddButton({
        Title    = "Refresh List Items",
        Callback = function()
            local fish, variant = refreshLists(false)
            notify("Refresh", ("Fish: %d | Variant: %d"):format(fish, variant), 3)
        end,
    })
    task.spawn(function()
        if not game:IsLoaded() then game.Loaded:Wait() end
        task.wait(1)
        if not initRefs() then task.wait(2); initRefs() end
        buildLists()
        for _ = 1, 30 do
            if listsReady() then break end
            task.wait(2)
            buildLists()
        end
        applyLists(true)
        local fish, variant, equip = #_fav.fishList, #_fav.variantList, #_fav.equipList
        if fish > 0 or variant > 0 or equip > 0 then
            notify("Auto Favorite",
                ("Loaded: %d fish | %d variants | %d equipment"):format(fish, variant, equip), 3)
        end
    end)
end
-- [Teleport Tab]
task.wait()
do
    local HttpService       = game:GetService("HttpService")
    local SAVE_FOLDER       = "LynxGUI_Configs"
    local SAVE_FILE         = SAVE_FOLDER .. "/LynxSavedLocationn.json"
    local _tp = {
        SelectedIsland      = nil,
        SelectedPlayer      = nil,
        SelectedPlayerLabel = nil,
        AutoTeleportEnabled = false,
        AutoTeleportConn    = nil,
        ForceTeleportCancel = false,
    }
    local function _root(char)
        char = char or LocalPlayer.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end
    local function _teleportTo(cf)
        local char = LocalPlayer.Character
        local root = _root(char)
        if not root then return false end
        return (pcall(function()
            if char.PrimaryPart then char:PivotTo(cf) else root.CFrame = cf end
        end))
    end
    local function _notify(title, desc)
        Library:MakeNotify({ Title = title, Description = desc, Delay = 3 })
    end
    local function _forceTeleport(targetCFrame)
        _tp.ForceTeleportCancel = false
        task.spawn(function()
            for _ = 1, 10 do
                if _tp.ForceTeleportCancel then break end
                if _totemSpawning then task.wait(0.5); continue end
                local root = _root()
                if root and root.Parent then root.CFrame = targetCFrame end
                task.wait(0.1)
            end
        end)
    end
    local function _loadSavedPosition()
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(SAVE_FILE)) end)
        if not ok or type(data) ~= "table" or #data ~= 12 then return nil end
        local cf
        if not pcall(function() cf = CFrame.new(table.unpack(data)) end) then return nil end
        return cf
    end
    local TeleportTab = MainWindow:AddTab({ Name = "Teleport", Icon = "gps" })
    do
        local _coords, _list, _loaded, _dropRef = {}, {}, false, nil
        local function _applyOptions()
            if not _dropRef then return end
            local opts = #_list > 0 and _list or { "(Gagal load)" }
            local last
            if #_list > 0 then
                local ok, saved = pcall(function()
                    return Library.ConfigSystem.Get("Dropdowns.Select_Island", nil)
                end)
                if ok and type(saved) == "string" and _coords[saved] then last = saved end
            end
            local flag = Library and Library.flags and Library.flags["Select_Island"]
            if flag and flag.SetValues then
                pcall(function() flag:SetValues(opts, last) end)
            elseif _dropRef.SetOptions then
                _dropRef:SetOptions(opts)
            end
            if last then _tp.SelectedIsland = last end
        end
        local function _load(onDone)
            if _loaded then if onDone then onDone() end; return end
            task.spawn(function()
                local coords = fetchIslandCoords()
                if coords then
                    table.clear(_coords); table.clear(_list)
                    for name, data in pairs(coords) do
                        _coords[name] = data
                        _list[#_list + 1] = name
                    end
                    table.sort(_list)
                    _loaded = true
                else
                    warn("[Teleport] Gagal load island coords.")
                end
                _applyOptions()
                if _loaded and onDone then onDone() end
            end)
        end
        _load()
        local IslandSection = TeleportTab:AddSection("Teleport to Island")
        local function _asString(v)
            if type(v) == "table" then
                local k, tv = next(v)
                v = (type(k) == "number" and tv) or (type(tv) == "boolean" and k) or k
            end
            return type(v) == "string" and v or ""
        end
        _dropRef = IslandSection:AddDropdown({
            Title    = "Select Island",
            Multi    = false,
            Options  = #_list > 0 and _list or { "Loading..." },
            Default  = nil,
            Callback = function(v)
                local val = _asString(v)
                if val == "Loading..." or val == "(Gagal load)" then val = "" end
                _tp.SelectedIsland = val
            end,
        })
        IslandSection:AddButton({
            Title    = "Teleport",
            Callback = function()
                if not _loaded then
                    _load(function() _notify("Teleport", "Island list dimuat, pilih island lalu tekan Teleport lagi.") end)
                    return
                end
                local data = _tp.SelectedIsland ~= "" and _coords[_tp.SelectedIsland]
                if not data then
                    _notify("Teleport", "Pilih island dulu dari dropdown!")
                    return
                end
                local lift = Vector3.new(0, 5, 0)
                if _teleportTo(CFrame.new(data.pos + lift, data.look + lift)) then
                    _notify("Teleport", "Teleported to " .. _tp.SelectedIsland)
                else
                    _notify("Teleport", "Karakter belum siap!")
                end
            end,
        })
    end
    do
        local PlayerSection = TeleportTab:AddSection("Teleport to Player", false)
        local _labels, _lookup, _dropRef = {}, {}, nil
        local function _refresh()
            table.clear(_labels); table.clear(_lookup)
            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer then
                    local label = (player.DisplayName or player.Name) .. " (" .. player.Name .. ")"
                    _labels[#_labels + 1] = label
                    _lookup[label] = player
                end
            end
            table.sort(_labels)
        end
        _refresh()
        _dropRef = PlayerSection:AddDropdown({
            Title    = "Select Player",
            Multi    = false,
            Options  = _labels,
            Default  = nil,
            NoSave   = false,
            Callback = function(v)
                if type(v) == "table" then
                    local k, tv = next(v)
                    v = (type(k) == "number" and tv) or (type(tv) == "boolean" and k) or k
                end
                local label = type(v) == "string" and v or ""
                _tp.SelectedPlayer      = _lookup[label]
                _tp.SelectedPlayerLabel = label
            end,
        })
        PlayerSection:AddButton({
            Title    = "Teleport to selected Player",
            Callback = function()
                if not _tp.SelectedPlayer then
                    _notify("Teleport", "Pilih player dulu dari dropdown!")
                    return
                end
                if not _root() then
                    _notify("Teleport", "Karakter kamu belum siap!")
                    return
                end
                local chars = workspace:FindFirstChild("Characters")
                local targetChar = chars and chars:FindFirstChild(_tp.SelectedPlayer.Name)
                local targetRoot = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                if not targetRoot then
                    _notify("Teleport", "Karakter target tidak ditemukan!")
                    return
                end
                _teleportTo(targetRoot.CFrame * CFrame.new(0, 3, 0))
                _notify("Teleport", "Teleported to " .. (_tp.SelectedPlayerLabel or ""))
            end,
        })
        PlayerSection:AddButton({
            Title    = "Refresh Player List",
            Callback = function()
                _refresh()
                if _dropRef and _dropRef.SetOptions then _dropRef:SetOptions(_labels) end
                _notify("Teleport", "Player list diperbarui.")
            end,
        })
    end
    do
        local SavedSection = TeleportTab:AddSection("Saved Location", false)
        local _autoToggle
        SavedSection:AddButton({
            Title    = "Save Current Location",
            Callback = function()
                local root = _root()
                if not root then _notify("Error", "Character tidak ditemukan!"); return end
                pcall(function() if not isfolder(SAVE_FOLDER) then makefolder(SAVE_FOLDER) end end)
                local ok = pcall(function()
                    writefile(SAVE_FILE, HttpService:JSONEncode({ root.CFrame:GetComponents() }))
                end)
                _notify(ok and "Saved" or "Error",
                    ok and "Lokasi berhasil disimpan!" or "Gagal menyimpan lokasi!")
            end,
        })
        SavedSection:AddButton({
            Title    = "Teleport to Saved",
            Callback = function()
                local saved = _loadSavedPosition()
                if not saved then _notify("Error", "Tidak ada lokasi tersimpan!"); return end
                if not _root() then _notify("Error", "Character tidak ditemukan!"); return end
                _forceTeleport(saved)
                _notify("Teleported", "Teleport ke lokasi tersimpan berhasil!")
            end,
        })
        SavedSection:AddButton({
            Title    = "Reset Saved Location",
            Callback = function()
                _tp.ForceTeleportCancel = true
                _tp.AutoTeleportEnabled = false
                if _tp.AutoTeleportConn then _tp.AutoTeleportConn:Disconnect(); _tp.AutoTeleportConn = nil end
                if _autoToggle then pcall(function() _autoToggle:SetValue(false) end) end
                local deleted = false
                pcall(function()
                    if isfile(SAVE_FILE) then
                        delfile(SAVE_FILE)
                        deleted = not isfile(SAVE_FILE)
                    else
                        deleted = true
                    end
                end)
                _tp.ForceTeleportCancel = false
                _notify(deleted and "Reset" or "Error",
                    deleted and "Lokasi tersimpan & auto teleport telah direset." or "Gagal menghapus file lokasi!")
            end,
        })
        _autoToggle = SavedSection:AddToggle({
            Title    = "Auto Teleport on Spawn",
            Default  = false,
            Callback = function(on)
                if on then
                    if _tp.AutoTeleportEnabled then return end
                    _tp.AutoTeleportEnabled = true
                    local function onSpawn(char)
                        task.spawn(function()
                            if not char:WaitForChild("HumanoidRootPart", 10) then return end
                            task.wait(1.5)
                            local waited = 0
                            while _totemSpawning and waited < 30 do task.wait(1); waited = waited + 1 end
                            if waited > 0 then task.wait(1.5) end
                            local saved = _loadSavedPosition()
                            if saved then
                                _forceTeleport(saved)
                                _notify("Auto Teleport", "Teleported ke lokasi tersimpan!")
                            end
                        end)
                    end
                    _tp.AutoTeleportConn = LocalPlayer.CharacterAdded:Connect(onSpawn)
                    if LocalPlayer.Character then onSpawn(LocalPlayer.Character) end
                else
                    _tp.AutoTeleportEnabled = false
                    if _tp.AutoTeleportConn then _tp.AutoTeleportConn:Disconnect(); _tp.AutoTeleportConn = nil end
                end
            end,
        })
    end
    do
        _ev = {
            active         = false,
            selectedEvents = {},
            priorityEvent  = nil,
            loopThread     = nil,
            origCF         = nil,
            curCF          = nil,
            curEventName   = nil,
            curIsGlacial   = false,
            charConn       = nil,
            refreshThread  = nil,
            wowAutoEnabled = false,
        }
        local _evReplion = (function()
            local rep = getCachedReplion()
            if not rep then return nil end
            local ok, data = pcall(function() return rep.Client:GetReplion("Events") end)
            if ok and data then return data end
            ok, data = pcall(function() return rep.Client:WaitReplion("Events") end)
            return ok and data or nil
        end)()
        local _evData = cachedRequire(ReplicatedStorage:FindFirstChild("Events"))
        local _ignoreList = {
            Cloudy = true, Day = true, ["Increased Luck"] = true, Mutated = true, Night = true,
            Snow = true, ["Sparkling Cove"] = true, Storm = true, Wind = true, Radiant = true,
            ["Present Rain"] = true,
            ["Admin - Super Mutated"] = true, ["Admin - Shocked"] = true, ["Admin - MEGA Luck"] = true,
            ["Admin - Super Luck"] = true, ["Admin - Night Celebration"] = true,
            ["Admin - Forgotten Tier"] = true, ["Admin - Galaxy Storm"] = true,
        }
        local GLACIAL_CF = CFrame.new(
            Vector3.new(877.625, 3.919, 3692.855),
            Vector3.new(872.989, 3.919, 3683.995)
        )
        _totemSpawning = false
        local function _activeEventNames()
            if not _evReplion then return {} end
            local active = _evReplion:Get("Events")
            local result = {}
            if type(active) == "table" then
                for _, name in pairs(active) do
                    if typeof(name) == "string" then result[name] = true end
                end
            end
            return result
        end
        local function _eventList()
            local result = {}
            if _evData then
                for eventId, info in pairs(_evData) do
                    if info.Coordinates and not _ignoreList[eventId] then result[#result + 1] = eventId end
                end
            end
            local hasGlacial = false
            for _, v in ipairs(result) do
                if string.find(v, "Glacial Serpent") then hasGlacial = true; break end
            end
            if not hasGlacial then result[#result + 1] = "Glacial Serpent" end
            table.sort(result)
            return result
        end
        local function _setAnchored(char, state)
            if not char then return end
            for _, v in ipairs(char:GetDescendants()) do
                if v:IsA("BasePart") then v.Anchored = state end
            end
        end
        local function _float(char, root)
            if not char then return end
            root = root or _root(char)
            if not root then return end
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = { char }
            params.IgnoreWater = false
            local hit = workspace:Raycast(root.Position + Vector3.new(0, 60, 0), Vector3.new(0, -220, 0), params)
            if not hit then return end
            local hum    = char:FindFirstChildOfClass("Humanoid")
            local standY = hit.Position.Y + ((hum and hum.HipHeight) or 2) + 2.5
            local cf     = char:GetPivot()
            char:PivotTo(cf.Rotation + Vector3.new(cf.Position.X, standY, cf.Position.Z))
        end
        local _partCache, _partCacheAt = {}, {}
        local CACHE_TTL = 3
        local function _findEventCFrame(eventName)
            if not eventName then return nil end
            if string.find(eventName, "Glacial Serpent") then return GLACIAL_CF, true end
            local now = tick()
            local cached = _partCache[eventName]
            if cached and cached.Parent and _partCacheAt[eventName] and (now - _partCacheAt[eventName]) < CACHE_TTL then
                return cached.CFrame, false
            end
            _partCache[eventName] = nil
            local propsFolders = {}
            for _, obj in ipairs(workspace:GetChildren()) do
                if obj.Name == "Props" then propsFolders[#propsFolders + 1] = obj end
            end
            local function remember(part)
                _partCache[eventName]   = part
                _partCacheAt[eventName] = now
                return part.CFrame, false
            end
            for _, props in ipairs(propsFolders) do
                for _, group in ipairs(props:GetChildren()) do
                    for _, desc in ipairs(group:GetDescendants()) do
                        if desc:IsA("TextLabel") and desc.Name == "DisplayName" then
                            local txt = desc.ContentText ~= "" and desc.ContentText or desc.Text
                            if txt:lower() == eventName:lower() then
                                local part = desc:FindFirstAncestorWhichIsA("BasePart")
                                            or group:FindFirstChild("Part")
                                if part and part:IsA("BasePart") then return remember(part) end
                            end
                        end
                    end
                end
            end
            for _, props in ipairs(propsFolders) do
                local group = props:FindFirstChild(eventName)
                if group then
                    local named = group:FindFirstChild(eventName, true)
                    if named and named:IsA("BasePart") then return remember(named) end
                    local p = group:FindFirstChild("Part")
                    if p and p:IsA("BasePart") then return remember(p) end
                    local best, lowestY = nil, math.huge
                    for _, desc in ipairs(group:GetDescendants()) do
                        if desc:IsA("BasePart") and desc.Position.Y < lowestY and desc.Position.Y > -10 then
                            lowestY, best = desc.Position.Y, desc
                        end
                    end
                    if best then return remember(best) end
                end
            end
            local info = _evData and _evData[eventName]
            if info and info.Coordinates and #info.Coordinates > 0 then
                local root, best = _root(), info.Coordinates[1]
                if #info.Coordinates > 1 and root then
                    local closest = math.huge
                    for _, coord in ipairs(info.Coordinates) do
                        local dist = (root.Position - coord).Magnitude
                        if dist < closest then closest, best = dist, coord end
                    end
                end
                return CFrame.new(best), false
            end
            return nil
        end
        local function _raised(cf)
            local p = cf.Position + Vector3.new(0, 10, 0)
            return CFrame.new(p, p + cf.LookVector)
        end
        local function _stopEvent()
            _ev.active = false
            if _ev.loopThread then pcall(task.cancel, _ev.loopThread); _ev.loopThread = nil end
            if _ev.charConn then pcall(function() _ev.charConn:Disconnect() end); _ev.charConn = nil end
            if _ev.wowAutoEnabled and _G._wowToggleRef then
                _ev.wowAutoEnabled = false
                pcall(function() _G._wowToggleRef:SetValue(false) end)
            end
            local char = LocalPlayer.Character
            _setAnchored(char, false)
            if _ev.origCF and char then char:PivotTo(_ev.origCF) end
            _ev.origCF, _ev.curCF, _ev.curEventName, _ev.curIsGlacial = nil, nil, nil, false
        end
        local function _startEvent()
            if _ev.active then _stopEvent() end
            if #_ev.selectedEvents == 0 and not _ev.priorityEvent then return false end
            _ev.active = true
            _ev.origCF, _ev.curCF, _ev.curEventName, _ev.curIsGlacial = nil, nil, nil, false
            _ev.loopThread = task.spawn(function()
                while _ev.active do
                    if _totemSpawning then task.wait(2); continue end
                    if _G._treasureHuntBusy then task.wait(1); continue end
                    if _tpPriority.yields("event") then task.wait(1); continue end
                    local ok, err = pcall(function()
                        local activeNames = _activeEventNames()
                        local foundCF, isGlacial, foundName
                        local candidates = {}
                        if _ev.priorityEvent then candidates[#candidates + 1] = _ev.priorityEvent end
                        for _, name in ipairs(_ev.selectedEvents) do candidates[#candidates + 1] = name end
                        for _, name in ipairs(candidates) do
                            if activeNames[name] then
                                local cf, glacial = _findEventCFrame(name)
                                if cf then foundCF, isGlacial, foundName = cf, glacial, name; break end
                            end
                        end
                        local char = LocalPlayer.Character
                        local root = _root(char)
                        if foundCF and root then
                            if _ev.curEventName ~= foundName then
                                _setAnchored(char, false)
                                _ev.curCF, _ev.curEventName, _ev.curIsGlacial = nil, foundName, isGlacial
                            end
                            if not _ev.origCF then _ev.origCF = root.CFrame end
                            if (root.Position - foundCF.Position).Magnitude > 40 then
                                local target = _raised(foundCF)
                                _ev.curCF   = target
                                root.CFrame = target
                                _setAnchored(char, true)
                                task.delay(3, function()
                                    if char and char.Parent then _setAnchored(char, false) end
                                end)
                            end
                        elseif not foundCF and _ev.curCF and root then
                            _setAnchored(char, false)
                            if _ev.origCF then char:PivotTo(_ev.origCF); _ev.origCF = nil end
                            _ev.curCF, _ev.curEventName, _ev.curIsGlacial = nil, nil, false
                        end
                    end)
                    if not ok then warn("[Auto Event Teleport] " .. tostring(err)) end
                    task.wait(1)
                end
                local char = LocalPlayer.Character
                _setAnchored(char, false)
                if _ev.origCF and char then char:PivotTo(_ev.origCF) end
                _ev.origCF, _ev.curCF, _ev.curEventName, _ev.curIsGlacial = nil, nil, nil, false
            end)
            if _ev.charConn then pcall(function() _ev.charConn:Disconnect() end) end
            _ev.charConn = LocalPlayer.CharacterAdded:Connect(function(char)
                if not _ev.active then return end
                task.spawn(function()
                    local root = char:WaitForChild("HumanoidRootPart", 5)
                    task.wait(0.3)
                    if not root then return end
                    if _ev.curCF then
                        if _ev.curIsGlacial then
                            root.CFrame = _ev.curCF
                        else
                            char:PivotTo(_ev.curCF)
                            _float(char, root)
                        end
                    elseif _ev.origCF then
                        char:PivotTo(_ev.origCF)
                        _float(char, root)
                    end
                end)
            end)
            if _G._wowToggleRef and not _G._wowToggleRef:GetValue() then
                _ev.wowAutoEnabled = true
                pcall(function() _G._wowToggleRef:SetValue(true) end)
            end
            return true
        end
        _ev.start, _ev.stop = _startEvent, _stopEvent
        _tpPriority.eventActive = function()
            if not _ev.active then return false end
            local activeNames = _activeEventNames()
            if _ev.priorityEvent and activeNames[_ev.priorityEvent] then return true end
            for _, name in ipairs(_ev.selectedEvents) do
                if activeNames[name] then return true end
            end
            return false
        end
        local EventSection = TeleportTab:AddSection("Event Teleport", false)
        local _dropRef, _toggleRef, _priorityDropRef
        local _syncing = false
        local function _setToggle(value)
            if not _toggleRef then return end
            _syncing = true
            pcall(function() _toggleRef:SetValue(value) end)
            _syncing = false
        end
        local function _restart()
            _stopEvent()
            task.wait(0.1)
            _startEvent()
        end
        local function _refreshDropdown(silent)
            local names = _eventList()
            if _dropRef and _dropRef.Refresh then
                local keep = {}
                for _, sel in ipairs(_ev.selectedEvents) do
                    for _, name in ipairs(names) do
                        if name == sel then keep[#keep + 1] = name; break end
                    end
                end
                _dropRef:Refresh(names, #keep == 0)
                if #keep > 0 then pcall(function() _dropRef:SetValue(keep) end) end
            end
            if _priorityDropRef and _priorityDropRef.Refresh then
                local keep
                if _ev.priorityEvent then
                    for _, name in ipairs(names) do
                        if name == _ev.priorityEvent then keep = name; break end
                    end
                end
                _priorityDropRef:Refresh(names, keep == nil)
                if keep then pcall(function() _priorityDropRef:SetValue(keep) end) end
            end
            if not silent then
                _notify("Event Scan", "Ditemukan " .. #names .. " event.")
            end
        end
        _dropRef = EventSection:AddDropdown({
            Title    = "Select Event",
            Options  = _eventList(),
            Default  = nil,
            Multi    = true,
            Callback = function(selected)
                _ev.selectedEvents = type(selected) == "table" and selected or (selected and { selected } or {})
                if _toggleRef and _toggleRef:GetValue() and #_ev.selectedEvents > 0 then _restart() end
            end,
        })
        _priorityDropRef = EventSection:AddDropdown({
            Title    = "Priority Event",
            Options  = _eventList(),
            Default  = nil,
            Multi    = false,
            Callback = function(selected)
                _ev.priorityEvent = (selected and selected ~= "") and selected or nil
                if _toggleRef and _toggleRef:GetValue() then _restart() end
            end,
        })
        EventSection:AddButton({
            Title    = "Refresh Event List",
            Callback = function() _refreshDropdown(false) end,
        })
        _toggleRef = EventSection:AddToggle({
            Title    = "Auto Event Teleport",
            Default  = false,
            Callback = function(on)
                if _syncing then return end
                if not on then
                    _stopEvent()
                    _notify("Auto Teleport", "Auto teleport dimatikan.")
                    return
                end
                if #_ev.selectedEvents == 0 then
                    _notify("Auto Teleport", "Pilih event terlebih dahulu!")
                    _setToggle(false)
                    return
                end
                if _startEvent() then
                    _notify("Auto Teleport", "Monitoring " .. #_ev.selectedEvents .. " event...")
                else
                    _notify("Auto Teleport", "Gagal start. Pilih event lagi.")
                    _setToggle(false)
                end
            end,
        })
        if _evReplion then
            _evReplion:OnChange("Events", inScriptContext(function()
                if not _ev.active then _refreshDropdown(true) end
            end))
        end
        _ev.refreshThread = task.spawn(function()
            task.wait(3)
            _refreshDropdown(true)
            while task.wait(120) do
                if not _ev.active then _refreshDropdown(true) end
            end
        end)
    end
    do
        local TRENCH_COORDS = {
            ["Mutation Vents"]  = { pos = Vector3.new(-9112.335,  -91.770, -1639.629), look = Vector3.new(-9116.346,  -91.770, -1648.789) },
            ["Lucky Abyss"]     = { pos = Vector3.new(-9132.198, -269.540,   813.391), look = Vector3.new(-9126.932, -269.540,   804.890) },
            ["Rushing Current"] = { pos = Vector3.new(-9687.612,  -74.279, -1779.643), look = Vector3.new(-9685.838,  -74.279, -1789.484) },
            ["Titan Pressure"]  = { pos = Vector3.new(-9867.534,  -84.105, -1188.156), look = Vector3.new(-9871.007,  -84.105, -1197.534) },
            ["Shiny Abyss"]     = { pos = Vector3.new(-9729.081, -269.540,   810.506), look = Vector3.new(-9725.213, -269.540,   819.728) },
            ["Lucky Volcano"]   = { pos = Vector3.new(-8569.072,  -69.104,  -424.655), look = Vector3.new(-8560.575,  -69.104,  -429.927) },
            ["Silent Reach"]    = { pos = Vector3.new(-10021.376, -72.101,   178.305), look = Vector3.new(-10017.688, -72.101,   169.009) },
        }
        local STAY_RADIUS = 40
        local Replion = cachedRequire(ReplicatedStorage.Packages.Replion)
        local S = { enabled = false, thread = nil, conns = {}, origCF = nil, targetCF = nil, chunk = nil }
        local TrenchSection = TeleportTab:AddSection("Teleport Active Trench", false)
        local function stopLoop()
            S.enabled = false
            if S.thread then pcall(task.cancel, S.thread); S.thread = nil end
            for _, c in ipairs(S.conns) do pcall(function() c:Disconnect() end) end
            table.clear(S.conns)
        end
        local function returnToOrigin()
            local cf = S.origCF
            S.origCF, S.targetCF, S.chunk = nil, nil, nil
            if cf then _teleportTo(cf) end
        end
        TrenchSection:AddToggle({
            Title    = "Enable Auto Teleport Active Trench",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                if not on then
                    stopLoop()
                    returnToOrigin()
                    _notify("Trench Teleport", "Stopped. Kembali ke posisi awal.")
                    return
                end
                S.enabled = true
                S.thread = task.spawn(function()
                    local replion
                    pcall(function() replion = Replion.Client:WaitReplion("MarianaTrench") end)
                    if not replion then
                        _notify("Trench Teleport", "Gagal konek ke Replion MarianaTrench.")
                        S.enabled = false
                        return
                    end
                    local function apply(chunkName, state)
                        if not S.enabled then return end
                        if state ~= "Open" or not chunkName then
                            if S.chunk then returnToOrigin() end
                            return
                        end
                        local coords = TRENCH_COORDS[chunkName]
                        if not coords then return end
                        if not S.origCF then
                            local root = _root()
                            if root then S.origCF = root.CFrame end
                        end
                        S.chunk    = chunkName
                        S.targetCF = CFrame.lookAt(coords.pos, coords.look)
                        task.wait(0.5)
                        _teleportTo(S.targetCF)
                    end
                    apply(replion:Get("ActiveAreaChunkName"), replion:Get("State"))
                    S.conns[#S.conns + 1] = replion:OnChange("ActiveVariationId", inScriptContext(function()
                        apply(replion:Get("ActiveAreaChunkName"), replion:Get("State"))
                    end))
                    S.conns[#S.conns + 1] = replion:OnChange("State", inScriptContext(function(newState)
                        apply(replion:Get("ActiveAreaChunkName"), newState)
                    end))
                    _notify("Trench Teleport", "Aktif! Memantau Mariana Trench...")
                    while S.enabled do
                        local root = _root()
                        if root and S.targetCF and (root.Position - S.targetCF.Position).Magnitude > STAY_RADIUS then
                            _teleportTo(S.targetCF)
                        end
                        task.wait(1)
                    end
                end)
            end,
        })
    end
    do
        local ELEMENTAL_COORDS = {
            ["Storm Elemental Event"]    = { pos = Vector3.new(-864.196,   56.557, 5305.733), look = Vector3.new(-874.166,   56.557, 5306.503) },
            ["Volcano Elemental Event"]  = { pos = Vector3.new(-820.989,   59.866, 5286.726), look = Vector3.new(-812.566,   59.866, 5292.116) },
            ["Blizzard Elemental Event"] = { pos = Vector3.new(-1051.939, 124.593, 5532.032), look = Vector3.new(-1048.086, 124.593, 5522.804) },
        }
        local ELEMENTAL_OPTIONS = { "Storm Elemental Event", "Volcano Elemental Event", "Blizzard Elemental Event" }
        local STAY_RADIUS, SETTLE_DELAY, WATCH_STEP = 40, 0.5, 1
        local Replion = cachedRequire(ReplicatedStorage.Packages.Replion)
        local S = { running = false, thread = nil, conns = {}, originCF = nil, activeEvent = nil, targetCF = nil, applying = false }
        local selected, syncing = {}, false
        local dropRef, toggleRef
        local ElementalSection = TeleportTab:AddSection("Teleport Elemental Zone", false)
        local function setToggle(value)
            if not toggleRef then return end
            syncing = true
            pcall(function() toggleRef:SetValue(value) end)
            syncing = false
        end
        local function selectedSet()
            local set = {}
            for _, name in ipairs(selected) do set[name] = true end
            return set
        end
        local function returnToOrigin()
            local cf = S.originCF
            S.originCF, S.activeEvent, S.targetCF, S.applying = nil, nil, nil, false
            if cf then _teleportTo(cf) end
        end
        local function stopLoop()
            S.running = false
            for _, c in ipairs(S.conns) do pcall(function() c:Disconnect() end) end
            table.clear(S.conns)
            if S.thread then pcall(task.cancel, S.thread); S.thread = nil end
        end
        local function applyEvent(eventName)
            if not S.running or S.applying then return end
            if not selectedSet()[eventName] then return end
            if _tpPriority.yields("elemental") then return end
            local coords = ELEMENTAL_COORDS[eventName]
            if not coords then return end
            S.applying = true
            if not S.originCF then
                local root = _root()
                if root then S.originCF = root.CFrame end
            end
            S.activeEvent = eventName
            S.targetCF    = CFrame.lookAt(coords.pos, coords.look)
            task.wait(SETTLE_DELAY)
            if S.running then _teleportTo(S.targetCF) end
            S.applying = false
        end
        local function startLoop()
            if S.running then return true end
            if #selected == 0 then return false end
            S.running = true
            S.thread = task.spawn(function()
                local replion
                pcall(function() replion = Replion.Client:WaitReplion("Events") end)
                if not replion then
                    S.running = false
                    _notify("Elemental Teleport", "Gagal konek ke Replion Events.")
                    setToggle(false)
                    return
                end
                local active = replion:Get("Events")
                if type(active) == "table" then
                    local set = selectedSet()
                    for _, eventName in ipairs(active) do
                        if set[eventName] and ELEMENTAL_COORDS[eventName] then
                            applyEvent(eventName)
                            break
                        end
                    end
                end
                S.conns[#S.conns + 1] = replion:OnArrayInsert("Events", inScriptContext(function(_, eventName)
                    if S.running then task.spawn(applyEvent, eventName) end
                end))
                S.conns[#S.conns + 1] = replion:OnArrayRemove("Events", inScriptContext(function(_, eventName)
                    if S.running and ELEMENTAL_COORDS[eventName] and S.activeEvent == eventName then
                        task.spawn(returnToOrigin)
                    end
                end))
                _notify("Elemental Teleport", "Aktif! Memantau " .. #selected .. " Elemental Event...")
                while S.running do
                    if _tpPriority.yields("elemental") then
                        task.wait(WATCH_STEP)
                        continue
                    end
                    if not S.applying and S.targetCF then
                        local root = _root()
                        if root and (root.Position - S.targetCF.Position).Magnitude > STAY_RADIUS then
                            _teleportTo(S.targetCF)
                        end
                    elseif not S.applying and not S.targetCF then
                        local live = replion:Get("Events")
                        if type(live) == "table" then
                            local set = selectedSet()
                            for _, eventName in ipairs(live) do
                                if set[eventName] and ELEMENTAL_COORDS[eventName] then
                                    task.spawn(applyEvent, eventName)
                                    break
                                end
                            end
                        end
                    end
                    task.wait(WATCH_STEP)
                end
            end)
            return true
        end
        dropRef = ElementalSection:AddDropdown({
            Title    = "Pilih Elemental Event",
            Options  = ELEMENTAL_OPTIONS,
            Default  = ELEMENTAL_OPTIONS,
            Multi    = true,
            Callback = function(list)
                selected = type(list) == "table" and list or {}
                if not (toggleRef and toggleRef:GetValue()) then return end
                if #selected > 0 then
                    stopLoop()
                    returnToOrigin()
                    task.wait(0.1)
                    startLoop()
                else
                    stopLoop()
                    returnToOrigin()
                    setToggle(false)
                    _notify("Elemental Teleport", "Tidak ada event terpilih — dimatikan.")
                end
            end,
        })
        _tpPriority.elementalActive = function()
            if not S.running then return false end
            local rep = Replion and Replion.Client:GetReplion("Events")
            if not rep then return false end
            local live = rep:Get("Events")
            if type(live) ~= "table" then return false end
            local set = selectedSet()
            for _, eventName in ipairs(live) do
                if set[eventName] and ELEMENTAL_COORDS[eventName] then return true end
            end
            return false
        end
        toggleRef = ElementalSection:AddToggle({
            Title    = "Enable Auto Teleport Elemental Zone",
            Default  = false,
            Callback = function(on)
                if syncing then return end
                if not on then
                    stopLoop()
                    returnToOrigin()
                    _notify("Elemental Teleport", "Stopped. Kembali ke posisi awal.")
                    return
                end
                if #selected == 0 and dropRef and dropRef.GetValue then
                    local v = dropRef:GetValue()
                    if type(v) == "table" then selected = v end
                end
                if #selected == 0 then
                    setToggle(false)
                    _notify("Elemental Teleport", "Pilih minimal 1 Elemental Event dulu!")
                    return
                end
                if not startLoop() then
                    setToggle(false)
                    _notify("Elemental Teleport", "Gagal start. Coba lagi.")
                end
            end,
        })
    end
    do
        local PrioritySection = TeleportTab:AddSection("Priority Settings", false)
        PrioritySection:AddParagraph({
            Title   = "Cara Kerja",
            Content = "Menentukan fitur mana yang menang kalau <b>Event Teleport</b> dan "
                .. "<b>Teleport Elemental Zone</b> sama-sama menyala dan sama-sama punya event aktif.\n"
                .. "Tanpa ini keduanya saling tarik tiap detik, jadi teleportnya bolak-balik.\n\n"
                .. "Yang mengalah cuma <b>diam di tempat</b>, tidak pulang ke posisi awal — jadi "
                .. "begitu event pemenangnya selesai, ia langsung menarik balik ke event-nya sendiri.\n"
                .. "<i>Contoh: sedang di Megalodon Hunt, lalu Elemental Event mulai → pindah ke Elemental. "
                .. "Begitu Elemental selesai → balik lagi ke Megalodon Hunt.</i>",
        })
        local statusPara = PrioritySection:AddParagraph({
            Title   = "Status",
            Content = "Prioritas: <b>Elemental Zone</b>\nMenunggu salah satu fitur dinyalakan...",
        })
        local watchThread = nil
        local function stopWatch()
            if watchThread then pcall(task.cancel, watchThread); watchThread = nil end
        end
        local function startWatch()
            if watchThread then return end
            watchThread = task.spawn(function()
                while _tpPriority.mode == "Elemental Zone" or _tpPriority.mode == "Event Teleport" do
                    local function probe(fn)
                        if type(fn) ~= "function" then return false end
                        local ok, v = pcall(fn)
                        return ok and v == true
                    end
                    local evOn   = probe(_tpPriority.eventActive)
                    local elemOn = probe(_tpPriority.elementalActive)
                    local line
                    if not evOn and not elemOn then
                        line = "Tidak ada event aktif dari kedua fitur."
                    elseif evOn and not elemOn then
                        line = "Event Teleport sedang berjalan (tidak ada Elemental aktif)."
                    elseif elemOn and not evOn then
                        line = "Elemental Zone sedang berjalan (tidak ada Event aktif)."
                    else
                        line = ("Keduanya aktif — <b>%s</b> yang dipakai, satunya menunggu."):format(_tpPriority.mode)
                    end
                    pcall(function()
                        statusPara:SetContent(("Prioritas: <b>%s</b>\n%s"):format(_tpPriority.mode, line))
                    end)
                    task.wait((evOn or elemOn) and 1 or 5)
                end
                watchThread = nil
                pcall(function() statusPara:SetContent("Off — keduanya jalan sendiri-sendiri.") end)
            end)
        end
        startWatch()
        PrioritySection:AddDropdown({
            Title    = "Prioritaskan",
            Options  = { "Off", "Elemental Zone", "Event Teleport" },
            Default  = "Elemental Zone",
            Callback = function(choice)
                if choice ~= "Elemental Zone" and choice ~= "Event Teleport" then choice = "Off" end
                _tpPriority.mode = choice
                if choice == "Off" then
                    stopWatch()
                    pcall(function() statusPara:SetContent("Off — keduanya jalan sendiri-sendiri.") end)
                else
                    startWatch()
                end
                Library:MakeNotify({
                    Title       = "Priority Settings",
                    Description = choice == "Off"
                        and "Prioritas dimatikan — kedua fitur jalan sendiri-sendiri."
                        or  ("Prioritas: " .. choice),
                    Delay = 3,
                })
            end,
        })
    end
    do
        local PlazaSection = TeleportTab:AddSection("Plaza Teleport", false)
        local function plazaButton(title, placeId)
            PlazaSection:AddButton({
                Title    = title,
                Callback = function()
                    pcall(function() NetEvents.RE_TradePlazaTeleport:FireServer(placeId) end)
                end,
            })
        end
        plazaButton("Teleport ke Trade Plaza",       79378095465365)
        plazaButton("Teleport ke Trade Plaza (Alt)", 82602826017494)
    end
    do
        local NpcSection = TeleportTab:AddSection("Teleport to NPC", false)
        local _list, _selected, _dropRef = {}, nil, nil
        local function _refresh()
            table.clear(_list)
            local folder = workspace:FindFirstChild("NPC")
            if folder then
                for _, npc in ipairs(folder:GetChildren()) do
                    if npc:IsA("Model") then _list[#_list + 1] = npc.Name end
                end
                table.sort(_list)
            end
            if _dropRef and _dropRef.SetOptions then _dropRef:SetOptions(_list) end
            return #_list
        end
        _dropRef = NpcSection:AddDropdown({
            Title    = "Pilih NPC",
            Options  = {},
            Default  = "",
            Callback = function(val) _selected = val end,
        })
        NpcSection:AddButton({
            Title    = "Teleport to NPC",
            Callback = function()
                if #_list == 0 then _refresh() end
                if not _selected or _selected == "" then
                    _notify("NPC TP", "Pilih NPC dulu!")
                    return
                end
                local folder = workspace:FindFirstChild("NPC")
                local npc = folder and folder:FindFirstChild(_selected)
                if not npc then
                    _notify("NPC TP", "NPC tidak ditemukan!")
                    return
                end
                local ok, pivot = pcall(function() return npc:GetPivot() end)
                if ok and pivot then _teleportTo(pivot * CFrame.new(0, 0, 3)) end
            end,
        })
        NpcSection:AddButton({
            Title    = "Refresh List",
            Callback = function()
                _notify("NPC TP", ("Ditemukan %d NPC"):format(_refresh()))
            end,
        })
        task.spawn(function() task.wait(2); _refresh() end)
    end
end
-- [Shop Tab]
task.wait()
do
    local _shopItemUtil, _shopReplion
    local function _getItemUtility()
        if not _shopItemUtil then
            pcall(function() _shopItemUtil = cachedRequire(ReplicatedStorage.Shared.ItemUtility) end)
        end
        return _shopItemUtil
    end
    local function _getReplionData()
        if not _shopReplion then
            pcall(function() _shopReplion = getCachedReplionData() end)
        end
        return _shopReplion
    end
    local ItemUtility = setmetatable({}, { __index = function(_, k)
        local u = _getItemUtility(); return u and u[k]
    end })
    local ReplionData = setmetatable({}, { __index = function(_, k)
        local r = _getReplionData(); if not r then return nil end
        local v = r[k]
        if type(v) == "function" then return function(_, ...) return v(r, ...) end end
        return v
    end })
    local ShopTab            = MainWindow:AddTab({ Name = "Shop", Icon = "cart" })
    do
        local SellSection = ShopTab:AddSection("Auto Sell")
        local _sellState  = { enabled = false, mode = "Timer", interval = 5, target = 235, lastSell = 0, timerTask = nil, countTask = nil, countConn = nil }
        local function getSellAllRemote()
            return NetEvents.RF_SellAllItems
        end
        local function parseNumber(text)
            if not text or text == "" then return 0 end
            local cleaned = tostring(text):gsub("%D", "")
            return tonumber(cleaned == "" and "0" or cleaned) or 0
        end
        local function getBagLabel()
            local gui = LocalPlayer:FindFirstChild("PlayerGui")
            if not gui then return nil end
            local inv = gui:FindFirstChild("Inventory")
            if not inv then return nil end
            local direct = inv:FindFirstChild("Main")
                and inv.Main:FindFirstChild("Top")
                and inv.Main.Top:FindFirstChild("Options")
                and inv.Main.Top.Options:FindFirstChild("Fish")
                and inv.Main.Top.Options.Fish:FindFirstChild("Label")
                and inv.Main.Top.Options.Fish.Label:FindFirstChild("BagSize")
            if direct and direct:IsA("TextLabel") then return direct end
            return inv:FindFirstChild("BagSize", true)
        end
        local function executeSellAll()
            local remote = getSellAllRemote()
            if not remote then return end
            if tick() - _sellState.lastSell < 0.5 then return end
            pcall(function() remote:InvokeServer() end)
            _sellState.lastSell = tick()
        end
        local function stopSellLoops()
            if _sellState.timerTask then task.cancel(_sellState.timerTask); _sellState.timerTask = nil end
            if _sellState.countTask then task.cancel(_sellState.countTask); _sellState.countTask = nil end
            if _sellState.countConn then _sellState.countConn:Disconnect(); _sellState.countConn = nil end
        end
        local function startSellLoop()
            stopSellLoops()
            if _sellState.mode == "Timer" then
                _sellState.timerTask = task.spawn(function()
                    while _sellState.enabled do
                        task.wait(_sellState.interval)
                        if _sellState.enabled then executeSellAll() end
                    end
                end)
            else
                local function attachCountWatcher()
                    local label = getBagLabel()
                    if not label then
                        _sellState.countTask = task.spawn(function()
                            while _sellState.enabled do
                                task.wait(1)
                                local lbl = getBagLabel()
                                if lbl then
                                    local current = parseNumber(lbl.Text:match("(.+)%/"))
                                    if current >= _sellState.target then
                                        executeSellAll()
                                    end
                                    if _sellState.countConn then _sellState.countConn:Disconnect() end
                                    _sellState.countConn = lbl:GetPropertyChangedSignal("Text"):Connect(function()
                                        if not _sellState.enabled then return end
                                        local count = parseNumber(lbl.Text:match("(.+)%/"))
                                        if count >= _sellState.target then
                                            executeSellAll()
                                        end
                                    end)
                                    break
                                end
                            end
                        end)
                        return
                    end
                    local current = parseNumber(label.Text:match("(.+)%/"))
                    if current >= _sellState.target then
                        executeSellAll()
                    end
                    _sellState.countConn = label:GetPropertyChangedSignal("Text"):Connect(function()
                        if not _sellState.enabled then return end
                        local count = parseNumber(label.Text:match("(.+)%/"))
                        if count >= _sellState.target then
                            executeSellAll()
                        end
                    end)
                end
                attachCountWatcher()
            end
        end
        SellSection:AddButton({ Title = "Sell All Now", Callback = executeSellAll })
        SellSection:AddDropdown({
            Title    = "Auto Sell Mode",
            Options  = {"Timer", "By Count"},
            Default  = "Timer",
            Callback = function(selected)
                _sellState.mode = selected
                if _sellState.enabled then startSellLoop() end
            end,
        })
        SellSection:AddInput({
            Title    = "Value (Seconds / Fish Count)",
            Default  = "5",
            Callback = function(value)
                local n = tonumber(value)
                if n and n >= 1 then
                    _sellState.interval = n
                    _sellState.target   = n
                    if _sellState.enabled and _sellState.mode ~= "Timer" then
                        startSellLoop()
                    end
                end
            end,
        })
        SellSection:AddToggle({
            Title    = "Enable Auto Sell",
            Default  = false,
            Callback = function(on)
                _sellState.enabled = on
                if on then
                    if not getSellAllRemote() then _sellState.enabled = false; return end
                    startSellLoop()
                else
                    stopSellLoops()
                end
            end,
        })
    end
    do
        local _weatherState = { enabled = false, selected = {}, task = nil, cooldownNotified = {} }
        local function getWeatherOptions()
            local ok, Events = pcall(function()
                return require(game.ReplicatedStorage.Events)
            end)
            if not ok or type(Events) ~= "table" then return {} end
            local options = {}
            for name, data in pairs(Events) do
                if type(data) == "table" and data.WeatherMachine and data.WeatherMachinePrice then
                    table.insert(options, name)
                end
            end
            table.sort(options)
            return options
        end
        local WeatherSection = ShopTab:AddSection("Buy Weather", false)
        WeatherSection:AddDropdown({
            Title    = "Weather",
            Multi    = true,
            Options  = getWeatherOptions(),
            Default  = {},
            Callback = function(selected)
                _weatherState.selected = type(selected) == "table" and selected or {}
            end,
        })
        WeatherSection:AddToggle({
            Title    = "Enable Auto Buy Weather",
            Default  = false,
            Callback = function(on)
                _weatherState.enabled = on
                if _weatherState.task then
                    pcall(task.cancel, _weatherState.task)
                    _weatherState.task = nil
                end
                if not on then
                    _weatherState.cooldownNotified = {}
                    Library:MakeNotify({ Title = "Auto Buy Weather", Description = "Stopped.", Delay = 2 })
                    return
                end
                if #_weatherState.selected == 0 then
                    _weatherState.enabled = false
                    Library:MakeNotify({ Title = "Auto Buy Weather", Description = "Pilih cuaca dulu.", Delay = 3 })
                    return
                end
                _weatherState.task = task.spawn(function()
                    local Replion = require(game.ReplicatedStorage.Packages.Replion)
                    local eventsReplion = Replion.Client:WaitReplion("Events")
                    local dataReplion = Replion.Client:WaitReplion("Data")
                    local remote = NetEvents.RF_PurchaseWeatherEvent
                    Library:MakeNotify({ Title = "Auto Buy Weather", Description = "Active!", Delay = 2 })
                    while _weatherState.enabled do
                        local qok, currentQueue = pcall(function()
                            return eventsReplion:Get("WeatherMachine") or {}
                        end)
                        if qok then
                            local slotsUsed = #currentQueue
                            for _, weather in ipairs(_weatherState.selected) do
                                if not _weatherState.enabled then break end
                                if slotsUsed >= 3 then break end
                                local alreadyActive = eventsReplion:Find("Events", weather)
                                local alreadyQueued = eventsReplion:Find("WeatherMachine", weather)
                                local cooldownEnd = nil
                                pcall(function()
                                    local cooldowns = dataReplion:Get("WeatherCooldown") or {}
                                    cooldownEnd = cooldowns[weather]
                                end)
                                local onCooldown = cooldownEnd and DateTime.now().UnixTimestamp < cooldownEnd
                                if onCooldown then
                                    if not _weatherState.cooldownNotified[weather] then
                                        local remaining = math.ceil((cooldownEnd - DateTime.now().UnixTimestamp) / 60)
                                        Library:MakeNotify({
                                            Title = weather,
                                            Description = "Cooldown: " .. remaining .. " menit lagi",
                                            Delay = 3,
                                        })
                                        _weatherState.cooldownNotified[weather] = true
                                    end
                                else
                                    _weatherState.cooldownNotified[weather] = nil
                                end
                                if not alreadyActive and not alreadyQueued and not onCooldown then
                                    local success, result = pcall(function()
                                        return remote:InvokeServer(weather)
                                    end)
                                    if success and result then
                                        slotsUsed = slotsUsed + 1
                                        _weatherState.cooldownNotified[weather] = nil
                                        Library:MakeNotify({
                                            Title = "Auto Buy Weather",
                                            Description = weather .. " berhasil diaktifkan!",
                                            Delay = 3,
                                        })
                                    end
                                    task.wait(1)
                                end
                            end
                        end
                        task.wait(15)
                    end
                end)
            end,
        })
    end
    do
        local BMSection = ShopTab:AddSection("Buy Black Market", false)
        local BUY_DELAY, STUCK_LIMIT, IDLE_WAIT, RETURN_HOLD = 0.3, 8, 5, 0.5
        local _bm = {
            enabled = false, thread = nil, buying = false,
            snapConn = nil, frozen = nil, homeCF = nil,
            replion = nil, data = nil, coinPath = nil,
        }
        local itemNames, itemByName, selected = {}, {}, {}
        local dropdownRef, toggleRef
        local statusParagraph = BMSection:AddParagraph({ Title = "Status", Content = "Idle" })
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Auto Buy BM", Description = desc, Delay = delay or 2 })
        end
        local function setStatus(content, title)
            pcall(function()
                statusParagraph:SetTitle(title or "Status")
                statusParagraph:SetContent(content)
            end)
        end
        local function config()
            return cachedRequire(ReplicatedStorage.Shared.BlackMarketConfig)
        end
        local function loadItems()
            table.clear(itemNames)
            table.clear(itemByName)
            pcall(function()
                for _, item in ipairs(config().GetItems()) do
                    local name = item.DisplayName or item.Id
                    if name and not itemByName[name] then
                        itemByName[name] = item
                        table.insert(itemNames, name)
                    end
                end
            end)
            return #itemNames
        end
        loadItems()
        local function ensureReplion()
            if _bm.replion and _bm.data and _bm.coinPath then return true end
            pcall(function()
                local Replion  = cachedRequire(ReplicatedStorage.Packages.Replion)
                local Currency = cachedRequire(ReplicatedStorage.Modules.CurrencyUtility)
                _bm.replion  = Replion.Client:WaitReplion(config().ChannelName)
                _bm.data     = Replion.Client:WaitReplion("Data")
                _bm.coinPath = Currency:GetCurrency("Coins").Path
            end)
            return _bm.replion ~= nil and _bm.data ~= nil
        end
        local function getStock(itemId)
            if not _bm.replion then return 0 end
            local ok, items = pcall(function() return _bm.replion:Get("Items") end)
            if not ok or type(items) ~= "table" then return 0 end
            local entry = items[itemId]
            return (entry and entry.Stock) or 0
        end
        local function canAfford(item)
            if not item or not item.Price then return true end
            if not (_bm.data and _bm.coinPath) then return true end
            local ok, coins = pcall(function() return _bm.data:Get(_bm.coinPath) end)
            if not ok or type(coins) ~= "number" then return true end
            return coins >= item.Price
        end
        local function alreadyOwned(item)
            if not (item and item.SingleCopy and _bm.data) then return false end
            local reward = item.RewardInfo
            if not reward or reward.Type == "Currency" then return false end
            local ok, owned = pcall(function()
                local ItemUtility       = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
                local InventoryMapping  = cachedRequire(ReplicatedStorage.Shared.InventoryMapping)
                local itemData = ItemUtility.GetItemDataFromItemType(reward.Type, reward.Identifier)
                if not itemData then return false end
                local inventory = _bm.data:Get("Inventory")
                local bucket = inventory and inventory[InventoryMapping[itemData.Data.Type] or "Items"]
                for _, entry in ipairs(bucket or {}) do
                    if entry.Id == itemData.Data.Id then return true end
                end
                return false
            end)
            return ok and owned
        end
        local function findDealer()
            local cfg = config()
            local ok, container = pcall(function()
                return workspace[cfg.WorldSetupFolderName][cfg.MapsFolderName][cfg.DealerContainerName]
            end)
            if not ok or not container then return nil end
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            local best, bestDist
            for _, part in ipairs(container:GetChildren()) do
                if part:IsA("BasePart") and part.Name == cfg.DealerName then
                    local dist = hrp and (part.Position - hrp.Position).Magnitude or 0
                    if not best or dist < bestDist then best, bestDist = part, dist end
                end
            end
            return best
        end
        local function pinTo(hrp, cf)
            if not (hrp and hrp.Parent and cf) then return end
            hrp.CFrame                  = cf
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
        local function freezeChar(targetCF)
            if _bm.frozen then return end
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if hum then
                _bm.frozen = { hum = hum, walk = hum.WalkSpeed, jump = hum.JumpPower }
                pcall(function()
                    hum.WalkSpeed, hum.JumpPower = 0, 0
                    hum:ChangeState(Enum.HumanoidStateType.Physics)
                end)
            end
            pcall(pinTo, hrp, targetCF)
            if _bm.snapConn then pcall(function() _bm.snapConn:Disconnect() end) end
            _bm.snapConn = RunService.Heartbeat:Connect((function()
                pcall(pinTo, hrp, targetCF)
            end))
        end
        local function unfreezeChar(returnCF)
            if _bm.snapConn then
                pcall(function() _bm.snapConn:Disconnect() end)
                _bm.snapConn = nil
            end
            local frozen = _bm.frozen
            _bm.frozen = nil
            if frozen and frozen.hum and frozen.hum.Parent then
                pcall(function()
                    frozen.hum.WalkSpeed = frozen.walk
                    frozen.hum.JumpPower = frozen.jump
                    frozen.hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end)
            end
            if not returnCF then return end
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            local deadline = os.clock() + RETURN_HOLD
            while hrp and os.clock() < deadline do
                pcall(pinTo, hrp, returnCF)
                RunService.Heartbeat:Wait()
            end
        end
        local function buyOne(name, item)
            local char   = LocalPlayer.Character
            local hrp    = char and char:FindFirstChild("HumanoidRootPart")
            local origCF = hrp and hrp.CFrame or nil
            local dealer = findDealer()
            _bm.buying = true
            _bm.homeCF = origCF
            freezeChar(dealer and (dealer.CFrame * CFrame.new(0, 0, -3)) or origCF)
            task.wait(0.3)
            local bought, stuck = 0, 0
            while _bm.enabled and getStock(item.Id) > 0 do
                if not canAfford(item) then
                    stuck += 1
                    setStatus(("Coin kurang — timeout %ds..."):format(STUCK_LIMIT - stuck))
                    task.wait(1)
                    if stuck >= STUCK_LIMIT then break end
                    continue
                end
                local ok, result = pcall(function()
                    return NetEvents.RF_PurchaseBlackMarketItem:InvokeServer(item.Id)
                end)
                if ok and result and result.Success then
                    bought += 1
                    stuck = 0
                    setStatus(("Dibeli x%d %s — sisa: %d"):format(bought, name, getStock(item.Id)))
                    if item.SingleCopy then break end
                    task.wait(BUY_DELAY)
                else
                    stuck += 1
                    setStatus(("Server reject — retry... (%ds)"):format(STUCK_LIMIT - stuck))
                    task.wait(1)
                    if stuck >= STUCK_LIMIT then break end
                end
            end
            _bm.buying = false
            unfreezeChar(origCF)
            _bm.homeCF = nil
            if bought > 0 then notify(("Dibeli x%d %s!"):format(bought, name), 3) end
            return bought
        end
        local function isBuyable(item)
            return item and not alreadyOwned(item) and getStock(item.Id) > 0 and canAfford(item)
        end
        local function hasAnyBuyable()
            for _, name in ipairs(selected) do
                if isBuyable(itemByName[name]) then return true end
            end
            return false
        end
        local function waitForRestock()
            if not _bm.replion then
                task.wait(10)
                return
            end
            local resumed = false
            local conn = _bm.replion:OnChange("Items", inScriptContext(function(newItems)
                if resumed or not _bm.enabled or type(newItems) ~= "table" then return end
                for _, name in ipairs(selected) do
                    local item = itemByName[name]
                    local entry = item and newItems[item.Id]
                    if entry and (entry.Stock or 0) > 0 then
                        resumed = true
                        return
                    end
                end
            end))
            while _bm.enabled and not resumed do task.wait(1) end
            pcall(function() conn:Disconnect() end)
        end
        dropdownRef = BMSection:AddDropdown({
            Title    = "Select Item",
            Multi    = true,
            Options  = itemNames,
            Default  = {},
            NoSave   = true,
            Callback = function(value)
                selected = type(value) == "table" and value or {}
            end,
        })
        BMSection:AddButton({
            Title    = "Refresh Item List",
            Callback = function()
                selected = {}
                local count = loadItems()
                pcall(function() dropdownRef:SetOptions(itemNames) end)
                notify(("List diperbarui: %d item."):format(count))
            end,
        })
        toggleRef = BMSection:AddToggle({
            Title    = "Auto Buy Black Market",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _bm.enabled = on
                if _bm.thread then pcall(task.cancel, _bm.thread); _bm.thread = nil end
                if not on then
                    _bm.buying = false
                    local home = _bm.homeCF
                    _bm.homeCF = nil
                    task.spawn(function() unfreezeChar(home) end)
                    setStatus("Idle")
                    notify("Stopped.")
                    return
                end
                if #selected == 0 then
                    _bm.enabled = false
                    setStatus("Pilih item dulu!")
                    notify("Pilih item dulu!")
                    task.defer(function() pcall(function() toggleRef:SetValue(false) end) end)
                    return
                end
                if not ensureReplion() then
                    _bm.enabled = false
                    setStatus("Gagal konek Replion.")
                    notify("Gagal konek Replion, coba lagi.", 3)
                    task.defer(function() pcall(function() toggleRef:SetValue(false) end) end)
                    return
                end
                notify("Active!")
                _bm.thread = task.spawn(function()
                    while _bm.enabled do
                        local anyBuyable = false
                        for _, name in ipairs(selected) do
                            if not _bm.enabled then break end
                            local item = itemByName[name]
                            if item then
                                if alreadyOwned(item) then
                                    setStatus(name .. " sudah dimiliki — skip.")
                                elseif getStock(item.Id) <= 0 then
                                    setStatus(name .. " — out of stock, skip.")
                                elseif not canAfford(item) then
                                    setStatus(name .. " — coin kurang, skip.")
                                else
                                    anyBuyable = true
                                    setStatus(("Stock: %d — Beli %s..."):format(getStock(item.Id), name))
                                    buyOne(name, item)
                                    task.wait(0.5)
                                end
                            end
                        end
                        if not _bm.enabled then break end
                        if not anyBuyable and not hasAnyBuyable() then
                            setStatus("Semua item out of stock — nunggu restock...")
                            waitForRestock()
                        else
                            task.wait(IDLE_WAIT)
                        end
                    end
                end)
            end,
        })
    end
    do
        local SellEquipSection = ShopTab:AddSection("Auto Sell Equipment")
        local EQUIP_FLAG       = "Select_Equipment"
        local SELL_INTERVAL    = 0.2
        local EXCLUDED_ITEMS   = { ["Withering Core"] = true, ["Tribunal Withering Core"] = true }
        local PLACEHOLDERS     = { ["Klik Refresh List"] = true, ["No Sellable Item"] = true }
        local _equipSell       = { enabled = false, task = nil, selected = {}, savedLoaded = false }
        local _vendorUtil, _soldTypes
        local function getVendorRefs()
            if not _vendorUtil then
                pcall(function() _vendorUtil = cachedRequire(ReplicatedStorage.Shared.VendorUtility) end)
            end
            if not _soldTypes then
                pcall(function() _soldTypes = cachedRequire(ReplicatedStorage.Shared.SoldItemTypes) end)
            end
            return _vendorUtil ~= nil and type(_soldTypes) == "table"
        end
        local function isSellable(entry, item)
            local data = entry and entry.Data
            if not data or data.Type == "Fish" or not table.find(_soldTypes, data.Type) then return false end
            if EXCLUDED_ITEMS[data.DisplayName or data.Name] then return false end
            local ok, price = pcall(function() return _vendorUtil:GetSellPrice(item) end)
            return ok and price ~= nil
        end
        local function buildEquipList()
            local list, seen = {}, {}
            if getVendorRefs() then
                pcall(function()
                    for _, item in ipairs(ReplionData:GetExpect({ "Inventory", "Items" })) do
                        if not item.Favorited then
                            local entry = ItemUtility:GetItemData(item.Id)
                            local data  = entry and entry.Data
                            local name  = data and (data.DisplayName or data.Name)
                            if name and not seen[name] and isSellable(entry, item) then
                                seen[name] = true
                                list[#list + 1] = name
                            end
                        end
                    end
                end)
            end
            for name in pairs(_equipSell.selected) do
                if not seen[name] then
                    seen[name] = true
                    list[#list + 1] = name
                end
            end
            table.sort(list)
            return list
        end
        local function loadSavedSelection()
            if _equipSell.savedLoaded then return end
            _equipSell.savedLoaded = true
            if next(_equipSell.selected) then return end
            local saved = Library.ConfigSystem.Get("MultiDropdowns." .. EQUIP_FLAG, {})
            if type(saved) ~= "table" then return end
            for _, v in ipairs(saved) do
                if type(v) == "string" and not PLACEHOLDERS[v] and not EXCLUDED_ITEMS[v] then
                    _equipSell.selected[v] = true
                end
            end
        end
        local function refreshEquipList()
            loadSavedSelection()
            local list = buildEquipList()
            local flag = Library.flags and Library.flags[EQUIP_FLAG]
            if flag and flag.SetValues then
                local selectedList = {}
                for name in pairs(_equipSell.selected) do selectedList[#selectedList + 1] = name end
                pcall(function() flag:SetValues(#list > 0 and list or { "No Sellable Item" }, selectedList) end)
            end
            return #list
        end
        local function sellSelected()
            local sellRemote = NetEvents.RF_SellItem
            if not sellRemote or not next(_equipSell.selected) or not getVendorRefs() then return end
            pcall(function()
                local targets = {}
                for _, item in ipairs(ReplionData:GetExpect({ "Inventory", "Items" })) do
                    if not item.Favorited then
                        local entry = ItemUtility:GetItemData(item.Id)
                        local data  = entry and entry.Data
                        local name  = data and (data.DisplayName or data.Name)
                        if name and _equipSell.selected[name] and isSellable(entry, item) then
                            targets[#targets + 1] = item.UUID
                        end
                    end
                end
                for _, uuid in ipairs(targets) do
                    pcall(function() sellRemote:InvokeServer(uuid) end)
                    task.wait(0.1)
                end
            end)
        end
        SellEquipSection:AddDropdown({
            Title    = "Select Equipment",
            Multi    = true,
            Options  = { "Klik Refresh List" },
            Default  = {},
            Callback = function(selected)
                local set = {}
                if type(selected) == "table" then
                    for _, v in ipairs(selected) do
                        if not PLACEHOLDERS[v] then set[v] = true end
                    end
                end
                _equipSell.selected = set
            end,
        })
        SellEquipSection:AddButton({
            Title    = "Refresh Equipment List",
            Callback = function()
                local count = refreshEquipList()
                Library:MakeNotify({
                    Title       = "Auto Sell Equipment",
                    Description = count > 0 and ("List diperbarui: %d item."):format(count) or "Tidak ada item yang bisa dijual.",
                    Delay       = 2,
                })
            end,
        })
        SellEquipSection:AddToggle({
            Title    = "Enable Auto Sell Equipment",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                if on then
                    if _equipSell.enabled then return end
                    if not NetEvents.RF_SellItem or not ReplionData or not ItemUtility then return end
                    loadSavedSelection()
                    _equipSell.enabled = true
                    _equipSell.task = task.spawn(function()
                        while _equipSell.enabled do
                            sellSelected()
                            task.wait(SELL_INTERVAL)
                        end
                    end)
                else
                    _equipSell.enabled = false
                    if _equipSell.task then
                        task.cancel(_equipSell.task)
                        _equipSell.task = nil
                    end
                end
            end,
        })
    end
    do
        local BattlepassShop  = cachedRequire(ReplicatedStorage.Shared.BattlepassShop)
        local CurrencyUtility = cachedRequire(ReplicatedStorage.Modules.CurrencyUtility)
        local REWARDS  = (BattlepassShop and BattlepassShop.Rewards) or {}
        local CURRENCY = (BattlepassShop and BattlepassShop.CurrencyName) or "Coins"
        local _evShop  = { enabled = false, thread = nil }
        local coinPath
        pcall(function() coinPath = CurrencyUtility:GetCurrency(CURRENCY).Path end)
        local Section = ShopTab:AddSection("Buy Event Shop", false)
        local statusPara = Section:AddParagraph({ Title = "Status", Content = "Idle" })
        local function setStatus(text)
            pcall(function() statusPara:SetContent(text) end)
        end
        Section:AddParagraph({
            Title   = "Info",
            Content = ("Beli semua item Event Shop pakai %s otomatis, berurutan (aturan game)."):format(CURRENCY),
        })
        local function claimedSet(data)
            local ok, got = pcall(function() return data:Get(BattlepassShop.DataPath) end)
            return (ok and type(got) == "table") and got or {}
        end
        local function buyLoop()
            while _evShop.enabled do
                local data = getCachedReplionData()
                if not data then
                    setStatus("Nunggu data player...")
                else
                    local got, nextIdx = claimedSet(data), nil
                    for i = 1, #REWARDS do
                        if got[tostring(i)] ~= true then nextIdx = i; break end
                    end
                    if not nextIdx then
                        setStatus("Semua item sudah dibeli.")
                        break
                    else
                        local reward = REWARDS[nextIdx]
                        local okBal, have = pcall(function() return data:Get(coinPath) end)
                        have = (okBal and tonumber(have)) or 0
                        if have >= reward.RequiredCoins then
                            setStatus(("Membeli #%d %s (%d %s)..."):format(nextIdx, tostring(reward.DisplayName), reward.RequiredCoins, CURRENCY))
                            pcall(function() NetEvents.RE_BPPurchaseRequest:FireServer(nextIdx) end)
                            local t0 = os.clock()
                            repeat task.wait(0.2)
                            until not _evShop.enabled or claimedSet(data)[tostring(nextIdx)] == true or os.clock() - t0 > 5
                            if _evShop.enabled and claimedSet(data)[tostring(nextIdx)] ~= true then
                                setStatus(("Pembelian #%d belum diterima server, dicoba lagi..."):format(nextIdx))
                            end
                        else
                            setStatus(("Nunggu %s...\nItem #%d %s: %d / %d (kurang %d)"):format(
                                CURRENCY, nextIdx, tostring(reward.DisplayName), have, reward.RequiredCoins, reward.RequiredCoins - have))
                        end
                    end
                end
                task.wait(1)
            end
        end
        Section:AddToggle({
            Title    = "Auto Buy Event Shop",
            Default  = false,
            Callback = function(on)
                _evShop.enabled = on
                if _evShop.thread then
                    pcall(task.cancel, _evShop.thread)
                    _evShop.thread = nil
                end
                if not on then
                    setStatus("Idle")
                    Library:MakeNotify({ Title = "Event Shop", Description = "Dihentikan.", Delay = 2 })
                    return
                end
                if #REWARDS == 0 or not coinPath then
                    setStatus("Data Event Shop tidak ketemu di game.")
                    return
                end
                Library:MakeNotify({ Title = "Event Shop", Description = "Aktif!", Delay = 2 })
                _evShop.thread = task.spawn(buyLoop)
            end,
        })
    end
    do
        local MerchantSection = ShopTab:AddSection("Remote Merchant")
        local PlayerGui       = LocalPlayer:FindFirstChild("PlayerGui")
        MerchantSection:AddButton({
            Title    = "Open Merchant",
            Callback = function()
                pcall(function()
                    local gui      = PlayerGui or LocalPlayer:WaitForChild("PlayerGui", 5)
                    local merchant = gui and (gui:FindFirstChild("Merchant") or gui:WaitForChild("Merchant", 3))
                    if merchant then merchant.Enabled = true end
                end)
            end,
        })
        MerchantSection:AddButton({
            Title    = "Close Merchant",
            Callback = function()
                pcall(function()
                    local gui      = PlayerGui or LocalPlayer:FindFirstChild("PlayerGui")
                    local merchant = gui and gui:FindFirstChild("Merchant")
                    if merchant then merchant.Enabled = false end
                end)
            end,
        })
    end
    do
        local MerchantSection = ShopTab:AddSection("Buy Merchant", false)
        local BUY_DELAY, RETRY_DELAY, MAX_FAIL = 0.3, 2, 5
        local _mb = {
            enabled = false, thread = nil, conn = nil, busy = false,
            item = nil, amount = 1, bought = 0, data = nil, merch = nil,
        }
        local itemNames, itemByName = {}, {}
        do
            local MarketItemData  = cachedRequire(ReplicatedStorage.Shared.MarketItemData)
            local MarketItemUtil  = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
            local CurrencyUtility = cachedRequire(ReplicatedStorage.Modules.CurrencyUtility)
            for _, market in ipairs(MarketItemData or {}) do
                if not market.SkinCrate and not market.ProductId and market.Price and market.Currency then
                    local itemData = MarketItemUtil.GetItemDataFromItemType(market.Type, market.Identifier)
                    local currency = CurrencyUtility:GetCurrency(market.Currency)
                    if itemData and currency then
                        local name = (itemData.Data and itemData.Data.Name) or ("Item #" .. tostring(market.Id))
                        if not itemByName[name] then
                            itemByName[name] = { id = market.Id, name = name, price = market.Price, path = currency.Path }
                            table.insert(itemNames, name)
                        end
                    end
                end
            end
            table.sort(itemNames)
        end
        local toggleRef
        local statusParagraph = MerchantSection:AddParagraph({
            Title   = "Status",
            Content = "Item   : -\nMode   : Idle\nDibeli : 0 / 0",
        })
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Auto Buy Merchant", Description = desc, Delay = delay or 3 })
        end
        local function setStatus(mode)
            pcall(function()
                statusParagraph:SetContent(("Item   : %s\nMode   : %s\nDibeli : %d / %d"):format(
                    _mb.item and _mb.item.name or "-", mode, _mb.bought, _mb.amount))
            end)
        end
        local function ensureReplion()
            if _mb.data and _mb.merch then return true end
            pcall(function()
                local Replion = cachedRequire(ReplicatedStorage.Packages.Replion)
                _mb.data  = Replion.Client:WaitReplion("Data")
                _mb.merch = Replion.Client:WaitReplion("Merchant")
            end)
            return _mb.data ~= nil and _mb.merch ~= nil
        end
        local function inMerchant(item)
            local ok, items = pcall(function() return _mb.merch:GetExpect("Items") end)
            if not ok or type(items) ~= "table" then return false end
            for _, id in ipairs(items) do
                if id == item.id then return true end
            end
            return false
        end
        local function balanceOf(item)
            local ok, value = pcall(function() return _mb.data:Get(item.path) end)
            return (ok and value) or 0
        end
        local function buyLoop()
            local item = _mb.item
            if _mb.busy or not item or not _mb.enabled then return end
            _mb.busy = true
            if not inMerchant(item) then
                setStatus("Idle - Nunggu Item Muncul")
                _mb.busy = false
                return
            end
            setStatus("Membeli...")
            local fails = 0
            while _mb.enabled and _mb.bought < _mb.amount do
                if balanceOf(item) < item.price then
                    setStatus("Idle - Saldo Kurang")
                    break
                end
                local ok, result = pcall(function()
                    return NetEvents.RF_PurchaseMarketItem:InvokeServer(item.id)
                end)
                if ok and result then
                    _mb.bought += 1
                    fails = 0
                    setStatus("Membeli...")
                    task.wait(BUY_DELAY)
                else
                    fails += 1
                    if fails >= MAX_FAIL then
                        setStatus("Idle - Gagal Beli")
                        break
                    end
                    task.wait(RETRY_DELAY)
                end
            end
            if _mb.bought >= _mb.amount then
                _mb.bought = 0
                setStatus("Idle - Nunggu Refresh Harian")
            end
            _mb.busy = false
        end
        _mb.item = itemNames[1] and itemByName[itemNames[1]] or nil
        MerchantSection:AddDropdown({
            Title    = "Pilih Item",
            Options  = itemNames,
            Default  = itemNames[1],
            NoSave   = true,
            Callback = function(selected)
                local name  = type(selected) == "table" and selected[1] or selected
                local entry = itemByName[name]
                if not entry then return end
                _mb.item, _mb.bought = entry, 0
                setStatus("Idle")
            end,
        })
        MerchantSection:AddInput({
            Title    = "Jumlah Beli",
            Default  = "1",
            Numeric  = true,
            NoSave   = true,
            Callback = function(value)
                local n = tonumber(value)
                if n and n >= 1 then
                    _mb.amount = math.floor(n)
                    setStatus("Idle")
                end
            end,
        })
        toggleRef = MerchantSection:AddToggle({
            Title    = "Auto Buy (Idle & Watch)",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _mb.enabled = on
                if _mb.thread then pcall(task.cancel, _mb.thread); _mb.thread = nil end
                if _mb.conn then pcall(function() _mb.conn:Disconnect() end); _mb.conn = nil end
                _mb.busy = false
                if not on then
                    setStatus("Idle")
                    notify(("Dihentikan. Total dibeli: %d"):format(_mb.bought))
                    return
                end
                local function abort(reason)
                    _mb.enabled = false
                    notify(reason)
                    task.defer(function() pcall(function() toggleRef:SetValue(false) end) end)
                end
                if not _mb.item then return abort("Pilih item dari dropdown dulu!") end
                if not ensureReplion() then return abort("Gagal konek Replion, coba lagi.") end
                _mb.bought = 0
                notify("Aktif! Idle watch mode nyala.")
                _mb.conn = _mb.merch:OnChange("Items", inScriptContext(function()
                    if not _mb.enabled or _mb.busy then return end
                    task.spawn(function()
                        task.wait(1)
                        buyLoop()
                    end)
                end))
                _mb.thread = task.spawn(buyLoop)
                return
            end,
        })
        setStatus("Idle")
    end
    do
        local BuyRodSection = ShopTab:AddSection("Buy Rod")
        local _buyRodState  = { selectedName = nil, selectedId = nil }
        local rodNames, rodLookup, rodLoaded = {}, {}, false
        local function loadRods()
            if rodLoaded then return end
            rodLoaded = true
            pcall(function()
                local rods = ItemUtility:GetFishingRods()
                for _, rod in ipairs(rods) do
                    local price = rod.Price or 0
                    if price >= 1 and not rod.LinkedGamePass then
                        local name = rod.Data.Name
                        table.insert(rodNames, name)
                        rodLookup[name] = { Id = rod.Data.Id, Price = price }
                    end
                end
                table.sort(rodNames, function(a, b)
                    return (rodLookup[a].Price) < (rodLookup[b].Price)
                end)
            end)
            if rodNames[1] then
                _buyRodState.selectedName = rodNames[1]
                local d = rodLookup[rodNames[1]]
                if d then _buyRodState.selectedId = d.Id end
            end
        end
        loadRods()
        BuyRodSection:AddDropdown({
            Title    = "Select Rod",
            Options  = rodNames,
            Default  = nil,
            Callback = function(value)
                loadRods()
                _buyRodState.selectedName = value
                local d = rodLookup[value]
                if d then _buyRodState.selectedId = d.Id end
            end,
        })
        BuyRodSection:AddButton({
            Title    = "Buy Rod",
            Callback = function()
                loadRods()
                pcall(function()
                    if not _buyRodState.selectedName or not _buyRodState.selectedId then return end
                    local d = rodLookup[_buyRodState.selectedName]
                    if not d then return end
                    local inventory = ReplionData:GetExpect({ "Inventory", "Fishing Rods" })
                    for _, item in ipairs(inventory) do
                        if item.Id == _buyRodState.selectedId then return end
                    end
                    local coins = ReplionData:GetExpect("Coins") or 0
                    if coins < d.Price then return end
                    local success, newItemId = NetEvents.RF_PurchaseFishingRod:InvokeServer(_buyRodState.selectedId)
                    if success and newItemId then
                        NetEvents.RE_EquipItem:FireServer(newItemId, "Fishing Rods")
                    end
                end)
            end,
        })
    end
    do
        local BuyBaitSection = ShopTab:AddSection("Buy Bait")
        local _buyBaitState  = { selectedName = nil, selectedId = nil }
        local baitNames, baitLookup, baitLoaded = {}, {}, false
        local function loadBaits()
            if baitLoaded then return end
            baitLoaded = true
            pcall(function()
                local baits = ItemUtility:GetBaits()
                for _, bait in ipairs(baits) do
                    if not bait.HiddenInShop then
                        local price = bait.Price or 0
                        if price >= 1 and not bait.LinkedGamePass then
                            local name = bait.Data.Name
                            table.insert(baitNames, name)
                            baitLookup[name] = { Id = bait.Data.Id, Price = price }
                        end
                    end
                end
                table.sort(baitNames, function(a, b)
                    return (baitLookup[a].Price) < (baitLookup[b].Price)
                end)
            end)
            if baitNames[1] then
                _buyBaitState.selectedName = baitNames[1]
                local d = baitLookup[baitNames[1]]
                if d then _buyBaitState.selectedId = d.Id end
            end
        end
        loadBaits()
        BuyBaitSection:AddDropdown({
            Title    = "Select Bait",
            Options  = baitNames,
            Default  = nil,
            Callback = function(value)
                loadBaits()
                _buyBaitState.selectedName = value
                local d = baitLookup[value]
                if d then _buyBaitState.selectedId = d.Id end
            end,
        })
        BuyBaitSection:AddButton({
            Title    = "Buy Bait",
            Callback = function()
                loadBaits()
                pcall(function()
                    if not _buyBaitState.selectedName or not _buyBaitState.selectedId then return end
                    local d = baitLookup[_buyBaitState.selectedName]
                    if not d then return end
                    local inventory = ReplionData:GetExpect({ "Inventory", "Baits" })
                    for _, item in ipairs(inventory) do
                        if item.Id == _buyBaitState.selectedId then return end
                    end
                    local coins = ReplionData:GetExpect("Coins") or 0
                    if coins < d.Price then return end
                    local success, newItemId = NetEvents.RF_PurchaseBait:InvokeServer(_buyBaitState.selectedId)
                    if success and newItemId then
                        NetEvents.RE_EquipBait:FireServer(_buyBaitState.selectedId)
                    end
                end)
            end,
        })
    end
end
-- [Automation]
task.wait()
do
    local AutoTab = MainWindow:AddTab({ Name = "Automation", Icon = "next" })
    do
        _G.__LynxAutoIndexGen = (_G.__LynxAutoIndexGen or 0) + 1
        local INDEX_GEN = _G.__LynxAutoIndexGen
        local function isCurrentInstance() return INDEX_GEN == _G.__LynxAutoIndexGen end
        local _index = {
            enabled         = false,
            instant         = true,
            thread          = nil,
            watchdog        = nil,
            beat            = 0,
            statusParagraph = nil,
            excludedTiers   = {},
            castConns       = {},
            autoBuy         = true,
            buyTried        = {},
            eventBlocked    = {},
            caughtConn      = nil, -- plays the catch animation like the other auto fishing features
            unreachable     = {}, -- fish no owned rod can lift; skipped until the feature is restarted
            target          = nil,
            targetCasts     = 0,
        }
        local TARGET_RECHECK = 40 -- casts on one target before picking again
        local AREA_COORDS = {}
        local BLACKLISTED_AREAS = {
            ["Starfall Gardens"] = true,
            ["The Celestarium"]  = true,
            ["Mariana Trench"]   = true,
            ["Throne Room"]      = true,
            ["Arcadia"]          = true,
            ["Invader's Reach"]  = true,
            ["Hallows Eve"]      = true,
            ["The Forgotten Graveyard"] = true,
        }
        local ELEMENTAL_ZONES = {
            ["Elemental Island - Ice Zone"]   = "Elemental Island [Blizzard]",
            ["Elemental Island - Lava Zone"]  = "Elemental Island [Volcano]",
            ["Elemental Island - Storm Zone"] = "Elemental Island [Storm]",
        }
        local function elementalZonesReady()
            for zoneName in pairs(ELEMENTAL_ZONES) do
                if AREA_COORDS[zoneName] then return true end
            end
            return false
        end
        local AREA_SPOT_KEYS = {
            ["Throne Room"] = { "Throne Room (Blizzard)", "Throne Room (Storm)", "Throne Room (Volcano)" },
        }
        local AREA_SPOTS = {}
        local SPOT_ROTATE_AFTER = 90
        task.spawn(function()
            local coords = fetchIslandCoords()
            if not coords then return end
            for k, v in pairs(coords) do
                local areaName = k
                if areaName == "Vulcanic Cavern" then areaName = "Volcanic Cavern" end
                if areaName == "Sawers"           then areaName = "Sewers" end
                if areaName == "Sysiphus Statue"  then areaName = "Sisyphus Statue" end
                if areaName == "Copper Canyon [SPOT 1]" then areaName = "Copper Canyon" end
                AREA_COORDS[areaName] = v
                if areaName == "Weather Machine" then
                    AREA_COORDS["Ocean"] = v
                end
            end
            for zoneName, coordKey in pairs(ELEMENTAL_ZONES) do
                if AREA_COORDS[coordKey] then AREA_COORDS[zoneName] = AREA_COORDS[coordKey] end
            end
            for areaName, keys in pairs(AREA_SPOT_KEYS) do
                local spots = {}
                for _, key in ipairs(keys) do
                    if AREA_COORDS[key] then table.insert(spots, AREA_COORDS[key]) end
                end
                if #spots > 0 then
                    AREA_SPOTS[areaName]  = spots
                    AREA_COORDS[areaName] = AREA_COORDS[areaName] or spots[1]
                end
            end
        end)
        local TIER_NAME_TO_LEVEL = {
            ["Common"] = 1, ["Uncommon"] = 2, ["Rare"] = 3, ["Epic"] = 4,
            ["Legendary"] = 5, ["Mythic"] = 6, ["SECRET"] = 7, ["FORGOTTEN"] = 8,
        }
        local function setStatus(title, content)
            pcall(function()
                _index.statusParagraph:SetTitle(title)
                _index.statusParagraph:SetContent(content)
            end)
        end
        local function notify(desc, delay, title)
            Library:MakeNotify({ Title = title or "Auto Index", Description = desc, Delay = delay or 3 })
        end
        local function liveData()
            local ok, rep = pcall(require, ReplicatedStorage.Packages.Replion)
            if not ok or not rep or not rep.Client then return nil end
            local ok2, data = pcall(function() return rep.Client:GetReplion("Data") end)
            return ok2 and data or nil
        end
        local function liveGet(key)
            local data = liveData()
            if not data then return nil end
            local ok, value = pcall(data.Get, data, key)
            return ok and value or nil
        end
        local function bounded(timeout, fn, ...)
            local args, box = table.pack(...), { done = false }
            task.spawn(function()
                local packed = table.pack(pcall(fn, table.unpack(args, 1, args.n)))
                box.res, box.done = packed, true
            end)
            local deadline = os.clock() + timeout
            while not box.done and os.clock() < deadline do task.wait(0.05) end
            if not box.done then return false end
            return table.unpack(box.res, 1, box.res.n)
        end
        local _originalLuckModifiers, _originalFriendLuck = nil, nil
        local _luckSettingsManaged = false
        local _tunedFor = nil
        local function getLuckSettings()
            local settings = liveGet("Settings") or {}
            local luckMod, friendLuck = settings["Luck Modifiers"], settings["Friend Luck"]
            if luckMod    == nil then luckMod    = true end
            if friendLuck == nil then friendLuck = true end
            return luckMod, friendLuck
        end
        local PSU_TTL = 15
        local _psuCache, _psuAt = nil, 0
        local function setLuckSetting(settingName, value)
            _psuCache = nil
            safeFire(function() NetEvents.RE_ChangeSetting:FireServer(settingName, value) end)
            local t0 = os.clock()
            repeat
                task.wait(0.1)
                local settings = liveGet("Settings") or {}
                if settings[settingName] == value then return true end
            until os.clock() - t0 > 2
            return false
        end
        local function applyLuckSettings(on)
            local luckMod, friendLuck = getLuckSettings()
            local done = true
            if luckMod    ~= on then done = setLuckSetting("Luck Modifiers", on) and done end
            if friendLuck ~= on then done = setLuckSetting("Friend Luck",    on) and done end
            return done
        end
        local function saveOriginalLuckSettings()
            if _luckSettingsManaged then return end
            _originalLuckModifiers, _originalFriendLuck = getLuckSettings()
            _luckSettingsManaged = true
        end
        local function restoreLuckSettings()
            if not _luckSettingsManaged then return end
            local luckMod, friendLuck = getLuckSettings()
            if _originalLuckModifiers ~= nil and luckMod ~= _originalLuckModifiers then
                setLuckSetting("Luck Modifiers", _originalLuckModifiers)
            end
            if _originalFriendLuck ~= nil and friendLuck ~= _originalFriendLuck then
                setLuckSetting("Friend Luck", _originalFriendLuck)
            end
            _luckSettingsManaged   = false
            _originalLuckModifiers = nil
            _originalFriendLuck    = nil
            _tunedFor              = nil
        end
        local function luckCutoff(luck)
            if not luck or luck <= 1 then return 1 end
            if luck >= 1000 then return 0.005 end
            if luck >= 500  then return 0.00625 end
            if luck >= 15   then return 0.0125 end
            if luck >= 6    then return 1 / 60 end
            if luck >= 4    then return 0.02 end
            if luck >= 1.5  then return 1 / math.clamp(math.floor((luck - 1) * 6), 1, 25) end
            return 1
        end
        local function luckBoundFor(chance)
            if not chance or chance <= 0 or chance <= 0.005 then return math.huge end
            if chance <= 0.00625 then return 1000 end
            if chance <= 0.0125  then return 500 end
            if chance <= 1 / 60  then return 15 end
            if chance <= 0.02    then return 6 end
            local steps = math.floor(1 / chance)
            if steps < 3 then return 1.5 end
            return math.min(1 + (steps + 1) / 6, 4)
        end
        local PSU_CHANNELS = { "Data", "Events", "ServerLuck" }
        local function psuLuck(fresh)
            if not fresh and _psuCache and os.clock() - _psuAt < PSU_TTL then return _psuCache end
            local ok, rep = pcall(require, ReplicatedStorage.Packages.Replion)
            if not ok or not rep or not rep.Client then return nil end
            for _, channel in ipairs(PSU_CHANNELS) do
                local okCh, replion = pcall(function() return rep.Client:GetReplion(channel) end)
                if not okCh or not replion then return nil end
            end
            local okMods, mods = pcall(function()
                return require(ReplicatedStorage.Shared.PlayerStatsUtility)
                    :GetPlayerModifiers(LocalPlayer, LocalPlayer:GetAttribute("LocationName"))
            end)
            local luck = okMods and mods and tonumber(mods.BaseLuck) or nil
            if luck then _psuCache, _psuAt = luck, os.clock() end
            return luck
        end
        local LUCK_SLACK = 0.05
        local function rodLuckOf(rodItem, rodData)
            local luck = tonumber(rodData.RollData and rodData.RollData.BaseLuck) or 0
            if rodData.Modifiers and tonumber(rodData.Modifiers.BaseLuck) then
                luck = tonumber(rodData.Modifiers.BaseLuck)
            end
            local meta = rodItem.Metadata and rodItem.Metadata.Modifiers
            if meta and tonumber(meta.BaseLuck) then luck = luck + tonumber(meta.BaseLuck) end
            return luck
        end
        local function baitLuckOf(baitItem, baitData)
            local luck = tonumber(baitData.Modifiers and baitData.Modifiers.BaseLuck) or 0
            local meta = baitItem.Metadata and baitItem.Metadata.Modifiers
            if meta and tonumber(meta.BaseLuck) then luck = tonumber(meta.BaseLuck) end
            return luck
        end
        local function getFishInfo(fishName)
            local ok, result = pcall(function()
                local ItemUtility = require(ReplicatedStorage.Shared.ItemUtility)
                local TierUtility = require(ReplicatedStorage.Shared.TierUtility)
                local itemData    = ItemUtility:GetItemData(fishName)
                if not itemData then return nil end
                local prob = itemData.Probability or itemData.ForcedProbability
                if not prob then return nil end
                local tierData = TierUtility:GetTierFromRarity(prob.Chance)
                local tierName = tierData and tierData.Name or "Common"
                return {
                    name      = fishName,
                    chance    = prob.Chance,
                    tierName  = tierName,
                    tierLevel = TIER_NAME_TO_LEVEL[tierName] or 1,
                    minWeight = itemData.Weight and itemData.Weight.Default and itemData.Weight.Default.Min or 0,
                    luckBound = luckBoundFor(prob.Chance),
                    windows   = itemData.CatchTimeWindows,
                }
            end)
            return ok and result or nil
        end
        local function getInventoryRods()
            local rods = {}
            pcall(function()
                local replionData = liveData()
                if not replionData then return end
                local ItemUtility = require(ReplicatedStorage.Shared.ItemUtility)
                local invRods     = replionData:Get({ "Inventory", "Fishing Rods" })
                if not invRods then return end
                local seenRod = {}
                for key, rodItem in pairs(invRods) do
                    local rodData = nil
                    pcall(function() rodData = ItemUtility.GetItemDataFromItemType("Fishing Rods", rodItem.Id) end)
                    if not rodData or not rodData.MaxWeight then continue end
                    local maxW = rodData.MaxWeight
                    if rodItem.Metadata and rodItem.Metadata.Modifiers and rodItem.Metadata.Modifiers.MaxWeight then
                        maxW = maxW + rodItem.Metadata.Modifiers.MaxWeight
                    end
                    local entry = {
                        uuid      = rodItem.UUID or key,
                        id        = rodItem.Id,
                        name      = (rodData.Data and rodData.Data.Name) or tostring(rodItem.Id),
                        maxWeight = maxW,
                        effLuck   = rodLuckOf(rodItem, rodData),
                    }
                    local prev = seenRod[rodItem.Id]
                    if not prev then
                        seenRod[rodItem.Id] = entry
                        table.insert(rods, entry)
                    elseif entry.effLuck > prev.effLuck or (entry.effLuck == prev.effLuck and entry.maxWeight > prev.maxWeight) then
                        for k, v in pairs(entry) do prev[k] = v end
                    end
                end
            end)
            table.sort(rods, function(a, b)
                if a.effLuck ~= b.effLuck then return a.effLuck < b.effLuck end
                return a.maxWeight < b.maxWeight
            end)
            return rods
        end
        local function getInventoryBaits()
            local baits = {}
            pcall(function()
                local replionData = liveData()
                if not replionData then return end
                local ItemUtility = require(ReplicatedStorage.Shared.ItemUtility)
                local invBaits    = replionData:Get({ "Inventory", "Baits" })
                if not invBaits then return end
                local seenBait = {}
                for key, baitItem in pairs(invBaits) do
                    local baitData = nil
                    pcall(function() baitData = ItemUtility.GetItemDataFromItemType("Baits", baitItem.Id) end)
                    if not baitData then continue end
                    if seenBait[baitItem.Id] then continue end
                    seenBait[baitItem.Id] = true
                    table.insert(baits, {
                        uuid    = baitItem.UUID or key,
                        id      = baitItem.Id,
                        name    = (baitData.Data and baitData.Data.Name) or tostring(baitItem.Id),
                        effLuck = baitLuckOf(baitItem, baitData),
                    })
                end
            end)
            table.sort(baits, function(a, b)
                if a.effLuck ~= b.effLuck then return a.effLuck < b.effLuck end
                return tostring(a.id) < tostring(b.id)
            end)
            return baits
        end
        local function equippedRodUUID()
            local items = liveGet("EquippedItems")
            return items and items[1] or nil
        end
        local function equippedBaitId()
            return liveGet("EquippedBaitId") or 0
        end
        local function equippedGearLuck(allRods, allBaits)
            local luck, rodUUID, baitId = 0, equippedRodUUID(), equippedBaitId()
            for _, rod in ipairs(allRods) do
                if rod.uuid == rodUUID then luck = luck + rod.effLuck; break end
            end
            for _, bait in ipairs(allBaits) do
                if bait.id == baitId then luck = luck + bait.effLuck; break end
            end
            return luck
        end
        local function baseLuckWithoutGear(allRods, allBaits)
            local total = psuLuck()
            return total and total - equippedGearLuck(allRods, allBaits)
        end
        local function lastingLuck(allRods, allBaits)
            local total = psuLuck()
            if not total then return nil end
            local client = require(ReplicatedStorage.Packages.Replion).Client
            local server, events = client:GetReplion("ServerLuck"), client:GetReplion("Events")
            local mult, boost = server and server:Get("ServerMultiplier") or 1, 0
            for _, name in ipairs(events and events:Get("Events") or {}) do
                local event = cachedRequire(ReplicatedStorage.Events)[name]
                boost = boost + (tonumber(event and event.Modifiers and event.Modifiers.BaseLuck) or 0)
            end
            return (mult > 1 and total / mult or total) - boost - equippedGearLuck(allRods, allBaits)
        end
        local function selectGearForFish(fishName, allRods, allBaits, otherLuck)
            if #allRods == 0 then return nil, nil, 0, math.huge, false, 0 end
            local info        = getFishInfo(fishName)
            local bound       = info and info.luckBound or math.huge
            local minWeight   = info and info.minWeight or 0
            local ceiling     = bound - LUCK_SLACK
            local base        = otherLuck or 0
            local baitOptions = #allBaits > 0 and allBaits or { false }
            local bestRod, bestBait, bestLuck
            local lowRod, lowBait, lowLuck
            for _, rod in ipairs(allRods) do
                if minWeight <= 0 or rod.maxWeight >= minWeight then
                    for _, bait in ipairs(baitOptions) do
                        local total = base + rod.effLuck + (bait and bait.effLuck or 0)
                        if total < ceiling and (not bestLuck or total > bestLuck) then
                            bestRod, bestBait, bestLuck = rod, bait or nil, total
                        end
                        if not lowLuck or total < lowLuck then
                            lowRod, lowBait, lowLuck = rod, bait or nil, total
                        end
                    end
                end
            end
            if lowRod and info and info.tierLevel == 1 then
                return lowRod, lowBait, lowLuck, bound, lowLuck < ceiling, lowLuck
            end
            if bestRod then return bestRod, bestBait, bestLuck, bound, true, lowLuck or bestLuck end
            if lowRod then return lowRod, lowBait, lowLuck, bound, false, lowLuck end
            local rod      = allRods[1]
            local fallback = base + rod.effLuck
            return rod, allBaits[1], fallback, bound, false, fallback
        end
        local function canRodHandleFish(rod, fishName)
            if not rod then return false end
            local info = getFishInfo(fishName)
            if not info or info.minWeight <= 0 then return true end
            return rod.maxWeight >= info.minWeight
        end
        local function catchableNow(fishName)
            local info = getFishInfo(fishName)
            local windows = info and info.windows
            if type(windows) ~= "table" or #windows == 0 then return true end
            local hour = workspace:GetAttribute("ClockTime")
            if type(hour) ~= "number" then return true end
            for _, w in ipairs(windows) do
                local from, to = w.StartHour, w.EndHour
                if from and to then
                    if from <= to then
                        if hour >= from and hour < to then return true end
                    elseif hour >= from or hour < to then -- window wraps past midnight
                        return true
                    end
                end
            end
            return false
        end
        local function catchableOf(list)
            local out = {}
            for _, fishName in ipairs(list) do
                if catchableNow(fishName) then table.insert(out, fishName) end
            end
            return out
        end
        local function selectBestTarget(remaining, allRods, allBaits, otherLuck)
            local best, bestTier, bestChance, bestFits = remaining[1], math.huge, -1, false
            for _, fishName in ipairs(remaining) do
                local info = getFishInfo(fishName)
                if info then
                    local rod, _, _, _, fits = selectGearForFish(fishName, allRods, allBaits, otherLuck)
                    local reachable = fits and canRodHandleFish(rod, fishName)
                    if reachable and not bestFits then
                        best, bestTier, bestChance, bestFits = fishName, info.tierLevel, info.chance, true
                    elseif reachable == bestFits then
                        if info.tierLevel < bestTier then
                            best, bestTier, bestChance = fishName, info.tierLevel, info.chance
                        elseif info.tierLevel == bestTier and info.chance > bestChance then
                            best, bestChance = fishName, info.chance
                        end
                    end
                end
            end
            return best
        end
        local function tuneLuckSettings(target, allRods, allBaits, otherLuck, lowestLuck, bound)
            saveOriginalLuckSettings()
            local info   = getFishInfo(target)
            local common = info and info.tierLevel == 1
            if _tunedFor ~= target then
                _tunedFor = target
                if not common and applyLuckSettings(true) then
                    otherLuck = baseLuckWithoutGear(allRods, allBaits) or otherLuck
                    local _, _, _, newBound, _, newLow = selectGearForFish(target, allRods, allBaits, otherLuck)
                    bound, lowestLuck = newBound, newLow
                end
            end
            if common or (bound ~= math.huge and lowestLuck + LUCK_SLACK >= bound) then
                if applyLuckSettings(false) then
                    otherLuck = baseLuckWithoutGear(allRods, allBaits) or otherLuck
                end
            end
            return otherLuck
        end
        local function cancelFishing()
            bounded(5, function() return NetEvents.RF_CancelFishingInputs:InvokeServer() end)
        end
        local function rodInHand() -- a held pickaxe or totem also has the tool model, so check what is actually held
            return liveGet("EquippedType") == "Fishing Rods" and liveGet("EquippedId") == equippedRodUUID()
        end
        local function drawRodFromHotbar()
            if rodInHand() then return true end
            safeFire(function() NetEvents.RF_EquipToolFromHotbar:FireServer(1) end)
            for _ = 1, 8 do
                if rodInHand() then return true end
                task.wait(0.15)
            end
            return false
        end
        local function swapGear(equip, isSet)
            for _ = 1, 4 do
                cancelFishing()
                task.wait(0.2)
                safeFire(equip)
                for _ = 1, 16 do
                    if isSet() then return true end
                    task.wait(0.1)
                end
            end
            return isSet()
        end
        local function ensureGear(rod, bait)
            local needRod  = rod  and equippedRodUUID() ~= rod.uuid
            local needBait = bait and equippedBaitId()  ~= bait.id
            if not (needRod or needBait) then return true end
            _psuCache = nil
            pcall(function() cachedRequire(ReplicatedStorage.Controllers.FishingController):RequestClientStopFishing(true) end)
            if needRod and not swapGear(function() NetEvents.RE_EquipItem:FireServer(rod.uuid, "Fishing Rods") end,
                function() return equippedRodUUID() == rod.uuid end) then
                notify("Rod gagal ganti ke " .. rod.name .. ", dicoba lagi", 2)
                return false
            end
            if needBait and not swapGear(function() NetEvents.RE_EquipBait:FireServer(bait.id) end,
                function() return equippedBaitId() == bait.id end) then
                notify("Bait gagal ganti ke " .. bait.name .. ", dicoba lagi", 2)
                return false
            end
            drawRodFromHotbar()
            return true
        end
        local function chargeRodAwait()
            local t0 = os.clock()
            repeat
                local ok, accepted = safeFire(function()
                    return NetEvents.RF_ChargeFishingRod:InvokeServer(nil, nil, workspace:GetServerTimeNow(), nil)
                end)
                if ok and accepted then return true end
                task.wait(0.05)
            until os.clock() - t0 > 3
            return false
        end
        local function waitReelWindow(mgData, receivedAt)
            local constants   = cachedRequire(ReplicatedStorage.Shared.Constants)
            local clickTiming = constants and constants:GetClickTiming() or 0.19
            local clickPower  = type(mgData) == "table" and tonumber(mgData.FishingClickPower)
            local window = clickPower and math.ceil(1 / math.max(clickPower, 0.001)) * clickTiming or 3.5
            local d = (receivedAt or os.clock()) + window + 0.05 - os.clock()
            if d > 0 then task.wait(d) end
        end
        local function dropCastConns() -- a worker cancelled mid-wait never reaches its own Disconnect
            for _, c in ipairs(_index.castConns) do pcall(function() c:Disconnect() end) end
            table.clear(_index.castConns)
        end
        local function waitCastResult(timeout)
            local result
            dropCastConns()
            _index.castConns[1] = NetEvents.RE_FishCaught.OnClientEvent:Connect(function() result = "caught" end)
            _index.castConns[2] = NetEvents.RE_FishingStopped.OnClientEvent:Connect(function() result = "stopped" end)
            local t0 = os.clock()
            repeat task.wait() until result or os.clock() - t0 > (timeout or 4)
            dropCastConns()
            return result
        end
        local function castingPaused()
            if _index.instant then return false end
            setStatus("Pause", "Instant fishing OFF.\nTeleport, gear, dan scan tetap jalan.")
            task.wait(1)
            return true
        end
        local function doOneCast()
            _index.beat = os.clock()
            if castingPaused() then return "paused" end
            if LocalPlayer:GetAttribute("InCutscene") then task.wait(0.5); return "busy" end
            if not rodInHand() then
                cancelFishing()
                if not drawRodFromHotbar() then task.wait(0.5); return "charge" end
            end
            local okCharge, charged = bounded(6, chargeRodAwait)
            if not (okCharge and charged) then task.wait(0.4); return "charge" end
            local ok, castSuccess, mgData, receivedAt = bounded(15, function()
                local s, d = NetEvents.RF_RequestMinigame:InvokeServer(-1.2, CAST_POWER_NORMAL, workspace:GetServerTimeNow())
                return s, d, os.clock()
            end)
            if not (ok and castSuccess and type(mgData) == "table") then
                cancelFishing()
                task.wait(0.4)
                return "rejected"
            end
            if getgenv()._shouldSkipRarity then
                local skipOk, shouldSkip = pcall(getgenv()._shouldSkipRarity, mgData)
                if skipOk and shouldSkip then
                    cancelFishing()
                    return "skipped"
                end
            end
            waitReelWindow(mgData, receivedAt)
            safeFire(function() NetEvents.RE_FishingCompleted:FireServer() end)
            return waitCastResult() or "timeout"
        end
        local function getCaughtMastery()
            local replionData = liveData()
            if not replionData then return {} end
            return replionData:Get("CaughtFishMastery") or {}
        end
        local function syncRemaining(remaining)
            local cm = getCaughtMastery()
            local stillMissing, caughtList = {}, {}
            for _, fn in ipairs(remaining) do
                if cm[fn] then table.insert(caughtList, fn) else table.insert(stillMissing, fn) end
            end
            return stillMissing, caughtList
        end
        local function teleportTo(coords)
            local char = LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root or not coords then return false end
            cancelFishing()
            root.CFrame = CFrame.lookAt(coords.pos, coords.look)
            root.AssemblyLinearVelocity  = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            task.wait(1)
            return true
        end
        local BAIT_BUDGET = 0.25 -- a bait only speeds things up, so it may take at most this share of the coins
        local EVENT_RETRY = 60   -- seconds before a fish held back by a server event is tried again
        local function ownedIds(list)
            local owned = {}
            for _, item in ipairs(list) do owned[item.id] = true end
            return owned
        end
        local function forSale(d, remote, owned)
            local id = d.Data and d.Data.Id
            return id and d.Price and d.Price > 0 and not (owned[id] or _index.buyTried[remote .. id]
                or d.Hidden or d.HiddenInShop or d.LinkedGamePass or d.EventTag or d.IsSkin)
        end
        local function buyItem(d, remote, getOwned, fishName)
            local id = d.Data.Id
            _index.buyTried[remote .. id] = true
            notify(("Beli %s (%d coin) untuk %s"):format(d.Data.Name, d.Price, fishName), 4)
            bounded(8, function() return NetEvents[remote]:InvokeServer(id) end)
            for _ = 1, 30 do
                if ownedIds(getOwned())[id] then return true end
                task.wait(0.1)
            end
            return false
        end
        local function buyRodFor(fishName, allRods, allBaits, otherLuck)
            if not _index.autoBuy then return false end
            local info, data = getFishInfo(fishName), liveData()
            if not (info and data) then return false end
            local ceiling  = info.luckBound - LUCK_SLACK
            local baitLuck = allBaits[1] and allBaits[1].effLuck or 0
            local owned, best = ownedIds(allRods), nil
            for _, d in ipairs(cachedRequire(ReplicatedStorage.Shared.ItemUtility):GetFishingRods()) do
                if forSale(d, "RF_PurchaseFishingRod", owned) and d.MaxWeight and d.MaxWeight >= info.minWeight
                    and otherLuck + rodLuckOf({}, d) + baitLuck < ceiling
                    and (not best or d.Price < best.Price) then
                    best = d
                end
            end
            if not best or (data:Get("Coins") or 0) < best.Price then return false end
            return buyItem(best, "RF_PurchaseFishingRod", getInventoryRods, fishName)
        end
        local function buyBaitFor(fishName, rod, totalLuck, allBaits, otherLuck)
            if not _index.autoBuy then return false end
            local info, data = getFishInfo(fishName), liveData()
            if not (info and data) or info.tierLevel == 1 then return false end -- Common fish stay on the weakest gear
            local ceiling = info.luckBound - LUCK_SLACK
            local budget  = (data:Get("Coins") or 0) * BAIT_BUDGET
            local owned, best, bestLuck = ownedIds(allBaits), nil, nil
            for _, d in ipairs(cachedRequire(ReplicatedStorage.Shared.ItemUtility):GetBaits()) do
                local luck = tonumber(d.Modifiers and d.Modifiers.BaseLuck)
                if luck and forSale(d, "RF_PurchaseBait", owned) and d.Price <= budget then
                    local total = otherLuck + rod.effLuck + luck
                    if total > totalLuck and total < ceiling and (not best or luck > bestLuck) then
                        best, bestLuck = d, luck
                    end
                end
            end
            return best ~= nil and buyItem(best, "RF_PurchaseBait", getInventoryBaits, fishName)
        end
        local KOHANA, MAGMA, MAGMA_ID = "Kohana Gatekeeper", "Magma Charm", 3
        local function kohanaDone(data)
            local comp = data:Get("CompletedQuests")
            return comp and table.find(comp, KOHANA) ~= nil
        end
        local function kohanaProgress(data) -- { [objective id] = progress } or nil when the quest isn't taken
            local quest = (data:Get({ "Quests", "Mainline" }) or {})[KOHANA]
            if not quest then return nil end
            local progress = {}
            for _, obj in ipairs(quest.Objectives or {}) do progress[obj.Id] = obj.Progress or 0 end
            return progress
        end
        local function acceptKohana(data)
            for _ = 1, 10 do
                if kohanaProgress(data) or kohanaDone(data) then return true end
                pcall(function() NetEvents.RE_DialogueEnded:FireServer("Magma Fisherman", 1, 2) end)
                task.wait(1)
            end
            return kohanaProgress(data) ~= nil
        end
        local function keepMagmaCharm(data) -- cheap to call every cast; only acts once the running charm is used up
            local progress = kohanaProgress(data)
            if (progress and (progress[2] or 0) >= 2) or (not progress and _index.magmaEquipped) then
                _index.magmaEquipped = nil
                if data:Get("EquippedCharmId") == MAGMA_ID then
                    pcall(function() NetEvents.RE_UnequipCharm:FireServer() end)
                end
                return
            end
            if not progress then return end
            if ((data:Get("CharmModifiers") or {})[MAGMA] or 0) > 0 then return end
            local owned = false
            for _, charm in ipairs(data:Get({ "Inventory", "Charms" }) or {}) do
                if charm.Id == MAGMA_ID then owned = true; break end
            end
            if not owned then
                bounded(8, function() return NetEvents.RF_PurchaseCharm:InvokeServer(MAGMA_ID) end)
                task.wait(0.5)
            end
            pcall(function() NetEvents.RE_EquipCharm:FireServer(MAGMA) end)
            _index.magmaEquipped = true
        end
        local function fishArea(missingList, areaName)
            local remaining = {}
            do
                local cm = getCaughtMastery()
                for _, f in ipairs(missingList) do
                    if not cm[f] then table.insert(remaining, f) end
                end
            end
            if #remaining == 0 then return remaining end
            if #getInventoryRods() == 0 then
                notify("Tidak ada Fishing Rod!", 3)
                return remaining
            end
            local spots        = AREA_SPOTS[areaName]
            local spotIndex    = 1
            local lastProgress = os.clock()
            _index.target = nil
            while #remaining > 0 and _index.enabled and isCurrentInstance() do
                _index.beat = os.clock()
                if castingPaused() then continue end
                if _G.AutoMineActive or _G.OrbThrowing or _G._treasureHuntBusy or _totemSpawning then
                    setStatus("Pause - " .. areaName, "Fitur lain sedang memakai karakter, menunggu...")
                    task.wait(1)
                    continue
                end
                local caught
                remaining, caught = syncRemaining(remaining)
                for _, fn in ipairs(caught) do notify("Dapat: " .. fn, 3) end
                if #caught > 0 then lastProgress = os.clock() end
                if #remaining == 0 then break end
                if spots and #spots > 1 and (os.clock() - lastProgress) >= SPOT_ROTATE_AFTER then
                    spotIndex    = spotIndex % #spots + 1
                    lastProgress = os.clock()
                    notify(("Pindah ke spot %d/%d di %s"):format(spotIndex, #spots, areaName), 3)
                end
                local allRods, allBaits = getInventoryRods(), getInventoryBaits()
                if #allRods == 0 then
                    notify("Tidak ada Fishing Rod!", 3)
                    break
                end
                local otherLuck = baseLuckWithoutGear(allRods, allBaits)
                if not otherLuck then
                    setStatus("Fishing - " .. areaName, "Data luck belum siap, menunggu...")
                    task.wait(0.5)
                    continue
                end
                pcall(keepMagmaCharm, liveData()) -- Kohana's charm objective advances with every catch anywhere
                local open = catchableOf(remaining)
                if #open == 0 then
                    notify(("%s: sisa %d ikan belum masuk jam tangkapnya, pindah area."):format(areaName, #remaining), 4)
                    break
                end
                local target = _index.target
                local stillFits = target and select(5, selectGearForFish(target, allRods, allBaits, otherLuck))
                if not (stillFits and table.find(open, target)) or _index.targetCasts >= TARGET_RECHECK then
                    target = selectBestTarget(open, allRods, allBaits, otherLuck)
                    _index.target, _index.targetCasts = target, 0
                end
                local _, _, _, bound, _, lowest = selectGearForFish(target, allRods, allBaits, otherLuck)
                otherLuck = tuneLuckSettings(target, allRods, allBaits, otherLuck, lowest, bound)
                local rod, bait, totalLuck, luckBound, fits = selectGearForFish(target, allRods, allBaits, otherLuck)
                if not (fits and canRodHandleFish(rod, target)) then
                    psuLuck(true) -- this can spend coins or drop the fish, so don't decide on a cached luck
                    otherLuck = baseLuckWithoutGear(allRods, allBaits) or otherLuck
                    rod, bait, totalLuck, luckBound, fits = selectGearForFish(target, allRods, allBaits, otherLuck)
                end
                if not (fits and canRodHandleFish(rod, target)) then
                    local okLuck, lasting = pcall(lastingLuck, allRods, allBaits)
                    lasting = okLuck and lasting or otherLuck
                    if buyRodFor(target, allRods, allBaits, lasting) then continue end
                    if select(5, selectGearForFish(target, allRods, allBaits, lasting)) then
                        notify("Tunda " .. target .. " (luck event server terlalu tinggi)", 3)
                        _index.eventBlocked[target] = os.clock() + EVENT_RETRY
                    else
                        notify("Skip " .. target .. " (tidak ada rod yang cocok)", 3)
                        _index.unreachable[target] = true -- or the next scan sends us back to this area forever
                    end
                    _index.target = nil
                    local nr = {}
                    for _, f in ipairs(remaining) do
                        if f ~= target then table.insert(nr, f) end
                    end
                    remaining = nr
                    continue
                end
                if buyBaitFor(target, rod, totalLuck, allBaits, otherLuck) then continue end
                local coords = (spots and spots[spotIndex]) or AREA_COORDS[areaName]
                if coords then
                    local char = LocalPlayer.Character
                    local root = char and char:FindFirstChild("HumanoidRootPart")
                    if root and (root.Position - coords.pos).Magnitude > 30 then
                        teleportTo(coords)
                        continue
                    end
                end
                if not ensureGear(rod, bait) then
                    task.wait(1)
                    continue
                end
                local info = getFishInfo(target)
                setStatus(
                    spots and string.format("Fishing - %s (spot %d/%d)", areaName, spotIndex, #spots)
                        or string.format("Fishing - %s", areaName),
                    string.format(
                        "Target : %s [%s]\nChance : %.4f%% (1 : %s)\nRod    : %s [W:%.0f L:%.2f]\nBait   : %s [L:%.2f]\nLuck   : %.2f / batas %s\nCutoff : %.5f\nSisa   : %d ikan",
                        target,
                        info and info.tierName or "?",
                        (info and info.chance or 0) * 100,
                        (info and info.chance and info.chance > 0) and string.format("%.0f", 1 / info.chance) or "?",
                        rod and rod.name or "-", rod and rod.maxWeight or 0, rod and rod.effLuck or 0,
                        bait and bait.name or "none", bait and bait.effLuck or 0,
                        totalLuck,
                        luckBound == math.huge and "bebas" or string.format("%.2f", luckBound),
                        luckCutoff(totalLuck + LUCK_SLACK),
                        #remaining
                    )
                )
                local castResult = doOneCast()
                _index.targetCasts += 1
                if castResult == "charge" or castResult == "rejected" or castResult == "timeout" then
                    _index.castMiss = (_index.castMiss or 0) + 1
                    if _index.castMiss >= 8 then
                        _index.castMiss = 0
                        cancelFishing()
                        if clearNetEventsCache then pcall(clearNetEventsCache) end
                        setStatus("Fishing - " .. areaName, "Server tidak merespon, remote di-resolve ulang...")
                        task.wait(2)
                    end
                else
                    _index.castMiss = 0
                end
            end
            cancelFishing()
            remaining = syncRemaining(remaining)
            return remaining
        end
        local function isLavaBasinUnlocked(replionData)
            local unlocked = false
            pcall(function()
                local comp = replionData:Get("CompletedQuests")
                if comp and table.find(comp, "Kohana Gatekeeper") then unlocked = true; return end
                if replionData:Find("Locations", "Lava Basin") ~= nil then unlocked = true end
            end)
            return unlocked
        end
        local VOYAGE = "Voyage" -- the Storm Boat area
        local function atVoyage() return LocalPlayer:GetAttribute("LocationName") == VOYAGE end
        local function questArea(areaData)
            return areaData.Items and not areaData.NoDisplay and not (areaData.Chapter and areaData.Chapter ~= 1)
        end
        local function questProgress()
            local ok, text = pcall(function()
                local data, AreaUtility = liveData(), cachedRequire(ReplicatedStorage.Shared.AreaUtility)
                local seen, have, need = {}, 0, 0
                for areaName, areaData in pairs(cachedRequire(ReplicatedStorage.Areas)) do
                    if questArea(areaData) then
                        local range, names = AreaUtility:GetAreaCompletion(data, areaName, { Chapter = 1 }, true)
                        local dup = 0 -- a fish listed in several areas counts once, as in GetTotalAreaCompletion
                        for _, n in ipairs(names) do if seen[n] then dup += 1 else seen[n] = true end end
                        need += math.max(range.Max - dup, 0)
                        have += math.max(range.Min - dup, 0)
                    end
                end
                return ("Withering Rod Part 1: %d / %d\n"):format(math.min(have, need), need)
            end)
            return ok and text or ""
        end
        local function getMissingFishByArea(excludedTiers)
            local Replion     = require(ReplicatedStorage.Packages.Replion)
            local Areas       = require(ReplicatedStorage.Areas)
            local AreaUtility = require(ReplicatedStorage.Shared.AreaUtility)
            local ItemUtility = require(ReplicatedStorage.Shared.ItemUtility)
            local TierUtility = require(ReplicatedStorage.Shared.TierUtility)
            local replionData = Replion.Client:GetReplion("Data")
            if not replionData then return {} end
            local caughtMastery = replionData:Get("CaughtFishMastery") or {}
            local excludeSet    = {}
            if excludedTiers then
                for _, t in ipairs(excludedTiers) do excludeSet[t] = true end
            end
            local result       = {}
            local skippedAreas = {}
            local extra, fishable, blockedSeen = { blocked = {} }, {}, {}
            for areaName, areaData in pairs(Areas) do
                if not questArea(areaData) then continue end
                if BLACKLISTED_AREAS[areaName] then
                    local ok, _, counted = pcall(AreaUtility.GetAreaCompletion, AreaUtility, replionData, areaName, { Chapter = 1 }, true)
                    for _, fishName in ipairs(ok and counted or {}) do
                        if not caughtMastery[fishName] then blockedSeen[fishName] = areaName end
                    end
                    continue
                end
                if areaName == "Lava Basin" and not isLavaBasinUnlocked(replionData) then
                    table.insert(skippedAreas, areaName)
                    continue
                end
                local ok, _, counted = pcall(AreaUtility.GetAreaCompletion, AreaUtility, replionData, areaName, { Chapter = 1 }, true)
                local missing = {}
                for _, fishName in ipairs(ok and counted or {}) do
                    fishable[fishName] = true
                    local itemData = ItemUtility:GetItemData(fishName)
                    local prob = itemData and itemData.Probability
                    local tierData = prob and TierUtility:GetTierFromRarity(prob.Chance)
                    if tierData and excludeSet[tierData.Name] then continue end
                    if not caughtMastery[fishName] and not _index.unreachable[fishName] and not _index.eventBlocked[fishName] then table.insert(missing, fishName) end
                end
                if #missing > 0 then
                    table.insert(result, {
                        areaName = areaName,
                        missing  = missing,
                        coords   = AREA_COORDS[areaName],
                        order    = areaData.Order or 9999,
                    })
                end
            end
            table.sort(result, function(a, b) return a.order < b.order end)
            table.sort(skippedAreas)
            for _, skipped in ipairs(skippedAreas) do
                notify("Skip " .. skipped .. " (belum unlock, selesaikan quest dulu!)", 4)
            end
            for fishName, areaName in pairs(blockedSeen) do
                if not fishable[fishName] then table.insert(extra.blocked, fishName .. " (" .. areaName .. ")") end
            end
            table.sort(extra.blocked)
            return result, extra
        end
        local function teleportToArea(coords, areaName)
            if not coords then
                if LocalPlayer:GetAttribute("LocationName") == areaName then return true end
                notify("Koordinat " .. areaName .. " tidak ada di database. Harap teleport manual!", 6)
                for _ = 1, 15 do
                    if LocalPlayer:GetAttribute("LocationName") == areaName then return true end
                    task.wait(1)
                end
                return false
            end
            if teleportTo(coords) then
                local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if root and (root.Position - coords.pos).Magnitude <= 700 then return true end
            end
            notify("Teleport gagal ke " .. areaName .. ", retry...", 3)
            return false
        end
        local function runKohanaQuest(data)
            if kohanaDone(data) then return true end
            notify("Kohana Quest untuk unlock Lava Basin...", 3)
            if not acceptKohana(data) then
                notify("Gagal ambil quest Kohana Gatekeeper.", 3, "Kohana Quest")
                return false
            end
            local kvCoords = AREA_COORDS["Kohana Volcano"]
                or { pos = Vector3.new(-552.305, 20.729, 183.195), look = Vector3.new(-604.901, 20.729, 42.719) }
            if not teleportToArea(kvCoords, "Kohana Volcano") then
                notify("Gagal teleport ke Kohana Volcano.", 3, "Kohana Quest")
                return false
            end
            local allRods, allBaits = getInventoryRods(), getInventoryBaits()
            if #allRods > 0 then ensureGear(allRods[#allRods], allBaits[#allBaits]) end -- Blueflame Ray is 1 in 93k
            local lastTurnIn = 0
            while not kohanaDone(data) and _index.enabled and isCurrentInstance() do
                keepMagmaCharm(data)
                local progress = kohanaProgress(data) or {}
                local uses = (data:Get("CharmModifiers") or {})[MAGMA] or 0
                setStatus("Kohana Quest", ("Blueflame Ray: %d/1\nMagma Charm dipakai: %d/2 (sisa pakai charm aktif: %d)")
                    :format(progress[1] or 0, progress[2] or 0, uses))
                if (progress[1] or 0) >= 1 and (progress[2] or 0) >= 2 and os.clock() - lastTurnIn > 10 then
                    lastTurnIn = os.clock() -- objectives met: hand it in at the Magma Fisherman
                    pcall(function() NetEvents.RE_DialogueEnded:FireServer("Magma Fisherman", 1, 2) end)
                end
                doOneCast()
            end
            cancelFishing()
            if kohanaDone(data) then
                notify("Quest Selesai! Lava Basin Terbuka!", 4, "Kohana Quest")
                return true
            end
            return false
        end
        local AutoIndexSection = AutoTab:AddSection("Complete Fish Index [BETA]", false)
        _index.statusParagraph = AutoIndexSection:AddParagraph({ Title = "Status", Content = "Idle" })
        AutoIndexSection:AddParagraph({
            Title   = "Info",
            Content = "FULL AUTO - Teleport, smart gear selection, fishing otomatis!\n"
                .. "- Luck dibaca langsung dari game, bukan taksiran\n"
                .. "- Rod + Bait dipilih pas dengan kelangkaan ikan target\n"
                .. "- Gear dicek ulang sebelum tiap lemparan\n"
                .. "- Auto sell saat inventory penuh | Event fish dilewati",
        })
        AutoIndexSection:AddDropdown({
            Title    = "Exclude Rarity",
            Multi    = true,
            Default  = {},
            Options  = { "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic" }, -- SECRET and up never count
            Callback = function(selected) _index.excludedTiers = selected end,
        })
        AutoIndexSection:AddToggle({
            Title    = "Instant Fishing Index",
            Default  = true,
            Callback = function(on)
                _index.instant = on
                if not on then cancelFishing() end
                Library:MakeNotify({
                    Title       = "Auto Index",
                    Description = on and "Instant fishing ON." or "Instant fishing OFF, mancing dipause.",
                    Delay       = 2,
                })
            end,
        })
        AutoIndexSection:AddToggle({
            Title    = "Auto Buy Rod & Bait",
            Default  = true,
            Callback = function(on) _index.autoBuy = on end,
        })
        AutoIndexSection:AddToggle({
            Title    = "Enable Auto Complete Fish Index",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _index.enabled = on
                _G.AutoIndexActive = on
                if _index.thread then
                    pcall(task.cancel, _index.thread)
                    _index.thread = nil
                end
                if _index.watchdog then
                    pcall(task.cancel, _index.watchdog)
                    _index.watchdog = nil
                end
                dropCastConns()
                table.clear(_index.unreachable)
                table.clear(_index.buyTried)
                table.clear(_index.eventBlocked)
                _index.target = nil
                if _index.caughtConn then _index.caughtConn:Disconnect(); _index.caughtConn = nil end
                if on and onCatchShared then _index.caughtConn = onCatchShared() end
                if not on then
                    cancelFishing()
                    restoreLuckSettings()
                    setStatus("Status", "Idle")
                    notify("Dihentikan.", 2)
                    return
                end
                local function runIndexLoop()
                    local waitStart = os.clock()
                    while next(AREA_COORDS) == nil and os.clock() - waitStart < 15 do task.wait(0.25) end
                    pcall(function()
                        local data = liveData()
                        if data and not isLavaBasinUnlocked(data) and not kohanaDone(data) then acceptKohana(data) end
                    end)
                    while _index.enabled and isCurrentInstance() do
                        for fishName, retryAt in pairs(_index.eventBlocked) do
                            if os.clock() >= retryAt then _index.eventBlocked[fishName] = nil end
                        end
                        local missingAreas = getMissingFishByArea(_index.excludedTiers)
                        if #missingAreas == 0 and next(_index.eventBlocked) then
                            setStatus("Menunggu event", "Sisa ikan butuh luck rendah, menunggu event luck server selesai...")
                            _index.beat = os.clock()
                            task.wait(1)
                            continue
                        end
                        if #missingAreas == 0 then
                            local data = require(ReplicatedStorage.Packages.Replion).Client:GetReplion("Data")
                            if data and not isLavaBasinUnlocked(data) then
                                if runKohanaQuest(data) then continue end
                                setStatus("Berhenti", "Kohana Quest gagal, Lava Basin belum kebuka.\nSelesaikan quest-nya manual lalu nyalakan lagi.")
                                notify("Kohana Quest gagal, fitur dihentikan.", 4)
                                _index.enabled = false
                                break
                            end
                            setStatus("Complete!", "Semua fish index sudah lengkap!")
                            notify("Semua fish index sudah lengkap!", 4)
                            _index.enabled = false
                            break
                        end
                        local totalAreas, areasDone, fishedAny = #missingAreas, 0, false
                        for _, areaInfo in ipairs(missingAreas) do
                            if not (_index.enabled and isCurrentInstance()) then break end
                            if #catchableOf(areaInfo.missing) == 0 then continue end -- every fish here is out of its hours
                            if atVoyage() then continue end
                            fishedAny = true
                            if areaInfo.areaName == "Lava Basin" then
                                local checkData = nil
                                pcall(function() checkData = liveData() end)
                                if checkData and not isLavaBasinUnlocked(checkData) then
                                    notify("Skip Lava Basin (belum unlock)", 4)
                                    continue
                                end
                            end
                            areasDone += 1
                            _index.beat = os.clock()
                            notify(string.format("Menuju: %s (%d ikan) [%d/%d]", areaInfo.areaName, #areaInfo.missing, areasDone, totalAreas), 3)
                            if not teleportToArea(areaInfo.coords, areaInfo.areaName) then
                                notify("Gagal ke " .. areaInfo.areaName .. ", skip.", 4)
                                continue
                            end
                            if not _index.enabled then break end
                            task.wait(2)
                            local remaining = fishArea(areaInfo.missing, areaInfo.areaName)
                            if #remaining == 0 then notify(areaInfo.areaName .. " complete!", 3) end
                            task.wait(1)
                        end
                        if not fishedAny and _index.enabled then
                            if atVoyage() then
                                setStatus("Di Voyage", "Lanjut ke pulau lain setelah Storm Boat kembali.")
                            else
                                setStatus("Menunggu jam", ("Sisa ikan hanya bisa ditangkap di jam tertentu.\nJam game sekarang: %.1f"):format(workspace:GetAttribute("ClockTime") or 0))
                            end
                            for _ = 1, 15 do
                                _index.beat = os.clock()
                                task.wait(1)
                            end
                        end
                    end
                    cancelFishing()
                    restoreLuckSettings()
                    if not _index.enabled then
                        if _index.caughtConn then _index.caughtConn:Disconnect(); _index.caughtConn = nil end
                        _G.AutoIndexActive = false -- finished on its own: let the other fishing loops resume
                        setStatus("Status", "Idle")
                    end
                end
                _index.beat = os.clock()
                _index.thread = task.spawn(runIndexLoop)
                if _index.watchdog then pcall(task.cancel, _index.watchdog) end
                _index.watchdog = task.spawn(function()
                    while _index.enabled and isCurrentInstance() do
                        task.wait(10)
                        if not (_index.enabled and isCurrentInstance()) then break end
                        pcall(function()
                            local worker = _index.thread
                            local dead   = worker == nil or coroutine.status(worker) == "dead"
                            local stale  = os.clock() - (_index.beat or os.clock()) > 90
                            if not (dead or stale) then return end
                            notify(dead and "Loop berhenti sendiri, di-restart." or "Loop macet, di-restart otomatis.", 4)
                            if worker then pcall(task.cancel, worker) end
                            dropCastConns()
                            cancelFishing()
                            _index.castMiss = 0
                            _index.beat     = os.clock()
                            _index.thread   = task.spawn(runIndexLoop)
                        end)
                    end
                    _index.watchdog = nil
                end)
            end,
        })
        AutoIndexSection:AddButton({
            Title    = "Scan Missing Now",
            Callback = function()
                task.spawn(function()
                    local missingAreas, extra = getMissingFishByArea(_index.excludedTiers)
                    extra = extra or { blocked = {} }
                    local progress = questProgress()
                    local lines, totalMissing = {}, 0
                    for _, info in ipairs(missingAreas) do
                        totalMissing += #info.missing
                        table.insert(lines, ("%s (%d): %s"):format(info.areaName, #info.missing, table.concat(info.missing, ", ")))
                    end
                    if #extra.blocked > 0 then
                        table.insert(lines, ("Tidak bisa dipancing (%d): %s"):format(#extra.blocked, table.concat(extra.blocked, ", ")))
                    end
                    if totalMissing == 0 and #extra.blocked == 0 then
                        setStatus("Complete!", progress .. "Semua ikan untuk misi sudah ke-index!")
                        notify("Semua ikan untuk misi Withering Rod Part 1 sudah lengkap!", 3)
                        return
                    end
                    setStatus("Kurang " .. totalMissing .. " ikan", progress .. table.concat(lines, "\n"))
                    notify(totalMissing .. " ikan masih dibutuhkan untuk misi Withering Rod Part 1.", 4)
                end)
            end,
        })
    end
    do
        local TreasureJoinSection = AutoTab:AddSection("Join Treasure Hunt Server", false)
        local COOLDOWN_FAILED, COOLDOWN_FULL, SCAN_INTERVAL, COOLDOWN_WAIT = 120, 30, 3, 10
        local EVENT_NAME = "Treasure Hunt"
        local _tj = { enabled = false, thread = nil, lastJobId = nil, scanning = false, cooldowns = {}, replion = nil }
        local toggleRef
        local statusParagraph = TreasureJoinSection:AddParagraph({
            Title   = "Status",
            Content = "Idle",
        })
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Treasure Hunt", Description = desc, Delay = delay or 3 })
        end
        local function setStatus(title, content)
            pcall(function()
                statusParagraph:SetTitle(title)
                statusParagraph:SetContent(content)
            end)
        end
        local function setToggle(value)
            if not toggleRef then return end
            pcall(function()
                if toggleRef.SetValue then toggleRef:SetValue(value) else toggleRef:Set(value) end
            end)
        end
        local function onCooldown(jobId)
            local expiry = _tj.cooldowns[jobId]
            if not expiry then return false end
            if tick() >= expiry then
                _tj.cooldowns[jobId] = nil
                return false
            end
            return true
        end
        local function setCooldown(jobId, duration)
            _tj.cooldowns[jobId] = tick() + duration
        end
        local function getServers()
            if not _tj.replion then
                local Replion = cachedRequire(ReplicatedStorage.Packages.Replion)
                if not Replion then return nil end
                local ok, rep = pcall(function() return Replion.Client:WaitReplion("ServerBrowser") end)
                _tj.replion = ok and rep or nil
            end
            if not _tj.replion then return nil end
            local ok, servers = pcall(function() return _tj.replion:Get("Servers") end)
            return ok and servers or nil
        end
        local function hasEvent(serverData)
            for _, name in ipairs(serverData and serverData.Events or {}) do
                if name == EVENT_NAME then return true end
            end
            return false
        end
        local function currentServerHasEvent()
            local servers = getServers()
            return servers ~= nil and hasEvent(servers[game.JobId])
        end
        local function findServers()
            local now = tick()
            for jobId, expiry in pairs(_tj.cooldowns) do
                if now >= expiry then _tj.cooldowns[jobId] = nil end
            end
            local servers = getServers()
            if not servers then return {}, 0, 0 end
            local maxPlayers = Players.MaxPlayers
            local candidates, skippedCooldown, skippedFull = {}, 0, 0
            for jobId, serverData in pairs(servers) do
                if jobId ~= game.JobId and hasEvent(serverData) then
                    local players = serverData.Players or 0
                    if players >= maxPlayers then
                        skippedFull += 1
                        if not onCooldown(jobId) then setCooldown(jobId, COOLDOWN_FULL) end
                    elseif onCooldown(jobId) then
                        skippedCooldown += 1
                    else
                        table.insert(candidates, {
                            jobId   = jobId,
                            ping    = serverData.Ping or 9999,
                            players = players,
                            max     = maxPlayers,
                        })
                    end
                end
            end
            table.sort(candidates, function(a, b)
                if a.players ~= b.players then return a.players < b.players end
                return a.ping < b.ping
            end)
            return candidates, skippedCooldown, skippedFull
        end
        local function scan()
            local candidates, skippedCooldown, skippedFull = {}, 0, 0
            pcall(function() candidates, skippedCooldown, skippedFull = findServers() end)
            if candidates[1] then _tj.lastJobId = candidates[1].jobId end
            return candidates, skippedCooldown, skippedFull
        end
        local function describe(candidates, skippedCooldown, skippedFull)
            if #candidates == 0 then
                return "Not Found",
                    ("Tidak ada server tersedia.\n%d cooldown | %d penuh"):format(skippedCooldown, skippedFull)
            end
            local best = candidates[1]
            return ("Found! (%d server)"):format(#candidates),
                ("Terbaik: %d/%d | ping %dms\nSkip cooldown: %d | Skip penuh: %d")
                    :format(best.players, best.max, best.ping, skippedCooldown, skippedFull)
        end
        local function hopTo(jobId)
            sharedQueueAutoExecute(true)
            return (pcall(function() NetEvents.RE_ServerHop:FireServer(jobId) end))
        end
        local function waitCancellable(seconds)
            local waited = 0
            while _tj.enabled and waited < seconds do
                task.wait(1)
                waited += 1
            end
        end
        local function startLoop()
            if _tj.thread then pcall(task.cancel, _tj.thread); _tj.thread = nil end
            _tj.thread = task.spawn(function()
                setStatus("Connecting...", "Menghubungkan ke ServerBrowser...")
                if not getServers() then
                    setStatus("Error", "Gagal akses ServerBrowser Replion.")
                    notify("Gagal akses ServerBrowser!", 4)
                    _tj.enabled = false
                    setToggle(false)
                    return
                end
                while _tj.enabled do
                    if currentServerHasEvent() then
                        setStatus("Active", "Sudah di server Treasure Hunt!\nMenunggu event selesai...")
                        notify("Already on a Treasure Hunt server!")
                        repeat task.wait(5) until not _tj.enabled or not currentServerHasEvent()
                        table.clear(_tj.cooldowns)
                        continue
                    end
                    _tj.scanning = true
                    local candidates, skippedCooldown, skippedFull = scan()
                    _tj.scanning = false
                    if not _tj.enabled then break end
                    if #candidates == 0 then
                        local waitTime = skippedCooldown > 0 and COOLDOWN_WAIT or SCAN_INTERVAL
                        setStatus(("Rescan %ds"):format(waitTime),
                            ("Tidak ada server siap.\n%d cooldown | %d penuh\nRescan dalam %d detik...")
                                :format(skippedCooldown, skippedFull, waitTime))
                        waitCancellable(waitTime)
                        continue
                    end
                    setStatus(describe(candidates, skippedCooldown, skippedFull))
                    notify(#candidates .. " server ditemukan! Mencoba satu per satu...", 2)
                    local joined = false
                    for _, candidate in ipairs(candidates) do
                        if not _tj.enabled then break end
                        if not onCooldown(candidate.jobId) then
                            local shortId = candidate.jobId:sub(1, 8) .. "..."
                            local info    = ("%d/%d | ping %dms"):format(candidate.players, candidate.max, candidate.ping)
                            setStatus("Joining...", shortId .. "\n" .. info)
                            if hopTo(candidate.jobId) then
                                _tj.lastJobId = candidate.jobId
                                notify("Hop -> " .. shortId .. " | " .. info)
                                task.wait(5)
                                if currentServerHasEvent() then
                                    joined = true
                                    break
                                end
                            else
                                notify("Gagal hop -> " .. shortId, 2)
                                task.wait(0.5)
                            end
                            setCooldown(candidate.jobId, COOLDOWN_FAILED)
                        end
                    end
                    if not joined and _tj.enabled then
                        setStatus(("Rescan %ds"):format(SCAN_INTERVAL),
                            ("Semua kandidat dicoba.\n%d masih cooldown.\nRescan dalam %d detik...")
                                :format(skippedCooldown, SCAN_INTERVAL))
                        waitCancellable(SCAN_INTERVAL)
                    end
                end
                setStatus("Status", "Idle")
            end)
        end
        TreasureJoinSection:AddParagraph({
            Title   = "Info",
            Content = "Scan server Treasure Hunt & hop via ServerHop remote (sama seperti tombol Join in-game).\n"
                .. "Server dicoba satu per satu, paling sedikit player & ping terendah duluan.\n"
                .. "Server gagal/penuh dapat cooldown otomatis.\n"
                .. "Cooldown penuh: " .. COOLDOWN_FULL .. "s | Gagal hop: " .. COOLDOWN_FAILED .. "s",
        })
        toggleRef = TreasureJoinSection:AddToggle({
            Title    = "Enable Auto Join Treasure Hunt",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _tj.enabled = on
                table.clear(_tj.cooldowns)
                if not on then
                    if _tj.thread then pcall(task.cancel, _tj.thread); _tj.thread = nil end
                    _tj.scanning = false
                    setStatus("Status", "Idle")
                    return
                end
                startLoop()
            end,
        })
        TreasureJoinSection:AddButton({
            Title    = "Scan Now",
            Callback = function()
                if _tj.scanning then
                    notify("Sedang scanning...", 2)
                    return
                end
                _tj.scanning = true
                setStatus("Scanning...", "Manual scan...")
                task.spawn(function()
                    if not getServers() then
                        _tj.scanning = false
                        setStatus("Error", "Gagal akses ServerBrowser Replion.")
                        return
                    end
                    local candidates, skippedCooldown, skippedFull = scan()
                    _tj.scanning = false
                    setStatus(describe(candidates, skippedCooldown, skippedFull))
                    if #candidates > 0 then
                        notify(#candidates .. " server ditemukan!", 4)
                    else
                        notify("Tidak ada server Treasure Hunt.")
                    end
                end)
            end,
        })
        TreasureJoinSection:AddButton({
            Title    = "Teleport Now",
            Callback = function()
                if not _tj.lastJobId then
                    notify("Belum ada server. Scan dulu!")
                    return
                end
                notify("Hop ke: " .. _tj.lastJobId:sub(1, 8) .. "...")
                hopTo(_tj.lastJobId)
            end,
        })
        TreasureJoinSection:AddButton({
            Title    = "Reset Cooldowns",
            Callback = function()
                table.clear(_tj.cooldowns)
                setStatus("Status", "Cooldown di-reset. Siap scan ulang.")
                notify("Semua cooldown di-reset!", 2)
            end,
        })
        task.spawn(function()
            task.wait(8)
            if getgenv().__autoTreasureJoin then
                getgenv().__autoTreasureJoin = nil
                _tj.enabled = true
                table.clear(_tj.cooldowns)
                startLoop()
                task.wait(1)
                setToggle(true)
            end
        end)
    end
    do
        local TreasureSection = AutoTab:AddSection("Treasure Hunt", false)
        local OXYGEN_ID, TWEEN_SPEED, SURFACE_Y_OFFSET, MAX_RETRY = 105, 100, 80, 3
        local _th = {
            running = false, atEvent = false, busy = false, o2 = false,
            loopThread = nil, tween = nil, divingConn = nil, charConn = nil,
            savedPos = nil, lastStream = 0, procThread = nil, procStart = 0, doneWreck = nil,
        }
        local PROCESS_TIMEOUT = 300 -- a run takes about a minute per chest; past this it is stuck
        local function setBusy(state)
            _th.busy = state
            _G.SetTreasureBusy(state)
        end
        local function getHRP()
            local char = LocalPlayer.Character
            return char and char:FindFirstChild("HumanoidRootPart")
        end
        local function snap(hrp, cf)
            if not (hrp and hrp.Parent) then return end
            pcall(function()
                hrp.CFrame                  = cf
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
        end
        local function unanchor()
            local hrp = getHRP()
            if hrp then pcall(function() hrp.Anchored = false end) end
        end
        local function cancelTween()
            if _th.tween then _th.tween.cancelled = true end
            _th.tween = nil
            unanchor()
        end
        local function tweenTo(hrp, targetCF, duration)
            cancelTween()
            local state = {}
            _th.tween = state
            local startCF, dur, elapsed = hrp.CFrame, math.max(0.1, duration or 2), 0
            pcall(function() hrp.Anchored = true end)
            while not state.cancelled and elapsed < dur and hrp.Parent do
                elapsed += RunService.Heartbeat:Wait()
                local a = math.min(elapsed / dur, 1)
                local eased = if a < 0.5 then 2 * a * a else 1 - (-2 * a + 2) ^ 2 / 2
                pcall(function() hrp.CFrame = startCF:Lerp(targetCF, eased) end)
            end
            pcall(function() hrp.Anchored = false end)
            if not state.cancelled then snap(hrp, targetCF) end
            if _th.tween == state then _th.tween = nil end
        end
        local function oxygenId()
            local data = getCachedReplionData()
            local ok, id = pcall(function() return data and data:Get("EquippedOxygenTankId") end)
            return ok and id or nil
        end
        local function stopDivingWatch()
            if _th.divingConn then pcall(function() _th.divingConn:Disconnect() end) end
            _th.divingConn = nil
        end
        local function equipO2()
            stopDivingWatch()
            local data = getCachedReplionData()
            if not data then return end
            if oxygenId() ~= OXYGEN_ID then
                task.spawn(safeFire, function() NetEvents.RF_EquipOxygenTank:InvokeServer(OXYGEN_ID) end)
            end
            _th.o2 = true
            _th.divingConn = data:OnChange("EquippedOxygenTankId", inScriptContext(function(newValue)
                if not (_th.o2 and _th.running and _th.atEvent) or newValue == OXYGEN_ID then return end
                task.defer(function()
                    if _th.o2 and _th.running and _th.atEvent and oxygenId() ~= OXYGEN_ID then
                        task.spawn(safeFire, function() NetEvents.RF_EquipOxygenTank:InvokeServer(OXYGEN_ID) end)
                    end
                end)
            end))
        end
        local function unequipO2()
            stopDivingWatch()
            _th.o2 = false
            if oxygenId() == OXYGEN_ID then
                task.spawn(safeFire, function() NetEvents.RF_UnequipOxygenTank:InvokeServer() end)
            end
        end
        local function firePrompt(prompt) -- some mobile executors have no fireproximityprompt
            if type(fireproximityprompt) == "function" then return fireproximityprompt(prompt) end
            prompt:InputHoldBegin()
            task.wait(prompt.HoldDuration + 0.05)
            prompt:InputHoldEnd()
        end
        local function streamAround(position)
            if tick() - _th.lastStream < 20 then return end
            _th.lastStream = tick()
            pcall(function() LocalPlayer:RequestStreamAroundAsync(position, 300) end)
        end
        local function getChests()
            local chests = {}
            local sw = workspace:FindFirstChild("Sunken Wreckage")
            for _, child in ipairs(sw and sw:GetChildren() or {}) do
                if child.Name == "Treasure" and not child:GetAttribute("Opened") then
                    chests[#chests + 1] = child
                end
            end
            return chests
        end
        local function chestDone(chest)
            return not (chest and chest.Parent) or chest:GetAttribute("Opened") == true
        end
        local function returnToSaved()
            cancelTween()
            local target, hrp = _th.savedPos, getHRP()
            _th.savedPos = nil
            if not (target and hrp) then return end
            task.wait(0.05)
            snap(hrp, target)
            task.wait(0.1)
            snap(hrp, target)
        end
        local function openChest(chest, surfaceY)
            local hrp = getHRP()
            if chestDone(chest) or not hrp then return end
            local chestPos = chest:GetPivot().Position
            local chestCF  = chest:GetPivot() * CFrame.new(0, 3, 3)
            local surface  = Vector3.new(chestPos.X, surfaceY, chestPos.Z)
            streamAround(chestPos)
            snap(hrp, CFrame.new(surface))
            task.wait(0.3)
            if not (_th.running and _th.atEvent) then return end
            tweenTo(hrp, chestCF, math.max(1, (surface - chestCF.Position).Magnitude / TWEEN_SPEED))
            if not (_th.running and _th.atEvent) then return end
            pcall(function()
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hum then hum:ChangeState(Enum.HumanoidStateType.Swimming) end
            end)
            task.wait(0.5)
            snap(hrp, chestCF)
            for attempt = 1, MAX_RETRY do
                if chestDone(chest) or not (_th.running and _th.atEvent) then break end
                local prompt = chest:FindFirstChildWhichIsA("ProximityPrompt", true)
                if not prompt then break end
                local deadline, lastFire, lastSnap = tick() + 15, 0, 0
                while not chestDone(chest) and tick() < deadline and _th.running and _th.atEvent do
                    local now = tick()
                    if now - lastFire >= 0.5 then pcall(firePrompt, prompt); lastFire = now end
                    if now - lastSnap >= 0.8 then snap(hrp, chestCF); lastSnap = now end
                    task.wait(0.1)
                end
                if chestDone(chest) or attempt == MAX_RETRY then break end
                local backoffCF = chestCF * CFrame.new(0, 15, 15)
                tweenTo(hrp, backoffCF, 2)
                task.wait(1)
                tweenTo(hrp, chestCF, math.max(1, (backoffCF.Position - chestCF.Position).Magnitude / TWEEN_SPEED))
                task.wait(0.5)
            end
            unanchor()
        end
        local function processEvent()
            local sw = workspace:FindFirstChild("Sunken Wreckage")
            if not _th.running or _th.busy or not sw then return end
            setBusy(true)
            _th.atEvent = true
            streamAround(sw:GetPivot().Position)
            task.wait(0.5)
            local chests, hrp = getChests(), getHRP()
            if #chests > 0 and hrp then
                _th.savedPos = hrp.CFrame
                local surfaceY = sw:GetPivot().Position.Y + SURFACE_Y_OFFSET
                equipO2()
                task.wait(0.5)
                for _, chest in ipairs(chests) do
                    if not (_th.running and _th.atEvent) then break end
                    openChest(chest, surfaceY)
                end
                if _th.running and _th.atEvent then _th.doneWreck = sw end
                returnToSaved()
                task.wait(1.5)
                unequipO2()
            end
            _th.atEvent = false
            setBusy(false)
        end
        local function stopRun()
            local t = _th.procThread
            _th.procThread = nil
            if t and t ~= coroutine.running() then pcall(task.cancel, t) end
            cancelTween()
            _th.atEvent = false
            setBusy(false)
        end
        local function startRun()
            local t = _th.procThread
            if t and coroutine.status(t) ~= "dead" then return end
            _th.procStart = os.clock()
            _th.procThread = task.spawn(function()
                local ok, err = pcall(processEvent)
                if not ok then
                    warn("[Treasure Hunt] " .. tostring(err))
                    pcall(returnToSaved)
                    if _th.o2 then pcall(unequipO2) end
                    _th.atEvent = false
                    setBusy(false)
                end
            end)
        end
        local function cleanup()
            stopRun()
            if _th.o2 then unequipO2() else stopDivingWatch() end
            if _th.loopThread then pcall(task.cancel, _th.loopThread) end
            if _th.charConn then _th.charConn:Disconnect() end
            _th.loopThread, _th.charConn = nil, nil
        end
        TreasureSection:AddButton({
            Title    = "Teleport Now (di atas lokasi)",
            Callback = function()
                local sw, hrp = workspace:FindFirstChild("Sunken Wreckage"), getHRP()
                if not (sw and hrp) then
                    Library:MakeNotify({ Title = "Treasure Hunt", Description = sw and "Character tidak ditemukan!" or "Sunken Wreckage tidak ditemukan!", Delay = 2 })
                    return
                end
                task.spawn(function()
                    local pos      = sw:GetPivot().Position
                    local targetCF = CFrame.new(pos.X, pos.Y + SURFACE_Y_OFFSET, pos.Z)
                    local startCF  = hrp.CFrame
                    setBusy(true)
                    for i = 1, 6 do
                        snap(hrp, startCF:Lerp(targetCF, i / 6))
                        task.wait(0.08)
                    end
                    snap(hrp, targetCF)
                    setBusy(false)
                end)
            end,
        })
        TreasureSection:AddToggle({
            Title    = "Auto Treasure Hunt",
            Default  = false,
            Callback = function(on)
                if not on and _th.atEvent then returnToSaved() end
                cleanup()
                _th.running = on
                if not on then return end
                _th.doneWreck = nil -- switching it back on retries the current wreck
                _th.charConn = LocalPlayer.CharacterAdded:Connect(function()
                    task.wait(3)
                    stopDivingWatch()
                    _th.o2 = false
                    stopRun() -- the old run was still driving the dead character; the loop starts a fresh one
                end)
                _th.loopThread = task.spawn(function()
                    while _th.running do
                        pcall(function()
                            local t = _th.procThread
                            if t and coroutine.status(t) ~= "dead" then
                                if os.clock() - _th.procStart > PROCESS_TIMEOUT then
                                    pcall(returnToSaved)
                                    if _th.o2 then pcall(unequipO2) end
                                    stopRun()
                                end
                            elseif #getChests() > 0 and workspace:FindFirstChild("Sunken Wreckage") ~= _th.doneWreck then
                                if _th.busy or _th.atEvent then stopRun() end -- flags a dead run left behind
                                startRun()
                            end
                        end)
                        task.wait(3)
                    end
                end)
            end,
        })
    end
    do
        local CollectionService = game:GetService("CollectionService")
        local TweenService, RunService = game:GetService("TweenService"), game:GetService("RunService")
        local TAG, PICKAXE_ID, NEAR_ISLAND, STREAM_EVERY = "GlowingCrystal", 20220, 400, 10
        local COOLDOWN, GLIDE_SPEED, SETTLE = 11.6, 24, 1
        local _extract = { nextOk = 0, suspicious = false, conn = nil }
        local function watchExtract()
            if _extract.conn and _extract.conn.Connected then return end
            pcall(function()
                _extract.conn = NetEvents.RE_TextNotification.OnClientEvent:Connect(function(p)
                    local text = type(p) == "table" and p.Text
                    if type(text) ~= "string" then return end
                    local secs = text:match("wait (%d+) seconds? before extracting")
                    if secs then
                        _extract.nextOk = math.max(_extract.nextOk, os.clock() + tonumber(secs) + 0.3)
                    elseif text:find("wait before extracting", 1, true) then
                        _extract.nextOk = math.max(_extract.nextOk, os.clock() + 3)
                    elseif text:find("Suspicious movement", 1, true) then
                        _extract.suspicious = true
                    elseif text:find("You extracted", 1, true) then
                        _extract.nextOk = os.clock() + COOLDOWN
                    end
                end)
            end)
        end
        local function addCrystalMiner(cfg)
            local _m = { enabled = false, run = 0 }
            local Section = AutoTab:AddSection(cfg.section)
            Section:AddParagraph({
                Title   = "Note",
                Content = ("Begitu %s muncul, teleport ke %s, mining, lalu balik ke lokasi awal.\n"
                    .. "Bisa dari pulau mana saja & jalan bareng auto fishing."):format(cfg.drop, cfg.island),
            })
            local function notify(desc, delay)
                Library:MakeNotify({ Title = cfg.title, Description = desc, Delay = delay or 3 })
            end
            Section:AddToggle({
                Title    = cfg.toggle,
                Default  = false,
                NoSave   = true,
                Callback = function(on)
                    _m.enabled = on
                    _m.run += 1 -- a fresh loop every time it's switched on; an old one sees the bump and quits
                    notify(on and "Aktif!" or "Dihentikan.", 2)
                    if not on then return end
                    local run = _m.run
                    local function alive() return _m.enabled and _m.run == run end
                    task.spawn(function()
                        local skip, streamedAt = {}, 0
                        local function root()
                            return LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                        end
                        local function moveTo(cf)
                            local hrp = root()
                            if hrp then hrp.CFrame, hrp.AssemblyLinearVelocity = cf, Vector3.zero end
                        end
                        local function jump(cf)
                            local hrp = root()
                            if not hrp then return end
                            hrp.CFrame, hrp.Anchored = cf + Vector3.new(0, 5, 0), true
                            task.wait(3)
                            hrp.Anchored, hrp.CFrame, hrp.AssemblyLinearVelocity = false, cf, Vector3.zero
                            task.wait(0.5)
                        end
                        local function glide(cf)
                            local hrp = root()
                            if not hrp then return end
                            local dist = (hrp.Position - cf.Position).Magnitude
                            if dist < 4 then moveTo(cf) return end
                            local char = hrp.Parent
                            local noclip = RunService.Stepped:Connect(function()
                                for _, v in ipairs(char:GetDescendants()) do
                                    if v:IsA("BasePart") then v.CanCollide = false end
                                end
                                hrp.AssemblyLinearVelocity = Vector3.zero
                            end)
                            local tween = TweenService:Create(hrp, TweenInfo.new(dist / GLIDE_SPEED, Enum.EasingStyle.Linear), { CFrame = cf })
                            tween:Play()
                            while tween.PlaybackState == Enum.PlaybackState.Playing do
                                if not (alive() and hrp.Parent) then tween:Cancel() break end
                                task.wait(0.1)
                            end
                            noclip:Disconnect()
                            hrp.AssemblyLinearVelocity = Vector3.zero
                        end
                        local function farAway()
                            local hrp = root()
                            return not hrp or (hrp.Position - cfg.spot.Position).Magnitude > NEAR_ISLAND
                        end
                        local function promptOf(crystal)
                            local p = crystal:FindFirstChildWhichIsA("ProximityPrompt", true)
                            return p and p.Enabled and p.Parent and p.Parent:IsA("BasePart") and p or nil
                        end
                        local function readyCrystals()
                            local islands = workspace:FindFirstChild("Islands")
                            local folder = islands and islands:FindFirstChild(cfg.island)
                            folder = folder and folder:FindFirstChild("Crystals")
                            local list = {}
                            for _, crystal in ipairs(folder and folder:GetChildren() or {}) do
                                if (skip[crystal] or 0) < os.clock() and promptOf(crystal) then list[#list + 1] = crystal end
                            end
                            return list
                        end
                        local function pickaxeUUID(data)
                            for _, cat in ipairs({ "Items", "Gears" }) do
                                for _, item in ipairs(data:Get({ "Inventory", cat }) or {}) do
                                    if item.Id == PICKAXE_ID then return item.UUID end
                                end
                            end
                        end
                        local function holdPickaxe(data, uuid)
                            if data:Get("EquippedId") == uuid then return true end
                            local function slot() return table.find(data:Get("EquippedItems") or {}, uuid) end
                            for _ = 1, 3 do
                                if not slot() then
                                    pcall(function() NetEvents.RE_EquipItem:FireServer(uuid, "Gears") end)
                                    for _ = 1, 12 do if slot() then break end task.wait(0.25) end
                                end
                                if slot() then
                                    pcall(function() NetEvents.RF_EquipToolFromHotbar:FireServer(slot()) end)
                                    for _ = 1, 8 do
                                        if data:Get("EquippedId") == uuid then return true end
                                        task.wait(0.25)
                                    end
                                end
                                if not alive() then break end
                            end
                            return false
                        end
                        local function mine(data, uuid, crystal)
                            local prompt = promptOf(crystal)
                            if not prompt then return true end
                            local stand = CFrame.new(prompt.Parent.Position + Vector3.new(0, 4, 0))
                            local tagged = CollectionService:HasTag(crystal, TAG)
                            local function gone()
                                return not (crystal.Parent and prompt.Parent and prompt.Enabled)
                                    or (tagged and not CollectionService:HasTag(crystal, TAG))
                            end
                            glide(stand)
                            task.wait(SETTLE)
                            for _ = 1, 6 do
                                if gone() or not alive() then break end
                                while alive() and not gone() and os.clock() < _extract.nextOk do task.wait(0.2) end
                                if gone() or not alive() then break end
                                if not holdPickaxe(data, uuid) then return false end
                                _extract.suspicious = false
                                pcall(fireproximityprompt, prompt)
                                for _ = 1, math.ceil((prompt.HoldDuration + 2) / 0.25) do
                                    if gone() or _extract.suspicious or os.clock() < _extract.nextOk - 1 then break end
                                    task.wait(0.25)
                                end
                                if _extract.suspicious then
                                    moveTo(stand)
                                    task.wait(2)
                                end
                            end
                            if gone() then _extract.nextOk = math.max(_extract.nextOk, os.clock() + COOLDOWN - 1) end
                            return gone()
                        end
                        local warned = false
                        local function session(data, hrp)
                            local uuid = pickaxeUUID(data)
                            if not uuid then
                                if not warned then warned = true; notify("Pickaxe tidak ditemukan di inventory!", 4) end
                                return
                            end
                            warned = false
                            watchExtract()
                            local saved, mined, travelled = hrp.CFrame, 0, farAway()
                            _G.SetMining(true)
                            _totemSpawning = true
                            pcall(function()
                                task.spawn(pcall, function() NetEvents.RF_CancelFishingInputs:InvokeServer() end)
                                pcall(function() cachedRequire(ReplicatedStorage.Controllers.FishingController):RequestClientStopFishing(true) end)
                                pcall(function() LocalPlayer.Character.Humanoid:UnequipTools() end)
                                task.wait(1.5)
                                if travelled then
                                    notify(cfg.drop .. " muncul! Teleport ke " .. cfg.island .. "...")
                                    jump(cfg.spot)
                                    _extract.nextOk = math.max(_extract.nextOk, os.clock() + 2) -- let the big hop settle
                                end
                                while alive() do
                                    local ready, r = readyCrystals(), root()
                                    if #ready == 0 or not r then break end
                                    local here = r.Position
                                    table.sort(ready, function(a, b) return (a:GetPivot().Position - here).Magnitude < (b:GetPivot().Position - here).Magnitude end)
                                    if mine(data, uuid, ready[1]) then
                                        mined += 1
                                    else
                                        skip[ready[1]] = os.clock() + 15
                                    end
                                end
                            end)
                            pcall(function() if travelled then jump(saved) else moveTo(saved) end end)
                            _G.SetMining(false)
                            _totemSpawning = false
                            task.wait(0.5)
                            pcall(autoEquipRod)
                            if mined > 0 then notify(("%d %s ditambang, lanjut mancing."):format(mined, cfg.drop)) end
                        end
                        while alive() do
                            pcall(function()
                                local data, hrp = getCachedReplionData(), root()
                                if not (data and hrp) then return end
                                if farAway() and os.clock() - streamedAt >= STREAM_EVERY then
                                    streamedAt = os.clock()
                                    pcall(LocalPlayer.RequestStreamAroundAsync, LocalPlayer, cfg.spot.Position, 5)
                                end
                                if #readyCrystals() > 0 and not (_totemSpawning or _G._treasureHuntBusy or _G.OrbThrowing or _G.AutoMineActive) then
                                    session(data, hrp)
                                end
                            end)
                            task.wait(1)
                        end
                    end)
                end,
            })
        end
        addCrystalMiner({
            section = "Mining Crystal", title = "Auto Mine", toggle = "Enable Auto Mine Crystal",
            island = "Crystal Depths", drop = "Cave Crystal",
            spot = CFrame.lookAt(Vector3.new(5729.334, -904.818, 15408.078), Vector3.new(5691.893, -904.818, 15262.826)),
        })
        addCrystalMiner({
            section = "Mining Veilshard", title = "Auto Veilshard", toggle = "Enable Auto Mine Veilshard",
            island = "Lava Basin", drop = "Veilshard",
            spot = CFrame.lookAt(Vector3.new(894.223, 89.033, -10195.547), Vector3.new(1032.501, 89.033, -10137.418)),
        })
    end
    do
        local ClaimSection = AutoTab:AddSection("Claim Pirate Chest", false)
        local CLAIM_TIMEOUT, RETURN_HOLD, SCAN_DELAY = 5, 2, 1
        local _claim = { enabled = false, thread = nil, conn = nil, origin = nil, busy = false }
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Pirate Chest", Description = desc, Delay = delay or 2 })
        end
        local function getHRP()
            local char = LocalPlayer.Character
            return char and char:FindFirstChild("HumanoidRootPart")
        end
        local function moveTo(hrp, cf)
            hrp.CFrame                  = cf
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
        local function returnToOrigin()
            local origin = _claim.origin
            if not origin then return end
            local hrp = getHRP()
            if not hrp then
                _claim.origin = nil
                return
            end
            pcall(function()
                moveTo(hrp, CFrame.new(origin.Position + Vector3.new(0, 10, 0)) * (origin - origin.Position))
                hrp.Anchored = true
            end)
            task.wait(RETURN_HOLD)
            pcall(function()
                hrp.Anchored = false
                moveTo(hrp, origin)
                local humanoid = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if humanoid then humanoid:ChangeState(Enum.HumanoidStateType.Freefall) end
            end)
            _claim.origin = nil
        end
        local function claimChest(chest)
            if not (chest and chest.Parent) then return end
            local cover  = chest:FindFirstChild("Cover")
            local prompt = cover and cover:FindFirstChildOfClass("ProximityPrompt")
            local hrp    = getHRP()
            if not (prompt and hrp) then return end
            pcall(function() moveTo(hrp, chest:GetPivot() * CFrame.new(0, 0, -3)) end)
            task.wait(0.2)
            if not chest.Parent then return end
            pcall(fireproximityprompt, prompt)
            local waited = 0
            while chest.Parent and waited < CLAIM_TIMEOUT do
                task.wait(0.1)
                waited += 0.1
            end
        end
        local function claimAll(chests)
            if _claim.busy then return end
            local hrp = getHRP()
            if not hrp then return end
            _claim.busy   = true
            _claim.origin = hrp.CFrame
            for _, chest in ipairs(chests) do
                if not _claim.enabled then break end
                claimChest(chest)
            end
            returnToOrigin()
            _claim.busy = false
        end
        local function collectChests()
            local storage = workspace:FindFirstChild("PirateChestStorage")
            if not storage then return nil end
            local chests = {}
            for _, chest in ipairs(storage:GetChildren()) do
                if chest:IsA("Model") then table.insert(chests, chest) end
            end
            return chests
        end
        ClaimSection:AddToggle({
            Title    = "Enable Auto Claim",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _claim.enabled = on
                if _claim.thread then pcall(task.cancel, _claim.thread); _claim.thread = nil end
                if _claim.conn then pcall(function() _claim.conn:Disconnect() end); _claim.conn = nil end
                if not on then
                    _claim.busy = false
                    local hrp = getHRP()
                    if hrp then pcall(function() hrp.Anchored = false end) end
                    task.spawn(returnToOrigin)
                    notify("Stopped.")
                    return
                end
                _claim.thread = task.spawn(function()
                    while _claim.enabled do
                        if not _claim.busy then
                            local chests = collectChests()
                            if chests and #chests > 0 then claimAll(chests) end
                        end
                        task.wait(SCAN_DELAY)
                    end
                end)
                local storage = workspace:FindFirstChild("PirateChestStorage")
                if storage then
                    _claim.conn = storage.ChildAdded:Connect(function(child)
                        if _claim.enabled and not _claim.busy and child:IsA("Model") then
                            claimAll({ child })
                        end
                    end)
                end
                notify("Active!")
            end,
        })
    end
    do
        local CharmCraftSection = AutoTab:AddSection("Craft Charm", false)
        local CONFIRM_DELAY, RETRY_DELAY = 0.1, 1
        local _cc = { enabled = false, thread = nil, selected = nil, amount = 1, crafted = 0, charms = {}, names = {} }
        local dropdownRef, toggleRef
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Auto Craft Charm", Description = desc, Delay = delay or 3 })
        end
        local function buildCharmList()
            _cc.charms, _cc.names = {}, {}
            local shared = ReplicatedStorage:FindFirstChild("Shared")
            local module = shared and shared:FindFirstChild("CraftingItems")
            if not module then return 0 end
            local ok, CraftingItems = pcall(cachedRequire, module)
            if not ok or type(CraftingItems) ~= "table" or type(CraftingItems.Items) ~= "table" then return 0 end
            for index, entry in ipairs(CraftingItems.Items) do
                if type(entry) == "table" and entry.Type == "Charms" and entry.Name and not _cc.charms[entry.Name] then
                    _cc.charms[entry.Name] = index
                    table.insert(_cc.names, entry.Name)
                end
            end
            table.sort(_cc.names)
            return #_cc.names
        end
        local function craftLoop()
            while _cc.enabled and _cc.crafted < _cc.amount do
                local name  = _cc.selected
                local index = name and _cc.charms[name]
                if not index then
                    notify("Charm tidak ditemukan: " .. tostring(name) .. ". Tekan Refresh Charm List dulu.", 4)
                    break
                end
                local ok, started = pcall(function() return NetEvents.RF_StartCrafting:InvokeServer(index) end)
                if not ok or not started then
                    pcall(function() NetEvents.RF_CancelCrafting:InvokeServer() end)
                    notify("Gagal start! Bahan kurang atau quest belum selesai.")
                    break
                end
                task.wait(CONFIRM_DELAY)
                if not _cc.enabled then break end
                local okConfirm, confirmed = pcall(function() return NetEvents.RF_ConfirmCrafting:InvokeServer() end)
                if okConfirm and confirmed then
                    _cc.crafted += 1
                    notify(("[%d/%d] Berhasil craft: %s"):format(_cc.crafted, _cc.amount, name), 2)
                    task.wait()
                else
                    pcall(function() NetEvents.RF_CancelCrafting:InvokeServer() end)
                    notify("Gagal confirm craft, mencoba lagi...", 2)
                    task.wait(RETRY_DELAY)
                end
            end
            if _cc.crafted >= _cc.amount then
                notify(("Selesai! Total craft: %dx %s"):format(_cc.crafted, _cc.selected or ""), 4)
            end
        end
        buildCharmList()
        _cc.selected = _cc.names[1]
        CharmCraftSection:AddParagraph({
            Title   = "Info",
            Content = "Auto Craft Charm otomatis start & confirm crafting.\n"
                .. "Pilih charm dari dropdown lalu aktifkan toggle.\n"
                .. "Pastikan bahan crafting tersedia di inventory.\n"
                .. "Quest Kohana Gatekeeper harus sudah selesai.",
        })
        dropdownRef = CharmCraftSection:AddDropdown({
            Title    = "Pilih Charm",
            Options  = #_cc.names > 0 and _cc.names or { "Loading..." },
            Default  = _cc.names[1],
            Callback = function(value)
                local name = type(value) == "table" and value[1] or value
                if _cc.charms[name] then _cc.selected = name end
            end,
        })
        CharmCraftSection:AddInput({
            Title    = "Jumlah Craft",
            Default  = "1",
            Callback = function(value)
                local n = tonumber(value)
                if n and n > 0 then _cc.amount = math.floor(n) end
            end,
        })
        toggleRef = CharmCraftSection:AddToggle({
            Title    = "Enable Auto Craft",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                local wasRunning = _cc.enabled
                _cc.enabled = on
                if _cc.thread then pcall(task.cancel, _cc.thread); _cc.thread = nil end
                if not on then
                    if wasRunning then
                        pcall(function() NetEvents.RF_CancelCrafting:InvokeServer() end)
                        notify(("Dihentikan. Tercrafted: %d/%d"):format(_cc.crafted, _cc.amount))
                    end
                    return
                end
                if not (_cc.selected and _cc.charms[_cc.selected]) then
                    _cc.enabled = false
                    notify("Pilih charm dari dropdown dulu!")
                    task.defer(function() pcall(function() toggleRef:SetValue(false) end) end)
                    return
                end
                _cc.crafted = 0
                notify(("Mulai craft %dx %s"):format(_cc.amount, _cc.selected), 2)
                _cc.thread = task.spawn(function()
                    craftLoop()
                    _cc.enabled = false
                    _cc.thread  = nil
                    pcall(function() toggleRef:SetValue(false) end)
                end)
            end,
        })
        CharmCraftSection:AddButton({
            Title    = "Refresh Charm List",
            Callback = function()
                local count = buildCharmList()
                pcall(function() dropdownRef:SetOptions(count > 0 and _cc.names or { "No Items Found" }) end)
                if not (_cc.selected and _cc.charms[_cc.selected]) then _cc.selected = _cc.names[1] end
                notify("List diperbarui: " .. count .. " charm.", 2)
            end,
        })
    end
    do
        local AtlantisSection = AutoTab:AddSection("Atlantis Machine")
        local IDLE_WAIT, RETRY_LIMIT, STREAM_RADIUS = 10, 3, 200
        _atlantis = {
            enabled  = false,
            thread   = nil,
            selling  = false,
            savedPos = nil,
            replion  = nil,
            data     = nil,
            config   = nil,
            part     = nil,
            lastPos  = nil,
        }
        local toggleRef
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Atlantis", Description = desc, Delay = delay or 2 })
        end
        local function init()
            if _atlantis.replion and _atlantis.data and _atlantis.config then return true end
            pcall(function()
                local client = getCachedReplion().Client
                _atlantis.config  = cachedRequire(ReplicatedStorage.Shared.AtlantisMachineConfig)
                _atlantis.replion = client:WaitReplion(_atlantis.config.Channel)
                _atlantis.data    = client:WaitReplion("Data")
            end)
            return _atlantis.replion ~= nil and _atlantis.data ~= nil and _atlantis.config ~= nil
        end
        local function findPart()
            if _atlantis.part and _atlantis.part.Parent then return _atlantis.part end
            local ok, found = pcall(function()
                local city    = workspace.Islands:FindFirstChild(_atlantis.config.LocationName)
                local machine = city and city:FindFirstChild("Atlantis Machine")
                if not machine then return nil end
                local prompt = machine:FindFirstChildWhichIsA("ProximityPrompt", true)
                if prompt and prompt.Parent and prompt.Parent:IsA("BasePart") then return prompt.Parent end
                return machine:FindFirstChildWhichIsA("BasePart")
            end)
            _atlantis.part = ok and found or nil
            if _atlantis.part then _atlantis.lastPos = _atlantis.part.Position end
            return _atlantis.part
        end
        local function getPart()
            local part = findPart()
            if part or not _atlantis.lastPos then return part end
            pcall(function() LocalPlayer:RequestStreamAroundAsync(_atlantis.lastPos, STREAM_RADIUS) end)
            task.wait(1)
            return findPart()
        end
        local function currentPoints()
            local ok, value = pcall(function() return _atlantis.replion:Get("CurrentPoints") end)
            return (ok and value) or 0
        end
        local function isBoostActive()
            local ok, boostId = pcall(function() return _atlantis.replion:Get("ActiveBoostId") end)
            if not ok or not boostId or boostId == "" then return false end
            local ok2, endsAt = pcall(function() return _atlantis.replion:Get("ActiveBoostEndsAt") end)
            return ok2 and (endsAt or 0) > workspace:GetServerTimeNow()
        end
        local function inventoryPoints()
            local ok, entries = pcall(function()
                return _atlantis.config:BuildEligibleEntries(_atlantis.data:Get({ "Inventory", "Items" }) or {})
            end)
            if not ok or type(entries) ~= "table" then return 0 end
            local total = 0
            for _, entry in ipairs(entries) do total += (entry.Points or 0) end
            return total
        end
        local function teleportTo(cf, times)
            for _ = 1, times do
                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    hrp.CFrame                  = cf
                    hrp.AssemblyLinearVelocity  = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                end
                task.wait(0.15)
            end
        end
        local function teleportBack()
            if not _atlantis.savedPos then return end
            local target = _atlantis.savedPos
            _atlantis.savedPos = nil
            teleportTo(target, 5)
        end
        local function doSacrifice()
            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end
            local part = getPart()
            if not part then
                notify("Atlantis Machine belum ter-load, coba lagi nanti.", 4)
                return false
            end
            _atlantis.savedPos = hrp.CFrame
            _atlantis.selling  = true
            teleportTo(CFrame.new(part.Position + Vector3.new(0, 3, 0)), 3)
            task.wait(0.3)
            local done = false
            for _ = 1, RETRY_LIMIT do
                if not _atlantis.selling then break end
                local ok, result = pcall(function()
                    return NetEvents.RF_SacrificeAtlantisSellAll:InvokeServer()
                end)
                if ok and result and result.Success then
                    done = true
                    break
                end
                task.wait(1)
            end
            task.wait(0.3)
            _atlantis.selling = false
            notify(done and "Sacrifice All berhasil!" or "Sacrifice gagal setelah beberapa percobaan.", done and 2 or 4)
            teleportBack()
            return done
        end
        AtlantisSection:AddParagraph({
            Title   = "Info",
            Content = "Otomatis sacrifice ikan ke Atlantis Machine di Underwater City.\n"
                .. "• Kumpulkan poin dulu dari hasil mancing\n"
                .. "• Kalau inventory sudah cukup untuk isi mesin → baru teleport\n"
                .. "• Sacrifice sekaligus → langsung balik ke posisi mancing\n"
                .. "• Boost sedang aktif → idle, tunggu selesai\n"
                .. "• Mesin penuh → idle, cek ulang tiap 10 detik\n"
                .. "• Toggle OFF → langsung balik ke posisi terakhir",
        })
        toggleRef = AtlantisSection:AddToggle({
            Title    = "Auto Atlantis Machine",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _atlantis.enabled = on
                if _atlantis.thread then pcall(task.cancel, _atlantis.thread); _atlantis.thread = nil end
                if not on then
                    _atlantis.selling = false
                    task.spawn(teleportBack)
                    return
                end
                _atlantis.thread = task.spawn(function()
                    if not init() then
                        notify("Gagal memuat data Atlantis Machine.", 4)
                        _atlantis.enabled = false
                        _atlantis.thread  = nil
                        pcall(function() toggleRef:SetValue(false) end)
                        return
                    end
                    while _atlantis.enabled do
                        if isBoostActive() then
                            task.wait(IDLE_WAIT)
                            continue
                        end
                        local needed = (_atlantis.config.MaxPoints or 1000) - currentPoints()
                        if needed <= 0 or inventoryPoints() < needed then
                            task.wait(if needed <= 0 then IDLE_WAIT else 5)
                            continue
                        end
                        doSacrifice()
                        task.wait(3)
                    end
                end)
            end,
        })
        AtlantisSection:AddButton({
            Title    = "Sacrifice Now",
            Callback = function()
                if _atlantis.selling then return end
                task.spawn(function()
                    if not init() then
                        notify("Gagal memuat data Atlantis Machine.", 4)
                        return
                    end
                    doSacrifice()
                end)
            end,
        })
    end
    do
        local BuyCharmSection = AutoTab:AddSection("Buy Charm", false)
        local BUY_DELAY = 0.1
        local _bc = { byName = {}, selected = nil, amount = 1, buying = false, loaded = false, pending = nil }
        local infoParagraph, charmDropdown, loadCharmList
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Auto Buy Charm", Description = desc, Delay = delay or 3 })
        end
        local function showInfo(entry, extra)
            if not entry then
                infoParagraph:SetContent("Belum ada charm yang dipilih.")
                return
            end
            infoParagraph:SetContent(
                ("Name: %s\nPrice: %s coins%s"):format(entry.Name, tostring(entry.Price), extra or "")
            )
        end
        local function selectCharm(name)
            local entry = _bc.byName[name]
            if not entry then return false end
            _bc.selected = entry
            showInfo(entry)
            return true
        end
        loadCharmList = function()
            infoParagraph:SetContent("Memuat daftar charm...")
            local folder = ReplicatedStorage:FindFirstChild("Charms")
            if not folder then
                local ok, res = pcall(function() return ReplicatedStorage:WaitForChild("Charms", 5) end)
                folder = ok and res or nil
            end
            if not folder then
                infoParagraph:SetContent("Folder Charms tidak ditemukan.")
                return
            end
            local list = {}
            for _, mod in ipairs(folder:GetChildren()) do
                if mod:IsA("ModuleScript") then
                    local ok, data = pcall(require, mod)
                    if ok and type(data) == "table" and data.Data and (data.Price or 0) > 0 then
                        table.insert(list, {
                            Name  = tostring(data.Data.Name or mod.Name),
                            Id    = data.Data.Id,
                            Price = data.Price,
                        })
                    end
                end
            end
            table.sort(list, function(a, b) return a.Name < b.Name end)
            local names = {}
            _bc.byName = {}
            for _, entry in ipairs(list) do
                _bc.byName[entry.Name] = entry
                table.insert(names, entry.Name)
            end
            _bc.loaded = true
            if #names == 0 then
                infoParagraph:SetContent("Tidak ada charm yang dijual.")
                return
            end
            pcall(function() charmDropdown:SetOptions(names) end)
            local pick = (_bc.pending and _bc.byName[_bc.pending]) and _bc.pending or names[1]
            _bc.pending = nil
            selectCharm(pick)
            pcall(function() charmDropdown:SetValue(pick) end)
        end
        infoParagraph = BuyCharmSection:AddParagraph({
            Title   = "Charm Info",
            Content = "Memuat daftar charm...",
        })
        charmDropdown = BuyCharmSection:AddDropdown({
            Title    = "Charm Type",
            Options  = { "Memuat..." },
            Default  = "Memuat...",
            Callback = function(selected)
                local name = type(selected) == "table" and selected[1] or selected
                if not _bc.loaded then
                    _bc.pending = name
                    task.spawn(loadCharmList)
                    return
                end
                selectCharm(name)
            end,
        })
        BuyCharmSection:AddInput({
            Title    = "Amount Charm",
            Default  = "1",
            Callback = function(value)
                local n = tonumber(value)
                if n and n > 0 then _bc.amount = math.floor(n) end
            end,
        })
        BuyCharmSection:AddButton({
            Title    = "Buy Charm",
            Callback = function()
                if _bc.buying then return end
                if not _bc.loaded then
                    task.spawn(loadCharmList)
                    notify("Daftar charm belum siap, coba lagi sebentar.")
                    return
                end
                local entry  = _bc.selected
                local remote = NetEvents.RF_PurchaseCharm
                if not entry then
                    notify("Pilih charm terlebih dahulu!")
                    return
                end
                if not remote then
                    notify("Remote RF_PurchaseCharm tidak ditemukan!")
                    return
                end
                local total = _bc.amount
                _bc.buying = true
                notify(("Mulai membeli %dx %s..."):format(total, entry.Name))
                task.spawn(function()
                    local success, failed = 0, 0
                    for i = 1, total do
                        if not _bc.buying then break end
                        local data  = getCachedReplionData()
                        local coins = (data and data:Get("Coins")) or 0
                        if coins < entry.Price then
                            notify(("Coins tidak cukup (butuh %s, punya %s)."):format(
                                tostring(entry.Price), tostring(coins)), 4)
                            break
                        end
                        local ok, result = pcall(function() return remote:InvokeServer(entry.Id) end)
                        if ok and result == true then success += 1 else failed += 1 end
                        if i % 5 == 0 or i == total then
                            showInfo(entry, ("\nProgress: %d/%d (OK: %d, Gagal: %d)"):format(i, total, success, failed))
                        end
                        if i < total and _bc.buying then task.wait(BUY_DELAY) end
                    end
                    _bc.buying = false
                    notify(("Selesai! Berhasil %d/%d %s"):format(success, total, entry.Name), 4)
                    showInfo(entry, ("\nTerakhir: %d/%d berhasil"):format(success, total))
                end)
            end,
        })
        BuyCharmSection:AddButton({
            Title    = "Stop Buying",
            Callback = function() _bc.buying = false end,
        })
        BuyCharmSection:AddButton({
            Title    = "Refresh Charm List [Buy]",
            Callback = function()
                if _bc.buying then return end
                task.spawn(loadCharmList)
            end,
        })
        task.spawn(function()
            task.wait(1)
            pcall(loadCharmList)
        end)
    end
    do
        local PotionSection = AutoTab:AddSection("Use Potion", false)
        local _potion = { enabled = false, task = nil, selected = {} }
        local POTION_IDS, POTION_NAMES = {}, {}
        for _, p in pairs(cachedRequire(ReplicatedStorage:FindFirstChild("Potions")) or {}) do
            local d = type(p) == "table" and p.Data
            local module = p and p._moduleScript
            if type(d) == "table" and d.Id and d.Name and not p.Infinite
                and not (module and module.Name:find("Totem")) and not d.Name:find("Totem")
                and (p.VFX or p.InstantWeather or d.Name:find("Potion"))
            then
                POTION_IDS[d.Name] = d.Id
                POTION_NAMES[#POTION_NAMES + 1] = d.Name
            end
        end
        table.sort(POTION_NAMES, function(a, b) return POTION_IDS[a] < POTION_IDS[b] end)
        PotionSection:AddDropdown({
            Title    = "Select Potions",
            Options  = POTION_NAMES,
            Multi    = true,
            Default  = {},
            Callback = function(selected)
                _potion.selected = type(selected) == "table" and selected or {}
            end,
        })
        PotionSection:AddToggle({
            Title    = "Auto Use Potions",
            Default  = false,
            Callback = function(on)
                _potion.enabled = on
                if _potion.task then pcall(task.cancel, _potion.task); _potion.task = nil end
                if not on then return end
                _potion.task = task.spawn(function()
                    while _potion.enabled do
                        local data = getCachedReplionData()
                        for _, name in ipairs(data and _potion.selected or {}) do
                            if name == "Cave Crystal" then
                                pcall(function() NetEvents.RF_ConsumeCaveCrystal:InvokeServer() end)
                            elseif POTION_IDS[name] then
                                for _, item in ipairs(data:Get({ "Inventory", "Potions" }) or {}) do
                                    if item.Id == POTION_IDS[name] then
                                        pcall(function() NetEvents.RF_ConsumePotion:InvokeServer(item.UUID, 1) end)
                                        break
                                    end
                                end
                            end
                        end
                        task.wait(1)
                    end
                end)
            end,
        })
    end
    do
        local _orb = { enabled = false, thread = nil, castConn = nil, lastCast = nil }
        local OrbSection = AutoTab:AddSection("Use Orb", false)
        local function isOrbItem(data)
            return data and data.BathBomb and data.Data and data.Data.Type == "Gears"
        end
        local function getOrbList()
            local list = {}
            pcall(function()
                local replionData = getCachedReplionData()
                local ItemUtility = require(ReplicatedStorage.Shared.ItemUtility)
                if not replionData then return end
                for _, item in pairs(replionData:Get({"Inventory", "Items"}) or {}) do
                    local data = ItemUtility:GetItemData(item.Id)
                    if isOrbItem(data) and not table.find(list, data.Data.Name) then
                        table.insert(list, data.Data.Name)
                    end
                end
            end)
            if #list == 0 then table.insert(list, "Tidak ada Orb") end
            return list
        end
        local selectedOrb = ""
        local orbDropdown = OrbSection:AddDropdown({
            Title    = "Pilih Orb",
            Options  = getOrbList(),
            Default  = "",
            Callback = function(val) selectedOrb = val or "" end,
        })
        OrbSection:AddButton({
            Title    = "Refresh Orb List",
            Callback = function()
                orbDropdown:SetOptions(getOrbList())
                Library:MakeNotify({ Title = "Auto Orb", Description = "Orb list diperbarui.", Delay = 2 })
            end,
        })
        OrbSection:AddToggle({
            Title    = "Enable Auto Use Orb",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _orb.enabled = on
                if on and _G._autoEquipRodToggleRef then
                    pcall(function() _G._autoEquipRodToggleRef:SetValue(true) end)
                end
                if _orb.thread then
                    pcall(task.cancel, _orb.thread)
                    _orb.thread = nil
                end
                if _orb.castConn then _orb.castConn:Disconnect(); _orb.castConn = nil end
                _G.SetOrbThrowing(false)
                if not on then
                    Library:MakeNotify({ Title = "Auto Orb", Description = "Stopped.", Delay = 2 })
                    return
                end
                Library:MakeNotify({ Title = "Auto Orb", Description = "Active!", Delay = 2 })
                pcall(function()
                    _orb.castConn = NetEvents.RE_BaitCastVisual.OnClientEvent:Connect(function(player, castData)
                        if player == LocalPlayer and type(castData) == "table" and typeof(castData.CastPosition) == "Vector3" then
                            _orb.lastCast = { pos = castData.CastPosition, power = tonumber(castData.Power) }
                        end
                    end)
                end)
                _orb.thread = task.spawn(function()
                    local Replion        = require(ReplicatedStorage.Packages.Replion)
                    local ItemUtility    = require(ReplicatedStorage.Shared.ItemUtility)
                    local RaycastUtility = require(ReplicatedStorage.Shared.RaycastUtility)
                    local Constants      = require(ReplicatedStorage.Shared.Constants)
                    local replionData    = Replion.Client:GetReplion("Data")
                    local poolContainer  = workspace:WaitForChild("BathBombPools", 10)
                    local throwCount     = 0
                    local failCount      = 0
                    local function getFishingThrowPosition()
                        local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                        if not root then return nil end
                        local cast = _orb.lastCast
                        if cast and (Vector3.new(cast.pos.X, 0, cast.pos.Z) - Vector3.new(root.Position.X, 0, root.Position.Z)).Magnitude <= 40 then
                            return cast.pos
                        end
                        local pos
                        pcall(function()
                            local params = RaycastParams.new()
                            params.IgnoreWater                = false
                            params.RespectCanCollide          = false
                            params.FilterType                 = Enum.RaycastFilterType.Exclude
                            params.FilterDescendantsInstances = RaycastUtility:getFilteredTargets(LocalPlayer)
                            local power  = (cast and cast.power) or 0.5
                            local origin = root.Position + root.CFrame.LookVector * (power * 15 + 10)
                            local hit    = workspace:Raycast(origin, Vector3.new(0, -(Constants.FishingDistance or 200), 0), params)
                            if hit then pos = hit.Position end
                        end)
                        return pos
                    end
                    local function findOrbItem(targetName)
                        local found = nil
                        pcall(function()
                            if not replionData then return end
                            for _, item in pairs(replionData:Get({"Inventory", "Items"}) or {}) do
                                local data = ItemUtility:GetItemData(item.Id)
                                if isOrbItem(data) and data.Data.Name == targetName then
                                    found = item
                                    break
                                end
                            end
                        end)
                        return found
                    end
                    local function getActivePool()
                        if not poolContainer then return nil, nil end
                        for _, f in ipairs(poolContainer:GetChildren()) do
                            if f:IsA("Folder") and f:GetAttribute("OwnerUserId") == LocalPlayer.UserId then
                                local state = f:GetAttribute("State")
                                if state == "Active" or state == "Pending" then
                                    return f, f:GetAttribute("ExpiresAt")
                                end
                            end
                        end
                        return nil, nil
                    end
                    local function waitForPoolExpired(poolFolder, expiresAt)
                        local expired = false
                        local done    = Instance.new("BindableEvent")
                        local conn    = poolFolder:GetAttributeChangedSignal("State"):Connect(function()
                            if poolFolder:GetAttribute("State") == "Expired" then
                                expired = true
                                done:Fire()
                            end
                        end)
                        task.spawn(function()
                            while not expired and _orb.enabled do
                                if math.ceil(expiresAt - workspace:GetServerTimeNow()) <= 0 then
                                    done:Fire()
                                    break
                                end
                                task.wait(1)
                            end
                            if not expired then done:Fire() end
                        end)
                        done.Event:Wait()
                        conn:Disconnect()
                        done:Destroy()
                    end
                    local function equipOrb(orbUUID)
                        if not replionData then return false, "Replion tidak tersedia" end
                        local slotKey = nil
                        local timeout = tick()
                        while tick() - timeout < 5 do
                            if not _orb.enabled then return false, "Disabled" end
                            local stillExists = false
                            pcall(function()
                                for _, item in pairs(replionData:Get({"Inventory", "Items"}) or {}) do
                                    if item.UUID == orbUUID then stillExists = true; break end
                                end
                            end)
                            if not stillExists then return false, "Item hilang dari inventory" end
                            local okEq, equippedItems = pcall(function()
                                return replionData:Get("EquippedItems")
                            end)
                            if not okEq then return false, "Replion error saat baca EquippedItems" end
                            for key, uuid in pairs(equippedItems or {}) do
                                if uuid == orbUUID then slotKey = key end
                            end
                            if slotKey then break end
                            pcall(function() NetEvents.RE_EquipItem:FireServer(orbUUID, "Gears") end)
                            task.wait(0.5)
                        end
                        if not slotKey then return false, "Equip timeout" end
                        pcall(function() NetEvents.RF_EquipToolFromHotbar:FireServer(slotKey) end)
                        task.wait(0.4)
                        local timeout2 = tick()
                        while tick() - timeout2 < 3 do
                            if not _orb.enabled then return false, "Disabled" end
                            local okChk, heldId, heldType = pcall(function()
                                return replionData:Get("EquippedId"), replionData:Get("EquippedType")
                            end)
                            if not okChk then return false, "Replion error saat verifikasi equip" end
                            if (heldId or "") == orbUUID and (heldType or "") == "Gears" then
                                return true
                            end
                            task.wait(0.2)
                        end
                        return true
                    end
                    local function throwOrb(item, pos)
                        if not NetEvents.RF_ThrowBathBomb then return false, "Remote tidak tersedia" end
                        _G.SetOrbThrowing(true)
                        pcall(function() NetEvents.RF_CancelFishingInputs:InvokeServer() end)
                        pcall(function() local ok, fc = pcall(function() return require(game:GetService("ReplicatedStorage").Controllers.FishingController) end); if ok and fc and fc.RequestClientStopFishing then fc:RequestClientStopFishing(true) end end)
                        pcall(function()
                            local char = game:GetService("Players").LocalPlayer.Character
                            if char and char:FindFirstChild("Humanoid") then
                                char.Humanoid:UnequipTools()
                            end
                        end)
                        task.wait(1.5)
                        local ok, err = equipOrb(item.UUID)
                        if not ok then 
                            _G.SetOrbThrowing(false)
                            return false, err 
                        end
                        local success = false
                        local errMsg  = "Throw gagal"
                        pcall(function()
                            local ok2, result = pcall(function()
                                return NetEvents.RF_ThrowBathBomb:InvokeServer(item.UUID, pos)
                            end)
                            if ok2 and typeof(result) == "table" then
                                if result.Success == true then
                                    success = true
                                else
                                    errMsg = result.ErrorMessage or "Throw ditolak server"
                                end
                            else
                                errMsg = tostring(result)
                            end
                        end)
                        _G.SetOrbThrowing(false)
                        task.wait(1.5)
                        return success, errMsg
                    end
                    while _orb.enabled do
                        if selectedOrb == "" then task.wait(2); continue end
                        if not replionData then replionData = Replion.Client:GetReplion("Data") end
                        local activePool, expiresAt = getActivePool()
                        if activePool then
                            waitForPoolExpired(activePool, expiresAt)
                            if not _orb.enabled then break end
                            task.wait(1)
                            continue
                        end
                        local item = findOrbItem(selectedOrb)
                        if not item then task.wait(5); continue end
                        local pos = getFishingThrowPosition()
                        if not pos then task.wait(3); continue end
                        local ok, err = throwOrb(item, pos)
                        if ok then
                            throwCount = throwCount + 1
                            Library:MakeNotify({
                                Title       = "Auto Orb",
                                Description = string.format("%s #%d dilempar!", selectedOrb, throwCount),
                                Delay       = 3,
                            })
                            task.wait(2)
                        else
                            failCount = failCount + 1
                            Library:MakeNotify({ Title = "Auto Orb", Description = "Throw gagal: " .. err, Delay = 3 })
                            task.wait(3)
                        end
                    end
                end)
            end,
        })
    end
    do
        local EnchantSection = AutoTab:AddSection("Enchant Features", false)
        local TYPE_ORDER = {
            "Normal Enchant", "Second Enchant", "Evolved Enchant",
            "Candy Enchant", "Eggy Enchant", "Runic Enchant",
        }
        local ENCHANT_TYPES = {
            ["Normal Enchant"]  = { stone = 10,  slot = 1 },
            ["Second Enchant"]  = { stone = 246, slot = 2 },
            ["Evolved Enchant"] = { stone = 558, slot = 1 },
            ["Candy Enchant"]   = { stone = 714, slot = 1 },
            ["Eggy Enchant"]    = { stone = 873, slot = 1 },
            ["Runic Enchant"]   = { stone = 929, slot = 1 },
        }
        local EQUIP_TIMEOUT, ROLL_TIMEOUT, ROLL_COOLDOWN = 5, 5, 1.5
        local _en = {
            enabled = false, thread = nil, statusThread = nil, updateConn = nil,
            stone = 10, slot = 1, targetId = 10, targetName = "XPerienced I",
            waiting = false, rolledId = nil, rolls = 0,
        }
        local toggleRef
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Auto Enchant", Description = desc, Delay = delay or 3 })
        end
        local function getData()
            local ok, data = pcall(getCachedReplionData)
            return ok and data or nil
        end
        local function itemUtility()
            local ok, util = pcall(cachedRequire, ReplicatedStorage.Shared.ItemUtility)
            return ok and util or nil
        end
        local enchantMapping, enchantNames = {}, {}
        pcall(function()
            local folder = ReplicatedStorage:FindFirstChild("Enchants")
                or ReplicatedStorage:WaitForChild("Enchants", 5)
            if not folder then return end
            for _, child in ipairs(folder:GetChildren()) do
                if child:IsA("ModuleScript") then
                    local ok, data = pcall(require, child)
                    if ok and data and data.Data and data.Data.Name and data.Data.Id then
                        enchantMapping[data.Data.Name] = data.Data.Id
                        table.insert(enchantNames, data.Data.Name)
                    end
                end
            end
            table.sort(enchantNames)
        end)
        local function getEquippedRod()
            local data = getData()
            if not data then return nil end
            local equipped = data:Get("EquippedItems") or {}
            local rods     = data:Get({ "Inventory", "Fishing Rods" }) or {}
            for _, uuid in pairs(equipped) do
                for _, rod in ipairs(rods) do
                    if rod.UUID == uuid then return rod end
                end
            end
            return nil
        end
        local function currentEnchantId()
            local rod = getEquippedRod()
            local meta = rod and rod.Metadata
            if not meta then return nil end
            return if _en.slot == 2 then meta.EnchantId2 else meta.EnchantId
        end
        local function findStones()
            local data = getData()
            if not data then return 0, nil end
            local ok, items = pcall(function() return data:GetExpect({ "Inventory", "Items" }) end)
            if not ok or type(items) ~= "table" then return 0, nil end
            local count, first = 0, nil
            for _, item in pairs(items) do
                if item.Id == _en.stone then
                    count += 1
                    first = first or item.UUID
                end
            end
            return count, first
        end
        local StatusParagraph = EnchantSection:AddParagraph({
            Title   = "Enchant Status",
            Content = "Current Rod : None\nEnchant 1 : None\nEnchant 2 : None\nEnchant Stones Left : 0",
        })
        local function enchantName(id)
            if not id then return "None" end
            local util = itemUtility()
            local ok, data = pcall(function() return util:GetEnchantData(id) end)
            return (ok and data and data.Data and data.Data.Name) or "None"
        end
        local function refreshStatus()
            local rod  = getEquippedRod()
            local meta = rod and rod.Metadata
            local rodName = "None"
            if rod then
                local util = itemUtility()
                local ok, data = pcall(function() return util:GetItemData(rod.Id) end)
                rodName = (ok and data and data.Data and data.Data.Name) or "None"
            end
            StatusParagraph:SetContent(
                ("Current Rod : %s\nEnchant 1 : %s\nEnchant 2 : %s\nEnchant Stones Left : %d"):format(
                    rodName, enchantName(meta and meta.EnchantId), enchantName(meta and meta.EnchantId2), (findStones())
                )
            )
        end
        local function findUpdateRemote()
            local index = ReplicatedStorage:FindFirstChild("Packages")
            index = index and index:FindFirstChild("_Index")
            if not index then return nil end
            for _, pkg in ipairs(index:GetChildren()) do
                if pkg.Name:lower():find("replion") then
                    local ok, remote = pcall(function() return pkg.replion.Remotes.Update end)
                    if ok and remote then return remote end
                end
            end
            return nil
        end
        local function disconnectListener()
            if _en.updateConn then
                pcall(function() _en.updateConn:Disconnect() end)
                _en.updateConn = nil
            end
        end
        local function connectListener()
            if _en.updateConn then return end
            local remote = findUpdateRemote()
            if not remote then return end
            _en.updateConn = remote.OnClientEvent:Connect(function(_, path, value)
                if not (_en.enabled and _en.waiting) then return end
                if type(path) ~= "table" or #path < 4 then return end
                if path[1] ~= "Inventory" or path[2] ~= "Fishing Rods" or path[4] ~= "Metadata" then return end
                local field = if _en.slot == 2 then "EnchantId2" else "EnchantId"
                local rolled
                if path[5] == field then
                    rolled = value
                elseif type(value) == "table" then
                    rolled = value[field]
                end
                rolled = rolled or currentEnchantId()
                if not rolled then return end
                _en.rolls   += 1
                _en.rolledId = rolled
                _en.waiting  = false
            end)
        end
        local function stopStatusLoop()
            if _en.statusThread then
                pcall(task.cancel, _en.statusThread)
                _en.statusThread = nil
            end
        end
        local function rollLoop()
            while _en.enabled do
                local char = LocalPlayer.Character
                if not (char and char:FindFirstChild("HumanoidRootPart")) then
                    task.wait(1)
                    continue
                end
                local _, stoneUUID = findStones()
                if not stoneUUID then
                    notify("Out of enchant stones!", 4)
                    break
                end
                local slotKey
                local deadline = tick() + EQUIP_TIMEOUT
                while _en.enabled and tick() < deadline do
                    local data = getData()
                    for key, uuid in pairs(data and data:Get("EquippedItems") or {}) do
                        if uuid == stoneUUID then slotKey = key; break end
                    end
                    if slotKey then break end
                    safeFire(function() NetEvents.RE_EquipItem:FireServer(stoneUUID, "Enchant Stones") end)
                    task.wait(0.5)
                end
                if not slotKey then
                    task.wait(1)
                    continue
                end
                safeFire(function() NetEvents.RF_EquipToolFromHotbar:FireServer(slotKey) end)
                task.wait(0.4)
                if not _en.enabled then break end
                safeFire(function()
                    if _en.slot == 2 then
                        NetEvents.RE_ActivateSecondEnchantingAltar:FireServer()
                    else
                        NetEvents.RE_ActivateEnchantingAltar:FireServer()
                    end
                end)
                task.wait(0.6)
                if not _en.enabled then break end
                local before = currentEnchantId()
                _en.waiting, _en.rolledId = true, nil
                safeFire(function() NetEvents.RE_RollEnchant:FireServer() end)
                local rollDeadline = tick() + ROLL_TIMEOUT
                while _en.enabled and _en.waiting and tick() < rollDeadline do task.wait(0.1) end
                if _en.waiting then
                    _en.waiting = false
                    local after = currentEnchantId()
                    if after and after ~= before then
                        _en.rolledId = after
                        _en.rolls   += 1
                    else
                        task.wait(1.5)
                        continue
                    end
                end
                if (_en.rolledId or currentEnchantId()) == _en.targetId then
                    notify("Successfully obtained enchant: " .. _en.targetName, 5)
                    break
                end
                local cooldown = tick() + ROLL_COOLDOWN
                while _en.enabled and tick() < cooldown do task.wait(0.5) end
            end
        end
        EnchantSection:AddDropdown({
            Title    = "Enchant Type",
            Options  = TYPE_ORDER,
            Default  = "Normal Enchant",
            Callback = function(value)
                local t = ENCHANT_TYPES[value] or ENCHANT_TYPES["Normal Enchant"]
                _en.stone, _en.slot = t.stone, t.slot
            end,
        })
        EnchantSection:AddDropdown({
            Title    = "Target Enchant",
            Options  = enchantNames,
            Default  = "XPerienced I",
            Callback = function(value)
                local id = enchantMapping[value]
                if id then
                    _en.targetId, _en.targetName = id, value
                end
            end,
        })
        toggleRef = EnchantSection:AddToggle({
            Title    = "Auto Enchant Reroll",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _en.enabled = on
                _en.waiting = false
                if _en.thread then pcall(task.cancel, _en.thread); _en.thread = nil end
                stopStatusLoop()
                if not on then
                    disconnectListener()
                    return
                end
                if currentEnchantId() == _en.targetId then
                    _en.enabled = false
                    notify("Rod already has enchant: " .. _en.targetName)
                    task.defer(function() pcall(function() toggleRef:SetValue(false) end) end)
                    return
                end
                _en.rolls, _en.rolledId = 0, nil
                connectListener()
                _en.statusThread = task.spawn(function()
                    while _en.enabled do
                        pcall(refreshStatus)
                        task.wait(2)
                    end
                end)
                _en.thread = task.spawn(function()
                    rollLoop()
                    _en.enabled = false
                    _en.thread  = nil
                    disconnectListener()
                    stopStatusLoop()
                    pcall(function() toggleRef:SetValue(false) end)
                end)
            end,
        })
        local function teleportTo(cf)
            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            hrp.CFrame                  = cf
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
        EnchantSection:AddButton({
            Title    = "Teleport to Altar 1",
            Callback = function() teleportTo(CFrame.new(3245, -1301, 1394)) end,
        })
        EnchantSection:AddButton({
            Title    = "Teleport to Altar 2",
            Callback = function()
                teleportTo(CFrame.new(
                    1479.35742, 124.582748, -604.037476,
                    -0.171021342, 0.0301617607, 0.984805524,
                    0.173656046, 0.984806359, -4.67896461e-06,
                    -0.969842851, 0.171016648, -0.173660636
                ))
            end,
        })
    end
    do
        local TranscendedSection = AutoTab:AddSection("Create Transcended Stone", false)
        local _tr = {
            enabled = false,
            thread  = nil,
            amount  = 1,
            target  = nil,
            counts  = {},   
            busy    = false, 
        }
        local fishDropdown, toggleRef
        local function notify(desc, delay)
            Library:MakeNotify({ Title = "Transcended Stone", Description = desc, Delay = delay or 3 })
        end
        local function scanSecretFish()
            local data = getCachedReplionData()
            if not data then return {}, {} end
            local ItemUtility = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
            local TierUtility = cachedRequire(ReplicatedStorage.Shared.TierUtility)
            local ok, items = pcall(function() return data:GetExpect({ "Inventory", "Items" }) end)
            if not ok or type(items) ~= "table" then return {}, {} end
            local counts, firstUUID = {}, {}
            for _, item in ipairs(items) do
                if item.Favorited ~= true and item.UUID then
                    local d = ItemUtility.GetItemDataFromItemType("Fish", item.Id)
                    if d and d.Data and d.Data.Type == "Fish" and d.Probability then
                        local tier = TierUtility:GetTierFromRarity(d.Probability.Chance)
                        if tier and tier.Tier == 7 then
                            local name = d.Data.Name or tostring(item.Id)
                            counts[name] = (counts[name] or 0) + 1
                            if not firstUUID[name] then firstUUID[name] = item.UUID end
                        end
                    end
                end
            end
            return counts, firstUUID
        end
        local function displayOptions(counts)
            local opts = {}
            for name, n in pairs(counts) do
                if n > 0 then table.insert(opts, name .. " x" .. n) end
            end
            table.sort(opts)
            return opts
        end
        local function stripCount(label)
            return label and (label:match("^(.-)%s+x%d+$") or label) or nil
        end
        local function refreshFishList()
            local counts = scanSecretFish()
            _tr.counts = counts
            local opts = displayOptions(counts)
            pcall(function() fishDropdown:SetOptions(opts) end)
            if not (_tr.target and counts[_tr.target]) then
                _tr.target = stripCount(opts[1])
            end
            return #opts
        end
        local function uuidQueueFor(targetName)
            local data = getCachedReplionData()
            if not data then return {} end
            local ItemUtility = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
            local TierUtility = cachedRequire(ReplicatedStorage.Shared.TierUtility)
            local ok, items = pcall(function() return data:GetExpect({ "Inventory", "Items" }) end)
            if not ok or type(items) ~= "table" then return {} end
            local q = {}
            for _, item in ipairs(items) do
                if item.Favorited ~= true and item.UUID then
                    local d = ItemUtility.GetItemDataFromItemType("Fish", item.Id)
                    if d and d.Data and d.Data.Type == "Fish" and d.Probability
                        and (d.Data.Name or "") == targetName then
                        local tier = TierUtility:GetTierFromRarity(d.Probability.Chance)
                        if tier and tier.Tier == 7 then q[#q + 1] = item.UUID end
                    end
                end
            end
            return q
        end
        local function uuidStillOwned(uuid)
            local data = getCachedReplionData()
            if not data then return false end
            for _, item in ipairs(data:Get({ "Inventory", "Items" }) or {}) do
                if item.UUID == uuid then return true end
            end
            return false
        end
        local function slotOfUUID(data, uuid)
            for key, id in pairs(data:Get("EquippedItems") or {}) do
                if id == uuid then return key end
            end
            return nil
        end
        local function waitUntil(check, timeout)
            local deadline = os.clock() + (timeout or 3)
            while _tr.enabled do
                local ok, done = pcall(check)
                if ok and done then return true end
                if os.clock() >= deadline then return false end
                task.wait(0.05)
            end
            return false
        end
        local function makeOneStone(uuid)
            local data = getCachedReplionData()
            if not data then return false, "Data pemain belum siap." end
            if not uuidStillOwned(uuid) then return false, "SKIP" end
            local slot = slotOfUUID(data, uuid)
            if not slot then
                safeFire(function() NetEvents.RE_EquipItem:FireServer(uuid, "Fish") end)
                if not waitUntil(function() return slotOfUUID(data, uuid) ~= nil end, 3) then
                    return false, "Ikan tidak masuk hotbar."
                end
                slot = slotOfUUID(data, uuid)
            end
            if data:Get("EquippedId") ~= uuid then
                safeFire(function() NetEvents.RF_EquipToolFromHotbar:FireServer(slot) end)
                if not waitUntil(function() return data:Get("EquippedId") == uuid end, 3) then
                    return false, "Ikan gagal dipegang."
                end
            end
            local rf = NetEvents.RF_CreateTranscendedStone
            if not rf then return false, "Remote tidak ditemukan." end
            for step, page in ipairs({ 3, 2, 2 }) do
                safeFire(function() NetEvents.RE_DialogueEnded:FireServer("Temple Guardian", step, page) end)
            end
            task.wait(0.15)
            local invoked, result, err = pcall(function() return rf:InvokeServer() end)
            if not invoked then return false, "Invoke gagal." end
            if not result then return false, tostring(err or "Ditolak server.") end
            waitUntil(function() return not uuidStillOwned(uuid) end, 3)
            return true
        end
        TranscendedSection:AddParagraph({
            Title   = "Info",
            Content = "[EN] Unfavorite the secret fish first! Favorited fish are skipped and never show up in the dropdown.\n"
                .. "[ID] Unfavorite dulu ikan secret-nya! Ikan yang masih di-favorite akan dilewati dan tidak akan muncul di dropdown.",
        })
        fishDropdown = TranscendedSection:AddDropdown({
            Title    = "Select Secret Fish",
            Options  = {},
            Default  = "",
            NoSave   = true,
            Callback = function(selected)
                if not selected or selected == "" then return end
                _tr.target = stripCount(selected)
            end,
        })
        TranscendedSection:AddButton({
            Title    = "Refresh Fish List",
            Callback = function()
                if _tr.busy then
                    notify("Sedang berjalan — tunggu selesai dulu.", 2)
                    return
                end
                local n = refreshFishList()
                notify(n > 0 and (n .. " jenis ikan secret ditemukan.")
                    or "Tidak ada ikan secret yang belum di-favorite.", 4)
            end,
        })
        TranscendedSection:AddInput({
            Title    = "Amount",
            Default  = "1",
            Callback = function(value)
                local num = tonumber(value)
                if num and num > 0 then _tr.amount = math.floor(num) end
            end,
        })
        toggleRef = TranscendedSection:AddToggle({
            Title    = "Enable Auto Create",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                if not on then
                    local wasRunning = _tr.enabled
                    _tr.enabled = false
                    if wasRunning then notify("Stopped.", 2) end
                    return
                end
                if _tr.busy then
                    notify("Masih ada proses berjalan.", 2)
                    return
                end
                if not _tr.target then refreshFishList() end
                if not _tr.target then
                    notify("Tidak ada ikan secret yang belum di-favorite.", 4)
                    pcall(function() toggleRef:SetValue(false) end)
                    return
                end
                _tr.enabled = true
                _tr.busy    = true
                _tr.thread = task.spawn(function()
                    local created, failStreak = 0, 0
                    local name = _tr.target
                    local queue = uuidQueueFor(name)
                    local head  = 1
                    notify(("Starting... %d %s siap dipakai."):format(#queue, tostring(name)), 2)
                    while _tr.enabled and created < _tr.amount do
                        if not name then
                            notify("Belum ada ikan yang dipilih. Refresh dulu.", 4)
                            break
                        end
                        if head > #queue then
                            queue, head = uuidQueueFor(name), 1
                            if #queue == 0 then
                                notify(name .. " habis. Proses berhenti.", 4)
                                break
                            end
                        end
                        local uuid = queue[head]
                        head = head + 1
                        local ok, err = makeOneStone(uuid)
                        if ok then
                            created = created + 1
                            failStreak = 0
                            notify("Created " .. created .. " of " .. _tr.amount)
                        elseif err == "SKIP" then
                        else
                            failStreak = failStreak + 1
                            notify(err or "Creation failed.")
                            if failStreak >= 3 then
                                notify("Gagal 3x berturut-turut. Berhenti.", 5)
                                break
                            end
                            queue, head = uuidQueueFor(name), 1
                            task.wait(1)
                        end
                    end
                    if created >= _tr.amount and created > 0 then
                        notify("All " .. created .. " stones created!", 4)
                    end
                    _tr.enabled = false
                    _tr.busy    = false
                    _tr.thread  = nil
                    pcall(function() toggleRef:SetValue(false) end)
                    pcall(refreshFishList)
                end)
            end,
        })
    end
    do
        local TotemSection = AutoTab:AddSection("Spawn Totem", false)
        local _totemState = {
            enabled       = false,
            task          = nil,
            selectedTotem = nil,
            data          = nil,
            totemMap      = {},
            totemNames    = {},
            placedUUID    = nil,
        }
        local _totemDropdownRef = nil
        local function _scanTotems()
            _totemState.totemMap   = {}
            _totemState.totemNames = {}
            pcall(function()
                local folder = ReplicatedStorage:FindFirstChild("Totems")
                if not folder then return end
                for _, mod in ipairs(folder:GetChildren()) do
                    if mod:IsA("ModuleScript") then
                        local ok, data = pcall(function() return require(mod) end)
                        if ok and type(data) == "table" and data.Data and data.Data.Id then
                            local name = data.Data.Name or mod.Name
                            _totemState.totemMap[name] = data.Data.Id
                            table.insert(_totemState.totemNames, name)
                        end
                    end
                end
                table.sort(_totemState.totemNames)
            end)
        end
        task.spawn(function()
            _scanTotems()
            _totemState.selectedTotem = _totemState.totemNames[1]
            if _totemDropdownRef and _totemDropdownRef.SetOptions then
                _totemDropdownRef:SetOptions(
                    #_totemState.totemNames > 0 and _totemState.totemNames or { "No Totems Found" }
                )
            end
        end)
        _totemDropdownRef = TotemSection:AddDropdown({
            Title    = "Totem Type",
            Options  = #_totemState.totemNames > 0 and _totemState.totemNames or { "Loading..." },
            Default  = nil,
            Callback = function(selected)
                _totemState.selectedTotem = selected
            end,
        })
        TotemSection:AddButton({
            Title    = "Refresh Totem List",
            Callback = function()
                _scanTotems()
                if _totemDropdownRef and _totemDropdownRef.SetOptions then
                    _totemDropdownRef:SetOptions(
                        #_totemState.totemNames > 0 and _totemState.totemNames or { "No Totems Found" }
                    )
                end
            end,
        })
        TotemSection:AddToggle({
            Title    = "Enable Auto Spawn",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                if on then
                    if _totemState.enabled then return end
                    if not _totemState.data then
                        pcall(function() _totemState.data = getCachedReplionData() end)
                        if not _totemState.data then
                            local rep = getCachedReplion()
                            if rep then _totemState.data = rep.Client:WaitReplion("Data") end
                        end
                    end
                    if not _totemState.data then
                        warn("[AutoSpawn] Data belum siap!"); return
                    end
                    if not NetEvents.IsInitialized then
                        warn("[AutoSpawn] EventResolver belum siap!"); return
                    end
                    _totemState.placedUUID = nil
                    _totemState.enabled = true
                    local function pickFromInventory()
                        local targetId = _totemState.totemMap[_totemState.selectedTotem]
                        if not targetId then return nil end
                        local ok, inv = pcall(function() return _totemState.data:Get("Inventory") end)
                        if not ok or not inv or not inv.Totems then return nil end
                        for _, item in pairs(inv.Totems) do
                            if item and item.UUID and tonumber(item.Id) == targetId then
                                return item.UUID
                            end
                        end
                        return nil
                    end
                    _totemState.task = task.spawn(function()
                        while _totemState.enabled do
                            local ok, boosts = pcall(function()
                                return _totemState.data:Get("TotemBoosts")
                            end)
                            local active = ok and type(boosts) == "table" and boosts[1] or nil
                            if active then
                                _totemState.placedUUID = active.TotemUUID or _totemState.placedUUID
                            else
                                if _totemState.placedUUID then
                                    safeFire(function()
                                        NetEvents.RE_TotemPickup:FireServer(_totemState.placedUUID)
                                    end)
                                    _totemState.placedUUID = nil
                                    task.wait(2)
                                end
                                local fresh = pickFromInventory()
                                if fresh and LocalPlayer.Character then
                                    safeFire(function()
                                        NetEvents.RE_SpawnTotem:FireServer(fresh)
                                    end)
                                    task.wait(1.5)
                                    local okAfter, after = pcall(function()
                                        return _totemState.data:Get("TotemBoosts")
                                    end)
                                    local placed = okAfter and type(after) == "table" and after[1] or nil
                                    _totemState.placedUUID = placed and placed.TotemUUID or nil
                                end
                            end
                            task.wait(3)
                        end
                    end)
                    Library:MakeNotify({ Title = "Auto Spawn Totem", Description = "Aktif.", Delay = 2 })
                else
                    _totemState.enabled = false
                    _totemState.placedUUID = nil
                    if _totemState.task then
                        task.cancel(_totemState.task)
                        _totemState.task = nil
                    end
                    Library:MakeNotify({ Title = "Auto Spawn Totem", Description = "Dihentikan.", Delay = 2 })
                end
            end,
        })
        TotemSection:AddButton({
            Title    = "Spawn Now",
            Callback = function()
                if not _totemState.data then
                    pcall(function() _totemState.data = getCachedReplionData() end)
                end
                if not _totemState.data then return end
                local totemUUID = nil
                pcall(function()
                    local targetId = _totemState.totemMap[_totemState.selectedTotem]
                    if not targetId then return end
                    local ok, inv = pcall(function()
                        return _totemState.data:Get("Inventory")
                    end)
                    if ok and inv and inv.Totems then
                        for _, item in pairs(inv.Totems) do
                            if item and item.UUID and tonumber(item.Id) == targetId then
                                if (item.Count or 1) >= 1 then
                                    totemUUID = item.UUID
                                    break
                                end
                            end
                        end
                    end
                end)
                if totemUUID then
                    pcall(function()
                        NetEvents.RE_SpawnTotem:FireServer(totemUUID)
                    end)
                end
            end,
        })
    end
    do
        local TotemSection = AutoTab:AddSection("Spawn 4X Totem(Mix)[BETA]", false)
        local TITLE           = "4x Totem Mix"
        local SLOT_NONE       = "None (Skip)"
        local SLOT_COUNT      = 4
        local MISSING_CONFIRM = 3
        local MAX_RETRY       = 3
        local NEAR_SPOT       = 10
        local STREAM_RADIUS   = 150
        local TWEEN_SPEED, SETTLE_DELAY, SPAWN_GAP = 40, 1, 2.5
        local SPOT_OFFSETS = {
            Vector3.new(-50.1, 0, -50.1),
            Vector3.new( 50.1, 0, -50.1),
            Vector3.new(-50.1, 0,  50.1),
            Vector3.new( 50.1, 0,  50.1),
        }
        local MIN_GAP = 100.2
        local ALL_STATES = {
            Enum.HumanoidStateType.Running, Enum.HumanoidStateType.Swimming,
            Enum.HumanoidStateType.Jumping, Enum.HumanoidStateType.GettingUp,
            Enum.HumanoidStateType.Freefall, Enum.HumanoidStateType.Landed,
            Enum.HumanoidStateType.Climbing, Enum.HumanoidStateType.FallingDown,
            Enum.HumanoidStateType.Physics, Enum.HumanoidStateType.Ragdoll,
            Enum.HumanoidStateType.PlatformStanding, Enum.HumanoidStateType.RunningNoPhysics,
            Enum.HumanoidStateType.StrafingNoPhysics, Enum.HumanoidStateType.Seated,
            Enum.HumanoidStateType.Flying,
        }
        local _totem = {
            active = false, thread = nil, monitorThread = nil,
            stateConn = nil, holdConn = nil, noclipConn = nil, physicsSession = 0,
            totemMap = {}, totemNames = {}, selectedSlots = {}, data = nil,
            placed = {}, failed = {}, basePos = nil,
            session = 0, restoring = false, weEquippedTank = false,
        }
        local function alive(sess) return _totem.active and _totem.session == sess end
        local _totemOriginal = { saved = false, AnimateEnabled = true, CFrame = nil, CanCollide = {} }
        local _dropdownRefs  = {}
        local function notify(desc, delay)
            Library:MakeNotify({ Title = TITLE, Description = desc, Delay = delay or 3 })
        end
        local function _scanTotems()
            _totem.totemMap, _totem.totemNames = {}, {}
            pcall(function()
                local folder = ReplicatedStorage:FindFirstChild("Totems")
                if not folder then return end
                for _, mod in ipairs(folder:GetChildren()) do
                    if mod:IsA("ModuleScript") then
                        local ok, data = pcall(require, mod)
                        if ok and type(data) == "table" and data.Data and data.Data.Id then
                            local name = data.Data.Name or mod.Name
                            _totem.totemMap[name] = data.Data.Id
                            table.insert(_totem.totemNames, name)
                        end
                    end
                end
                table.sort(_totem.totemNames)
            end)
        end
        local function slotOptions()
            local opts = { SLOT_NONE }
            for _, name in ipairs(_totem.totemNames) do table.insert(opts, name) end
            return opts
        end
        local function _updateDropdowns()
            local opts = slotOptions()
            for i = 1, SLOT_COUNT do
                if _dropdownRefs[i] and _dropdownRefs[i].SetOptions then _dropdownRefs[i]:SetOptions(opts) end
                if _totem.selectedSlots[i] and not _totem.totemMap[_totem.selectedSlots[i]] then
                    _totem.selectedSlots[i] = nil
                end
            end
        end
        local function inventoryTotems()
            local ok, inv = pcall(function() return _totem.data and _totem.data:Get("Inventory") end)
            return (ok and inv and inv.Totems) or {}
        end
        local function serverNow() return workspace:GetServerTimeNow() end
        local function totemNear(pos, ignore)
            local folder = workspace:FindFirstChild("Totems")
            if not folder then return nil end
            for _, m in ipairs(folder:GetChildren()) do
                if m:IsA("Model") and not (ignore and ignore[m]) and (m:GetPivot().Position - pos).Magnitude <= NEAR_SPOT then
                    return m
                end
            end
            return nil
        end
        local function expireOf(model)
            local handle = model and model:FindFirstChild("Handle")
            return handle and tonumber(handle:GetAttribute("ExpireTime")) or nil
        end
        local function inInventory(uuid)
            for _, item in pairs(inventoryTotems()) do
                if item and item.UUID == uuid then return true end
            end
            return false
        end
        local function slotSpot(si)
            return _totem.basePos + SPOT_OFFSETS[si]
        end
        local function clearSpot(spot, gap)
            gap = gap or MIN_GAP
            local folder = workspace:FindFirstChild("Totems")
            if not folder then return spot end
            local function dir(v, fallback) return v ~= 0 and math.sign(v) or (fallback >= 0 and 1 or -1) end
            for _ = 1, 4 do
                local moved = false
                for _, m in ipairs(folder:GetChildren()) do
                    local d = spot - m:GetPivot().Position
                    if math.abs(d.X) < gap and math.abs(d.Z) < gap then
                        local sx, sz = gap - math.abs(d.X), gap - math.abs(d.Z)
                        local away = spot - _totem.basePos
                        spot += sx <= sz and Vector3.new(dir(d.X, away.X) * sx, 0, 0) or Vector3.new(0, 0, dir(d.Z, away.Z) * sz)
                        moved = true
                    end
                end
                if not moved then break end
            end
            return spot
        end
        local BOX_REACH = 51
        local function outOfReach(pos)
            local out = {}
            for si, p in pairs(_totem.placed) do
                local t = (p.model and p.model.Parent and p.model:GetPivot().Position) or p.spot
                if math.abs(t.X - pos.X) > BOX_REACH or math.abs(t.Z - pos.Z) > BOX_REACH then out[#out + 1] = si end
            end
            table.sort(out)
            return out
        end
        local function recordPlaced(si, model, spot)
            _totem.placed[si] = { model = model, spot = spot, expire = expireOf(model) or (serverNow() + 3600), missing = 0 }
            _totem.failed[si] = nil
        end
        local function recordFailed(si)
            local f = _totem.failed[si] or { count = 0 }
            f.count += 1
            f.retryAt = serverNow() + 30 * f.count
            _totem.failed[si] = f
            notify(("Slot %d gagal dipasang (%d/%d)."):format(si, f.count, MAX_RETRY), 3)
        end
        local function spawnAndConfirm(uuid, pos)
            local before = {}
            local folder = workspace:FindFirstChild("Totems")
            for _, m in ipairs(folder and folder:GetChildren() or {}) do before[m] = true end
            safeFire(function() NetEvents.RE_SpawnTotem:FireServer(uuid) end)
            local deadline = os.clock() + 4
            repeat
                task.wait(0.25)
                local model = totemNear(pos, before)
                if model then return model end
            until os.clock() > deadline
            if not inInventory(uuid) then return false end
            return nil
        end
        local function allocateUUIDs(slots)
            local used, uuids, missing = {}, {}, {}
            local inv = inventoryTotems()
            for _, si in ipairs(slots) do
                local name = _totem.selectedSlots[si]
                local id   = name and _totem.totemMap[name]
                if id then
                    for _, item in pairs(inv) do
                        if item and item.UUID and tonumber(item.Id) == id and not used[item.UUID] then
                            uuids[si], used[item.UUID] = item.UUID, true
                            break
                        end
                    end
                    if not uuids[si] then table.insert(missing, name) end
                end
            end
            return uuids, missing
        end
        local function getFlyPart()
            local c = LocalPlayer.Character
            return c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Torso") or c:FindFirstChild("UpperTorso"))
        end
        local ADVANCED_TANK, DIVING_GEAR = 575, 105
        local function currentTank()
            local ok, id = pcall(function() return _totem.data and _totem.data:Get("EquippedOxygenTankId") end)
            return ok and id or nil
        end
        local function wearTank(id)
            safeFire(function() NetEvents.RF_EquipOxygenTank:InvokeServer(id) end)
            for _ = 1, 10 do
                if currentTank() == id then return true end
                task.wait(0.1)
            end
            return false
        end
        local function equipO2()
            local before = currentTank()
            if before == ADVANCED_TANK or before == DIVING_GEAR then return end
            if not _totem.weEquippedTank then _totem.tankBefore = before end
            _totem.weEquippedTank = true
            if wearTank(ADVANCED_TANK) or wearTank(DIVING_GEAR) then return end
            safeFire(function() NetEvents.RF_PurchaseGear:InvokeServer(DIVING_GEAR) end)
            if not wearTank(DIVING_GEAR) then notify("Gagal pakai Diving Gear, hati-hati tenggelam!", 4) end
        end
        local function unequipO2()
            if not _totem.weEquippedTank then return end
            _totem.weEquippedTank = false
            local before = _totem.tankBefore
            _totem.tankBefore = nil
            if before and before ~= 0 then
                wearTank(before)
            else
                safeFire(function() NetEvents.RF_UnequipOxygenTank:InvokeServer() end)
            end
        end
        local function saveOriginalState(cf)
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if not hum or _totemOriginal.saved then return end
            _totemOriginal.saved  = true
            _totemOriginal.CFrame = cf
            _totemOriginal.CanCollide = {}
            _totemOriginal.AnimateEnabled = not (char:FindFirstChild("Animate") and char.Animate.Disabled)
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") then _totemOriginal.CanCollide[part] = part.CanCollide end
            end
        end
        local function zeroVelocity(part)
            if part and part.Parent then
                part.AssemblyLinearVelocity  = Vector3.zero
                part.AssemblyAngularVelocity = Vector3.zero
            end
        end
        local function stopHold()
            if _totem.holdConn then _totem.holdConn:Disconnect(); _totem.holdConn = nil end
        end
        local function restoreOriginalState()
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            local mp   = char and char:FindFirstChild("HumanoidRootPart")
            local cf   = _totemOriginal.CFrame or (mp and mp.CFrame)
            stopHold()
            if _totem.stateConn  then _totem.stateConn:Disconnect();  _totem.stateConn  = nil end
            if _totem.noclipConn then _totem.noclipConn:Disconnect(); _totem.noclipConn = nil end
            _totem.physicsSession = _totem.physicsSession + 1
            if not (_totemOriginal.saved or _totem.physicsApplied) then return end
            _totem.physicsApplied = false
            pcall(function()
                for _, v in ipairs(mp and mp:GetChildren() or {}) do
                    if v.Name == "FlyGuiGyro" or v.Name == "FlyGuiVelocity" then v:Destroy() end
                end
            end)
            task.wait(0.15)
            pcall(function()
                for part, was in pairs(_totemOriginal.CanCollide) do
                    if part and part.Parent then part.CanCollide = was end
                end
            end)
            if hum then
                for _, st in ipairs(ALL_STATES) do pcall(function() hum:SetStateEnabled(st, true) end) end
                hum.PlatformStand = false
                pcall(function() hum:ChangeState(Enum.HumanoidStateType.Freefall) end)
            end
            pcall(function()
                if char and char:FindFirstChild("Animate") then
                    char.Animate.Disabled = not _totemOriginal.AnimateEnabled
                end
            end)
            task.wait(0.1)
            pcall(function()
                if mp and cf then mp.CFrame = cf end
                zeroVelocity(mp)
            end)
            _totemOriginal.CFrame = nil
            _totemOriginal.CanCollide = {}
            _totemOriginal.saved = false
            if mp then
                task.spawn(function()
                    for _ = 1, 30 do
                        pcall(zeroVelocity, mp)
                        RunService.Heartbeat:Wait()
                    end
                end)
            end
        end
        local function enablePhysics(sess)
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            local mp   = getFlyPart()
            if not mp or not hum or not alive(sess) then return end
            _totem.physicsApplied = true
            _totem.physicsSession = _totem.physicsSession + 1
            local ses = _totem.physicsSession
            pcall(function() if char:FindFirstChild("Animate") then char.Animate.Disabled = true end end)
            hum.PlatformStand = true
            pcall(function() for _, st in ipairs(ALL_STATES) do hum:SetStateEnabled(st, false) end end)
            if _totem.stateConn then _totem.stateConn:Disconnect() end
            _totem.stateConn = RunService.Heartbeat:Connect((function()
                if alive(sess) and _totem.physicsSession == ses and hum.Parent then
                    pcall(function()
                        hum:SetStateEnabled(Enum.HumanoidStateType.Swimming, true)
                        hum:ChangeState(Enum.HumanoidStateType.Swimming)
                    end)
                end
            end))
            local bg = mp:FindFirstChild("FlyGuiGyro") or Instance.new("BodyGyro", mp)
            bg.Name, bg.P, bg.maxTorque, bg.CFrame = "FlyGuiGyro", 9e4, Vector3.new(9e9, 9e9, 9e9), mp.CFrame
            local bv = mp:FindFirstChild("FlyGuiVelocity") or Instance.new("BodyVelocity", mp)
            bv.Name, bv.velocity, bv.maxForce = "FlyGuiVelocity", Vector3.new(0, 0.1, 0), Vector3.new(9e9, 9e9, 9e9)
            local noclipParts = {}
            local function setNoCollide(part)
                if part and part:IsA("BasePart") then part.CanCollide = false; noclipParts[part] = true end
            end
            for _, p in ipairs(char:GetDescendants()) do setNoCollide(p) end
            if _totem.noclipConn then _totem.noclipConn:Disconnect() end
            _totem.noclipConn = char.DescendantAdded:Connect(function(desc)
                if alive(sess) and _totem.physicsSession == ses then setNoCollide(desc) end
            end)
            task.spawn(function()
                while alive(sess) and _totem.physicsSession == ses and char.Parent do
                    for part in pairs(noclipParts) do
                        if part.Parent then part.CanCollide = false else noclipParts[part] = nil end
                    end
                    if hum.Parent then hum.Health = hum.MaxHealth end
                    task.wait(0.25)
                end
            end)
        end
        local function flyTo(pos, sess)
            local mp = getFlyPart()
            if not mp or not alive(sess) then return end
            stopHold()
            local from    = mp.Position
            local dur     = math.max(1, (pos - from).Magnitude / TWEEN_SPEED)
            local elapsed = 0
            local conn
            conn = RunService.Heartbeat:Connect((function(dt)
                if not alive(sess) then
                    conn:Disconnect()
                    if _totem.holdConn == conn then _totem.holdConn = nil end
                    return
                end
                if not mp.Parent then return end
                elapsed = math.min(elapsed + dt, dur)
                local a = elapsed / dur
                local eased = if a < 0.5 then 2 * a * a else 1 - (-2 * a + 2) ^ 2 / 2
                mp.CFrame = CFrame.new(from:Lerp(pos, eased))
                zeroVelocity(mp)
            end))
            _totem.holdConn = conn
            while alive(sess) and elapsed < dur and mp.Parent do task.wait() end
        end
        local function waitForOtherFeatures(sess)
            if not (_atlantis and _atlantis.selling) then return true end
            notify("Menunggu fitur lain selesai...")
            while alive(sess) and _atlantis and _atlantis.selling do task.wait(1) end
            if not alive(sess) then return false end
            task.wait(5)
            return alive(sess)
        end
        local function runSpawn(slots, sess)
            if not waitForOtherFeatures(sess) then return 0 end
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then return 0 end
            local startCF = hrp.CFrame
            _totem.basePos = _totem.basePos or startCF.Position
            local todo, done = {}, 0
            for _, si in ipairs(slots) do
                local existing = totemNear(slotSpot(si))
                if existing then
                    recordPlaced(si, existing, slotSpot(si))
                    done += 1
                else
                    table.insert(todo, si)
                end
            end
            local uuids, missing = allocateUUIDs(todo)
            local order = {}
            for _, si in ipairs(todo) do if uuids[si] then table.insert(order, si) end end
            if #missing > 0 then notify("Skip (tidak di tas): " .. table.concat(missing, ", "), 4) end
            if #order == 0 or not alive(sess) then return done end
            _totemSpawning = true
            saveOriginalState(startCF)
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then hum.Health = hum.MaxHealth end
            equipO2(); task.wait(0.3)
            if not alive(sess) then return done end
            enablePhysics(sess); task.wait(0.5)
            for _, si in ipairs(order) do
                if not alive(sess) then break end
                local spot = clearSpot(slotSpot(si))
                flyTo(spot, sess)
                if not alive(sess) then break end
                task.wait(SETTLE_DELAY)
                if not alive(sess) then break end
                local settled = clearSpot(spot)
                if (settled - spot).Magnitude > 0.5 then
                    spot = settled
                    flyTo(spot, sess)
                    if not alive(sess) then break end
                    task.wait(SETTLE_DELAY)
                    if not alive(sess) then break end
                end
                local root  = getFlyPart()
                local model = spawnAndConfirm(uuids[si], root and root.Position or spot)
                for try = 1, 2 do
                    if model ~= nil or not alive(sess) then break end
                    spot = clearSpot(spot, MIN_GAP + 0.3 * try)
                    flyTo(spot, sess)
                    task.wait(SETTLE_DELAY)
                    if not alive(sess) then break end
                    root  = getFlyPart()
                    model = spawnAndConfirm(uuids[si], root and root.Position or spot)
                end
                if model ~= nil then
                    recordPlaced(si, model or nil, spot)
                    done += 1
                else
                    recordFailed(si)
                end
                task.wait(SPAWN_GAP)
            end
            if not alive(sess) then return done end
            local home = startCF.Position
            flyTo(home, sess)
            if not alive(sess) then return done end
            stopHold()
            restoreOriginalState()
            task.delay(1, function()
                local hrpNow = getFlyPart()
                if hrpNow and ((hrpNow.Position - home) * Vector3.new(1, 0, 1)).Magnitude > 0.05 then
                    hrpNow.CFrame = CFrame.new(home.X, hrpNow.Position.Y, home.Z) * hrpNow.CFrame.Rotation
                    zeroVelocity(hrpNow)
                end
            end)
            local far = outOfReach(home)
            if #far > 0 then
                notify(("Totem slot %s digeser karena dekat totem lain, efeknya mungkin tidak sampai ke posisimu."):format(table.concat(far, ", ")), 5)
            end
            _totemSpawning = false
            unequipO2()
            return done
        end
        local function startMonitor(sess)
            if _totem.monitorThread then pcall(task.cancel, _totem.monitorThread) end
            _totem.monitorThread = task.spawn(function()
                while alive(sess) do
                    task.wait(1)
                    if not alive(sess) then break end
                    local char = LocalPlayer.Character
                    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                    if not hrp then continue end
                    local now, due = serverNow(), {}
                    for si = 1, SLOT_COUNT do
                        local p, f = _totem.placed[si], _totem.failed[si]
                        if p then
                            if now >= p.expire + 1 then
                                table.insert(due, si)
                            elseif (hrp.Position - p.spot).Magnitude <= STREAM_RADIUS then
                                local found = (p.model and p.model.Parent and p.model) or totemNear(p.spot)
                                if found then
                                    p.model, p.missing = found, 0
                                    p.expire = expireOf(found) or p.expire
                                else
                                    p.missing += 1
                                    if p.missing >= MISSING_CONFIRM then table.insert(due, si) end
                                end
                            end
                        elseif f and f.count < MAX_RETRY then
                            if now >= f.retryAt then table.insert(due, si) end
                        elseif f and not f.notified then
                            f.notified = true
                            notify(("Slot %d dilewati setelah %d kali gagal."):format(si, MAX_RETRY), 4)
                        end
                    end
                    if #due > 0 then
                        local names = {}
                        for _, si in ipairs(due) do
                            _totem.placed[si] = nil
                            table.insert(names, _totem.selectedSlots[si] or "?")
                        end
                        notify("Re-spawn: " .. table.concat(names, ", "))
                        runSpawn(due, sess)
                    end
                end
            end)
        end
        _scanTotems()
        TotemSection:AddParagraph({
            Title = "Auto Totem Info",
            Content = "[EN] Pick a totem per slot (duplicates are fine, each slot uses a separate unit). "
                .. "Totems last 1 hour; when a slot's totem is gone it is re-spawned automatically.\n"
                .. "[ID] Pilih totem per slot (boleh sama, tiap slot pakai unit berbeda). "
                .. "Totem bertahan 1 jam; kalau totem di suatu slot habis otomatis dipasang ulang.",
        })
        for i = 1, SLOT_COUNT do
            local idx = i
            local default = _totem.totemNames[idx] or SLOT_NONE
            _totem.selectedSlots[idx] = default ~= SLOT_NONE and default or nil
            _dropdownRefs[idx] = TotemSection:AddDropdown({
                Title    = ("Totem Slot %d"):format(idx),
                Options  = slotOptions(),
                Default  = default,
                Callback = function(sel)
                    _totem.selectedSlots[idx] = (sel ~= SLOT_NONE) and sel or nil
                end,
            })
        end
        TotemSection:AddButton({
            Title    = "Refresh Totem List [Mix]",
            Callback = function() _scanTotems(); _updateDropdowns() end,
        })
        TotemSection:AddToggle({
            Title = "Enable Spawn Totem Mix", Default = false, NoSave = true,
            Callback = function(on)
                if on then
                    if _totem.active then return end
                    if not _totem.data then notify("Data belum siap!", 4); return end
                    if not NetEvents.IsInitialized then notify("EventResolver belum siap!", 4); return end
                    local slots = {}
                    for i = 1, SLOT_COUNT do
                        if _totem.selectedSlots[i] then table.insert(slots, i) end
                    end
                    if #slots == 0 then notify("Belum ada slot yang dipilih!", 4); return end
                    _totem.session += 1
                    local sess = _totem.session
                    _totem.active = true
                    _totem.placed, _totem.failed, _totem.basePos = {}, {}, nil
                    local names = {}
                    for _, si in ipairs(slots) do table.insert(names, _totem.selectedSlots[si]) end
                    notify("Dimulai: " .. table.concat(names, " | "))
                    _totem.thread = task.spawn(function()
                        while _totem.restoring do task.wait(0.1) end
                        if not alive(sess) then return end
                        local done = runSpawn(slots, sess)
                        if not alive(sess) then return end
                        if done == 0 and not next(_totem.failed) then
                            notify("Gagal: tidak ada totem di inventory!", 4)
                            _totem.active = false
                            return
                        end
                        notify(("Selesai! %d/%d totem terpasang."):format(done, #slots))
                        startMonitor(sess)
                    end)
                else
                    local wasRunning = _totem.active
                    _totem.session += 1
                    _totem.active    = false
                    _totemSpawning   = false
                    _totem.placed, _totem.failed, _totem.basePos = {}, {}, nil
                    if _totem.thread        then pcall(task.cancel, _totem.thread);        _totem.thread        = nil end
                    if _totem.monitorThread then pcall(task.cancel, _totem.monitorThread); _totem.monitorThread = nil end
                    stopHold()
                    _totem.restoring = true
                    task.spawn(function()
                        pcall(restoreOriginalState)
                        pcall(unequipO2)
                        _totem.restoring = false
                    end)
                    if wasRunning then notify("Dihentikan.", 2) end
                end
            end,
        })
        task.spawn(function()
            pcall(function() _totem.data = getCachedReplionData() end)
            if not _totem.data then
                local rep = getCachedReplion()
                if rep then _totem.data = rep.Client:WaitReplion("Data") end
            end
        end)
    end
    do
        local EVENTS = {
            {
                Name          = "Ancient Lochness Monster",
                Tracker       = "Event Tracker",
                Position      = Vector3.new(6096.14, -585.92, 4669.50),
                LookDirection = Vector3.new(-0.8317, -0.4007, 0.3842),
            },
            {
                Name          = "Mutant Runic Koi",
                Tracker       = "UnderwaterCity Event Tracker",
                Position      = Vector3.new(-3140.3860, -643.4843, -10451.0654),
                LookDirection = Vector3.new(1.0000, 0.0000, -0.0054),
            },
        }
        local STREAM_RADIUS   = 1000
        local STREAM_INTERVAL = 5
        local depsCache = nil
        local function getDeps()
            if depsCache and depsCache.Parent then return depsCache end
            depsCache = workspace:FindFirstChild("!!! DEPENDENCIES")
            return depsCache
        end
        local function trackerItems(cfg)
            local d = getDeps()
            if not d then return nil end
            local ok, items = pcall(function() return d[cfg.Tracker].Main.Gui.Content.Items end)
            return ok and items or nil
        end
        local function eventStats(cfg)
            local items = trackerItems(cfg)
            return items and items:FindFirstChild("Stats") or nil
        end
        local function isActive(cfg)
            local stats = eventStats(cfg)
            return stats ~= nil and stats.Visible == true
        end
        local function timerText(cfg)
            local stats = eventStats(cfg)
            local ok, text = pcall(function() return stats.Timer.Label.Text end)
            return ok and text or "?"
        end
        local function countdownText(cfg)
            local items = trackerItems(cfg)
            local ok, text = pcall(function() return items.Countdown.Label.Text end)
            return ok and text or "?"
        end
        local function streamAround(pos)
            task.spawn(function()
                pcall(function() LocalPlayer:RequestStreamAroundAsync(pos, STREAM_RADIUS) end)
            end)
        end
        local function teleport(cf)
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end
            hrp.CFrame, hrp.Anchored = cf + Vector3.new(0, 5, 0), true
            task.wait(3)
            if not hrp.Parent then return false end
            hrp.Anchored, hrp.CFrame = false, cf
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            return true
        end
        for _, cfg in ipairs(EVENTS) do
            local st       = { enabled = false, thread = nil, respawnConn = nil, savedPos = nil, atEvent = false, shown = nil }
            local eventCF  = CFrame.lookAt(cfg.Position, cfg.Position + cfg.LookDirection)
            local Section  = AutoTab:AddSection("Auto " .. cfg.Name, false)
            local Status   = Section:AddParagraph({ Title = "Status", Content = "Idle" })
            local function notify(desc)
                Library:MakeNotify({ Title = cfg.Name, Description = desc, Delay = 3 })
            end
            local function setStatus(title, content)
                local key = title .. "\0" .. content
                if st.shown == key then return end
                st.shown = key
                Status:SetTitle(title)
                Status:SetContent(content)
            end
            local function savePos()
                local char = LocalPlayer.Character
                local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                if hrp then st.savedPos = hrp.CFrame end
            end
            local function goBack()
                st.atEvent = false
                if not st.savedPos then return false end
                local ok = teleport(st.savedPos)
                st.savedPos = nil
                return ok
            end
            Section:AddParagraph({
                Title   = "Info",
                Content = "Saves current position before TP to event\nAuto return after event ends\n6 events per day",
            })
            Section:AddButton({
                Title    = "Teleport to " .. cfg.Name,
                Callback = function()
                    savePos()
                    streamAround(cfg.Position)
                    task.spawn(teleport, eventCF)
                end,
            })
            Section:AddButton({
                Title    = "Return to Saved Pos (" .. cfg.Name .. ")",
                Callback = function()
                    if not st.savedPos then
                        notify("No saved position!")
                        return
                    end
                    task.spawn(goBack)
                end,
            })
            Section:AddToggle({
                Title    = "Auto " .. cfg.Name .. " Teleport",
                Default  = false,
                NoSave   = true,
                Callback = function(on)
                    st.enabled = on
                    if st.thread      then pcall(task.cancel, st.thread); st.thread = nil end
                    if st.respawnConn then st.respawnConn:Disconnect();   st.respawnConn = nil end
                    if not on then
                        if st.atEvent then
                            task.spawn(function()
                                if goBack() then notify("Stopped, returned to original position.") end
                            end)
                        end
                        st.atEvent = false
                        st.shown   = nil
                        Status:SetTitle("Status")
                        Status:SetContent("Idle")
                        return
                    end
                    st.respawnConn = LocalPlayer.CharacterAdded:Connect(function()
                        task.wait(3)
                        if st.enabled and st.atEvent and isActive(cfg) then teleport(eventCF) end
                    end)
                    st.thread = task.spawn(function()
                        local nextStream = 0
                        while st.enabled do
                            if not getDeps() then
                                setStatus("Waiting...", "Waiting for DEPENDENCIES to load...")
                                task.wait(1)
                                continue
                            end
                            local active = isActive(cfg)
                            if active and not st.atEvent then
                                savePos()
                                streamAround(cfg.Position)
                                task.wait(0.5)
                                if st.enabled and teleport(eventCF) then
                                    st.atEvent = true
                                    notify("Event active! Teleporting to location.")
                                end
                            elseif not active and st.atEvent then
                                if goBack() then notify("Event ended! Returned to original position.") end
                            end
                            if st.atEvent and os.clock() >= nextStream then
                                nextStream = os.clock() + STREAM_INTERVAL
                                streamAround(cfg.Position)
                            end
                            if active then
                                setStatus("EVENT ACTIVE", "Time left: " .. timerText(cfg)
                                    .. "\nStatus: " .. (st.atEvent and "At event location" or "Teleporting..."))
                            else
                                setStatus("Waiting for Event", "Starts in: " .. countdownText(cfg))
                            end
                            task.wait(1)
                        end
                    end)
                end,
            })
        end
    end
    do
        local _machine = { enabled = false, thread = nil, tpThread = nil }
        local function machineDefs()
            local ok, defs = pcall(function() return cachedRequire(ReplicatedStorage.Shared.FixableMachines) end)
            return (ok and type(defs) == "table") and defs or nil
        end
        local function questDefs()
            local ok, q = pcall(function() return cachedRequire(ReplicatedStorage.Modules.Quests) end)
            return (ok and type(q) == "table") and q or nil
        end
        local function npcGivers()
            local ok, g = pcall(function() return cachedRequire(ReplicatedStorage.Shared.NPCQuestGivers) end)
            return (ok and type(g) == "table") and g or nil
        end
        local function itemName(id)
            local ok, d = pcall(function()
                return cachedRequire(ReplicatedStorage.Shared.ItemUtility):GetItemData(id)
            end)
            return (ok and d and d.Data and d.Data.Name) or ("Item " .. tostring(id))
        end
        local FISH_SPOT = {
            ["Magma Regulator"]       = CFrame.new(Vector3.new(-864.196, 56.557, 5305.733), Vector3.new(-874.166, 56.557, 5306.503)),
            ["Glacial Regulator"]     = CFrame.new(Vector3.new(-978.046, 46.334, 5302.684), Vector3.new(-984.551, 46.334, 5310.279)),
            ["Atmospheric Regulator"] = CFrame.new(Vector3.new(-813.357, 59.866, 5269.538), Vector3.new(-807.491, 59.866, 5277.637)),
        }
        local ORDER = { "Magma Regulator", "Glacial Regulator", "Atmospheric Regulator" }
        local Section = AutoTab:AddSection("Auto Fix Elemental Machines", false)
        local infoPara = Section:AddParagraph({ Title = "Mesin & Ikan", Content = "Memuat..." })
        task.spawn(function()
            local defs = machineDefs()
            if not defs then return end
            local lines = {}
            for _, name in ipairs(ORDER) do
                local d = defs[name]
                if d then
                    local giver = npcGivers() and npcGivers()[d.QuestId]
                    lines[#lines + 1] = ("<b>%s</b> — butuh <b>%s</b>%s"):format(
                        name, itemName(d.ItemRequiredToRepair),
                        giver and ("\n   NPC: " .. tostring(giver.NPC)) or "")
                end
            end
            lines[#lines + 1] = "\n<i>Ikannya SECRET (peluang 1 : 4.000.000). Nyalakan auto fishing sendiri di tab Main — fitur ini cuma mengantar ke spot, memegang ikannya, lalu memasukkannya ke mesin.</i>"
            pcall(function() infoPara:SetContent(table.concat(lines, "\n")) end)
        end)
        local function root()
            local char = LocalPlayer.Character
            return char and char:FindFirstChild("HumanoidRootPart")
        end
        local function teleport(cf)
            local hrp = root()
            if not hrp then return false end
            pcall(function()
                hrp.CFrame = cf
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
            return true
        end
        local function machineModel(name)
            local ws = workspace:FindFirstChild("WorldSetup")
            local fm = ws and ws:FindFirstChild("FixableMachines")
            return fm and fm:FindFirstChild(name) or nil
        end
        local function waitForMachine(name, seconds)
            local deadline = os.clock() + (seconds or 8)
            while _machine.enabled and os.clock() < deadline do
                local m = machineModel(name)
                if m and m.PrimaryPart then return m end
                task.wait(0.5)
            end
            return machineModel(name)
        end
        local function fishUUID(itemId)
            local data = getCachedReplionData()
            if not data then return nil end
            for _, v in ipairs(data:Get({ "Inventory", "Items" }) or {}) do
                if type(v) == "table" and tonumber(v.Id) == itemId then return v.UUID end
            end
            return nil
        end
        local function holdFish(uuid)
            local data = getCachedReplionData()
            if not data then return false end
            if data:Get("EquippedId") == uuid then return true end
            local function slotOf()
                for slot, id in pairs(data:Get("EquippedItems") or {}) do
                    if id == uuid then return slot end
                end
                return nil
            end
            local slot = slotOf()
            if not slot then
                pcall(function() NetEvents.RE_EquipItem:FireServer(uuid, "Fish") end)
                for _ = 1, 12 do
                    task.wait(0.25)
                    slot = slotOf()
                    if slot then break end
                end
            end
            if not slot then return false end
            for _ = 1, 3 do
                pcall(function() NetEvents.RF_EquipToolFromHotbar:FireServer(slot) end)
                for _ = 1, 8 do
                    task.wait(0.25)
                    if data:Get("EquippedId") == uuid then return true end
                end
            end
            return data:Get("EquippedId") == uuid
        end
        local function questCompleted(questId)
            local data = getCachedReplionData()
            if not data then return false end
            local ok, found = pcall(function() return data:Find("CompletedQuests", questId) end)
            return ok and found ~= nil
        end
        local function questEntry(questId, questType)
            local data = getCachedReplionData()
            if not data then return nil end
            local ok, q = pcall(function() return data:Get({ "Quests", questType, questId }) end)
            return ok and q or nil
        end
        local function objProgress(questId, questType, idx)
            local q = questEntry(questId, questType)
            local obj = q and q.Objectives and q.Objectives[idx]
            return obj and (obj.Progress or 0) or 0
        end
        local function dialogue(npc, path, index)
            pcall(function() NetEvents.RE_DialogueEnded:FireServer(npc, path, index) end)
        end
        local function startSpotTeleport(cf)
            if _machine.tpThread then pcall(task.cancel, _machine.tpThread) end
            _machine.tpThread = task.spawn(function()
                while _machine.enabled do
                    local hrp = root()
                    if hrp and (hrp.Position - cf.Position).Magnitude > 20 then teleport(cf) end
                    task.wait(8)
                end
            end)
        end
        local function stopSpotTeleport()
            if _machine.tpThread then
                pcall(task.cancel, _machine.tpThread)
                _machine.tpThread = nil
            end
        end
        local function processMachine(name, def, qdef, giver)
            local questId, questType = def.QuestId, def.QuestType
            if questCompleted(questId) then return true end
            if not questEntry(questId, questType) then
                for _ = 1, 3 do
                    dialogue(giver.NPC, giver.Path, giver.Index)
                    for _ = 1, 6 do
                        task.wait(0.5)
                        if questEntry(questId, questType) then break end
                    end
                    if questEntry(questId, questType) then break end
                end
                if not questEntry(questId, questType) then return false end
            end
            local fixIdx  = def.FixedOnObjective or 1
            local fixGoal = (qdef.Objectives[fixIdx] and qdef.Objectives[fixIdx].Goal) or 1
            local itemId  = def.ItemRequiredToRepair
            local fishNm  = itemName(itemId)
            if objProgress(questId, questType, fixIdx) < fixGoal then
                local uuid = fishUUID(itemId)
                if not uuid then
                    startSpotTeleport(FISH_SPOT[name] or CFrame.new(0, 0, 0))
                    while _machine.enabled and not uuid do
                        task.wait(1)
                        uuid = fishUUID(itemId)
                    end
                    stopSpotTeleport()
                    if not _machine.enabled then return false end
                    Library:MakeNotify({ Title = name, Description = fishNm .. " didapat!", Delay = 3 })
                end
                if not holdFish(uuid) then return false end
                local model = waitForMachine(name, 10)
                local pp    = model and model.PrimaryPart
                if not pp then return false end
                teleport(CFrame.new(pp.Position + Vector3.new(0, 4, 6), pp.Position))
                task.wait(0.6)
                local prompt = pp:FindFirstChild("FixPrompt")
                if prompt and typeof(fireproximityprompt) == "function" then
                    for _ = 1, 5 do
                        if objProgress(questId, questType, fixIdx) >= fixGoal then break end
                        pcall(function() fireproximityprompt(prompt) end)
                        task.wait(1)
                    end
                end
                if objProgress(questId, questType, fixIdx) < fixGoal then return false end
                Library:MakeNotify({ Title = name, Description = "Mesin diperbaiki!", Delay = 3 })
            end
            local ret = qdef.Objectives[2] and qdef.Objectives[2].Requirements
            if ret and ret.NPC then
                for _ = 1, 3 do
                    dialogue(ret.NPC, ret.Path, ret.Index)
                    for _ = 1, 6 do
                        task.wait(0.5)
                        if questCompleted(questId) then break end
                    end
                    if questCompleted(questId) then break end
                end
            end
            if not questCompleted(questId) then return false end
            Library:MakeNotify({ Title = name, Description = "Quest selesai!", Delay = 3 })
            return true
        end
        Section:AddToggle({
            Title    = "Auto Fix Elemental Machines",
            Default  = false,
            Callback = function(on)
                _machine.enabled = on
                if _machine.thread then pcall(task.cancel, _machine.thread); _machine.thread = nil end
                stopSpotTeleport()
                if not on then
                    Library:MakeNotify({ Title = "Elemental Machine", Description = "Stopped.", Delay = 2 })
                    return
                end
                _machine.thread = task.spawn(function()
                    local defs, quests, givers = machineDefs(), questDefs(), npcGivers()
                    if not (defs and quests and givers) then
                        Library:MakeNotify({ Title = "Elemental Machine", Description = "Data mesin/quest game tidak terbaca.", Delay = 3 })
                        _machine.enabled = false
                        return
                    end
                    Library:MakeNotify({ Title = "Elemental Machine", Description = "Active!", Delay = 2 })
                    local done, failed = 0, 0
                    for _, name in ipairs(ORDER) do
                        if not _machine.enabled then break end
                        local def  = defs[name]
                        local qdef = def and quests[def.QuestType] and quests[def.QuestType][def.QuestId]
                        local give = def and givers[def.QuestId]
                        if def and qdef and give then
                            if processMachine(name, def, qdef, give) then done = done + 1 else failed = failed + 1 end
                        else
                            failed = failed + 1
                        end
                        task.wait(1)
                    end
                    stopSpotTeleport()
                    Library:MakeNotify({
                        Title       = "Elemental Machine",
                        Description = ("Selesai — %d beres, %d gagal."):format(done, failed),
                        Delay       = 5,
                    })
                    _machine.enabled = false
                end)
            end,
        })
    end
end
task.wait()
local EventTab    = MainWindow:AddTab({ Name = "Event", Icon = "boss" })
do
    local _journal = { enabled = false, thread = nil, spot = nil, origCF = nil, claimTry = {}, warned = {} }
    local STAY_RADIUS = 40
    local COORD_ALIAS = { ["Sisyphus Statue"] = "Sysiphus Statue" }
    local function notify(desc, delay)
        Library:MakeNotify({ Title = "Fishing Journal", Description = desc, Delay = delay or 3 })
    end
    local function journalDefs()
        return cachedRequire(ReplicatedStorage.Shared.FishingJournal), cachedRequire(ReplicatedStorage.Modules.Quests)
    end
    local function rootPart()
        local char = LocalPlayer.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end
    local function teleport(cf)
        local hrp = rootPart()
        if not hrp then return end
        pcall(function()
            hrp.CFrame = cf
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    local function spotFor(name)
        local coords = fetchIslandCoords()
        local c = coords and (coords[COORD_ALIAS[name] or name] or coords[name])
        return c and CFrame.new(c.pos + Vector3.new(0, 5, 0), c.look + Vector3.new(0, 5, 0))
    end
    local GUIDE_POS = {
        ["Island Guide - Fisherman Island"] = Vector3.new(-136.01, 13.23, 2815.21),
        ["Island Guide - Kohana"]           = Vector3.new(-576.64, 9.23, 679.72),
        ["Island Guide - Lost Isle"]        = Vector3.new(-3598.91, 6.93, -1023.9),
    }
    local function claimRewards(island, ratio)
        local data, FJ = getCachedReplionData(), journalDefs()
        local remote = NetEvents.RF_ClaimJournalReward
        if not (data and FJ and remote) then return end
        for i = 1, #(FJ.Islands[island].Rewards or {}) do
            local claimed = data:Find({ "FishingJournal", "ClaimedRewards", island }, i) ~= nil
            local key = island .. ":" .. i
            if not claimed and ratio >= i / 3 and os.clock() - (_journal.claimTry[key] or 0) > 30 then
                _journal.claimTry[key] = os.clock()
                local ok, res = pcall(remote.InvokeServer, remote, island, i)
                if ok and res then notify(("Reward %s #%d diklaim!"):format(island, i)) end
            end
        end
    end
    local function currentJournal()
        local data = getCachedReplionData()
        local FJ, Quests = journalDefs()
        if not (data and FJ and Quests) then return nil end
        for _, island in ipairs(FJ:GetOrder()) do
            local def   = FJ.Islands[island]
            local quest = def and Quests[def.Category] and Quests[def.Category][def.Quest]
            if quest then
                local progress = data:Get({ "Quests", def.Category, def.Quest })
                local done = data:Find("CompletedQuests", def.Quest) ~= nil
                local todo = {}
                for i, obj in ipairs(quest.Objectives) do
                    local p = progress and progress.Objectives and progress.Objectives[i]
                    if not done and (p and p.Progress or 0) < obj.Goal then todo[#todo + 1] = obj end
                end
                claimRewards(island, done and 1 or (#quest.Objectives - #todo) / #quest.Objectives)
                if not done then
                    return { island = island, quest = def.Quest, todo = todo, accepted = progress ~= nil, progress = progress }
                end
            end
        end
        return { allDone = true }
    end
    local function acceptJournal(j)
        local givers = cachedRequire(ReplicatedStorage.Shared.NPCQuestGivers)
        local giver  = givers and givers[j.quest]
        local data   = getCachedReplionData()
        if not (giver and data) then return end
        if giver.RequiredQuest and not data:Find("CompletedQuests", giver.RequiredQuest) then return end
        local npcFolder = workspace:FindFirstChild("NPC")
        local npc = npcFolder and npcFolder:FindFirstChild(giver.NPC)
        local npcPos = npc and npc:GetPivot().Position or GUIDE_POS[giver.NPC]
        if not npcPos then return end
        local hrp = rootPart()
        if hrp and not _journal.origCF then _journal.origCF = hrp.CFrame end
        notify("Ambil quest " .. j.quest .. " dari " .. giver.NPC .. "...")
        local look = npc and npc:GetPivot().LookVector or Vector3.new(0, 0, 1)
        local standAt = npcPos + look * 5 + Vector3.new(0, 3, 0)
        teleport(CFrame.lookAt(standAt, npcPos))
        task.wait(1.5)
        for _ = 1, 3 do
            pcall(function() NetEvents.RE_DialogueEnded:FireServer(giver.NPC, giver.Path, giver.Index) end)
            for _ = 1, 6 do
                task.wait(0.5)
                if data:Get({ "Quests", giver.Type or "Mainline", j.quest }) then
                    notify(j.quest .. " dimulai!")
                    return
                end
            end
        end
        notify("Gagal ambil quest dari " .. giver.NPC .. ", dicoba lagi nanti.", 4)
    end
    local BOARD_POS = Vector3.new(-643.64, 17.99, 599.8)
    local function bountyFish(data, slot)
        local util = cachedRequire(ReplicatedStorage.Shared.BountyUtility)
        for _, item in ipairs(data:Get({ "Inventory", "Items" }) or {}) do
            if item.Id == slot.Id and not item.Favorited then
                local hasMeta = slot.Metadata and next(slot.Metadata) ~= nil
                if not hasMeta then return item.UUID end
                local probe = { Id = item.Id, Metadata = item.Metadata and { VariantId = item.Metadata.VariantId, Shiny = item.Metadata.Shiny } }
                local ok, match = pcall(util.MatchArgs, util, probe, slot.Metadata)
                if ok and match then return item.UUID end
            end
        end
        return nil
    end
    local function holdFish(data, uuid)
        if data:Get("EquippedId") == uuid then return true end
        local function slotOf()
            for s, id in pairs(data:Get("EquippedItems") or {}) do
                if id == uuid then return s end
            end
        end
        if not slotOf() then
            pcall(function() NetEvents.RE_EquipItem:FireServer(uuid, "Fish") end)
            for _ = 1, 12 do task.wait(0.25); if slotOf() then break end end
        end
        local s = slotOf()
        if not s then return false end
        pcall(function() NetEvents.RF_EquipToolFromHotbar:FireServer(s) end)
        for _ = 1, 12 do
            task.wait(0.25)
            if data:Get("EquippedId") == uuid then return true end
        end
        return false
    end
    local function bountyStars(slot)
        local items = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
        local tiers = cachedRequire(ReplicatedStorage.Shared.TierUtility)
        local ok, tier = pcall(function()
            local d = items.GetItemDataFromItemType(slot.Type, slot.Name) or items.GetItemDataFromItemType(slot.Type, slot.Id)
            local t = d.Probability and tiers:GetTierFromRarity(d.Probability.Chance) or tiers:GetTier(d.Data.Tier)
            return t.Tier
        end)
        return ok and tier or 0
    end
    local function goToBoard()
        local board = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Bounty Board")
        local boardPos = board and board:GetPivot().Position or BOARD_POS
        local look = board and board:GetPivot().LookVector or Vector3.new(0, 0, 1)
        local hrp = rootPart()
        if hrp and not _journal.origCF then _journal.origCF = hrp.CFrame end
        _journal.spot = nil
        teleport(CFrame.lookAt(boardPos + look * 6 + Vector3.new(0, 3, 0), boardPos))
        task.wait(1)
    end
    local function handInBounty(slotIndex, name, uuid)
        if _journal.handing then return false end
        _journal.handing = true
        local data = getCachedReplionData()
        local ok, res = false, nil
        goToBoard()
        if data and holdFish(data, uuid) then
            ok, res = pcall(function() return NetEvents.RF_ClaimBounty:InvokeServer("Default", slotIndex, uuid) end)
        end
        pcall(autoEquipRod)
        _journal.handing = false
        if ok and res then
            _journal.bounty = nil
            notify("Bounty " .. tostring(name) .. " selesai!")
            return true
        end
        notify("Gagal serahkan bounty " .. tostring(name) .. ", dicoba lagi nanti.", 4)
        return false
    end
    local function bountyStep()
        local data = getCachedReplionData()
        local slots = data and data:Get({ "Bounty", "Slots" })
        if type(slots) ~= "table" then return false end
        local pick, pickStars
        for i, slot in ipairs(slots) do
            if not slot.Claimed and slot.Type == "Fish" then
                if slot.Locked then pick = i; break end
                local stars = bountyStars(slot)
                if not pick or stars > pickStars then pick, pickStars = i, stars end
            end
        end
        if not pick then return false end
        local slot = slots[pick]
        if not slot.Locked then
            goToBoard()
            pcall(function() NetEvents.RE_LockBounty:FireServer("Default", pick) end)
            for _ = 1, 8 do
                task.wait(0.25)
                if (data:Get({ "Bounty", "Slots", pick }) or {}).Locked then break end
            end
            if not (data:Get({ "Bounty", "Slots", pick }) or {}).Locked then
                notify("Gagal start bounty " .. tostring(slot.Name) .. ", dicoba lagi nanti.", 4)
                return false
            end
            notify(("Bounty dimulai: %s (%d bintang)"):format(slot.Name, bountyStars(slot)))
        end
        _journal.bounty = { slot = pick, id = slot.Id, name = slot.Name }
        local uuid = bountyFish(data, slot)
        if uuid then return handInBounty(pick, slot.Name, uuid) end
        local areas = cachedRequire(ReplicatedStorage.Areas)
        for areaName, area in pairs(areas or {}) do
            if type(area.Items) == "table" and table.find(area.Items, slot.Name) and spotFor(areaName) then
                if not _journal.warned["bounty:" .. slot.Name] then
                    _journal.warned["bounty:" .. slot.Name] = true
                    notify(("Bounty: tangkap %s di %s"):format(slot.Name, areaName), 5)
                end
                return false, areaName
            end
        end
        if not _journal.warned["bounty:" .. slot.Name] then
            _journal.warned["bounty:" .. slot.Name] = true
            notify("Lokasi " .. tostring(slot.Name) .. " tidak diketahui, tangkap manual.", 5)
        end
        return false
    end
    local BUY_REMOTE = {
        Charms         = "RF_PurchaseCharm",
        Baits          = "RF_PurchaseBait",
        Gears          = "RF_PurchaseGear",
        ["Fishing Rods"] = "RF_PurchaseFishingRod",
    }
    local BAG_OF = { Charms = "Charms", Baits = "Baits", Gears = "Items", ["Fishing Rods"] = "Fishing Rods" }
    local function ownsItem(data, itemType, id)
        for _, item in ipairs(data:Get({ "Inventory", BAG_OF[itemType] }) or {}) do
            if item.Id == id then return true end
        end
        return false
    end
    local function buyStep(j, obj)
        local req = obj.Requirements or {}
        local wanted, count, anyOf
        if obj.Type == "PurchaseCharm" then
            wanted, count = { "Charms", req.Charm }, true
        elseif obj.Type == "OwnItem" and BUY_REMOTE[req.Type] then
            wanted, count = { req.Type, req.Item }, req.Type == "Charms"
        elseif obj.Type == "FluorescentAstral" then
            wanted, anyOf = { "Fishing Rods", "Fluorescent Rod" }, { "Fluorescent Rod", "Astral Rod" }
        else
            return false
        end
        local key = j.quest .. ":" .. obj.Id
        if os.clock() - (_journal.claimTry[key] or 0) < 15 then return true end
        _journal.claimTry[key] = os.clock()
        local data  = getCachedReplionData()
        local items = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
        local function lookup(itemType, name)
            local ok, d = pcall(function() return items.GetItemDataFromItemType(itemType, name) end)
            return ok and d and d.Data and d or nil
        end
        local itemType, name = wanted[1], wanted[2]
        local def = lookup(itemType, name)
        if not (data and def) then return true end
        if not count then
            for _, n in ipairs(anyOf or { name }) do
                local d = lookup(itemType, n)
                if d and ownsItem(data, itemType, d.Data.Id) then return true end
            end
        end
        local p = j.progress and j.progress.Objectives and j.progress.Objectives[obj.Id]
        local need = count and math.max(1, (obj.Goal or 1) - (p and p.Progress or 0)) or 1
        if def.Price and (data:Get("Coins") or 0) < def.Price * need then
            if not _journal.warned[key] then
                _journal.warned[key] = true
                notify(("Koin kurang untuk %dx %s."):format(need, name), 5)
            end
            return true
        end
        local remote = NetEvents[BUY_REMOTE[itemType]]
        if not remote then return true end
        local reason, note = nil, NetEvents.RE_TextNotification
        local conn = note and note.OnClientEvent:Connect(function(n)
            if type(n) == "table" and type(n.Text) == "string" then reason = n.Text end
        end)
        for _ = 1, need do
            pcall(function() remote:InvokeServer(def.Data.Id) end)
            task.wait(0.5)
        end
        task.wait(0.5)
        if conn then conn:Disconnect() end
        if not count and not ownsItem(data, itemType, def.Data.Id) then
            local msg = ("Gagal beli %s: %s"):format(name, reason or "ditolak server")
            if _journal.warned[key] ~= msg then
                _journal.warned[key] = msg
                notify(msg, 6)
            end
            _journal.claimTry[key] = os.clock() + 45 -- try again in a minute instead of every 15 s
            return true
        end
        notify(("Beli %dx %s."):format(need, name))
        return true
    end
    local function step()
        local j = currentJournal()
        if not j then return end
        if j.allDone then
            if not _journal.warned.allDone then
                _journal.warned.allDone = true
                if _journal.origCF then teleport(_journal.origCF) end
                _journal.origCF, _journal.spot = nil, nil
                notify("Semua Journal yang ada sudah selesai! Kembali ke posisi awal.", 5)
            end
            return
        end
        if not j.accepted then
            _journal.spot = nil
            acceptJournal(j)
            return
        end
        local target, fallback, manual, bounty = nil, nil, {}, false
        for _, obj in ipairs(j.todo) do
            local req = obj.Requirements or {}
            if obj.Type == "Catch" or obj.Type == "CatchDifferent" or obj.Type == "EarnedCoins" then
                if req.Location and req.Location ~= j.island then
                    target = target or req.Location
                else
                    fallback = fallback or j.island
                end
            elseif obj.Type == "Bounty" then
                bounty = true
            elseif not buyStep(j, obj) then
                manual[#manual + 1] = obj.Name
            end
        end
        target = target or fallback
        if bounty then
            local claimed, fishArea = bountyStep()
            if claimed then return end
            target = target or fishArea
        end
        local manualKey = j.quest .. table.concat(manual, "|")
        if #manual > 0 and not _journal.warned[manualKey] then
            _journal.warned[manualKey] = true
            notify("Harus manual: " .. table.concat(manual, ", "), 6)
        end
        if not target then
            _journal.spot = nil
            return
        end
        local cf = spotFor(target)
        if not cf then
            if not _journal.warned[target] then
                _journal.warned[target] = true
                notify("Koordinat untuk " .. target .. " tidak ada.", 4)
            end
            return
        end
        if _journal.spot ~= target then
            _journal.spot = target
            notify(("%s → mancing di %s"):format(j.quest, target))
        end
        local hrp = rootPart()
        if hrp and (hrp.Position - cf.Position).Magnitude > STAY_RADIUS then
            if not _journal.origCF then _journal.origCF = hrp.CFrame end
            teleport(cf)
        end
    end
    local Section = EventTab:AddSection("Auto Complete Fishing Journal", false)
    Section:AddToggle({
        Title    = "Enable Auto Fishing Journal",
        Default  = false,
        NoSave   = true,
        Callback = function(on)
            _journal.enabled = on
            if _journal.thread then pcall(task.cancel, _journal.thread); _journal.thread = nil end
            if _journal.catchConn then _journal.catchConn:Disconnect(); _journal.catchConn = nil end
            if not on then
                _journal.bounty = nil
                if _journal.origCF then teleport(_journal.origCF) end
                _journal.origCF, _journal.spot = nil, nil
                table.clear(_journal.warned)
                notify("Dimatikan.", 2)
                return
            end
            notify("Aktif! Nyalakan auto fishing sendiri.")
            pcall(function()
                _journal.catchConn = NetEvents.RE_ObtainedNewFishNotification.OnClientEvent:Connect(function(itemId, _, extra)
                    local b = _journal.bounty
                    local inv = type(extra) == "table" and extra.InventoryItem
                    if not (b and itemId == b.id and type(inv) == "table" and inv.UUID) then return end
                    task.spawn(handInBounty, b.slot, b.name, inv.UUID)
                end)
            end)
            _journal.thread = task.spawn(function()
                while _journal.enabled do
                    if not (_totemSpawning or _G._treasureHuntBusy or _journal.handing) then pcall(step) end
                    task.wait(3)
                end
            end)
        end,
    })
end
do
    local Attacks        = ReplicatedStorage.Controllers.CharybdisFightController.Attacks
    local RaycastUtility = require(ReplicatedStorage.Shared.RaycastUtility)
    local HUNTER_QUEST   = "Defeat Charybdis"
    local _chary = { enabled = false, thread = nil, atArena = false, savedCF = nil, padPos = nil, platform = nil, attackRuns = {} }
    local ARENA_POS    = Vector3.new(657, -1, 895)
    local STAY_RADIUS  = 40
    local STAND_DIST   = 15   -- from the cannon; the cast then lands 25-40 studs out, inside the 125-wide zone
    local HOVER_HEIGHT = 30
    local function notify(desc)
        Library:MakeNotify({ Title = "Charybdis", Description = desc, Delay = 3 })
    end
    local function charyState()
        local ok, battle = pcall(function() return getCachedReplion().Client:GetReplion("CharybdisBattle") end)
        if not ok or not battle or battle.Destroyed then return nil end
        local state = battle:Get("State")
        return {
            active = battle:Get("Active") == true,
            health = type(state) == "table" and tonumber(state.Health) or 0,
        }
    end
    local function blockAttacks(on)
        for _, m in ipairs(Attacks:GetChildren()) do
            local ok, mod = pcall(require, m)
            if ok and type(mod) == "table" and not table.isfrozen(mod) then
                if on and not _chary.attackRuns[m] then
                    _chary.attackRuns[m] = mod.Run
                    mod.Run = function() end
                elseif not on and _chary.attackRuns[m] then
                    mod.Run, _chary.attackRuns[m] = _chary.attackRuns[m], nil
                end
            end
        end
    end
    local function acceptHunterQuest()
        local data  = getCachedReplionData()
        local def   = require(ReplicatedStorage.Modules.Quests).Mainline[HUNTER_QUEST]
        local giver = require(ReplicatedStorage.Shared.NPCQuestGivers)[HUNTER_QUEST]
        if not (data and def and giver) or data:Find("CompletedQuests", HUNTER_QUEST)
            or data:Get({ "Quests", "Mainline", HUNTER_QUEST }) or (data:Get("Level") or 0) < (def.LevelLocked or 0) then
            return
        end
        pcall(function() NetEvents.RE_DialogueEnded:FireServer(giver.NPC, giver.Path, giver.Index) end)
    end
    local function root()
        local char = LocalPlayer.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end
    local function teleport(cf)
        local hrp = root()
        if not hrp then return false end
        pcall(function()
            hrp.CFrame = cf
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
        return true
    end
    local function findPad()
        local zones = workspace:FindFirstChild("Zones")
        local part  = zones and zones:FindFirstChild("Charybdis Battle Pad", true)
        if part and not part:IsA("BasePart") then part = part:FindFirstChildWhichIsA("BasePart") end
        return part
    end
    local function castLandsOnPad(cf)
        local params = RaycastParams.new()
        params.IgnoreWater, params.RespectCanCollide = true, false
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = RaycastUtility:getFilteredTargets(LocalPlayer)
        for _, power in ipairs({ 0, 1 }) do
            local hit = workspace:Raycast(cf.Position + cf.LookVector * (power * 15 + 10), Vector3.new(0, -125, 0), params)
            if not (hit and hit.Instance.Name == "Charybdis Battle Pad") then return false end
        end
        return true
    end
    local function standCF(pad)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { LocalPlayer.Character, workspace:FindFirstChild("Zones"), workspace:FindFirstChild("WorldSetup") }
        params.IgnoreWater = false
        local hit = workspace:Raycast(pad.Position + Vector3.new(0, 60, 0), Vector3.new(0, -160, 0), params)
        local center = Vector3.new(pad.Position.X, (hit and hit.Position.Y or pad.Position.Y) + HOVER_HEIGHT, pad.Position.Z)
        local first
        for angle = 0, 315, 45 do
            local dir = CFrame.Angles(0, math.rad(angle), 0).LookVector
            local pos = center + dir * STAND_DIST
            local cf  = CFrame.lookAt(pos, pos + dir)
            first = first or cf
            if castLandsOnPad(cf) then return cf end
        end
        return first
    end
    local function flatDist(a, b)
        return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude
    end
    local function platformUnder(cf)
        local p = _chary.platform
        if not (p and p.Parent) then
            p = Instance.new("Part")
            p.Name, p.Size, p.Anchored, p.Transparency = "CharybdisStand", Vector3.new(10, 1, 10), true, 1
            p.Parent = workspace
            _chary.platform = p
        end
        p.CFrame = CFrame.new(cf.Position - Vector3.new(0, 3.5, 0))
        return p
    end
    local function hoverAt(cf)
        local hrp = root()
        if not hrp then return false end
        platformUnder(cf)
        pcall(function() hrp.Anchored = false end) -- left anchored by an older version
        teleport(cf)
        autoEquipRod() -- the fishing mode (Instant etc.) only lands catches with the rod in hand
        return true
    end
    local function offStand(hrp, at)
        local p = _chary.platform
        return not (p and p.Parent) or flatDist(hrp.Position, at) > STAY_RADIUS or hrp.Position.Y < p.Position.Y - 2
    end
    local function goHome()
        if _chary.platform then _chary.platform:Destroy(); _chary.platform = nil end
        if _chary.savedCF then
            teleport(_chary.savedCF)
            _chary.savedCF = nil
        end
        _chary.atArena, _chary.padPos = false, nil
    end
    local Section = EventTab:AddSection("Auto Charybdis Boss", false)
    Section:AddParagraph({
        Title   = "Info",
        Content = "Ikut boss Charybdis otomatis (Selasa 08:00 & Kamis 20:00 US Eastern).",
    })
    Section:AddToggle({
        Title    = "Enable Auto Charybdis Boss",
        Default  = false,
        Callback = function(on)
            _chary.enabled = on
            if _chary.thread then
                pcall(task.cancel, _chary.thread)
                _chary.thread = nil
            end
            blockAttacks(on)
            if not on then
                goHome()
                return
            end
            notify("Aktif!")
            acceptHunterQuest()
            _chary.thread = task.spawn(function()
                while _chary.enabled do
                    local state = charyState()
                    if state and (not state.active or state.health <= 0) then
                        if _chary.atArena then
                            goHome()
                            acceptHunterQuest() -- the quest may have unlocked or finished during the fight
                        end
                    elseif state then
                        local pad, hrp = findPad(), root()
                        if not _chary.atArena then
                            _chary.savedCF = (hrp and hrp.CFrame) or _chary.savedCF
                            _chary.atArena = true
                            notify("Charybdis muncul! Menuju arena.")
                        end
                        if not pad then
                            if hrp and offStand(hrp, ARENA_POS) then
                                hoverAt(CFrame.new(ARENA_POS + Vector3.new(0, HOVER_HEIGHT, 0)))
                            end
                        elseif hrp and offStand(hrp, pad.Position) then
                            if _chary.padPos and flatDist(_chary.padPos, pad.Position) > 1 then
                                notify("Progress 100%, meriam nembak! Pulau pindah, ikut pindah.")
                            end
                            hoverAt(standCF(pad))
                        end
                        _chary.padPos = pad and pad.Position or _chary.padPos
                    end
                    task.wait(_chary.atArena and 0.5 or 2)
                end
            end)
        end,
    })
end
do
    local cfgModule = ReplicatedStorage.Shared:FindFirstChild("AirShipEventConfig")
    local Config = cfgModule and cachedRequire(cfgModule)
    if Config then -- not `return`: at this level it would end the whole script
    local _sb = { enabled = false, run = 0, home = nil, holding = false, wasVoyage = false }
    local Section = EventTab:AddSection("Auto Storm Boat Voyage", false)
    local Status = Section:AddParagraph({ Title = "Status", Content = "Idle" })
    Section:AddParagraph({
        Title   = "Info",
        Content = "Saat event Storm Boat aktif (tiap 3 jam, 1 jam), langsung teleport ke Voyage tanpa naik kapal: Luck +0.5, Mutation +0.25. Auto fishing tetap jalan, lalu balik ke lokasi awal setelah selesai.",
    })
    local function setStatus(text) pcall(function() Status:SetContent(text) end) end
    local function notify(desc) Library:MakeNotify({ Title = "Storm Boat", Description = desc, Delay = 3 }) end
    local function fmt(s)
        s = math.max(0, math.floor(s))
        return s >= 3600 and ("%d:%02d:%02d"):format(s // 3600, s % 3600 // 60, s % 60) or ("%d:%02d"):format(s // 60, s % 60)
    end
    local function root() return LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") end
    local function hold(on) -- keeps fishing / Auto Index from moving the character while it boards
        if _sb.holding == on then return end
        _sb.holding = on
        _G.SetOrbThrowing(on)
    end
    local function atVoyage()
        return LocalPlayer:GetAttribute(Config.ParticipantAttribute) == true or LocalPlayer:GetAttribute("LocationName") == Config.AreaName
    end
    local function hop(cf) -- long teleport: hold above the spot while it streams in so the character doesn't fall
        local hrp = root()
        if not hrp then return end
        hrp.CFrame, hrp.Anchored = cf + Vector3.new(0, 5, 0), true
        task.spawn(pcall, LocalPlayer.RequestStreamAroundAsync, LocalPlayer, cf.Position, 5)
        task.wait(3)
        hrp.Anchored, hrp.CFrame, hrp.AssemblyLinearVelocity = false, cf, Vector3.zero
    end
    local VOYAGE_SPOT = CFrame.lookAlong(Vector3.new(-5735.948, 2200.500, 10195.104), Vector3.new(-0.3833, 0, -0.9236))
    local RETURN_GRACE = 20 -- after the event, give the server this long to send us back before going home ourselves
    local function goHome()
        if _sb.home then
            hop(_sb.home)
            pcall(autoEquipRod)
        end
        _sb.home, _sb.wasVoyage = nil, false
    end
    local function step(data)
        local now, hrp = workspace:GetServerTimeNow(), root()
        local active = data.Active and now < (data.EventEndsAt or 0) - Config.EndLeadSeconds
        if active then
            if atVoyage() then
                hold(false) -- let auto fishing run on the Voyage
                if not _sb.wasVoyage then _sb.wasVoyage = true; notify("Sampai di Voyage! Mancing dapat bonus Luck & Mutation.") end
                return setStatus(("Di Voyage. Selesai dalam %s"):format(fmt(data.EventEndsAt - now)))
            end
            if not hrp then return end
            if not _sb.home then _sb.home = hrp.CFrame end
            hold(true) -- keep fishing / Auto Index from moving the character mid-hop
            setStatus("Storm Boat aktif! Teleport ke Voyage...")
            hop(VOYAGE_SPOT)
            return
        end
        hold(false)
        if _sb.home or _sb.wasVoyage then
            if atVoyage() and now < (data.EventEndsAt or now) + RETURN_GRACE then
                return setStatus("Voyage selesai, menunggu dipulangkan...")
            end
            setStatus("Kembali ke lokasi awal...")
            return goHome()
        end
        setStatus(("Storm Boat berikutnya dalam %s"):format(fmt((data.NextEventAt or now) - now)))
    end
    Section:AddToggle({
        Title = "Enable Auto Storm Boat Voyage", Default = false,
        Callback = function(on)
            _sb.enabled = on
            _sb.run += 1
            if not on then
                hold(false)
                if _sb.home then task.spawn(goHome) end -- like Event Teleport: switching off brings you back
                setStatus("Idle")
                return
            end
            local run = _sb.run
            task.spawn(function()
                while _sb.enabled and _sb.run == run do
                    local ok, err = pcall(function()
                        local rep = getCachedReplion()
                        local r = rep and rep.Client:GetReplion(Config.ReplionChannel)
                        if not r then return setStatus("Nunggu data Storm Boat...") end
                        if not (_totemSpawning or _G._treasureHuntBusy or _G.AutoMineActive) or _sb.holding then step(r.Data) end
                    end)
                    if not ok then warn("[Storm Boat] " .. tostring(err)) end
                    task.wait(1)
                end
                hold(false)
            end)
        end,
    })
    end
end
-- [Trade Tab]
task.wait()
do
    local TradeTab = MainWindow:AddTab({ Name = "Trade", Icon = "payment" })
    local Replion, ItemUtility, VendorUtility, PlayerStatsUtility, TradeData, Data, InventoryMapping
    pcall(function()
        Replion            = getCachedReplion()
        ItemUtility        = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
        VendorUtility      = cachedRequire(ReplicatedStorage.Shared.VendorUtility)
        PlayerStatsUtility = cachedRequire(ReplicatedStorage.Shared.PlayerStatsUtility)
        TradeData          = cachedRequire(ReplicatedStorage.Shared.Trading.TradeData)
        InventoryMapping   = cachedRequire(ReplicatedStorage.Shared:FindFirstChild("InventoryMapping"))
        Data               = getCachedReplionData()
    end)
    local TIER_NAME = {
        [1] = "Common", [2] = "Uncommon", [3] = "Rare",
        [4] = "Epic", [5] = "Legendary", [6] = "Mythic", [7] = "Secret",
    }
    local MAX_IN_TRADE  = 20
    local LOCK_SECONDS  = 5
    local OFFER_TIMEOUT = 14
    pcall(function()
        local n = TradeData.MaxItemsInTrade
        if type(n) == "number" and n > 0 then MAX_IN_TRADE = math.floor(n) end
        LOCK_SECONDS  = math.max(TradeData.ConfirmCountdownTime or 5, TradeData.ChangeCountdownTime or 5)
        OFFER_TIMEOUT = (TradeData.TradeOfferExpiration or 10) + 4
    end)
    local MAX_FAILS = 10
    local PACE = { addItem = 0.05, settle = 0.35 }
    local BUCKET_FALLBACK = {
        ["Fish"] = "Items", ["Gears"] = "Items", ["Enchant Stones"] = "Items",
        ["Equipment"] = "Items", ["Trophies"] = "Items",
        ["Charms"] = "Charms", ["Baits"] = "Baits", ["Fishing Rods"] = "Fishing Rods",
        ["Boats"] = "Boats", ["Emotes"] = "Emotes", ["Halos"] = "Halos",
        ["Lanterns"] = "Lanterns", ["Pets"] = "Pets", ["Pet Eggs"] = "Pet Eggs",
        ["Potions"] = "Potions", ["Totems"] = "Totems",
    }
    local function bucketFor(itemType)
        if type(InventoryMapping) == "table" and type(InventoryMapping[itemType]) == "string" then
            return InventoryMapping[itemType]
        end
        return BUCKET_FALLBACK[itemType] or itemType
    end
    local _tr = {
        running = false, thread = nil, threadAlive = false, monitor = nil, toggle = nil,
        target = nil, mode = "ByName", status = "Idle", lastError = "",
        sent = {}, blocked = {}, activeCleanup = nil,
        item = nil, itemAmount = 1, coins = 0,
        rarity = "Common", rarityAmount = 1,
        stones = {}, stoneAmount = 1,
        charms = {}, charmAmount = 1,
        baitSkins = {}, baitSkinAmount = 1,
        gears = {}, gearAmount = 1,
        attempts = 0, success = 0, failed = 0, batches = 0,
        itemsSent = 0, coinsSent = 0, skipped = 0,
    }
    local function updateMonitor()
        if not _tr.monitor then return end
        pcall(function()
            _tr.monitor:SetContent(("%s\nTerkirim: %d unit | Batch sukses: %d | Percobaan: %d | Gagal: %d%s%s"):format(
                _tr.status,
                _tr.itemsSent,
                _tr.success,
                _tr.attempts,
                _tr.failed,
                _tr.skipped > 0 and ("\nDilewati (ditolak server): %d"):format(_tr.skipped) or "",
                _tr.coinsSent > 0 and ("\nCoins: %d"):format(_tr.coinsSent) or ""
            ))
        end)
    end
    local function setStatus(text)
        if text == _tr.status then return end
        _tr.status = text
        updateMonitor()
    end
    local function resetStats()
        _tr.attempts, _tr.success, _tr.failed, _tr.batches = 0, 0, 0, 0
        _tr.itemsSent, _tr.coinsSent, _tr.skipped, _tr.lastError = 0, 0, 0, ""
        _tr.sent, _tr.blocked = {}, {}
    end
    local function invoke(remote, timeout, ...)
        if not remote then return false, "no remote" end
        local box  = { done = false, expired = false, result = nil }
        local args = table.pack(...)
        task.spawn(function()
            local packed = table.pack(pcall(function()
                return remote:InvokeServer(table.unpack(args, 1, args.n))
            end))
            if not box.expired then
                box.result, box.done = packed, true
            end
        end)
        local deadline = os.clock() + timeout
        while not box.done and os.clock() < deadline do task.wait(0.05) end
        if not box.done then
            box.expired = true
            return false, "timeout"
        end
        return table.unpack(box.result, 1, box.result.n)
    end
    local function unitCount(entry)
        local q = entry and entry.Quantity
        return (type(q) == "number" and q > 0) and math.floor(q) or 1
    end
    local function bucketList(bucket)
        local ok, list = pcall(function() return Data and Data:Get({ "Inventory", bucket or "Items" }) end)
        return (ok and type(list) == "table") and list or {}
    end
    local function dataForEntry(bucket, id)
        if not (ItemUtility and id ~= nil) then return nil end
        local ok, d = pcall(function()
            return ItemUtility.GetItemDataFromItemType(bucket, id)
        end)
        if ok and d and d.Data then return d end
        return nil
    end
    local function tradeRuleReason(d, entry)
        if not (d and d.Data) then return "data item gak ketemu" end
        local itemType = d.Data.Type
        if not (TradeData and table.find(TradeData.TradableItemTypes or {}, itemType)) then
            return ("tipe %s gak bisa ditrade"):format(tostring(itemType))
        end
        if (TradeData.TradableItemsSkinOnly or {})[itemType] and not d.IsSkin then
            return "cuma versi SKIN yang bisa ditrade"
        end
        if (TradeData.ExcludeCoinsItems or {})[itemType] and d.Price then
            return "bisa dibeli pakai coin, jadi gak bisa ditrade"
        end
        if entry then
            if (entry.Metadata and entry.Metadata.TradeLock) or d.TradeLocked then
                return "kena trade lock"
            end
            if typeof(entry.PetCargo) == "table" and #entry.PetCargo > 0 then
                return "pet lagi bawa cargo"
            end
        end
        if not (itemType == "Potions" or itemType == "Pets" or itemType == "Charms" or not d.Modifiers) then
            return "punya Modifiers"
        end
        return nil
    end
    local function canTrade(d, entry)
        if not (d and d.Data) then return false end
        if TradeData and type(TradeData.FollowTradeRules) == "function" then
            local ok, res = pcall(TradeData.FollowTradeRules, d, entry)
            if ok then return res == true end
        end
        return tradeRuleReason(d, entry) == nil
    end
    local function excluded(uuid)
        return _tr.sent[uuid] or _tr.blocked[uuid]
    end
    local function unitsOwned(list)
        local buckets, owned = {}, {}
        for _, entry in ipairs(list) do buckets[entry.Bucket or "Items"] = true end
        for bucket in pairs(buckets) do
            for _, entry in ipairs(bucketList(bucket)) do
                if entry.UUID then owned[entry.UUID] = unitCount(entry) end
            end
        end
        local out = {}
        for _, entry in ipairs(list) do out[entry.UUID] = owned[entry.UUID] or 0 end
        return out
    end
    local function movedSince(list, baseline)
        local now, moved = unitsOwned(list), 0
        for _, entry in ipairs(list) do
            local gone = (baseline[entry.UUID] or 0) - (now[entry.UUID] or 0)
            if gone > 0 then moved += gone end
        end
        return moved, now
    end
    local function scan(bucket, accept)
        local out = {}
        for _, entry in ipairs(bucketList(bucket)) do
            local uuid = entry.UUID
            if uuid and not excluded(uuid) then
                local d = dataForEntry(bucket, entry.Id)
                if d and canTrade(d, entry) and accept(d, entry) then
                    table.insert(out, {
                        UUID     = uuid,
                        Bucket   = bucket,
                        Category = d.Data.Type,
                        Name     = d.Data.Name or "?",
                        Stock    = unitCount(entry),
                        Price    = 0,
                    })
                end
            end
        end
        return out
    end
    local function totalUnits(list)
        local n = 0
        for _, entry in ipairs(list) do n += entry.Stock end
        return n
    end
    local function buildBatch(pool, remaining)
        table.sort(pool, function(a, b)
            if a.Stock ~= b.Stock then return a.Stock < b.Stock end
            return tostring(a.UUID) < tostring(b.UUID)
        end)
        local batch = {}
        local limit = math.min(MAX_IN_TRADE, remaining, #pool)
        for i = 1, limit do batch[i] = pool[i] end
        return batch, #batch
    end
    local function serverNow() return workspace:GetServerTimeNow() end
    local function isBusy(player)
        return (player and player.Parent and player:GetAttribute("IsTrading")) and true or false
    end
    local function waitUntilIdle(target, timeout)
        local deadline = os.clock() + (timeout or 25)
        while os.clock() < deadline do
            if not _tr.running then return false end
            if not isBusy(LocalPlayer) and not isBusy(target) then return true end
            setStatus("Nunggu trade sebelumnya kelar...")
            task.wait(0.2)
        end
        return not isBusy(LocalPlayer) and not isBusy(target)
    end
    local function targetAcceptsTrades(target)
        if not (Replion and Replion.Client) then return true end
        local ok, rep = pcall(function() return Replion.Client:GetReplion("ReplicatedPlayerData") end)
        if not ok or not rep then return true end
        local ok2, record = pcall(function() return rep:Get("User_" .. target.UserId) end)
        if not ok2 or type(record) ~= "table" then return true end
        local settings = record.TradeSettings
        if type(settings) ~= "table" then return true end
        return settings.Trades == true
    end
    local function runTrade(items, coinValue)
        if not (_tr.running and TradeData and Replion) then return false, 0 end
        local target = Players:FindFirstChild(_tr.target or "")
        if not target then
            _tr.lastError = "target player gak ada di server"
            setStatus("Error: " .. _tr.lastError)
            return false, 0
        end
        if not targetAcceptsTrades(target) then
            _tr.lastError = ("%s lagi matiin trade request di setting-nya"):format(target.Name)
            setStatus("Error: " .. _tr.lastError)
            return false, 0
        end
        if not waitUntilIdle(target, 25) then
            if not _tr.running then return false, 0 end
            _tr.failed   += 1
            _tr.lastError = "salah satu pemain masih nyangkut di trade sebelumnya"
            setStatus("Gagal: " .. _tr.lastError)
            return false, 0
        end
        _tr.attempts += 1
        local label   = #items == 1 and items[1].Name or ("%d item"):format(#items)
        local myKey   = tostring(LocalPlayer.UserId)
        local session = {
            replion = nil, replionId = nil, result = nil,
            offerSent = false, alive = true, conns = {},
        }
        local function bind(signal, fn)
            local ok, conn = pcall(function() return signal:Connect(fn) end)
            if ok and conn then table.insert(session.conns, conn) end
        end
        local function cleanup()
            session.alive = false
            for _, conn in ipairs(session.conns) do pcall(function() conn:Disconnect() end) end
            table.clear(session.conns)
            if _tr.activeCleanup then _tr.activeCleanup = nil end
        end
        _tr.activeCleanup = cleanup
        local function adopt(rep)
            if not session.alive or session.replion then return end
            if not rep or rep.Destroyed then return end
            local d = rep.Data
            if type(d) ~= "table" then return end
            if not (type(d.Players) == "table" and d.Players[myKey]) then return end
            session.replion = rep
        end
        local function lookup(id)
            if not id then return nil end
            local ok, rep = pcall(function() return Replion.Client:GetReplion(id) end)
            return ok and rep or nil
        end
        bind(TradeData.Remotes.TradeCompleted.OnClientEvent, function()
            if session.offerSent and session.result == nil then session.result = true end
        end)
        bind(TradeData.Remotes.TradeEnded.OnClientEvent, function()
            if session.offerSent and session.result == nil then session.result = false end
        end)
        bind(TradeData.Remotes.TradeStarted.OnClientEvent, function(replionId)
            if not session.alive then return end
            session.replionId = replionId
            adopt(lookup(replionId))
        end)
        pcall(function()
            local conn = Replion.Client:OnReplionAdded(inScriptContext(function(rep)
                if session.alive then adopt(rep) end
            end))
            if conn then table.insert(session.conns, conn) end
        end)
        local function tradeData()
            local rep = session.replion
            if not rep or rep.Destroyed then return nil end
            local d = rep.Data
            return type(d) == "table" and d or nil
        end
        local function mySide()
            local d = tradeData()
            return (d and type(d.Players) == "table") and d.Players[myKey] or nil
        end
        local function stillOpen()
            return _tr.running and session.result == nil and tradeData() ~= nil
        end
        local function lockRemaining()
            local d = tradeData()
            local lmt = d and d.LastModifiedTime
            if type(lmt) ~= "number" then return 0 end
            return (lmt + LOCK_SECONDS) - serverNow()
        end
        local function offeredSet()
            local mine = mySide()
            if not (mine and type(mine.Items) == "table") then return nil end
            local out = {}
            for _, group in pairs(mine.Items) do
                if type(group) == "table" then
                    for key, value in pairs(group) do
                        local uuid = (type(value) == "table" and value.UUID) or key
                        if type(uuid) == "string" then out[uuid] = true end
                    end
                end
            end
            return out
        end
        local baseline = nil
        local function waitInventorySettled(list, expected, timeout)
            if not baseline then return end
            local deadline = os.clock() + (timeout or 6)
            while os.clock() < deadline do
                if movedSince(list, baseline) >= expected then return end
                task.wait(0.15)
            end
        end
        local function settle(list, ok)
            cleanup()
            baseline = baseline or unitsOwned(list)
            if ok ~= false then waitInventorySettled(list, #list, ok and 6 or 3) end
            local moved, now = movedSince(list, baseline)
            for _, entry in ipairs(list) do
                if (now[entry.UUID] or 0) <= 0 then _tr.sent[entry.UUID] = true end
            end
            local success = moved > 0
            if success then
                _tr.success   += 1
                _tr.itemsSent += moved
                _tr.coinsSent += (coinValue or 0)
                setStatus(("Sukses: %s - %d unit pindah (total %d)"):format(label, moved, _tr.itemsSent))
            else
                _tr.failed += 1
                if _tr.lastError == "" then _tr.lastError = "trade kelar tapi gak ada item yang pindah" end
                setStatus(("Gagal: %s"):format(label))
            end
            task.wait(PACE.settle)
            return success, moved
        end
        local function abort(reason, list)
            _tr.lastError = reason
            task.spawn(function() pcall(function() TradeData.Remotes.CancelTrade:InvokeServer() end) end)
            cleanup()
            local moved = 0
            if list and baseline then
                task.wait(0.5)
                local now
                moved, now = movedSince(list, baseline)
                for _, entry in ipairs(list) do
                    if (now[entry.UUID] or 0) <= 0 then _tr.sent[entry.UUID] = true end
                end
            end
            if moved > 0 then
                _tr.success   += 1
                _tr.itemsSent += moved
                setStatus(("Sukses (nyusul): %s - %d unit pindah"):format(label, moved))
                task.wait(PACE.settle)
                return true, moved
            end
            _tr.failed += 1
            setStatus(reason)
            task.wait(0.8)
            return false, 0
        end
        setStatus(("Kirim offer ke %s: %s"):format(target.Name, label))
        local sentOk, sentValue, sentErr = invoke(TradeData.Remotes.SendTradeOffer, 10, target)
        if not sentOk or not sentValue then
            cleanup()
            _tr.failed   += 1
            _tr.lastError = "Gagal kirim offer: " .. tostring(sentErr or sentValue or "?")
            setStatus(_tr.lastError)
            task.wait(1)
            return false, 0
        end
        session.offerSent = true
        setStatus("Nunggu target nerima offer...")
        local offerDeadline = os.clock() + OFFER_TIMEOUT
        while session.alive and not session.replion and os.clock() < offerDeadline do
            if not _tr.running then cleanup(); return false, 0 end
            if session.result ~= nil then return settle(items, session.result) end
            if session.replionId then adopt(lookup(session.replionId)) end
            task.wait(0.1)
        end
        if not session.replion then
            return abort(("Target gak nerima offer dalam %ds"):format(OFFER_TIMEOUT))
        end
        baseline = unitsOwned(items)
        setStatus(("Masukin %d item ke offer..."):format(#items))
        local pending = {}
        for _, entry in ipairs(items) do pending[entry.UUID] = true end
        local addDeadline = os.clock() + 75
        for _ = 1, 3 do
            local queue = {}
            for _, entry in ipairs(items) do
                if pending[entry.UUID] then table.insert(queue, entry) end
            end
            if #queue == 0 then break end
            for _, entry in ipairs(queue) do
                if not stillOpen() or os.clock() > addDeadline then break end
                local ok, added, err = invoke(TradeData.Remotes.AddItem, 8, entry.Category, entry.UUID)
                if ok and added then
                    pending[entry.UUID] = nil
                elseif ok then
                    pending[entry.UUID]    = nil
                    _tr.blocked[entry.UUID] = true
                    _tr.skipped += 1
                    _tr.lastError = ("%s ditolak: %s"):format(entry.Name, tostring(err or added))
                end
                task.wait(PACE.addItem)
            end
            local set = offeredSet()
            if set then
                for uuid in pairs(set) do
                    if pending[uuid] then pending[uuid] = nil end
                    if _tr.blocked[uuid] then
                        _tr.blocked[uuid] = nil
                        _tr.skipped = math.max(0, _tr.skipped - 1)
                    end
                end
            end
            if next(pending) == nil then break end
            if not stillOpen() or os.clock() > addDeadline then break end
            task.wait(0.3)
        end
        if session.result ~= nil then return settle(items, session.result) end
        if not stillOpen() then return abort("Trade keburu berakhir pas masukin item", items) end
        local offered = offeredSet()
        local accepted = {}
        for _, entry in ipairs(items) do
            if offered then
                if offered[entry.UUID] then table.insert(accepted, entry) end
            elseif not pending[entry.UUID] and not _tr.blocked[entry.UUID] then
                table.insert(accepted, entry)
            end
        end
        if #accepted == 0 then
            return abort("Gak ada item yang berhasil masuk ke offer", items)
        end
        local lockDeadline = os.clock() + 60
        while os.clock() < lockDeadline do
            if not stillOpen() then break end
            local left = lockRemaining()
            if left <= 0 then break end
            setStatus(("Lock countdown: %.1fs (%d item siap)"):format(left, #accepted))
            task.wait(math.clamp(left, 0.1, 0.5))
        end
        if session.result ~= nil then return settle(accepted, session.result) end
        if not stillOpen() then return abort("Trade berakhir pas lock countdown", accepted) end
        local function iAmReady()
            local mine = mySide()
            return mine ~= nil and mine.IsReady == true
        end
        local function bothReady()
            local d = tradeData()
            if not d then return false end
            if d.PlayersReady == true then return true end
            if type(d.PlayersReady) == "table" then
                local any = false
                for _, v in pairs(d.PlayersReady) do
                    if not v then return false end
                    any = true
                end
                return any
            end
            return false
        end
        setStatus(("Set ready (%d item)..."):format(#accepted))
        local readyDeadline, nextReady, paired = os.clock() + 180, 0, false
        while os.clock() < readyDeadline do
            if not stillOpen() then break end
            if bothReady() then
                paired = true
                break
            end
            if not iAmReady() and lockRemaining() <= 0 and os.clock() >= nextReady then
                nextReady = os.clock() + 1.2
                invoke(TradeData.Remotes.SetReady, 8, true)
            elseif iAmReady() then
                setStatus("Nunggu lawan ready...")
            end
            task.wait(0.15)
        end
        if session.result ~= nil then return settle(accepted, session.result) end
        if not stillOpen() then return abort("Trade berakhir pas nunggu ready", accepted) end
        if not paired then return abort("Lawan gak ready dalam 180s", accepted) end
        local function iAmConfirmed()
            local mine = mySide()
            return mine ~= nil and mine.IsConfirmed == true
        end
        setStatus("Konfirmasi trade...")
        local confirmDeadline, nextConfirm = os.clock() + 180, 0
        while session.result == nil and os.clock() < confirmDeadline do
            if not _tr.running then break end
            if tradeData() == nil then break end
            if not iAmConfirmed() and lockRemaining() <= 0 and os.clock() >= nextConfirm then
                nextConfirm = os.clock() + 1.2
                task.spawn(function() pcall(function() TradeData.Remotes.ConfirmTrade:InvokeServer() end) end)
            elseif iAmConfirmed() then
                setStatus("Nunggu lawan konfirmasi...")
            end
            task.wait(0.15)
        end
        if session.result == nil and os.clock() >= confirmDeadline then
            return abort("Lawan gak konfirmasi dalam 180s", accepted)
        end
        return settle(accepted, session.result)
    end
    local function makeTypeHandler(itemType, opts)
        opts = opts or {}
        local H = { itemType = itemType, bucket = bucketFor(itemType), names = {}, blockedNames = {} }
        local CATALOG_PROBE = {}
        function H.buildCatalog()
            H.names, H.blockedNames = {}, {}
            pcall(function()
                if not (ItemUtility and opts.getAll) then return end
                local seen = {}
                for _, d in pairs(opts.getAll() or {}) do
                    local dd = d and d.Data
                    if type(dd) == "table" and dd.Name and dd.Type == itemType and not seen[dd.Name] then
                        if not (opts.filter and not opts.filter(d)) then
                            seen[dd.Name] = true
                            if canTrade(d, CATALOG_PROBE) then
                                table.insert(H.names, dd.Name)
                            else
                                H.blockedNames[dd.Name] = tradeRuleReason(d, CATALOG_PROBE) or "ditolak server"
                            end
                        end
                    end
                end
                table.sort(H.names)
            end)
            return H.names
        end
        function H.countOwned()
            local counts, blocked = {}, {}
            for _, entry in ipairs(bucketList(H.bucket)) do
                local d = dataForEntry(H.bucket, entry.Id)
                if d and d.Data.Type == itemType and not (opts.filter and not opts.filter(d)) then
                    local name = d.Data.Name or "?"
                    counts[name] = (counts[name] or 0) + unitCount(entry)
                    if not canTrade(d, entry) then
                        blocked[name] = tradeRuleReason(d, entry) or "ditolak server"
                    end
                end
            end
            return counts, blocked
        end
        function H.collect(selected)
            return scan(H.bucket, function(d)
                if d.Data.Type ~= itemType then return false end
                if opts.filter and not opts.filter(d) then return false end
                return selected[d.Data.Name or "?"] == true
            end)
        end
        return H
    end
    local StoneTrade = makeTypeHandler("Enchant Stones", {
        getAll = function() return ItemUtility:GetEnchantStones() end,
    })
    local CharmTrade = makeTypeHandler("Charms", {
        getAll = function() return ItemUtility:GetCharms() end,
    })
    local BaitSkinTrade = makeTypeHandler("Baits", {
        getAll = function() return ItemUtility:GetBaits() end,
        filter = function(d) return d.IsSkin == true end,
    })
    local GearTrade = makeTypeHandler("Gears", {
        getAll = function() return ItemUtility:GetGears() end,
    })
    local function collectFish(match)
        return scan("Items", function(d, entry)
            return d.Data.Type == "Fish" and entry.Favorited ~= true and match(d, entry)
        end)
    end
    local MODES = {
        ByName = {
            label   = "ikan",
            collect = function() return collectFish(function(d) return d.Data.Name == _tr.item end) end,
            total   = function() return _tr.itemAmount end,
            empty   = "Ikan itu gak ada / gak bisa ditrade",
            needSelection = function() return _tr.item ~= nil end,
            missing = "pilih ikan dulu di dropdown",
        },
        ByRarity = {
            label   = "ikan",
            collect = function() return collectFish(function(d) return TIER_NAME[d.Data.Tier] == _tr.rarity end) end,
            total   = function() return _tr.rarityAmount end,
            empty   = "Gak ada ikan dengan rarity itu",
        },
        ByEnchantStone = {
            label   = "enchant stone",
