    local function pricedFish()
        local multiplier = 1
        pcall(function()
            local modifiers = PlayerStatsUtility:GetPlayerModifiers(LocalPlayer)
            multiplier = (modifiers and modifiers.CoinMultiplier) or 1
        end)
        local out = {}
        for _, entry in ipairs(bucketList("Items")) do
            local uuid = entry.UUID
            if uuid and not excluded(uuid) and entry.Favorited ~= true then
                local d = dataForEntry("Items", entry.Id)
                if d and d.Data.Type == "Fish" and canTrade(d, entry) then
                    local price = 0
                    pcall(function() price = VendorUtility:GetSellPrice(entry) or d.SellPrice or 0 end)
                    if price == 0 then price = d.SellPrice or 0 end
                    price = math.ceil(price * multiplier)
                    if price > 0 then
                        table.insert(out, {
                            UUID   = uuid, Bucket = "Items", Category = "Fish",
                            Name   = d.Data.Name or "?", Stock = unitCount(entry), Price = price,
                        })
                    end
                end
            end
        end
        table.sort(out, function(a, b) return a.Price < b.Price end)
        return out
    end
    local function failWait(fails)
        local wait = math.min(2 + fails, 8)
        setStatus(("Gagal (%d/%d), ulangi %ds lagi... [%s]"):format(
            fails, MAX_FAILS, wait, _tr.lastError ~= "" and _tr.lastError or "gak diketahui"))
        for _ = 1, math.ceil(wait / 0.25) do
            if not _tr.running then return end
            task.wait(0.25)
        end
    end
    local function runByCoin(config)
        local remaining = config.total()
        if remaining <= 0 then
            setStatus("Error: target coins harus lebih dari 0")
            return
        end
        local fails = 0
        while _tr.running and remaining > 0 do
            local pool = pricedFish()
            if #pool == 0 then
                setStatus("Berhenti: " .. config.empty)
                break
            end
            local batch, value = {}, 0
            for _, entry in ipairs(pool) do
                if #batch >= MAX_IN_TRADE or value >= remaining then break end
                table.insert(batch, entry)
                value += entry.Price
            end
            if #batch == 0 then break end
            setStatus(("Batch %d - %d ikan ~%d coins"):format(_tr.success + 1, #batch, value))
            local ok = runTrade(batch, value)
            if ok then
                fails = 0
                remaining -= value
            elseif not _tr.running then
                break
            else
                fails += 1
                if fails >= MAX_FAILS then
                    setStatus(("Berhenti: gagal %dx berturut-turut. Terakhir: %s"):format(
                        fails, _tr.lastError ~= "" and _tr.lastError or "gak diketahui"))
                    break
                end
                failWait(fails)
            end
        end
    end
    local function runUnits(config)
        if config.needSelection and not config.needSelection() then
            setStatus("Error: " .. (config.missing or "pilihan belum diisi"))
            return
        end
        local total = config.total()
        if total < 1 then
            setStatus("Error: jumlah harus lebih dari 0")
            return
        end
        local available = totalUnits(config.collect())
        if available == 0 then
            setStatus("Error: " .. config.empty)
            return
        end
        if total > available then total = available end
        _tr.batches = math.max(1, math.ceil(total / MAX_IN_TRADE))
        setStatus(("Mulai: %d unit %s (punya %d)"):format(total, config.label, available))
        local traded, fails = 0, 0
        while _tr.running and traded < total do
            local pool = config.collect()
            if #pool == 0 then
                setStatus(("Berhenti: %s (%d/%d unit terkirim)"):format(config.empty, traded, total))
                break
            end
            local remaining = total - traded
            local batch, units = buildBatch(pool, remaining)
            if #batch == 0 then break end
            local stacks = 0
            for _, entry in ipairs(batch) do
                if entry.Stock > 1 then stacks += 1 end
            end
            setStatus(("Batch %d - kirim %d unit%s | progress %d/%d"):format(
                _tr.success + 1, units,
                stacks > 0 and (" (%d dari stack)"):format(stacks) or "",
                traded, total))
            local ok, moved = runTrade(batch, 0)
            if ok then
                fails = 0
                traded += (moved > 0 and moved or units)
                if traded < total and _tr.running then
                    setStatus(("Terkirim %d/%d unit. Lanjut..."):format(traded, total))
                end
            elseif not _tr.running then
                break
            else
                fails += 1
                if fails >= MAX_FAILS then
                    setStatus(("Berhenti: gagal %dx berturut-turut (%d/%d unit). Terakhir: %s"):format(
                        fails, traded, total, _tr.lastError ~= "" and _tr.lastError or "gak diketahui"))
                    break
                end
                failWait(fails)
            end
        end
    end
    local function stopTrade()
        if not _tr.running then return end
        _tr.running = false
        if _tr.activeCleanup then pcall(_tr.activeCleanup) end
        task.spawn(function()
            pcall(function() TradeData.Remotes.CancelTrade:InvokeServer() end)
        end)
        setStatus(("Dihentikan - %d unit terkirim"):format(_tr.itemsSent))
    end
    local function startTrade(mode, monitor, toggle)
        if _tr.running then stopTrade() end
        local deadline = os.clock() + 12
        while _tr.threadAlive and os.clock() < deadline do task.wait(0.1) end
        if _tr.threadAlive then
            if _tr.thread then pcall(task.cancel, _tr.thread) end
            _tr.threadAlive, _tr.thread = false, nil
        end
        _tr.monitor, _tr.toggle, _tr.mode = monitor, toggle, mode
        local function reject(reason)
            setStatus("Error: " .. reason)
            task.defer(function() pcall(function() toggle:SetValue(false) end) end)
        end
        if not (TradeData and Replion) then return reject("modul trade gagal dimuat") end
        if not Data then
            Data = getCachedReplionData()
            if not Data then return reject("data inventory belum siap, coba lagi") end
        end
        if not _tr.target then return reject("target player belum dipilih") end
        local target = Players:FindFirstChild(_tr.target)
        if not target then return reject("target player gak ada di server") end
        if not targetAcceptsTrades(target) then
            return reject(("%s matiin trade request di setting-nya"):format(target.Name))
        end
        local config = MODES[mode]
        if not config then return reject("mode trade gak dikenal") end
        resetStats()
        _tr.running     = true
        _tr.threadAlive = true
        setStatus("Mulai...")
        _tr.thread = task.spawn(function()
            local ok, err = pcall(function()
                if config.byCoin then runByCoin(config) else runUnits(config) end
            end)
            if not ok then
                _tr.lastError = tostring(err)
                setStatus("Error: " .. tostring(err))
            end
            if _tr.running then
                _tr.running = false
                local previous = _tr.status or ""
                if not (previous:find("^Berhenti") or previous:find("^Error")) then
                    setStatus(_tr.attempts == 0 and "Selesai: gak ada trade yang dijalankan"
                        or ("Selesai - %d unit terkirim"):format(_tr.itemsSent))
                end
            end
            if _tr.activeCleanup then pcall(_tr.activeCleanup) end
            _tr.threadAlive = false
            pcall(function() toggle:SetValue(false) end)
        end)
        return
    end
