    local function addBucketSection(title, mode, toggleTitle, handler, info, dropdownTitle, amountTitle, noun, setter)
        return addModeSection(title, mode, toggleTitle, function(section, monitor)
            if info then section:AddParagraph({ Title = "Info", Content = info }) end
            handler.buildCatalog()
            local dropdown = section:AddDropdown({
                Title    = dropdownTitle,
                Options  = #handler.names > 0 and handler.names or { "Tidak ada yang bisa ditrade" },
                Default  = {},
                Multi    = true,
                Callback = function(selected)
                    local set = {}
                    if type(selected) == "table" then
                        for _, name in ipairs(selected) do set[name] = true end
                    end
                    setter(set, nil)
                end,
            })
            section:AddInput({
                Title    = amountTitle,
                Default  = "1",
                Callback = function(value)
                    setter(nil, math.max(1, math.floor(tonumber(value) or 1)))
