                        table.insert(list, ("%s x%d%s"):format(
                            name, count, blocked[name] and ("  [GAK BISA: " .. blocked[name] .. "]") or ""))
                    end
                    table.sort(list)
                    pcall(function()
                        monitor:SetContent(#list > 0 and (noun .. " di inventory:\n" .. table.concat(list, "\n"))
                            or ("Gak ada " .. noun .. " di inventory"))
                    end)
                end,
            })
            section:AddButton({
                Title    = "Refresh " .. noun .. " List",
                Callback = function()
                    handler.buildCatalog()
                    pcall(function()
                        dropdown:SetOptions(#handler.names > 0 and handler.names
                            or { "Tidak ada yang bisa ditrade" })
                    end)
                    local notes = {}
                    for name, reason in pairs(handler.blockedNames) do
                        table.insert(notes, ("%s - %s"):format(name, reason))
                    end
                    table.sort(notes)
                    pcall(function()
                        monitor:SetContent(("List diperbarui: %d %s bisa ditrade.%s"):format(
                            #handler.names, noun,
                            #notes > 0 and ("\n\nDikunci server:\n" .. table.concat(notes, "\n")) or ""))
                    end)
                end,
            })
        end)
    end
