    })
    local function handleIncomingTrade(replionId)
        local myKey = tostring(LocalPlayer.UserId)
        local replion
        local deadline = os.clock() + 10
        while os.clock() < deadline do
            local ok, rep = pcall(function() return Replion.Client:GetReplion(replionId) end)
            if ok and rep and not rep.Destroyed and type(rep.Data) == "table"
                and type(rep.Data.Players) == "table" and rep.Data.Players[myKey] then
                replion = rep
                break
            end
            task.wait(0.1)
        end
        if not replion then return end
        local function data()
            if replion.Destroyed then return nil end
            return type(replion.Data) == "table" and replion.Data or nil
        end
        local function alive()
            return _accept.enabled and not _tr.running and data() ~= nil
        end
        local function mySide()
            local d = data()
            return (d and type(d.Players) == "table") and d.Players[myKey] or nil
        end
        local function lockRemaining()
            local d = data()
            local lmt = d and d.LastModifiedTime
            if type(lmt) ~= "number" then return 0 end
            return (lmt + LOCK_SECONDS) - workspace:GetServerTimeNow()
        end
        local function bothReady()
            local d = data()
            if not d then return false end
            if d.PlayersReady == true then return true end
            if type(d.PlayersReady) == "table" then
                local any = false
                for _, v in pairs(d.PlayersReady) do
                    if not v then return false end
                    any = true
                end
                return any
            end
            return false
        end
        local overall = os.clock() + 600
        local nextReady, nextConfirm = 0, 0
        while alive() and os.clock() < overall do
            local mine = mySide()
            if mine then
                if lockRemaining() <= 0 then
                    if not bothReady() then
                        if mine.IsReady ~= true and os.clock() >= nextReady then
                            nextReady = os.clock() + 1.2
                            pcall(function() TradeData.Remotes.SetReady:InvokeServer(true) end)
                        end
                    elseif mine.IsConfirmed ~= true and os.clock() >= nextConfirm then
                        nextConfirm = os.clock() + 1.2
                        pcall(function() TradeData.Remotes.ConfirmTrade:InvokeServer() end)
                    end
                end
            end
            task.wait(0.2)
        end
    end
    AcceptSection:AddToggle({
        Title    = "Enable Auto Accept Trade",
        Default  = false,
        NoSave   = true,
        Callback = function(on)
            if not on then
                _accept.enabled = false
                if _accept.hooked and _accept.origFire then
                    pcall(function()
                        cachedRequire(ReplicatedStorage.Controllers.PromptController).FirePrompt = _accept.origFire
                    end)
                    _accept.origFire, _accept.hooked = nil, false
                end
                for _, conn in ipairs(_accept.conns) do pcall(function() conn:Disconnect() end) end
                table.clear(_accept.conns)
                Library:MakeNotify({ Title = "Auto Accept Trade", Description = "Dihentikan", Delay = 2 })
                return
            end
            if _accept.enabled then return end
            if not (TradeData and Replion) then
                Library:MakeNotify({ Title = "Auto Accept Trade", Description = "Modul trade gagal dimuat", Delay = 3 })
                return
            end
            if not _accept.hooked then
                pcall(function()
                    local controller = cachedRequire(ReplicatedStorage.Controllers.PromptController)
                    _accept.origFire = controller.FirePrompt
                    controller.FirePrompt = function(self, message, ...)
                        if _accept.enabled then
                            local text = tostring(message or ""):lower()
                            if text:find("trade request") or text:find("do you want to accept") then
                                return cachedRequire(ReplicatedStorage.Packages.Promise).resolve(true)
                            end
                        end
                        return _accept.origFire(self, message, ...)
                    end
                    _accept.hooked = true
                end)
            end
            _accept.enabled = true
            table.insert(_accept.conns, TradeData.Remotes.TradeStarted.OnClientEvent:Connect(function(replionId)
                if not _accept.enabled or _tr.running then return end
                task.spawn(function() handleIncomingTrade(replionId) end)
            end))
            local warned = false
            pcall(function()
                local rep = Replion.Client:GetReplion("ReplicatedPlayerData")
                local record = rep and rep:Get("User_" .. LocalPlayer.UserId)
                local settings = record and record.TradeSettings
                if type(settings) == "table" and settings.Trades ~= true then
                    warned = true
                    Library:MakeNotify({
                        Title = "Auto Accept Trade",
                        Description = "Setting 'Trades' kamu lagi OFF - request masuk gak bakal kebaca",
                        Delay = 5,
                    })
                end
            end)
            if not warned then
                Library:MakeNotify({ Title = "Auto Accept Trade", Description = "Dimulai", Delay = 2 })
            end
        end,
    })
end
-- [Webhook Tab]
task.wait()
do
    local cleanStr, cleanId, formatPrice     = Webhook.cleanStr, Webhook.cleanId, Webhook.formatPrice
    local queueWebhook, sendHTTP             = Webhook.queue, Webhook.send
    local extractAssetId, getDiscordImageUrl = Webhook.assetId, Webhook.imageUrl
    local buildDiscordPayload                = Webhook.payload
    local TIER_NAMES, TIER_COLORS            = Webhook.TierNames, Webhook.TierColors
    local BOT_NAME    = "Lynx"
    local function buildMention(userId)
        if userId ~= "" and #userId >= 17 then
            return "<@" .. userId .. ">"
        end
        return ""
    end
    local function buildPayload(opts)
        local mention     = buildMention(opts.userId or "")
        local contentText = opts.contentText
            or (mention ~= "" and (mention .. " " .. (opts.alertText or "")) or (opts.alertText or ""))
        return buildDiscordPayload({
            botName    = BOT_NAME,
            mention    = mention,
            content    = contentText,
            authorName = BOT_NAME .. " Webhook | " .. (opts.headerTitle or ""),
            footerName = BOT_NAME .. " Webhook",
            bodyText   = opts.bodyText,
            color      = opts.color,
            fields     = opts.fields,
            imageUrl   = opts.imageUrl,
        })
    end
    local function getDisplayName(hideStr, fallback)
        return (hideStr ~= "") and hideStr or (fallback or (LocalPlayer.DisplayName or LocalPlayer.Name))
    end
    local Items   = {}
    local Variants = {}
    local _itemsLoaded  = false
    local _itemsLoading = false
    local function scanModulesRecursive(folder, target)
        for _, child in ipairs(folder:GetChildren()) do
            if child:IsA("ModuleScript") then
                local ok, data = pcall(require, child)
                if ok and type(data) == "table" and data.Data then
                    table.insert(target, data)
                end
            else
                local hasChildren = false
                pcall(function() hasChildren = #child:GetChildren() > 0 end)
                if hasChildren then
                    scanModulesRecursive(child, target)
                end
            end
        end
    end
    local function loadItems()
        if _itemsLoaded then return true end
        if _itemsLoading then return false end
        _itemsLoading = true
        pcall(function()
            local itemsFolder    = ReplicatedStorage:FindFirstChild("Items")
            local variantsFolder = ReplicatedStorage:FindFirstChild("Variants")
            if itemsFolder    then scanModulesRecursive(itemsFolder,    Items)    end
            if variantsFolder then scanModulesRecursive(variantsFolder, Variants) end
        end)
        _itemsLoaded  = true
        _itemsLoading = false
        return true
    end
    local function getFish(itemId)
        local idNum = tonumber(itemId)
        local idStr = tostring(itemId)
        for _, f in ipairs(Items) do
            if f.Data then
                local fId = f.Data.Id
                if fId == idNum or fId == idStr or tostring(fId) == idStr then
                    return f
                end
            end
        end
        return nil
    end
    local function getVariant(id)
        local idStr = tostring(id)
        for _, v in ipairs(Variants) do
            if v.Data and (tostring(v.Data.Id) == idStr or tostring(v.Data.Name) == idStr) then return v end
        end
        return nil
    end
    local function getFishImageUrl(fish)
        if not fish or not fish.Data then return "https://i.imgur.com/UMWNYK7.png" end
        local d = fish.Data
        local assetId = extractAssetId(d.Icon) or extractAssetId(d.ImageId) or extractAssetId(d.Image)
        if assetId then
            local url = getDiscordImageUrl(assetId)
            if url then return url end
        end
        return "https://i.imgur.com/UMWNYK7.png"
    end
    local WebhookTab = MainWindow:AddTab({ Name = "Webhook", Icon = "send" })
    local FishSection = WebhookTab:AddSection("Fish Caught Webhook")
    local _fishState  = {
        url = "", id = "", hide = "",
        rarities = {}, filterNames = {}, filterVariants = {}, weightMode = "All",
        running = false, conn = nil, gearConn = nil, caughtConn = nil,
    }
    local function isMaxTon(itemData, weight)
        local ok, res = pcall(function() return tonumber(weight) >= itemData.Weight.Big.Max end)
        return ok and res == true
    end
    local _fishDebounce        = {}
    local _recentCatch         = {}   -- item name -> metadata of its latest FishCaught
    local FISH_DEBOUNCE_TIME   = 0.5
    local _fishDebounceCleanup = 0
    FishSection:AddInput({ Title = "Webhook URL (Fish)",     Default = "", Placeholder = "https://discord.com/api/webhooks/...", Callback = function(v) _fishState.url  = cleanStr(v) end })
    FishSection:AddInput({ Title = "Discord User ID (Fish)", Default = "", Placeholder = "123456789012345678",                  Callback = function(v) _fishState.id   = cleanId(v)  end })
    FishSection:AddInput({ Title = "Hide Identity (Fish)",   Default = "", Placeholder = "Enter custom name...",                Callback = function(v) _fishState.hide = cleanStr(v) end })
    FishSection:AddParagraph({
        Title   = "Filter Logic (AND)",
        Content = "All active filters work as AND.\nEmpty filters are ignored.\nExample: Mythic + Corrupt → only Mythic fish with Corrupt variant.",
    })
    FishSection:AddDropdown({
        Title    = "Rarity Filter (empty = all)",
        Options  = { "Common","Uncommon","Rare","Epic","Legendary","Mythic","SECRET","FORGOTTEN" },
        Multi    = true, Default = {},
        Callback = function(sel) _fishState.rarities = type(sel) == "table" and sel or {} end,
    })
    FishSection:AddDropdown({
        Title    = "Weight Filter (Fish)",
        Options  = { "All", "MaxTon Only" },
        Default  = "All",
        Callback = function(v) _fishState.weightMode = (v == "MaxTon Only") and v or "All" end,
    })
    local _whFishList    = {}
    local _whVariantList = {}
    local _whListsBuilt  = false
    local WH_NAME_FILTER_TYPES = {
        ["Fish"]           = true,
        ["Gears"]          = true,
        ["Enchant Stones"] = true,
    }
    local function buildWhFilterLists()
        if _whListsBuilt then return end
        _whListsBuilt = true
        pcall(function()
            local itemsFolder = ReplicatedStorage:FindFirstChild("Items")
            if not itemsFolder then return end
            local seen = {}
            local function scan(folder)
                for _, child in ipairs(folder:GetChildren()) do
                    if child:IsA("ModuleScript") then
                        local ok, data = pcall(require, child)
                        if ok and data and data.Data and WH_NAME_FILTER_TYPES[data.Data.Type] then
                            local name = data.Data.DisplayName or data.Data.Name
                            if name and not seen[name] then
                                seen[name] = true
                                _whFishList[#_whFishList + 1] = name
                            end
                        end
                    else
                        local hasChildren = false
                        pcall(function() hasChildren = #child:GetChildren() > 0 end)
                        if hasChildren then scan(child) end
                    end
                end
            end
            scan(itemsFolder)
        end)
        table.sort(_whFishList)
        pcall(function()
            local variantsFolder = ReplicatedStorage:FindFirstChild("Variants")
            if not variantsFolder then return end
            for _, m in ipairs(variantsFolder:GetChildren()) do
                if m:IsA("ModuleScript") and m.Name ~= "1x1x1x1" and not table.find(_whVariantList, m.Name) then
                    _whVariantList[#_whVariantList + 1] = m.Name
                end
            end
        end)
        table.sort(_whVariantList)
    end
    local _whNameDropdown = FishSection:AddDropdown({
        Title = "Name Filter (empty = all)", Options = _whFishList, Multi = true, Default = {},
        Callback = function(sel)
            local set = {}
            if type(sel) == "table" then for _, v in ipairs(sel) do set[v] = true end end
            _fishState.filterNames = set
        end,
    })
    local _whVariantDropdown = FishSection:AddDropdown({
        Title = "Variant Filter (empty = all)", Options = _whVariantList, Multi = true, Default = {},
        Callback = function(sel)
            local set = {}
            if type(sel) == "table" then for _, v in ipairs(sel) do set[v] = true end end
            _fishState.filterVariants = set
        end,
    })
    task.spawn(function()
        task.wait(3)
        buildWhFilterLists()
        local savedNames    = Library.ConfigSystem.Get("MultiDropdowns.Name_Filter_(empty_=_all)", {})
        local savedVariants = Library.ConfigSystem.Get("MultiDropdowns.Variant_Filter_(empty_=_all)", {})
        if type(savedNames)    ~= "table" then savedNames    = {} end
        if type(savedVariants) ~= "table" then savedVariants = {} end
        local nameFlag    = Library.flags and Library.flags["Name_Filter_(empty_=_all)"]
        local variantFlag = Library.flags and Library.flags["Variant_Filter_(empty_=_all)"]
        if nameFlag    and nameFlag.SetValues    then nameFlag:SetValues(_whFishList, savedNames)          end
        if variantFlag and variantFlag.SetValues then variantFlag:SetValues(_whVariantList, savedVariants) end
        if #savedNames > 0 then
            local set = {} for _, v in ipairs(savedNames) do set[v] = true end
            _fishState.filterNames = set
        end
        if #savedVariants > 0 then
            local set = {} for _, v in ipairs(savedVariants) do set[v] = true end
            _fishState.filterVariants = set
        end
    end)
    FishSection:AddToggle({
        Title = "Enable Fish Webhook", Default = false,
        Callback = function(on)
            if on then
                if _fishState.running then return end
                if _fishState.url == "" then warn("[Webhook] Fish URL is not set!"); return end
                if not getHTTP() then warn("[Webhook] Executor does not support HTTP!"); return end
                task.spawn(loadItems)
                task.spawn(buildWhFilterLists)
                local re = NetEvents.RE_ObtainedNewFishNotification
                if not re then warn("[Webhook] Event not found!"); return end
                _fishState.running = true
                _fishState.conn = re.OnClientEvent:Connect(function(itemId, metadata, extraData)
                    local now = tick()
                    if _fishDebounce[itemId] and (now - _fishDebounce[itemId]) < FISH_DEBOUNCE_TIME then return end
                    _fishDebounce[itemId] = now
                    if now - _fishDebounceCleanup > 30 then
                        _fishDebounceCleanup = now
                        for k, t in pairs(_fishDebounce) do if now - t > 10 then _fishDebounce[k] = nil end end
                    end
                    task.spawn(function()
                        if not _itemsLoaded then
                            local t0 = tick()
                            while not _itemsLoaded and tick() - t0 < 3 do task.wait(0.3) end
                            if not _itemsLoaded then pcall(loadItems) end
                        end
                        local fish = getFish(itemId)
                        if not fish then return end
                        local meta  = metadata  or {}
                        local extra = extraData  or {}
                        local tier  = TIER_NAMES[fish.Data and fish.Data.Tier]  or "Unknown"
                        local color = TIER_COLORS[fish.Data and fish.Data.Tier] or 3447003
                        local hasRarityFilter  = _fishState.rarities and next(_fishState.rarities)
                        local hasNameFilter    = next(_fishState.filterNames)   ~= nil
                        local hasVariantFilter = next(_fishState.filterVariants) ~= nil
                        local rarityOk, nameOk, variantOk = true, true, true
                        if hasRarityFilter then
                            rarityOk = false
                            for _, v in ipairs(_fishState.rarities) do if v == tier then rarityOk = true; break end end
                        end
                        if hasNameFilter then
                            local fn = (fish.Data and (fish.Data.DisplayName or fish.Data.Name)) or ""
                            nameOk = _fishState.filterNames[fn] == true
                        end
                        if not rarityOk or not nameOk then return end
                        local maxTon = isMaxTon(fish, meta.Weight)
                        if _fishState.weightMode == "MaxTon Only" and not maxTon then return end
                        local extraMeta  = type(extra.InventoryItem) == "table"
                                           and type(extra.InventoryItem.Metadata) == "table"
                                           and extra.InventoryItem.Metadata or nil
                        local variantId  = (extraMeta and (extraMeta.Variant or extraMeta.Mutation or extraMeta.VariantId))
                                        or extra.Variant or extra.Mutation or extra.VariantId
                                        or meta.Variant  or meta.Mutation  or meta.VariantId
                        local isShiny    = meta.Shiny or extra.Shiny or (extraMeta and extraMeta.Shiny)
                        local mutText    = "None"
                        local finalPrice = fish.SellPrice or 0
                        if isShiny then mutText = "Shiny"; finalPrice = finalPrice * 2 end
                        if variantId then
                            local v = getVariant(variantId)
                            if v then
                                local vname = v.Data and v.Data.Name or tostring(variantId)
                                mutText      = (isShiny and "Shiny " or "")
                                            .. vname .. " (" .. tostring(v.SellMultiplier or "?") .. "x)"
                                finalPrice   = finalPrice * (v.SellMultiplier or 1)
                                if hasVariantFilter then
                                    variantOk = _fishState.filterVariants[vname] == true
                                            or _fishState.filterVariants[tostring(variantId)] == true
                                end
                            else
                                mutText = (isShiny and "Shiny " or "") .. tostring(variantId)
                                if hasVariantFilter then variantOk = _fishState.filterVariants[tostring(variantId)] == true end
                            end
                        else
                            if hasVariantFilter then variantOk = false end
                        end
                        if not variantOk then return end
                        local fishName   = (fish.Data and (fish.Data.Name or fish.Data.DisplayName)) or "Unknown"
                        local playerName = getDisplayName(_fishState.hide)
                        local payload = buildPayload({
                            userId      = _fishState.id,
                            alertText   = "New **" .. tier .. "** fish caught! **" .. fishName .. "**",
                            headerTitle = "Fish Caught",
                            bodyText    = string.format("**||%s||** You have obtained a new **%s** fish — **%s**!", playerName, tier, fishName),
                            color       = color,
                            imageUrl    = "https://i.imgur.com/UMWNYK7.png",
                            fields = {
                                { name = "\227\128\162Fish Name :",  value = fishName,                                    inline = false },
                                { name = "\227\128\162Fish Tier :",  value = tier,                                        inline = false },
                                { name = "\227\128\162Weight :",     value = string.format("%.2f Kg%s", meta.Weight or 0, maxTon and " (MAXTON)" or ""), inline = false },
                                { name = "\227\128\162Mutation :",   value = mutText,                                     inline = false },
                                { name = "\227\128\162Sell Price :", value = formatPrice(finalPrice),                     inline = false },
                            },
                        })
                        local imageOk, imageUrl = pcall(getFishImageUrl, fish)
                        if imageOk and imageUrl then payload.embeds[1].image = { url = imageUrl } end
                        queueWebhook(_fishState.url, payload)
                    end)
                end)
                pcall(function()
                    _fishState.caughtConn = NetEvents.RE_FishCaught.OnClientEvent:Connect(function(name, meta)
                        if type(name) == "string" and type(meta) == "table" then
                            _recentCatch[name] = { meta = meta, at = os.clock() }
                        end
                    end)
                end)
                pcall(function()
                    local tnRE = NetEvents.RE_TextNotification
                    if not tnRE then return end
                    _fishState.gearConn = tnRE.OnClientEvent:Connect(function(data)
                        if not _fishState.running or _fishState.url == "" then return end
                        if type(data) ~= "table" then return end
                        if data.Type ~= "Item" then return end
                        if not data.ItemType or not data.ItemId then return end
                        if data.ItemType ~= "Gears" then return end
                        local debounceKey = tostring(data.ItemId)
                        local now = tick()
                        if _fishDebounce["gear_" .. debounceKey] and (now - _fishDebounce["gear_" .. debounceKey]) < FISH_DEBOUNCE_TIME then return end
                        _fishDebounce["gear_" .. debounceKey] = now
                        task.spawn(function()
                            local ItemUtility = cachedRequire(game:GetService("ReplicatedStorage").Shared.ItemUtility)
                            local itemData = nil
                            pcall(function()
                                itemData = ItemUtility.GetItemDataFromItemType(data.ItemType, data.ItemId)
                            end)
                            local itemName  = (itemData and itemData.Data and (itemData.Data.Name or itemData.Data.DisplayName)) or tostring(data.ItemId)
                            local itemTier  = (itemData and itemData.Data and itemData.Data.Tier) or 7
                            local tier      = TIER_NAMES[itemTier]  or "SECRET"
                            local color     = TIER_COLORS[itemTier] or 65535
                            local playerName = getDisplayName(_fishState.hide)
                            local hasRarityFilter = _fishState.rarities and next(_fishState.rarities)
                            if hasRarityFilter then
                                local rarityOk = false
                                for _, v in ipairs(_fishState.rarities) do if v == tier then rarityOk = true; break end end
                                if not rarityOk then return end
                            end
                            if next(_fishState.filterNames) ~= nil and not _fishState.filterNames[itemName] then return end
                            local mutText = "None"
                            local function readVariant(t)
                                if type(t) ~= "table" then return nil end
                                return t.Variant or t.Mutation or t.VariantId
                            end
                            local invItem = type(data.InventoryItem) == "table" and data.InventoryItem or nil
                            local invMeta = invItem and type(invItem.Metadata) == "table" and invItem.Metadata or nil
                            local catchMeta
                            for _ = 1, 20 do
                                local catch = _recentCatch[itemName]
                                if catch and os.clock() - catch.at < 5 then catchMeta = catch.meta; break end
                                task.wait(0.1)
                            end
                            local variantId = readVariant(catchMeta) or readVariant(invMeta) or readVariant(data)
                                           or readVariant(data.Metadata) or readVariant(data.ExtraData)
                            local isShiny = (catchMeta and catchMeta.Shiny)
                                or (invMeta and invMeta.Shiny)
                                or data.Shiny
                                or (type(data.Metadata) == "table" and data.Metadata.Shiny)
                                or (type(data.ExtraData) == "table" and data.ExtraData.Shiny)
                            local weight = (catchMeta and catchMeta.Weight)
                                or (invMeta and invMeta.Weight)
                                or (type(data.Metadata) == "table" and data.Metadata.Weight)
                                or nil
                            local maxTon = isMaxTon(itemData, weight)
                            if _fishState.weightMode == "MaxTon Only" and not maxTon then return end
                            local basePrice  = itemData and itemData.SellPrice or nil
                            local finalPrice = basePrice
                            if isShiny then
                                mutText = "Shiny"
                                if finalPrice then finalPrice = finalPrice * 2 end
                            end
                            local hasVariantFilter = next(_fishState.filterVariants) ~= nil
                            local variantOk = true
                            if variantId then
                                local v = getVariant(variantId)
                                if v then
                                    local vname = v.Data and v.Data.Name or tostring(variantId)
                                    mutText = (isShiny and "Shiny " or "")
                                           .. vname .. " (" .. tostring(v.SellMultiplier or "?") .. "x)"
                                    if finalPrice then finalPrice = finalPrice * (v.SellMultiplier or 1) end
                                    if hasVariantFilter then
                                        variantOk = _fishState.filterVariants[vname] == true or _fishState.filterVariants[tostring(variantId)] == true
                                    end
                                else
                                    mutText = (isShiny and "Shiny " or "") .. tostring(variantId)
                                    if hasVariantFilter then
                                        variantOk = _fishState.filterVariants[tostring(variantId)] == true
                                    end
                                end
                            else
                                if hasVariantFilter then variantOk = false end
                            end
                            if not variantOk then return end
                            local imageUrl = "https://i.imgur.com/UMWNYK7.png"
                            pcall(function()
                                local assetId = extractAssetId((itemData and itemData.Data and itemData.Data.Icon) or data.Icon or "")
                                if assetId then
                                    local fetched = getDiscordImageUrl(assetId)
                                    if fetched and fetched ~= "" then imageUrl = fetched end
                                end
                            end)
                            local gearFields = {
                                { name = "\227\128\162Item Name :", value = itemName,             inline = false },
                                { name = "\227\128\162Item Tier :", value = tier,                 inline = false },
                                { name = "\227\128\162Item Type :", value = data.ItemType or "?", inline = false },
                            }
                            if weight then
                                gearFields[#gearFields + 1] =
                                    { name = "\227\128\162Weight :", value = string.format("%.2f Kg%s", weight, maxTon and " (MAXTON)" or ""), inline = false }
                            end
                            gearFields[#gearFields + 1] =
                                { name = "\227\128\162Mutation :", value = mutText, inline = false }
                            if finalPrice then
                                gearFields[#gearFields + 1] =
                                    { name = "\227\128\162Sell Price :", value = formatPrice(finalPrice), inline = false }
                            end
                            queueWebhook(_fishState.url, buildPayload({
                                userId      = _fishState.id,
                                alertText   = "New **" .. tier .. "** item obtained! **" .. itemName .. "**",
                                headerTitle = "Fish Caught",
                                bodyText    = string.format("**||%s||** You have obtained **%s**!", playerName, itemName),
                                color       = color,
                                imageUrl    = imageUrl,
                                fields = gearFields,
                            }))
                        end)
                    end)
                end)
            else
                _fishState.running = false
                if _fishState.conn then _fishState.conn:Disconnect(); _fishState.conn = nil end
                if _fishState.gearConn then _fishState.gearConn:Disconnect(); _fishState.gearConn = nil end
                if _fishState.caughtConn then _fishState.caughtConn:Disconnect(); _fishState.caughtConn = nil end
                table.clear(_recentCatch)
            end
        end,
    })
    FishSection:AddButton({
        Title = "Test Fish Webhook",
        Callback = function()
            if _fishState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Webhook URL is not set!", Delay = 3 }); return end
            local playerName = getDisplayName(_fishState.hide)
            local ok = sendHTTP(_fishState.url, buildPayload({
                userId      = _fishState.id,
                alertText   = "New **FORGOTTEN** fish caught! **Webhook Test**",
                headerTitle = "Fish Caught",
                bodyText    = string.format("**||%s||** You have obtained a new **FORGOTTEN** fish — **Webhook Test**!", playerName),
                color       = 15844367,
                imageUrl    = "https://i.imgur.com/UMWNYK7.png",
                fields = {
                    { name = "\227\128\162Fish Name :",  value = "Webhook Test", inline = false },
                    { name = "\227\128\162Fish Tier :",  value = "FORGOTTEN",    inline = false },
                    { name = "\227\128\162Weight :",     value = "12.50 Kg",     inline = false },
                    { name = "\227\128\162Mutation :",   value = "None",         inline = false },
                    { name = "\227\128\162Sell Price :", value = "10,000",       inline = false },
                },
            }))
            Library:MakeNotify({ Title = "Webhook", Description = ok and "Test message sent!" or "Failed! Check executor / URL.", Delay = ok and 3 or 4 })
        end,
    })
    local DisconnectSection = WebhookTab:AddSection("Disconnect Webhook")
    local _dcState = { url = "", id = "", hide = "", enabled = false, errorConn = nil, overlayConn = nil }
    local function dcCleanup()
        if _dcState.errorConn   then pcall(function() _dcState.errorConn:Disconnect()   end); _dcState.errorConn   = nil end
        if _dcState.overlayConn then pcall(function() _dcState.overlayConn:Disconnect() end); _dcState.overlayConn = nil end
    end
    DisconnectSection:AddParagraph({ Title = "Info", Content = "Sends a notification to Discord when Roblox disconnects, then auto-rejoins." })
    DisconnectSection:AddInput({ Title = "Webhook URL (Disconnect)",     Default = "", Placeholder = "https://discord.com/api/webhooks/...", Callback = function(v) _dcState.url  = cleanStr(v) end })
    DisconnectSection:AddInput({ Title = "Discord User ID (Disconnect)", Default = "", Placeholder = "123456789012345678",                  Callback = function(v) _dcState.id   = cleanId(v)  end })
    DisconnectSection:AddInput({ Title = "Hide Identity (Disconnect)",   Default = "", Placeholder = "Enter custom name...",                Callback = function(v) _dcState.hide = cleanStr(v) end })
    DisconnectSection:AddToggle({
        Title = "Enable Disconnect Webhook", Default = false,
        Callback = function(on)
            _dcState.enabled = on
            dcCleanup()
            if not on then return end
            local fired = false
            local function onDisconnect(reason)
                if fired or not _dcState.enabled or _dcState.url == "" then return end
                fired = true
                local playerName = getDisplayName(_dcState.hide, LocalPlayer and LocalPlayer.Name or "Unknown")
                sendHTTP(_dcState.url, buildPayload({
                    userId      = _dcState.id,
                    alertText   = "Your account got disconnected from the server!",
                    headerTitle = "Disconnect Alert",
                    bodyText    = "**Your Roblox session was disconnected.**\n\nAttempting to rejoin...",
                    color       = 16711680,
                    fields = {
                        { name = "Account", value = "```" .. playerName .. "```",                       inline = true  },
                        { name = "Time",    value = "```" .. os.date("%m/%d/%Y at %I:%M %p") .. "```", inline = true  },
                        { name = "Reason",  value = "```" .. (reason or "Disconnected") .. "```",      inline = false },
                    },
                }))
                task.wait(2)
                pcall(function() game:GetService("TeleportService"):Teleport(game.PlaceId, LocalPlayer) end)
            end
            pcall(function()
                _dcState.errorConn = game:GetService("GuiService").ErrorMessageChanged:Connect(function(msg)
                    if msg and msg ~= "" then onDisconnect(msg) end
                end)
            end)
            pcall(function()
                local overlay = game:GetService("CoreGui"):FindFirstChild("RobloxPromptGui")
                    and game:GetService("CoreGui").RobloxPromptGui:FindFirstChild("promptOverlay")
                if overlay then
                    _dcState.overlayConn = overlay.ChildAdded:Connect(function(child)
                        if child.Name == "ErrorPrompt" then
                            task.wait(1)
                            local lbl = child:FindFirstChildWhichIsA("TextLabel", true)
                            onDisconnect(lbl and lbl.Text or "Disconnected")
                        end
                    end)
                end
            end)
        end,
    })
    DisconnectSection:AddButton({
        Title = "Test Disconnect Webhook",
        Callback = function()
            if _dcState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Disconnect URL is not set!", Delay = 3 }); return end
            local playerName = getDisplayName(_dcState.hide, LocalPlayer and LocalPlayer.Name or "Unknown")
            local ok = sendHTTP(_dcState.url, buildPayload({
                userId      = _dcState.id,
                alertText   = "Your account got disconnected from the server!",
                headerTitle = "Disconnect Alert",
                bodyText    = "**Your Roblox session was disconnected.**\n\nAttempting to rejoin...",
                color       = 16711680,
                fields = {
                    { name = "Account", value = "```" .. playerName .. "```",                       inline = true  },
                    { name = "Time",    value = "```" .. os.date("%m/%d/%Y at %I:%M %p") .. "```", inline = true  },
                    { name = "Reason",  value = "```Test Successfully :3```",                       inline = false },
                },
            }))
            Library:MakeNotify({ Title = "Webhook", Description = ok and "Disconnect test sent!" or "Failed! Check executor / URL.", Delay = ok and 3 or 4 })
        end,
    })
    local WebhookServerSection = WebhookTab:AddSection("Webhook Server")
    local _wsState = {
        url = "", urlJoinLeave = "", customName = "", enabled = false,
        trackJoin = false, trackLeave = false,
        selectedTiers = { Epic=false, Legendary=false, Mythic=false, SECRET=false, FORGOTTEN=false },
        chatConn = nil, joinConn = nil, leaveConn = nil,
    }
    local WS_TIER_DATA = {
        { name = "Epic",      discordColor = 10181046, r = 179, g = 115, b = 248 },
        { name = "Legendary", discordColor = 15844367, r = 255, g = 185, b = 43  },
        { name = "Mythic",    discordColor = 16711680, r = 255, g = 25,  b = 25  },
        { name = "SECRET",    discordColor = 65535,    r = 24,  g = 255, b = 152 },
        { name = "FORGOTTEN", discordColor = 8421504,  r = 0,   g = 0,   b = 0   },
    }
    local WS_VARIANT_NAMES = {}
    local function wsLoadVariantNames()
        if #WS_VARIANT_NAMES > 0 then return end
        pcall(function()
            local folder = ReplicatedStorage:FindFirstChild("Variants")
            if not folder then return end
            for _, m in ipairs(folder:GetDescendants()) do
                if m:IsA("ModuleScript") then
                    local ok, data = pcall(require, m)
                    if ok and type(data) == "table" and data.Data and data.Data.Name then
                        local name = data.Data.Name
                        if not table.find(WS_VARIANT_NAMES, name) then
                            table.insert(WS_VARIANT_NAMES, name)
                        end
                    end
                end
            end
            table.sort(WS_VARIANT_NAMES, function(a, b) return #a > #b end)
        end)
    end
    local WS_TIER_BY_NAME = {}
    for _, t in ipairs(WS_TIER_DATA) do WS_TIER_BY_NAME[t.name] = t end
    local _wsNameIndex     = nil
    local _wsIndexBuilding = false
    local function wsNameKey(name)
        if type(name) ~= "string" then return nil end
        local key = name:lower():gsub("%s+", " "):gsub("^%s*(.-)%s*$", "%1")
        return key ~= "" and key or nil
    end
    local function wsBuildNameIndex()
        if _wsNameIndex or _wsIndexBuilding then return end
        _wsIndexBuilding = true
        pcall(loadItems)
        local index = {}
        pcall(function()
            for _, item in ipairs(Items) do
                local d = item.Data
                if d then
                    for _, n in ipairs({ d.Name, d.DisplayName }) do
                        local key = wsNameKey(n)
                        if key and not index[key] then index[key] = item end
                    end
                end
            end
        end)
        _wsNameIndex     = index
        _wsIndexBuilding = false
    end
    local function wsLookupItem(name)
        local key = wsNameKey(name)
        if not key or not _wsNameIndex then return nil end
        return _wsNameIndex[key]
    end
    local function wsSplitVariant(name)
        if wsLookupItem(name) then return nil, name end
        local low = name:lower()
        for _, v in ipairs(WS_VARIANT_NAMES) do
            if low:sub(1, #v + 1) == v:lower() .. " " then
                local rest = name:sub(#v + 2):gsub("^%s*", "")
                if wsLookupItem(rest) then return v, rest end
            end
        end
        if _wsNameIndex then return nil, name end
        for _, v in ipairs(WS_VARIANT_NAMES) do
            if low:sub(1, #v + 1) == v:lower() .. " " then
                local rest = name:sub(#v + 2):gsub("^%s*", "")
                if rest ~= "" then return v, rest end
            end
        end
        return nil, name
    end
    local function wsVariantByName(name)
        if type(name) ~= "string" or name == "" then return nil end
        local low = name:lower()
        for _, v in ipairs(WS_VARIANT_NAMES) do
            if v:lower() == low then return v end
        end
        return nil
    end
    local function wsNearestTier(color)
        if not color then return nil end
        local closest, best = nil, math.huge
        for _, t in ipairs(WS_TIER_DATA) do
            local d = math.sqrt((color.r - t.r)^2 + (color.g - t.g)^2 + (color.b - t.b)^2)
            if d < best then closest = t; best = d end
        end
        if closest and best < 55 then return closest end
        return nil
    end
    local function wsTierFromRGB(text, variantName)
        wsLoadVariantNames()
        local actionPos = text:find("obtained") or text:find("caught") or text:find("found") or text:find("unboxed") or 1
        local afterAction = text:sub(actionPos)
        local colors = {}
        for colorStr in afterAction:gmatch('<font color="rgb%(([%d%.,%s]+)%)">') do
            local r_str, g_str, b_str = colorStr:match("(%d+),%s*(%d+),%s*(%d+)")
            if r_str and g_str and b_str then
                table.insert(colors, { r = tonumber(r_str), g = tonumber(g_str), b = tonumber(b_str) })
            end
        end
        if #colors == 0 then return nil end
        local targetColor = colors[1]
        if variantName and variantName ~= "" and #colors > 1 then
            targetColor = colors[2]
        end
        return wsNearestTier(targetColor)
    end
    local function wsParseFishLog(text)
        local clean = text:gsub("<[^>]+>", "")
        clean = clean:gsub("^%s*%b[]%s*:%s*", "")
        local action = clean:match("obtained") or clean:match("caught") or clean:match("found") or clean:match("unboxed")
        if not action then return nil end
        local player = clean:match("^%s*(.-)%s+" .. action)
        local chance = clean:match("with a (1 in [%d%.,KkMmBb]+) chance") or "Unknown"
        if not player or player == "" then return nil end
        local after, variant, tierColor
        local actionPos = text:find(action, 1, true)
        if actionPos then
            local tail = text:sub(actionPos)
            local withPos = tail:find("with a", 1, true)
            if withPos then tail = tail:sub(1, withPos - 1) end
            local segs = {}
            for attr, body in tail:gmatch("<font([^>]*)>(.-)</font>") do
                local r, g, b = attr:match("rgb%((%d+)%s*,%s*(%d+)%s*,%s*(%d+)%)")
                segs[#segs + 1] = {
                    text  = (body:gsub("<[^>]+>", ""):gsub("^%s*(.-)%s*$", "%1")),
                    color = r and { r = tonumber(r), g = tonumber(g), b = tonumber(b) } or nil,
                }
            end
            local last = segs[#segs]
            if last and last.text ~= "" then
                after     = last.text
                tierColor = last.color
                local prev = segs[#segs - 1]
                if prev and prev.text ~= "" then
                    variant = wsVariantByName(prev.text)
                    if not variant and prev.text == prev.text:upper() then
                        variant = prev.text:sub(1, 1) .. prev.text:sub(2):lower()
                    end
                end
            end
        end
        local usedTags = after ~= nil
        if not after then
            after = clean:match(action .. " an?%s+(.-)%s+with a")
                 or clean:match(action .. " an?%s+([^!%.]+)")
                 or clean:match(action .. "%s+(.-)%s+with a")
                 or clean:match(action .. "%s+([^!%.]+)")
                 or ""
        end
        local weight = nil
        local paren = after:match("%(([^%(%)]*)%)%s*$")
        if paren and paren:lower():find("kg", 1, true) then
            weight = paren:gsub("^%s*(.-)%s*$", "%1")
            after  = after:gsub("%s*%([^%(%)]*%)%s*$", "")
        end
        after = after:gsub("^%s*(.-)%s*$", "%1")
        local shiny = false
        if after:lower():sub(1, 6) == "shiny " and not wsLookupItem(after) then
            shiny = true
            after = after:sub(7):gsub("^%s*", "")
        end
        local fish = after
        if not usedTags then variant, fish = wsSplitVariant(after) end
        fish = fish:gsub("^%s*(.-)%s*$", "%1")
        if fish == "" then return nil end
        return {
            player = player:gsub("^%s*(.-)%s*$", "%1"), fish = fish, weight = weight,
            variant = variant, shiny = shiny, chance = chance, tierColor = tierColor,
        }
    end
    local _wsImageCache = {}
    local function wsGetFishImageUrl(fishName)
        if _wsImageCache[fishName] then return _wsImageCache[fishName] end
        if not _itemsLoaded then pcall(loadItems) end
        local exact = wsLookupItem(fishName)
        if exact and exact.Data then
            local d = exact.Data
            local aid = extractAssetId(d.Icon) or extractAssetId(d.ImageId) or extractAssetId(d.Image) or extractAssetId(d.Thumbnail) or extractAssetId(d.AssetId)
            if aid then
                local f = getDiscordImageUrl(aid)
                if f and f ~= "" then _wsImageCache[fishName] = f; return f end
            end
        end
        local target = fishName:gsub("%s*%b()%s*$",""):gsub("^%s*(.-)%s*$","%1"):lower():gsub("%s+"," ")
        local bestMatch, bestScore = nil, 0
        for _, fish in ipairs(Items) do
            local d = fish.Data
            if d then
                for _, n in ipairs({ d.Name, d.DisplayName, d.InternalName, d.ShortName }) do
                    if n then
                        local nl = tostring(n):lower():gsub("%s+"," "):gsub("^%s*(.-)%s*$","%1")
                        local score = 0
                        if nl == target then score = 100
                        elseif nl:find(target,1,true) then score = math.floor((#target/#nl)*90)
                        elseif target:find(nl,1,true) then score = math.floor((#nl/#target)*70)
                        end
                        if score > bestScore then bestScore = score; bestMatch = fish end
                        if bestScore == 100 then break end
                    end
                end
                if bestScore == 100 then break end
            end
        end
        local url = "https://i.imgur.com/UMWNYK7.png"
        if bestMatch and bestScore >= 30 then
            local d = bestMatch.Data
            local aid = extractAssetId(d.Icon) or extractAssetId(d.ImageId) or extractAssetId(d.Image) or extractAssetId(d.Thumbnail) or extractAssetId(d.AssetId)
            if aid then local f = getDiscordImageUrl(aid); if f and f ~= "" then url = f end end
        end
        _wsImageCache[fishName] = url
        return url
    end
    local function wsTierOf(info, richText)
        local item = wsLookupItem(info.fish)
        if item and item.Data and item.Data.Tier then
            return WS_TIER_BY_NAME[TIER_NAMES[item.Data.Tier] or ""]
        end
        return wsNearestTier(info.tierColor) or wsTierFromRGB(richText, info.variant)
    end
    local function wsProcessMessage(richText)
        if not _wsState.enabled or _wsState.url == "" then return end
        task.spawn(function()
            if not _wsNameIndex then
                wsBuildNameIndex()
                local t0 = tick()
                while not _wsNameIndex and tick() - t0 < 5 do task.wait(0.1) end
            end
            wsLoadVariantNames()
            local info = wsParseFishLog(richText)
            if not info then return end
            local tierData = wsTierOf(info, richText)
            if not tierData or not _wsState.selectedTiers[tierData.name] then return end
            local imageUrl    = wsGetFishImageUrl(info.fish)
            local displayName = (_wsState.customName ~= "") and _wsState.customName or info.player
            local fields = {
                { name = "\227\128\162Fish Name :", value = info.fish,     inline = false },
                { name = "\227\128\162Fish Tier :", value = tierData.name, inline = false },
            }
            local variantText = info.variant
            if info.shiny then variantText = variantText and ("Shiny " .. variantText) or "Shiny" end
            if variantText then table.insert(fields, { name = "\227\128\162Variant :", value = variantText, inline = false }) end
            if info.weight then table.insert(fields, { name = "\227\128\162Weight :",  value = info.weight,  inline = false }) end
            table.insert(fields, { name = "\227\128\162Scope :",  value = "[Server]",  inline = false })
            table.insert(fields, { name = "\227\128\162Chance :", value = info.chance, inline = false })
            queueWebhook(_wsState.url, buildPayload({
                alertText   = "New **" .. tierData.name .. "** fish caught!",
                headerTitle = "Fish Caught",
                bodyText    = string.format("**||%s||** You have obtained a new **%s** fish!", displayName, tierData.name),
                color       = tierData.discordColor,
                imageUrl    = imageUrl,
                fields      = fields,
            }))
        end)
    end
    local function wsSetupChatListener()
        if _wsState.chatConn then return end
        task.spawn(function()
            local re, t0 = nil, tick()
            while not re and tick() - t0 < 10 do
                pcall(function() re = NetEvents.RE_DisplaySystemMessage end)
                if not re then task.wait(0.5) end
            end
            if not re then return end
            _wsState.chatConn = re.OnClientEvent:Connect(function(arg1, arg2)
                if type(arg1) ~= "string" or arg2 ~= nil then return end
                if not arg1:find("obtained") or not arg1:find("<font") then return end
                wsProcessMessage(arg1)
            end)
        end)
    end
    local function wsSendJoinLeave(player, isJoin)
        local url = (_wsState.urlJoinLeave ~= "") and _wsState.urlJoinLeave or _wsState.url
        if not _wsState.enabled or url == "" then return end
        if isJoin and not _wsState.trackJoin then return end
        if not isJoin and not _wsState.trackLeave then return end
        local name = player.DisplayName or player.Name
        queueWebhook(url, buildPayload({
            headerTitle = isJoin and "Player Joined" or "Player Left",
            bodyText    = string.format("**||%s||** has %s the server.", name, isJoin and "joined" or "left"),
            color       = isJoin and 0x55FF55 or 0xFF5555,
            fields = {
                { name = "\227\128\162Display Name :", value = "||" .. name .. "||",          inline = false },
                { name = "\227\128\162Status :",       value = isJoin and "Joined" or "Left", inline = false },
            },
        }))
    end
