    local function ewGetEventList()
        local result = {}
        local evData = cachedRequire(ReplicatedStorage:FindFirstChild("Events"))
        if not evData then return result end
        local ignoreList = {
            Cloudy = true, Day = true, ["Increased Luck"] = true, Mutated = true, Night = true, Snow = true, ["Sparkling Cove"] = true,
            Storm = true, Wind = true, Radiant = true, ["Present Rain"] = true, ["Admin - Super Mutated"] = true, ["Admin - Shocked"] = true,
            ["Admin - MEGA Luck"] = true, ["Admin - Super Luck"] = true, ["Admin - Night Celebration"] = true, ["Admin - Forgotten Tier"] = true,
            ["Admin - Galaxy Storm"] = true, ["Admin - 1x1x1x1 Rage"] = true, ["Admin - 2025 Anniversary"] = true, ["Admin - 2025 Christmas"] = true,
            ["Admin - 2026 Valentines"] = true, ["Admin - 3RR0R 3V3NT"] = true, ["Admin - Volcano Eruption"] = true, ["Admin - Meteor Rain"] = true,
            ["Admin - Leviathan Awakening"] = true,
        }
        for eventId, info in pairs(evData) do
            if info.Coordinates and not ignoreList[eventId] then
                table.insert(result, eventId)
            end
        end
        table.sort(result)
        return result
    end
