    local function getEventImageUrl(eventName)
        local imageUrl = "https://i.imgur.com/UMWNYK7.png"
        local imageColor = 16766720
        pcall(function()
            local pgui = LocalPlayer:FindFirstChild("PlayerGui")
            local eventsList = pgui and pgui:FindFirstChild("Events") and pgui.Events:FindFirstChild("Frame") and pgui.Events.Frame:FindFirstChild("Events")
            if eventsList then
                local eventUI = eventsList:FindFirstChild(eventName)
                local targetImg = eventUI
                if eventUI and eventUI:IsA("Frame") then
                    targetImg = eventUI:FindFirstChildOfClass("ImageLabel") or eventUI:FindFirstChildOfClass("ImageButton")
                end
                if targetImg and (targetImg:IsA("ImageLabel") or targetImg:IsA("ImageButton")) then
                    local aid = extractAssetId(targetImg.Image)
                    if aid then
                        local fetched = getDiscordImageUrl(aid)
                        if fetched and fetched ~= "" then imageUrl = fetched end
                    end
                    local c = targetImg.ImageColor3
                    imageColor = math.floor(c.R * 255) * 65536 + math.floor(c.G * 255) * 256 + math.floor(c.B * 255)
                    local gradient = targetImg:FindFirstChildOfClass("UIGradient") or (eventUI and eventUI:FindFirstChildOfClass("UIGradient"))
                    if gradient and gradient.Color and gradient.Color.Keypoints and gradient.Color.Keypoints[1] then
                        local gradC = gradient.Color.Keypoints[1].Value
                        imageColor = math.floor(gradC.R * 255) * 65536 + math.floor(gradC.G * 255) * 256 + math.floor(gradC.B * 255)
                    end
                end
            end
        end)
        if imageUrl == "https://i.imgur.com/UMWNYK7.png" and (eventName == "Ghost Shark Hunt" or eventName == "Shark Hunt" or eventName == "Megalodon Hunt") then
            local fetched = getDiscordImageUrl("74938397479780")
            if fetched and fetched ~= "" then imageUrl = fetched end
            imageColor = 7603173
        end
        return imageUrl, imageColor
    end
    EventWebhookSection:AddToggle({
        Title = "Enable Event Spawn Webhook", Default = false,
        Callback = function(on)
            _ewState.enabled = on
            if _ewState.conn then pcall(function() _ewState.conn:Disconnect() end); _ewState.conn = nil end
            if not on then return end
            if _ewState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Event URL is not set!", Delay = 3 }); return end
            local rep = getCachedReplion()
            if not rep then return end
            local evReplion = nil
            pcall(function() evReplion = rep.Client:GetReplion("Events") end)
            if not evReplion then pcall(function() evReplion = rep.Client:WaitReplion("Events") end) end
            if evReplion then
                local function updateActiveEvents()
                    local active = evReplion:Get("Events")
                    local currentActive = {}
                    if active then
                        for _, ev in pairs(active) do
                            if typeof(ev) == "string" then currentActive[ev] = true end
                        end
                    end
                    for _, evName in ipairs(_ewState.selectedEvents) do
                        if currentActive[evName] and not _ewState.activeEvents[evName] then
                            local imgUrl, imgColor = getEventImageUrl(evName)
                            queueWebhook(_ewState.url, buildPayload({
                                headerTitle = "Event Started",
                                bodyText    = string.format("**||Event Alert||** **%s** has started in your server!", evName),
                                color       = imgColor,
                                imageUrl    = imgUrl,
                                fields = {
                                    { name = "\227\128\162Event Name :", value = evName, inline = false },
                                    { name = "\227\128\162Server ID :",  value = "||" .. game.JobId .. "||", inline = false },
                                    { name = "\227\128\162Time :",       value = os.date("%m/%d/%Y at %I:%M %p"), inline = false },
                                },
                            }))
                        end
                    end
                    _ewState.activeEvents = currentActive
                end
                local activeInit = evReplion:Get("Events")
                if activeInit then
                    for _, ev in pairs(activeInit) do
                        if typeof(ev) == "string" then _ewState.activeEvents[ev] = true end
                    end
                end
                _ewState.conn = evReplion:OnChange("Events", inScriptContext(function()
                    if not _ewState.enabled or _ewState.url == "" then return end
                    updateActiveEvents()
                end))
            end
        end,
    })
