    TreasureWebhookSection:AddInput({ Title = "Hide Identity (Treasure Hunt)",   Default = "", Placeholder = "Enter custom name...",                Callback = function(v) _twState.hide = cleanStr(v) end })
    TreasureWebhookSection:AddToggle({
        Title = "Enable Treasure Hunt Webhook", Default = false,
        Callback = function(on)
            _twState.enabled = on
            if _twState.conn then pcall(function() _twState.conn:Disconnect() end); _twState.conn = nil end
            if not on then return end
            if _twState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Treasure Hunt URL is not set!", Delay = 3 }); return end
            if not getHTTP()       then Library:MakeNotify({ Title = "Webhook", Description = "Executor does not support HTTP!", Delay = 3 }); return end
            local function sendTreasureWebhook(sw)
                if not _twState.enabled or _twState.url == "" then return end
                local playerName = getDisplayName(_twState.hide)
                local swPos = "Unknown"
                pcall(function() local p = sw:GetPivot().Position; swPos = string.format("%.1f, %.1f, %.1f", p.X, p.Y, p.Z) end)
                local chestCount = 0
                pcall(function() for _, c in ipairs(sw:GetChildren()) do if c.Name == "Treasure" then chestCount += 1 end end end)
                queueWebhook(_twState.url, buildPayload({
                    userId      = _twState.id,
                    alertText   = "Treasure Hunt event started!",
                    headerTitle = "Treasure Hunt",
                    bodyText    = string.format("**||%s||** A **Treasure Hunt** event has started in your server!", playerName),
                    color       = 16744272,
                    fields = {
                        { name = "\227\128\162Event :",     value = "Sunken Wreckage",                   inline = false },
                        { name = "\227\128\162Chests :",    value = tostring(chestCount) .. " chest(s)", inline = false },
                        { name = "\227\128\162Location :",  value = swPos,                               inline = false },
                        { name = "\227\128\162Server ID :", value = "||" .. game.JobId .. "||",          inline = false },
                        { name = "\227\128\162Time :",      value = os.date("%m/%d/%Y at %I:%M %p"),     inline = false },
                    },
                }))
            end
            _twState.conn = workspace.ChildAdded:Connect(function(child)
                if not _twState.enabled then return end
                if child.Name == "Sunken Wreckage" then
                    task.wait(1)
                    task.spawn(function()
                        sendTreasureWebhook(child)
                        Library:MakeNotify({ Title = "Treasure Hunt Webhook", Description = "Notification sent to Discord!", Delay = 3 })
                    end)
                end
            end)
            local existing = workspace:FindFirstChild("Sunken Wreckage")
            if existing then
                task.spawn(function()
                    sendTreasureWebhook(existing)
                    Library:MakeNotify({ Title = "Treasure Hunt Webhook", Description = "Event already active — notification sent!", Delay = 3 })
                end)
            end
        end,
    })
    TreasureWebhookSection:AddButton({
        Title = "Test Treasure Hunt Webhook",
        Callback = function()
            if _twState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Treasure Hunt URL is not set!", Delay = 3 }); return end
            local playerName = getDisplayName(_twState.hide)
            local ok = sendHTTP(_twState.url, buildPayload({
                userId      = _twState.id,
                alertText   = "Treasure Hunt event started!",
                headerTitle = "Treasure Hunt",
                bodyText    = string.format("**||%s||** A **Treasure Hunt** event has started in your server!", playerName),
                color       = 16744272,
                fields = {
                    { name = "\227\128\162Event :",     value = "Sunken Wreckage",               inline = false },
                    { name = "\227\128\162Chests :",    value = "5 chest(s)",                    inline = false },
                    { name = "\227\128\162Location :",  value = "120.0, -45.0, 300.0",           inline = false },
                    { name = "\227\128\162Server ID :", value = "||" .. game.JobId .. "||",      inline = false },
                    { name = "\227\128\162Time :",      value = os.date("%m/%d/%Y at %I:%M %p"), inline = false },
                },
            }))
            Library:MakeNotify({ Title = "Webhook", Description = ok and "Treasure Hunt test sent!" or "Failed! Check executor / URL.", Delay = ok and 3 or 4 })
        end,
    })
    local CrystalSpawnSection = WebhookTab:AddSection("Crystal/Veilshard Spawn Webhook")
    local CS_NOTICE, CS_COOLDOWN = "crystals have spawned", 30
    local _csState = { url = "", id = "", hide = "", enabled = false, conn = nil, last = 0 }
    local function csSend(notice, isTest)
        local icon = "https://i.imgur.com/UMWNYK7.png"
        pcall(function()
            local d = cachedRequire(ReplicatedStorage.Shared.ItemUtility):GetItemData("Cave Crystal")
            local aid = d and d.Data and extractAssetId(d.Data.Icon)
            local fetched = aid and getDiscordImageUrl(aid)
            if fetched and fetched ~= "" then icon = fetched end
        end)
        local payload = buildPayload({
            userId      = _csState.id,
            alertText   = "Crystals have spawned!" .. (isTest and " (Test)" or ""),
            headerTitle = "Crystal Spawn",
            bodyText    = string.format("**||%s||** Crystals have spawned in your server!%s", getDisplayName(_csState.hide), isTest and " *(Test)*" or ""),
            color       = 7915775,
            imageUrl    = icon,
            fields = {
                { name = "\227\128\162Notification :", value = notice,                                                    inline = false },
                { name = "\227\128\162Spawns :",       value = "Cave Crystal (Crystal Depths)\nVeilshard (Lava Basin)", inline = false },
                { name = "\227\128\162Time :",         value = os.date("%m/%d/%Y at %I:%M %p"),                          inline = false },
            },
        })
        if isTest then return sendHTTP(_csState.url, payload) end
        queueWebhook(_csState.url, payload)
    end
    CrystalSpawnSection:AddParagraph({ Title = "Info", Content = "Sends a Discord notification when crystals (Cave Crystal / Veilshard) spawn in the server." })
    CrystalSpawnSection:AddInput({ Title = "Webhook URL (Crystal)",     Default = "", Placeholder = "https://discord.com/api/webhooks/...", Callback = function(v) _csState.url  = cleanStr(v) end })
    CrystalSpawnSection:AddInput({ Title = "Discord User ID (Crystal)", Default = "", Placeholder = "123456789012345678",                  Callback = function(v) _csState.id   = cleanId(v)  end })
    CrystalSpawnSection:AddInput({ Title = "Hide Identity (Crystal)",   Default = "", Placeholder = "Enter custom name...",                Callback = function(v) _csState.hide = cleanStr(v) end })
    CrystalSpawnSection:AddToggle({
        Title = "Enable Crystal Spawn Webhook", Default = false,
        Callback = function(on)
            _csState.enabled = on
            if _csState.conn then _csState.conn:Disconnect(); _csState.conn = nil end
            if not on then return end
            if _csState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Crystal webhook URL is not set!", Delay = 3 }); return end
            if not getHTTP() then Library:MakeNotify({ Title = "Webhook", Description = "Executor does not support HTTP!", Delay = 3 }); return end
            local re = NetEvents.RE_TextNotification
            if not re then Library:MakeNotify({ Title = "Webhook", Description = "TextNotification event not found!", Delay = 3 }); return end
            _csState.conn = re.OnClientEvent:Connect(function(data)
                local text = type(data) == "table" and type(data.Text) == "string" and data.Text or ""
                if not text:lower():find(CS_NOTICE, 1, true) then return end
                if os.clock() - _csState.last < CS_COOLDOWN then return end -- one message per wave
                _csState.last = os.clock()
                if _csState.enabled and _csState.url ~= "" then task.spawn(csSend, text) end
            end)
            Library:MakeNotify({ Title = "Crystal Spawn Webhook", Description = "Listening for crystal spawns!", Delay = 2 })
        end,
    })
    CrystalSpawnSection:AddButton({
        Title = "Test Crystal Webhook",
        Callback = function()
            if _csState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Crystal webhook URL is not set!", Delay = 3 }); return end
            local ok = csSend("Crystals have spawned in various locations, find them quickly!", true)
            Library:MakeNotify({ Title = "Webhook", Description = ok and "Crystal test sent!" or "Failed! Check executor / URL.", Delay = ok and 3 or 4 })
        end,
    })
    local _trState = { url = "", id = "", hide = "", enabled = false, conn = nil, claimConn = nil }
    local TreasureRewardSection = WebhookTab:AddSection("Treasure Hunt Reward Webhook")
    TreasureRewardSection:AddParagraph({ Title = "Info", Content = "Sends a Discord notification when you receive a reward from a Treasure Hunt chest." })
    TreasureRewardSection:AddInput({ Title = "Webhook URL (Treasure Reward)",     Default = "", Placeholder = "https://discord.com/api/webhooks/...", Callback = function(v) _trState.url  = cleanStr(v) end })
    TreasureRewardSection:AddInput({ Title = "Discord User ID (Treasure Reward)", Default = "", Placeholder = "123456789012345678",                  Callback = function(v) _trState.id   = cleanId(v)  end })
    TreasureRewardSection:AddInput({ Title = "Hide Identity (Treasure Reward)",   Default = "", Placeholder = "Enter custom name...",                Callback = function(v) _trState.hide = cleanStr(v) end })
    TreasureRewardSection:AddToggle({
        Title = "Enable Treasure Reward Webhook", Default = false,
        Callback = function(on)
            _trState.enabled = on
            if _trState.conn      then pcall(function() _trState.conn:Disconnect()      end); _trState.conn      = nil end
            if _trState.claimConn then pcall(function() _trState.claimConn:Disconnect() end); _trState.claimConn = nil end
            if not on then return end
            if _trState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Treasure Reward URL is not set!", Delay = 3 }); return end
            if not getHTTP()       then Library:MakeNotify({ Title = "Webhook", Description = "Executor does not support HTTP!", Delay = 3 }); return end
            local claimedRE = NetEvents.RE_TreasureChestClaimed
            if not claimedRE then Library:MakeNotify({ Title = "Webhook", Description = "TreasureChestClaimed event not found!", Delay = 3 }); return end
            local _pendingClaim = false
            _trState.conn = claimedRE.OnClientEvent:Connect(function(itemData, tierKey)
                if not _trState.enabled or not itemData then return end
                _pendingClaim = { itemData = itemData, tierKey = tierKey, time = os.clock() }
                task.delay(3, function() _pendingClaim = false end)
            end)
            local function sendRewardWebhook(itemName, itemType, tierName, tierColor, imageUrl)
                local playerName = getDisplayName(_trState.hide)
                queueWebhook(_trState.url, buildPayload({
                    userId      = _trState.id,
                    alertText   = "Treasure Hunt reward received!",
                    headerTitle = "Treasure Hunt Reward",
                    bodyText    = string.format("**||%s||** obtained a reward from **Treasure Hunt**!", playerName),
                    color       = tierColor,
                    imageUrl    = imageUrl,
                    fields = {
                        { name = "\227\128\162Item :",      value = itemName,                        inline = false },
                        { name = "\227\128\162Type :",      value = itemType,                        inline = false },
                        { name = "\227\128\162Tier :",      value = tierName,                        inline = false },
                        { name = "\227\128\162Server ID :", value = "||" .. game.JobId .. "||",      inline = false },
                        { name = "\227\128\162Time :",      value = os.date("%m/%d/%Y at %I:%M %p"), inline = false },
                    },
                }))
            end
            pcall(function()
                local Replion = cachedRequire(ReplicatedStorage.Packages.Replion)
                Replion.Client:AwaitReplion("Data", function(replion)
                    local Currency = cachedRequire(ReplicatedStorage.Modules.CurrencyUtility.Currency)
                    for currencyName, currencyData in pairs(Currency) do
                        replion:OnChange(currencyData.Path, inScriptContext(function(newVal, oldVal)
                            if not _trState.enabled or not _pendingClaim then return end
                            if newVal <= (oldVal or 0) then return end
                            local claim = _pendingClaim; _pendingClaim = false
                            task.spawn(function()
                                pcall(function()
                                    local itemName = currencyData.Singular or currencyData.Prefix or currencyName
                                    local itemType = claim.itemData.Type or "Unknown"
                                    local imageUrl = "https://i.imgur.com/UMWNYK7.png"
                                    local assetId  = extractAssetId(currencyData.Icon)
                                    if assetId then pcall(function() local f = getDiscordImageUrl(assetId); if f and f ~= "" then imageUrl = f end end) end
                                    sendRewardWebhook(itemName, itemType, "Common", TIER_COLORS[1] or 3447003, imageUrl)
                                end)
                            end)
                        end))
                    end
                    replion:OnChange({ "Inventory" }, inScriptContext(function(newVal, oldVal)
                        if not _trState.enabled or not _pendingClaim then return end
                        local claim = _pendingClaim; _pendingClaim = false
                        task.spawn(function()
                            pcall(function()
                                local itemData  = claim.itemData
                                local tierKey   = claim.tierKey
                                local itemType  = itemData.Type or "Unknown"
                                local itemId    = itemData.Id   or 0
                                local itemName  = tostring(itemId)
                                local itemTier  = 1
                                local imageUrl  = "https://i.imgur.com/UMWNYK7.png"
                                local function tryFetchImage(assetId)
                                    if not assetId or assetId == "" then return end
                                    pcall(function()
                                        local fetched = getDiscordImageUrl(assetId)
                                        if fetched and fetched ~= "" then imageUrl = fetched end
                                    end)
                                end
                                pcall(function()
                                    local ItemUtility = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
                                    local result = ItemUtility.GetItemDataFromItemType(itemType, itemId)
                                    if result and result.Data then
                                        local d = result.Data
                                        itemName = d.DisplayName or d.Name or itemName
                                        itemTier = d.Tier or 1
                                        tryFetchImage(extractAssetId(d.Icon) or extractAssetId(d.ImageId) or extractAssetId(d.Image) or extractAssetId(d.Thumbnail))
                                    end
                                end)
                                if itemName == tostring(itemId) then
                                    pcall(function()
                                        local lanternFolder = ReplicatedStorage.Modules.ModelDownloader.Collection:FindFirstChild("Lanterns")
                                        if lanternFolder then
                                            for _, v in ipairs(lanternFolder:GetChildren()) do
                                                if tostring(itemId):lower() == v.Name:lower() or v.Name:lower():find(tostring(itemId):lower(), 1, true) then
                                                    itemName = v.Name
                                                    itemTier = v:GetAttribute("Tier") or 5
                                                    local decal = v:FindFirstChildOfClass("Decal") or v:FindFirstChildOfClass("ImageLabel")
                                                    if decal then tryFetchImage(extractAssetId(decal.Texture or decal.Image)) end
                                                    break
                                                end
                                            end
                                        end
                                    end)
                                end
                                local tierName  = TIER_NAMES[itemTier]  or "Unknown"
                                local tierColor = TIER_COLORS[itemTier] or 3447003
                                if tierKey then
                                    pcall(function()
                                        local Tiers = cachedRequire(ReplicatedStorage.Tiers)
                                        local td = Tiers[tierKey]
                                        if td then
                                            tierName = tierKey
                                            local kp = td.TierColor and td.TierColor.Keypoints
                                            if kp and kp[1] then
                                                local c = kp[1].Value
                                                tierColor = math.floor(c.R*255)*65536 + math.floor(c.G*255)*256 + math.floor(c.B*255)
                                            end
                                        end
                                    end)
                                end
                                sendRewardWebhook(itemName, itemType, tierName, tierColor, imageUrl)
                            end)
                        end)
                    end))
                end)
            end)
            Library:MakeNotify({ Title = "Treasure Reward Webhook", Description = "Listening for Treasure Hunt rewards!", Delay = 2 })
        end,
    })
    local BoothSoldSection = WebhookTab:AddSection("Booth Sold Webhook")
    local _boothState      = { url = "", id = "", hide = "", enabled = false, conn = nil }
    BoothSoldSection:AddParagraph({
        Title   = "Info",
        Content = "Sends a Discord notification when someone buys an item from your booth.",
    })
    BoothSoldSection:AddInput({ Title = "Webhook URL (Booth)",     Default = "", Placeholder = "https://discord.com/api/webhooks/...", Callback = function(v) _boothState.url  = cleanStr(v) end })
    BoothSoldSection:AddInput({ Title = "Discord User ID (Booth)", Default = "", Placeholder = "123456789012345678",                  Callback = function(v) _boothState.id   = cleanId(v)  end })
    BoothSoldSection:AddInput({ Title = "Hide Identity (Booth)",   Default = "", Placeholder = "Enter custom name...",                Callback = function(v) _boothState.hide = cleanStr(v) end })
    BoothSoldSection:AddToggle({
        Title    = "Enable Booth Sold Webhook",
        Default  = false,
        Callback = function(on)
            _boothState.enabled = on
            if on then
                if _boothState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Booth webhook URL is not set!", Delay = 3 }); return end
                if not getHTTP() then warn("[Webhook] Executor does not support HTTP!"); return end
                if _boothState.conn then return end
                task.spawn(loadItems)
                task.spawn(function()
                    local TradeData = cachedRequire(ReplicatedStorage.Shared.Trading.TradeData)
                    if not TradeData then warn("[Webhook] Failed to load TradeData!"); return end
                    local ItemUtility = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
                    _boothState.conn = TradeData.Remotes.SaleListingSold.OnClientEvent:Connect(function(buyerPlayer, _listingId, _sellerId, itemType, itemData, tokensReceived)
                        task.spawn(function()
                            if not _boothState.enabled or _boothState.url == "" then return end
                            local itemName  = "Unknown"
                            local tierName  = "Unknown"
                            local tierColor = 3447003
                            local imageUrl  = "https://i.imgur.com/UMWNYK7.png"
                            local fullData  = nil
                            pcall(function()
                                if ItemUtility and itemData then
                                    fullData = ItemUtility.GetItemDataFromItemType(itemType, itemData.Id or itemData.Name)
                                    if fullData and fullData.Data then
                                        local d = fullData.Data
                                        itemName = d.DisplayName or d.Name or itemName
                                        local tier = d.Tier or 1
                                        tierName  = TIER_NAMES[tier]  or tierName
                                        tierColor = TIER_COLORS[tier] or tierColor
                                        local assetId = extractAssetId(d.Icon) or extractAssetId(d.ImageId) or extractAssetId(d.Image)
                                        if assetId then
                                            local fetched = getDiscordImageUrl(assetId)
                                            if fetched and fetched ~= "" then imageUrl = fetched end
                                        end
                                    end
                                end
                            end)
                            if itemName == "Unknown" and itemData then
                                itemName = itemData.DisplayName or itemData.Name or tostring(itemData.Id or "Unknown")
                            end
                            if tierName == "Unknown" and itemData and itemData.Tier then
                                tierName  = TIER_NAMES[itemData.Tier]  or "Unknown"
                                tierColor = TIER_COLORS[itemData.Tier] or tierColor
                            end
                            local sellerName = getDisplayName(_boothState.hide)
                            local buyerName  = buyerPlayer and (buyerPlayer.DisplayName or buyerPlayer.Name) or "Unknown"
                            local tokenStr   = formatPrice(tokensReceived or 0)
                            queueWebhook(_boothState.url, buildPayload({
                                userId      = _boothState.id,
                                alertText   = "Your item was sold at the booth!",
                                headerTitle = "Booth Item Sold",
                                bodyText    = string.format("**||%s||**'s item was purchased from the booth!", sellerName),
                                color       = tierColor,
                                imageUrl    = imageUrl,
                                fields = {
                                    { name = "\227\128\162Item Name :",       value = itemName,                        inline = false },
                                    { name = "\227\128\162Item Tier :",       value = tierName,                        inline = false },
                                    { name = "\227\128\162Item Type :",       value = tostring(itemType or "Unknown"), inline = false },
                                    { name = "\227\128\162Bought by :",       value = buyerName,                       inline = false },
                                    { name = "\227\128\162Tokens Received :", value = tokenStr .. " Trade Tokens",     inline = false },
                                },
                            }))
                        end)
                    end)
                end)
            else
                if _boothState.conn then _boothState.conn:Disconnect(); _boothState.conn = nil end
            end
        end,
    })
    BoothSoldSection:AddButton({
        Title    = "Test Booth Sold Webhook",
        Callback = function()
            if _boothState.url == "" then Library:MakeNotify({ Title = "Webhook", Description = "Booth webhook URL is not set!", Delay = 3 }); return end
            local sellerName = getDisplayName(_boothState.hide)
            local ok = sendHTTP(_boothState.url, buildPayload({
                userId      = _boothState.id,
                alertText   = "Your item was sold at the booth!",
                headerTitle = "Booth Item Sold",
                bodyText    = string.format("**||%s||**'s item was purchased from the booth! *(Test)*", sellerName),
                color       = 15844367,
                imageUrl    = "https://i.imgur.com/UMWNYK7.png",
                fields = {
                    { name = "\227\128\162Item Name :",       value = "Booth Sold Test",     inline = false },
                    { name = "\227\128\162Item Tier :",       value = "FORGOTTEN",           inline = false },
                    { name = "\227\128\162Item Type :",       value = "Fish",                inline = false },
                    { name = "\227\128\162Bought by :",       value = "TestPlayer",          inline = false },
                    { name = "\227\128\162Tokens Received :", value = "10,000 Trade Tokens", inline = false },
                },
            }))
            Library:MakeNotify({ Title = "Webhook", Description = ok and "Booth sold test sent!" or "Failed! Check executor / URL.", Delay = ok and 3 or 4 })
        end,
    })
end
-- [Skin Tab]
task.wait()
do
    local SkinTab = MainWindow:AddTab({ Name = "Skin Features", Icon = "user" })
    local function notify(title, desc, delay)
        Library:MakeNotify({ Title = title, Description = desc, Delay = delay or 3 })
    end
    local function setOptions(drop, list)
        pcall(function()
            if drop.Refresh then drop:Refresh(list, true) elseif drop.SetOptions then drop:SetOptions(list) end
        end)
    end
    local function childNames(folder)
        local out = {}
        for _, v in ipairs(folder and folder:GetChildren() or {}) do out[#out + 1] = v.Name end
        table.sort(out)
        return out
    end
    local function picker(o)
        local st = { enabled = false, choice = nil, conns = {}, thread = nil }
        local function run(quiet)
            local ok, msg = o.apply(st.choice)
            if not quiet then notify(o.name, ok and (msg or ("Aktif: " .. st.choice)) or (msg or "Gagal apply!"), ok and 3 or 2) end
            return ok
        end
        local function stop()
            for _, c in ipairs(st.conns) do c:Disconnect() end
            table.clear(st.conns)
            if st.thread then pcall(task.cancel, st.thread); st.thread = nil end
        end
        st.drop = o.section:AddDropdown({
            Title    = o.pick,
            Options  = o.options or {},
            NoSave   = o.options ~= nil,
            Callback = function(v)
                st.choice = v
                if st.enabled and v then task.spawn(run) end
            end,
        })
        if o.list then
            o.section:AddButton({
                Title    = "Refresh " .. o.refresh,
                Callback = function()
                    task.spawn(function()
                        local list = o.list()
                        setOptions(st.drop, list)
                        notify(o.name, #list > 0 and (#list .. " tersedia.") or "Daftar kosong!", 2)
                    end)
                end,
            })
        end
        o.section:AddToggle({
            Title    = "Enable " .. o.name,
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                stop()
                if not on then
                    st.enabled = false
                    if o.remove then task.spawn(o.remove) end
                    notify(o.name, "Dimatikan.", 2)
                    return
                end
                if not st.choice and o.list then
                    local list = o.list()
                    setOptions(st.drop, list)
                end
                if not st.choice then
                    notify(o.name, "Pilih dari dropdown dulu!", 2)
                    return
                end
                st.enabled = true
                task.spawn(run)
                st.conns[#st.conns + 1] = LocalPlayer.CharacterAdded:Connect(function()
                    task.wait(o.respawnDelay or 1.5)
                    if st.enabled then run(true) end
                end)
                if o.keep then
                    st.thread = task.spawn(function()
                        while st.enabled do
                            task.wait(o.keepEvery or 1)
                            if st.enabled and not o.keep() then run(true) end
                        end
                    end)
                end
            end,
        })
        return st
    end
    do
        local function folder()
            local ok, f = pcall(function()
                return ReplicatedStorage.Controllers.AccessoryReplicationController.Accessory
            end)
            return ok and f or nil
        end
        local function setSkin(v) return (pcall(function() LocalPlayer:SetAttribute("FishingRodSkin", v) end)) end
        picker({
            section = SkinTab:AddSection("Accessory Changer"), name = "Accessory", pick = "Pilih Accessory",
            refresh = "Accessory", list = function() return childNames(folder()) end,
            apply   = function(choice) return setSkin(choice), "Accessory aktif: " .. choice end,
            remove  = function() setSkin(nil) end,
        })
    end
    do
        local AVATARS = {
            { 7077243300, "TV_TIKMAN" }, { 6010134024, "Ninjaso02YT" }, { 1105009763, "s1mple" },
            { 3232392707, "G0DG0MER" }, { 8673396266, "spiderman" }, { 9939245108, "ApiqqStoreeX8" },
            { 8849874931, "SnoopDogs" }, { 495215054, "SnoopDog" }, { 3658593465, "CFIDxMuell" },
            { 8723543936, "Izyy" }, { 9068204572, "Cero" }, { 1922874709, "StanniBunny" },
            { 3853262070, "S4INTRL" }, { 1718757907, "1_PFT" }, { 8343523, "Neko_Overlord" },
            { 925872199, "gamer" }, { 9758684471, "Azure" }, { 776077949, "DuckXander" },
            { 293229095, "SinisterUGC" }, { 3622565596, "Bluff_006" }, { 77696047, "caIIdrops" },
            { 32958887, "Juno" }, { 63578527, "MistyPhantom" }, { 293215507, "LoneWalker_L" },
            { 178596165, "LilDisquit" }, { 7712365803, "TATA" }, { 9331384193, "Ficha_NR" },
            { 8898545773, "Gracee" }, { 8997690084, "3quinox" }, { 9273180503, "Your_Miffy" },
            { 425367613, "QueenChroma" }, { 147302717, "Hoshiko" }, { 8476353635, "kify168" },
            { 40397833, "WILDES" }, { 75974130, "TALON" }, { 510075070, "Solace A.K.A Soleh" },
            { 7909420830, "ZAER" }, { 111233359, "EA_GAMES" }, { 56602747, "Stealthy" }, { 47058434, "RZXTL" },
        }
        local idByLabel, labels = {}, {}
        for _, a in ipairs(AVATARS) do idByLabel[a[2]] = a[1]; labels[#labels + 1] = a[2] end
        local BODY_PARTS = {
            "Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg", "UpperTorso", "LowerTorso",
            "LeftUpperArm", "RightUpperArm", "LeftLowerArm", "RightLowerArm", "LeftHand", "RightHand",
            "LeftUpperLeg", "RightUpperLeg", "LeftLowerLeg", "RightLowerLeg", "LeftFoot", "RightFoot",
        }
        local WEARABLE = { Accessory = true, Hat = true, Shirt = true, Pants = true, ShirtGraphic = true, CharacterMesh = true }
        local descCache = {}
        local function descOf(userId)
            if not descCache[userId] then
                local ok, desc = pcall(Players.GetHumanoidDescriptionFromUserId, Players, userId)
                descCache[userId] = ok and desc or nil
            end
            return descCache[userId]
        end
        local function weldAccessory(acc, char)
            local handle = acc:FindFirstChild("Handle")
            if not handle then return end
            local att = handle:FindFirstChildWhichIsA("Attachment")
            local target
            for _, d in ipairs(att and char:GetDescendants() or {}) do
                if d:IsA("Attachment") and d.Name == att.Name and d.Parent ~= handle then target = d; break end
            end
            local old = handle:FindFirstChild("AccessoryWeld")
            if old then old:Destroy() end
            local weld = Instance.new("Weld")
            weld.Name, weld.Part1 = "AccessoryWeld", handle
            if target and target.Parent:IsA("BasePart") then
                weld.Part0, weld.C0, weld.C1 = target.Parent, target.CFrame, att.CFrame
            else
                weld.Part0 = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
            end
            if weld.Part0 then weld.Parent = handle else weld:Destroy() end
        end
        local function copyLook(dummy, char, desc)
            for _, obj in ipairs(char:GetChildren()) do
                if WEARABLE[obj.ClassName] then obj:Destroy() end
            end
            for _, obj in ipairs(dummy:GetChildren()) do
                if WEARABLE[obj.ClassName] then
                    pcall(function()
                        local copy = obj:Clone()
                        copy.Parent = char
                        if obj:IsA("Accoutrement") then weldAccessory(copy, char) end
                    end)
                end
            end
            for class, spec in pairs({ Shirt = { "ShirtTemplate", desc.Shirt }, Pants = { "PantsTemplate", desc.Pants },
                                       ShirtGraphic = { "Graphic", desc.GraphicTShirt } }) do
                if spec[2] and spec[2] ~= 0 and not char:FindFirstChildOfClass(class) then
                    pcall(function()
                        local o = Instance.new(class)
                        o[spec[1]], o.Parent = "rbxassetid://" .. spec[2], char
                    end)
                end
            end
            local dBC, mBC = dummy:FindFirstChildOfClass("BodyColors"), char:FindFirstChildOfClass("BodyColors")
            if dBC and mBC then
                for _, p in ipairs({ "HeadColor3", "TorsoColor3", "LeftArmColor3", "RightArmColor3", "LeftLegColor3", "RightLegColor3" }) do
                    mBC[p] = dBC[p]
                end
            end
            local dHead, mHead = dummy:FindFirstChild("Head"), char:FindFirstChild("Head")
            if dHead and mHead then
                local dMesh = dHead:FindFirstChildOfClass("SpecialMesh")
                if dMesh then
                    local mMesh = mHead:FindFirstChildOfClass("SpecialMesh") or Instance.new("SpecialMesh", mHead)
                    pcall(function()
                        mMesh.MeshType, mMesh.Scale, mMesh.Offset = dMesh.MeshType, dMesh.Scale, dMesh.Offset
                        mMesh.MeshId, mMesh.TextureId = dMesh.MeshId, dMesh.TextureId
                    end)
                end
                if desc.Face and desc.Face ~= 0 then
                    local face = mHead:FindFirstChild("face") or mHead:FindFirstChildOfClass("Decal") or Instance.new("Decal", mHead)
                    pcall(function() face.Name, face.Texture = "face", "rbxassetid://" .. desc.Face end)
                end
            end
            for _, name in ipairs(BODY_PARTS) do
                local dPart, mPart = dummy:FindFirstChild(name), char:FindFirstChild(name)
                if dPart and mPart then
                    pcall(function() mPart.Color = dPart.Color end)
                    local dSA, mSA = dPart:FindFirstChildOfClass("SurfaceAppearance"), mPart:FindFirstChildOfClass("SurfaceAppearance")
                    if dSA then
                        mSA = mSA or Instance.new("SurfaceAppearance", mPart)
                        pcall(function()
                            mSA.ColorMap, mSA.NormalMap = dSA.ColorMap, dSA.NormalMap
                            mSA.RoughnessMap, mSA.MetalnessMap = dSA.RoughnessMap, dSA.MetalnessMap
                        end)
                    elseif mSA then
                        mSA:Destroy()
                    end
                end
            end
        end
        local function applyUser(userId)
            local char, desc = LocalPlayer.Character, descOf(userId)
            if not (char and desc) then return false end
            local ok, dummy = pcall(Players.CreateHumanoidModelFromDescription, Players, desc, Enum.HumanoidRigType.R6)
            if not (ok and dummy) then return false end
            local done = pcall(copyLook, dummy, char, desc)
            pcall(function()
                local hum = char:FindFirstChildOfClass("Humanoid")
                hum.BodyDepthScale.Value, hum.BodyHeightScale.Value = desc.DepthScale, desc.HeightScale
                hum.BodyWidthScale.Value, hum.HeadScale.Value = desc.WidthScale, desc.HeadScale
            end)
            dummy:Destroy()
            return done
        end
        local section = SkinTab:AddSection("Avatar Changer")
        local function restore()
            applyUser(LocalPlayer.UserId)
            notify("Avatar Changer", "Avatar dikembalikan ke asli.", 2)
        end
        local st = picker({
            section = section, name = "Avatar Changer", pick = "Select Avatar", options = labels, respawnDelay = 2,
            apply   = function(label) return applyUser(idByLabel[label]), "Avatar: " .. label end,
            remove  = restore,
        })
        section:AddButton({ Title = "Reset to Original", Callback = function()
            st.enabled = false
            task.spawn(restore)
        end })
    end
    do
        local function folder()
            local assets = ReplicatedStorage:FindFirstChild("Assets")
            return assets and assets:FindFirstChild("Auras")
        end
        local function remove()
            for _, part in ipairs(LocalPlayer.Character and LocalPlayer.Character:GetChildren() or {}) do
                for _, fx in ipairs(part:GetChildren()) do
                    if fx:GetAttribute("IsAura") then fx:Destroy() end
                end
            end
        end
        picker({
            section = SkinTab:AddSection("Aura Skin"), name = "Aura", pick = "Pilih Aura",
            refresh = "Aura List", list = function() return childNames(folder()) end, remove = remove,
            apply = function(choice)
                local char, src = LocalPlayer.Character, folder() and folder():FindFirstChild(choice)
                if not (char and src) then return false end
                remove()
                for _, group in ipairs(src:GetChildren()) do
                    local part = char:FindFirstChild(group.Name)
                    for _, fx in ipairs(part and group:GetChildren() or {}) do
                        local copy = fx:Clone()
                        copy:SetAttribute("IsAura", true)
                        copy.Parent = part
                    end
                end
                return true, "Aura: " .. choice
            end,
        })
    end
    do
        local VFXController = cachedRequire(ReplicatedStorage.Controllers.VFXController)
        local VFXDownloader = cachedRequire(ReplicatedStorage.Shared.VFXDownloader)
        local ItemUtility   = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
        local vfx = { enabled = false, choice = "Default", conn = nil }
        local function rodNames()
            local out = {}
            local ok, rods = pcall(function() return ItemUtility:GetFishingRods() end)
            for _, r in ipairs(ok and rods or {}) do
                if r.Data and r.Data.Name then out[#out + 1] = r.Data.Name end
            end
            table.sort(out)
            return out
        end
        local function ensure(key)
            return VFXDownloader:Find(key) or (pcall(VFXDownloader.Ensure, VFXDownloader, key) and VFXDownloader:Find(key))
        end
        local Section = SkinTab:AddSection("Rod Bait Visual Override", false)
        local drop = Section:AddDropdown({
            Title = "Bait Dive VFX (by Rod Skin)", Options = { "Default" }, Default = "Default", NoSave = false,
            Callback = function(v) vfx.choice = v end,
        })
        Section:AddButton({ Title = "Muat Daftar Rod", Callback = function()
            local list = rodNames()
            table.insert(list, 1, "Default")
            setOptions(drop, list)
            notify("Rod VFX", ("%d rod dimuat. VFX diunduh saat dipakai."):format(#list - 1))
        end })
        Section:AddButton({ Title = "Scan VFX (lama, ~30 detik)", Callback = function()
            task.spawn(function()
                notify("Rod VFX", "Memindai... ini butuh sekitar 30 detik.", 4)
                local found = { "Default" }
                for _, name in ipairs(rodNames()) do
                    if ensure(name .. " Dive") then found[#found + 1] = name end
                    task.wait(0.05)
                end
                setOptions(drop, found)
            end)
        end })
        Section:AddToggle({
            Title = "Override Bait Dive VFX", Default = false, NoSave = true,
            Callback = function(on)
                vfx.enabled = on
                if vfx.conn then vfx.conn:Disconnect(); vfx.conn = nil end
                if not on then notify("Rod VFX", "Override dimatikan.", 2); return end
                if not (VFXController and VFXDownloader and NetEvents.RE_BaitCastVisual) then
                    vfx.enabled = false
                    notify("Rod VFX", "Gagal akses VFXController / remote.")
                    return
                end
                vfx.conn = NetEvents.RE_BaitCastVisual.OnClientEvent:Connect(function(player, cast)
                    if player ~= LocalPlayer or vfx.choice == "Default" or type(cast) ~= "table" or not cast.CastPosition then return end
                    task.spawn(function()
                        local key = vfx.choice .. " Dive"
                        if ensure(key) then
                            pcall(function() VFXController.PlayVFX:Fire(key, CFrame.new(cast.CastPosition + Vector3.new(0, 0.5, 0))) end)
                        end
                    end)
                end)
                notify("Rod VFX", "Override aktif!")
            end,
        })
    end
    do
        local KINDS = {   -- kind = { name patterns, looped, priority }
            ReelingIdle      = { { "reelingidle", "reeling idle" },           true,  Enum.AnimationPriority.Action3 },
            ReelIntermission = { { "reelintermission", "reel intermission" }, false, Enum.AnimationPriority.Action4 },
            ReelStart        = { { "reelstart", "reel start" },               false, Enum.AnimationPriority.Action4 },
            RodThrow         = { { "rodthrow", "rod throw" },                 false, Enum.AnimationPriority.Action4 },
            FishCaught       = { { "fishcaught", "fish caught" },             false, Enum.AnimationPriority.Action4 },
            EquipIdle        = { { "equipidle", "equip idle" },               true,  Enum.AnimationPriority.Action3 },
        }
        local ORDER = { "ReelingIdle", "ReelIntermission", "ReelStart", "RodThrow", "FishCaught", "EquipIdle" }
        local ids = {}                -- ids[kind][skin] = animation id
        local pools, active = {}, {}  -- our loaded tracks per kind, and the one playing
        local conn, watcher
        local function kindOf(name)
            name = name:lower()
            for _, kind in ipairs(ORDER) do
                for _, p in ipairs(KINDS[kind][1]) do
                    if name:find(p, 1, true) then return kind end
                end
            end
            return nil
        end
        local function scanSkins()
            table.clear(ids)
            local seen, skins = {}, {}
            for key, data in pairs(cachedRequire(ReplicatedStorage.Modules.Animations) or {}) do
                if type(key) == "string" and type(data) == "table" and not data.Disabled then
                    local kind = kindOf(key)
                    local skin = kind and key:match("^%s*(.-)%s*%-")
                    local id = data.Animation and data.Animation.AnimationId or data.AnimationId
                    if skin and skin ~= "" and id and id ~= "" then
                        ids[kind] = ids[kind] or {}
                        ids[kind][skin] = id
                        if not seen[skin] then seen[skin] = true; skins[#skins + 1] = skin end
                    end
                end
            end
            table.sort(skins)
            return skins
        end
        local function isOurs(track) return (track.Name or ""):find("_POOL_", 1, true) ~= nil end
        local function unload()
            if conn then conn:Disconnect(); conn = nil end
            if watcher then pcall(task.cancel, watcher); watcher = nil end
            for _, pool in pairs(pools) do
                for _, t in ipairs(pool) do pcall(function() t:Stop(0); t:Destroy() end) end
            end
            table.clear(pools); table.clear(active)
        end
        local function replace(hum, orig, kind)
            pcall(function() orig:Stop(0); orig:AdjustSpeed(0) end)
            local cur = active[kind]
            if cur and cur.IsPlaying then return end
            if kind == "FishCaught" or not KINDS[kind][2] then
                for other, t in pairs(active) do
                    if other ~= kind and (kind == "FishCaught" or not KINDS[other][2]) and t.IsPlaying then
                        pcall(function() t:Stop(0.1) end)
                        active[other] = nil
                    end
                end
            end
            if kind == "FishCaught" then
                for _, t in ipairs(hum:GetPlayingAnimationTracks()) do
                    if not isOurs(t) then pcall(function() t:Stop(0) end) end
                end
            end
            local nextTrack = pools[kind][1]
            for _, t in ipairs(pools[kind]) do
                if not t.IsPlaying then nextTrack = t; break end
            end
            pcall(function() nextTrack:Play(0, 1, 1) end)
            active[kind] = nextTrack
        end
        local function load(skin)
            unload()
            local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            local animator = hum and (hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum))
            if not animator then return false end
            if not next(ids) then scanSkins() end
            for kind, spec in pairs(KINDS) do
                local id = ids[kind] and ids[kind][skin]
                if id then
                    local anim = Instance.new("Animation")
                    anim.AnimationId = id
                    pools[kind] = {}
                    for i = 1, spec[2] and 1 or 3 do
                        local ok, track = pcall(animator.LoadAnimation, animator, anim)
                        if ok and track then
                            track.Priority, track.Looped, track.Name = spec[3], spec[2], kind .. "_POOL_" .. i
                            table.insert(pools[kind], track)
                        end
                    end
                    anim:Destroy()
                end
            end
            if not next(pools) then return false, "Skin tidak ditemukan di database!" end
            local function consider(track)
                if _animationsOff or isOurs(track) or not track.IsPlaying then return end
                local kind = kindOf((track.Name or "") .. " " .. (track.Animation and track.Animation.Name or ""))
                if kind and pools[kind] and #pools[kind] > 0 then task.spawn(replace, hum, track, kind) end
            end
            conn = hum.AnimationPlayed:Connect(consider)
            watcher = task.spawn(function()
                while hum.Parent do
                    task.wait(0.75)
                    for _, track in ipairs(hum:GetPlayingAnimationTracks()) do consider(track) end
                end
            end)
            return true, "Skin Animation: " .. skin
        end
        picker({
            section = SkinTab:AddSection("Skin Animation"), name = "Skin Animation", pick = "Select Skin",
            refresh = "Skin List", list = scanSkins, apply = load, remove = unload, respawnDelay = 2,
        })
    end
    do
        local section = SkinTab:AddSection("Custom Cutscenes")
        local RARITIES = { "Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "SECRET", "FORGOTTEN" }
        local NO_SERVER_SCENE = { Common = true, Uncommon = true, Rare = true, Epic = true }
        local finisher = { on = false, wrapped = false, tiers = { SECRET = true, FORGOTTEN = true }, conn = nil, last = nil, choice = "Ultimate Catch" }
        local function isFinisher(name) return (cachedRequire(ReplicatedStorage.Finishers) or {})[name] ~= nil end
        local function sceneName()
            return isFinisher(finisher.choice) and "Finisher:" .. finisher.choice or finisher.choice
        end
        local function choices() -- real finishers first, then the catch cutscenes; both read from the game so new ones appear
            local out, scenes = {}, {}
            for name in pairs(cachedRequire(ReplicatedStorage.Finishers) or {}) do out[#out + 1] = name end
            for _, mod in ipairs(ReplicatedStorage.Modules.FishingRuntime.Scenes:GetChildren()) do scenes[#scenes + 1] = mod.Name end
            table.sort(out); table.sort(scenes)
            for _, name in ipairs(scenes) do out[#out + 1] = name end
            return out
        end
        local function allowed() return finisher.on and not (_animationsOff or _worldStripped) end
        local function playAs(play, selfArg, scene, ...) -- marks this one call so Disable Cutscenes lets it through
            _finisherScene = scene
            local record = play(selfArg, scene, ...)
            _finisherScene = nil
            return record
        end
        local function cutscene()
            local cut = cachedRequire(ReplicatedStorage.Modules.FishingRuntime.Cutscene)
            if cut and cut.Play and not finisher.wrapped then
                local origPlay = cut.Play
                cut.Play = function(selfArg, scene, character, ...)
                    if allowed() and finisher.tiers[scene] and character == LocalPlayer.Character then
                        return playAs(origPlay, selfArg, sceneName(), character, ...)
                    end
                    return origPlay(selfArg, scene, character, ...)
                end
                finisher.wrapped = true
            end
            return cut
        end
        local function playFinisher(fishId, meta, withFish)
            local cut, char = cutscene(), LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not (cut and root) or cut:IsFishingBlocked() then return end
            task.spawn(function()
                setthreadidentity(2) -- the game refuses to load the scene module from an executor-level thread
                playAs(cut.Play, cut, sceneName(), char, root.Position, fishId, meta, withFish)
            end)
        end
        local function modelReady(fishId)
            local downloader = cachedRequire(ReplicatedStorage.Modules.ModelDownloader)
            return downloader and downloader:GetModel("Fish", fishId, false) ~= nil
        end
        local function onCaught(fishName, meta)
            if not allowed() or type(fishName) ~= "string" then return end
            local data = cachedRequire(ReplicatedStorage.Shared.ItemUtility):GetItemData(fishName)
            local prob = data and (data.Probability or data.ForcedProbability)
            local tier = prob and cachedRequire(ReplicatedStorage.Shared.TierUtility):GetTierFromRarity(prob.Chance)
            meta = type(meta) == "table" and meta or {}
            finisher.last = { id = data and data.Data.Id, meta = meta }
            if not (tier and NO_SERVER_SCENE[tier.Name] and finisher.tiers[tier.Name]) then return end
            local ready = false
            for _ = 1, 10 do
                ready = modelReady(data.Data.Id)
                if ready then break end
                task.wait(0.1)
            end
            if ready or isFinisher(finisher.choice) then playFinisher(data.Data.Id, meta, ready) end -- catch cutscenes need the fish
        end
        section:AddDropdown({
            Title = "Select Cutscene", Options = choices(), Default = "Ultimate Catch",
            Callback = function(value) if value ~= "" then finisher.choice = value end end,
        })
        section:AddDropdown({
            Title = "Cutscene Rarity", Multi = true, Options = RARITIES, Default = { "SECRET", "FORGOTTEN" },
            Callback = function(selected)
                table.clear(finisher.tiers)
                for _, name in ipairs(type(selected) == "table" and selected or {}) do finisher.tiers[name] = true end
            end,
        })
        section:AddToggle({
            Title = "Enable Custom Cutscenes", Default = false,
            Callback = function(on)
                finisher.on = on
                _finisherTiers = on and finisher.tiers or nil
                if finisher.conn then finisher.conn:Disconnect(); finisher.conn = nil end
                if not on then return end
                if not cutscene() then
                    finisher.on, _finisherTiers = false, nil
                    notify("Custom Cutscenes", "Gagal akses Cutscene.", 3)
                    return
                end
                finisher.conn = NetEvents.RE_FishCaught.OnClientEvent:Connect(function(...) pcall(onCaught, ...) end)
            end,
        })
        section:AddButton({ Title = "Preview Cutscene", Callback = function()
            local last = finisher.last
            if last and last.id and modelReady(last.id) then return playFinisher(last.id, last.meta, true) end
            if isFinisher(finisher.choice) then return playFinisher(nil, nil, false) end
            notify("Custom Cutscenes", "Nyalakan fiturnya dan tangkap 1 ikan dulu untuk preview cutscene ini.", 4)
        end })
    end
    do
        local emotes = {}
        local track, trackName
        local function list()
            table.clear(emotes)
            local out = {}
            for _, mod in ipairs(ReplicatedStorage:FindFirstChild("Emotes") and ReplicatedStorage.Emotes:GetChildren() or {}) do
                local d = cachedRequire(mod)
                if type(d) == "table" and d.Data and d.Data.Name and d.AnimationId then
                    emotes[d.Data.Name] = d
                    out[#out + 1] = d.Data.Name
                end
            end
            table.sort(out)
            return out
        end
        local function stop()
            if track then pcall(function() track:Stop(0.2) end) end
            track, trackName = nil, nil
        end
        local function play(name)
            if not next(emotes) then list() end
            local d = emotes[name]
            local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
            local animator = hum and (hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum))
            if not (d and animator) then return false end
            stop()
            local anim = Instance.new("Animation")
            anim.AnimationId = d.AnimationId
            local ok, t = pcall(animator.LoadAnimation, animator, anim)
            anim:Destroy()
            if not (ok and t) then return false end
            t.Priority, t.Looped = d.AnimationPriority or Enum.AnimationPriority.Action3, d.Looped or false
            pcall(function() t:Play(0.1, 1, d.PlaybackSpeed or 1) end)
            track, trackName = t, name
            return true, "Emote: " .. name
        end
        picker({
            section = SkinTab:AddSection("Emote", false), name = "Emote", pick = "Select Emote",
            refresh = "Emote List", list = list, apply = play, remove = stop, respawnDelay = 1,
            keep = function() return track ~= nil and track.IsPlaying end, keepEvery = 0.5,
        })
    end
end
