                fishSpot   = {
                    pos  = Vector3.new(-834.383, 18.966, 5054.680),
                    look = Vector3.new(-830.116, 18.966, 5063.724),
                },
            },
            {
                title      = "Level 3",
                levelKey   = "Level_3",
                completion = "ElementalIsland_LightCrystal_Level_3",
                fish       = "Thunderstorm Jelly",
                emitter    = Vector3.new(-897.650, 31.686, 5093.427),
                solution   = { Crystal01 = 1, Crystal02 = 2, Crystal03 = 3 },
                spotName   = "Elemental Door [Storm]",
                fishSpot   = {
                    pos  = Vector3.new(-914.241, 30.057, 5114.677),
                    look = Vector3.new(-921.251, 30.057, 5121.809),
                },
            },
        }
        local ROT_STEPS = 8
        local DOOR_OPTIONS = { "Level 1", "Level 2", "Level 3" }
        local selectedDoorLevels = { "Level 1", "Level 2", "Level 3" }
        local DoorSection = QuestTab:AddSection("Auto Open Elemental Door", false)
        DoorSection:AddParagraph({
            Title   = "Cara Kerja",
            Content = "Buka pintu es Elemental Island (Level 1 s/d 3), berurutan. Semua otomatis dalam 1 toggle:\n"
                .. "1. Belum punya ikannya? Teleport ke spot ikan level itu lalu tunggu sampai dapat.\n"
                .. "2. Pause auto fishing, pegang ikan, lalu Offer ke emitter.\n"
                .. "3. Putar crystal sampai laser benar-benar menyentuh receiver.\n"
                .. "4. Tunggu server konfirmasi, baru auto fishing dinyalakan lagi & lanjut level berikutnya.\n"
                .. "<b>Auto fishing-nya nyalakan sendiri di tab Main</b> — script ini cuma antar ke spotnya.",
        })
        DoorSection:AddParagraph({
            Title   = "Ikan & Spot Per Level",
            Content = "Level 1 : <b>Magmaquill Pufferfish</b> — Elemental Door [Volcano]\n"
                .. "Level 2 : <b>Tidecrest Dolphin</b> — Elemental Door [Blizzard]\n"
                .. "Level 3 : <b>Thunderstorm Jelly</b> — Elemental Door [Storm]\n"
                .. "1 ekor per pintu, ikannya habis dipakai saat Offer.",
        })
        local doorStatus = DoorSection:AddParagraph({ Title = "Status", Content = "Idle" })
        local function setDoorStatus(title, content)
            pcall(function()
                doorStatus:SetTitle(title)
                doorStatus:SetContent(content)
            end)
        end
        local function getPuzzleRoot()
            local islands = workspace:FindFirstChild("Islands")
            local island  = islands and islands:FindFirstChild("Elemental Island")
            return island and island:FindFirstChild("! IMPORTANT") or nil
        end
        local function resolveEmitterPos(level)
            local root = getPuzzleRoot()
            if root then
                local ok, pos = pcall(function()
                    local emitters = root:FindFirstChild("Emitters")
                    local folder   = emitters and emitters:FindFirstChild(level.levelKey)
                    local emitter  = folder and folder:FindFirstChild("Emitter")
                    local origin   = emitter and emitter:FindFirstChild("BeamOrigin", true)
                    if origin and origin:IsA("Attachment") then return origin.WorldPosition end
                    if emitter then return emitter:GetPivot().Position end
                    return nil
                end)
                if ok and pos then return pos end
            end
            return level.emitter
        end
        local function resolveSolution(level)
            local root = getPuzzleRoot()
            if root then
                local ok, sol = pcall(function()
                    local crystals = root:FindFirstChild("Crystals")
                    local folder   = crystals and crystals:FindFirstChild(level.levelKey)
                    if not folder then return nil end
                    local out, count = {}, 0
                    for _, crystal in ipairs(folder:GetChildren()) do
                        if crystal.Name ~= "LocalBeamSegments"
                            and (crystal:IsA("Model") or crystal:IsA("BasePart"))
                        then
                            local idx = crystal:GetAttribute("SolutionRotationIndex")
                            if type(idx) ~= "number" then return nil end
                            out[crystal.Name] = idx
                            count = count + 1
                        end
                    end
                    return count > 0 and out or nil
                end)
                if ok and sol then return sol end
            end
            return level.solution
        end
        local function getPuzzleContext()
            if type(debug) ~= "table" or type(debug.getupvalues) ~= "function" then return nil, nil end
            local ok, ctrl = pcall(function()
                return require(ReplicatedStorage.Controllers.LightCrystalPuzzleController)
            end)
            if not ok or type(ctrl) ~= "table" or type(ctrl.Start) ~= "function" then return nil, nil end
            local seen, levelSets, caches = {}, nil, {}
            local function scan(fn, depth)
                if depth > 4 or seen[fn] then return end
                seen[fn] = true
                local gotUps, ups = pcall(debug.getupvalues, fn)
                if not gotUps or type(ups) ~= "table" then return end
                for _, v in pairs(ups) do
                    if type(v) == "table" then
                        for k, val in pairs(v) do
                            if typeof(k) == "Instance" and type(val) == "table" and val._activePuzzles then
                                levelSets = levelSets or v
                            elseif type(k) == "string" and k:find("LightCrystal", 1, true) then
                                local dup = false
                                for _, c in ipairs(caches) do if c == v then dup = true end end
                                if not dup then caches[#caches + 1] = v end
                            end
                            break
                        end
                    elseif type(v) == "function" then
                        scan(v, depth + 1)
                    end
                end
            end
            pcall(scan, ctrl.Start, 0)
            local levelSet
            if levelSets then
                for _, ls in pairs(levelSets) do
                    if type(ls) == "table" and ls._activePuzzles then levelSet = ls; break end
                end
            end
            return levelSet, caches
        end
        local function getLevelSet()
            local ls = getPuzzleContext()
            return ls
        end
        local function getPuzzle(levelKey)
            local ls = getLevelSet()
            return ls and ls._activePuzzles and ls._activePuzzles[levelKey] or nil
        end
        local moveTo
        local function solveWithPrompts(level, solution)
            local root   = getPuzzleRoot()
            local folder = root and root:FindFirstChild("Crystals")
            folder = folder and folder:FindFirstChild(level.levelKey)
            if not folder or type(fireproximityprompt) ~= "function" then return false end
            local puzzle = getPuzzle(level.levelKey)
            local liveIndex = {}
            if puzzle then
                for _, c in pairs(puzzle._crystals) do liveIndex[c.instance.Name] = c.rotationIndex end
            end
            for _, crystal in ipairs(folder:GetChildren()) do
                if not _elemDoor.enabled then return false end
                if crystal.Name ~= "LocalBeamSegments" then
                    local rootPart = crystal:FindFirstChild("Root")
                    local prompt   = rootPart and rootPart:FindFirstChild("RotatePrompt")
                    local target   = solution and solution[crystal.Name]
                    if prompt and target then
                        local current = liveIndex[crystal.Name] or 0
                        local delta = (target - current) % ROT_STEPS
                        if delta > 0 then
                            moveTo(rootPart.Position)
                            for _ = 1, delta do
                                if not _elemDoor.enabled then return false end
                                pcall(function() fireproximityprompt(prompt) end)
                                task.wait(0.25)
                            end
                        end
                    end
                end
            end
            return true
        end
        local function isDoorCompleted(data, completionId)
            if not data then return false end
            local ok, entry = pcall(function()
                return data:Get({ "LightCrystalPuzzleCompletions", completionId })
            end)
            return ok and entry ~= nil
        end
        local function findFishUUID(data, fishName)
            if not data then return nil end
            local ItemUtility
            pcall(function() ItemUtility = require(ReplicatedStorage.Shared.ItemUtility) end)
            if not ItemUtility then return nil end
            local items = data:Get({ "Inventory", "Items" }) or {}
            for _, item in ipairs(items) do
                local ok, info = pcall(function() return ItemUtility:GetItemData(item.Id) end)
                local d = ok and info and info.Data
                if d and d.Name == fishName and d.Type == "Fish" then
                    return item.UUID
                end
            end
            return nil
        end
        local function hotbarSlotOf(data, uuid)
            for slot, id in pairs(data:Get("EquippedItems") or {}) do
                if id == uuid then return slot end
            end
            return nil
        end
        local function holdFish(data, uuid)
            if data:Get("EquippedId") == uuid then return true end
            local slot = hotbarSlotOf(data, uuid)
            if not slot then
                local hotbar = data:Get("EquippedItems") or {}
                local free
                for i = 1, 5 do
                    if hotbar[i] == nil then free = i; break end
                end
                if not free then
                    local victim = hotbar[5]
                    if victim then
                        if not _elemDoor.displacedUUID then _elemDoor.displacedUUID = victim end
                        pcall(function() NetEvents.RE_UnequipItem:FireServer(victim) end)
                        for _ = 1, 10 do
                            task.wait(0.3)
                            if (data:Get("EquippedItems") or {})[5] == nil then break end
                        end
                    end
                end
                pcall(function() NetEvents.RE_EquipItem:FireServer(uuid, "Fish") end)
                for _ = 1, 12 do
                    task.wait(0.3)
                    slot = hotbarSlotOf(data, uuid)
                    if slot then break end
                end
            end
            if not slot then return false end
            for _ = 1, 3 do
                pcall(function() NetEvents.RF_EquipToolFromHotbar:FireServer(slot) end)
                for _ = 1, 10 do
                    task.wait(0.3)
                    if data:Get("EquippedId") == uuid then return true end
                end
            end
            return data:Get("EquippedId") == uuid
        end
        local function pauseMainFishing()
            if _elemDoor.pausedFishing then return end
            local paused = {}
            for _, entry in ipairs(_mainFishingToggles) do
                if entry.active then
                    pcall(function() entry.ref:SetValue(false) end)
                    paused[#paused + 1] = entry
                end
            end
            _elemDoor.pausedFishing = paused
            if #paused > 0 then
                local names = {}
                for _, entry in ipairs(paused) do names[#names + 1] = entry.name end
                Library:MakeNotify({
                    Title       = "Elemental Door",
                    Description = "Pause auto fishing: " .. table.concat(names, ", "),
                    Delay       = 3,
                })
            end
            for _ = 1, 24 do
                if not _fishingActive then break end
                task.wait(0.25)
            end
            if _fishingActive then
                Library:MakeNotify({
                    Title       = "Elemental Door",
                    Description = "Masih ada auto fishing jalan yang tidak dikenali script. Matikan manual dulu biar Offer tidak gagal.",
                    Delay       = 6,
                })
            end
            if #paused == 0 and not _fishingActive then return end
            pcall(function()
                local char = LocalPlayer.Character
                local hum  = char and char:FindFirstChild("Humanoid")
                if hum then hum:UnequipTools() end
            end)
            pcall(function()
                if NetEvents.RF_CancelFishingInputs then NetEvents.RF_CancelFishingInputs:InvokeServer() end
            end)
            task.wait(1)
        end
        local function resumeMainFishing()
            local paused = _elemDoor.pausedFishing
            _elemDoor.pausedFishing = nil
            if not paused or #paused == 0 then return end
            for _, entry in ipairs(paused) do
                pcall(function() entry.ref:SetValue(true) end)
                task.wait(0.3)
            end
            local names = {}
            for _, entry in ipairs(paused) do names[#names + 1] = entry.name end
            Library:MakeNotify({
                Title       = "Elemental Door",
                Description = "Auto fishing dilanjutkan: " .. table.concat(names, ", "),
                Delay       = 3,
            })
        end
        local function restoreHotbar()
            if not _elemDoor.displacedUUID then return end
            pcall(function() NetEvents.RE_EquipItem:FireServer(_elemDoor.displacedUUID, "Fish") end)
            _elemDoor.displacedUUID = nil
        end
        moveTo = function(pos)
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end
            pcall(function()
                hrp.CFrame = CFrame.lookAt(pos + Vector3.new(0, 3, 4), pos)
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
            task.wait(1.5)
            return true
        end
        local function moveToSpot(spot)
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end
            pcall(function()
                hrp.CFrame = CFrame.lookAt(spot.pos, spot.look)
                hrp.AssemblyLinearVelocity  = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
            end)
            return true
        end
        local function waitForFish(data, level)
            local spot = level.fishSpot
            if not spot then return nil end
            Library:MakeNotify({
                Title       = "Elemental Door",
                Description = level.title .. ": belum punya " .. level.fish
                    .. ". Teleport ke " .. (level.spotName or "spot") .. " — nyalakan auto fishing kamu!",
                Delay       = 6,
            })
            local startedAt, lastTp = os.clock(), 0
            while _elemDoor.enabled do
                if os.clock() - lastTp >= 8 then
                    moveToSpot(spot)
                    lastTp = os.clock()
                end
                local uuid = findFishUUID(data, level.fish)
                if uuid then
                    Library:MakeNotify({
                        Title       = "Elemental Door",
                        Description = level.fish .. " didapat! Lanjut buka " .. level.title .. ".",
                        Delay       = 4,
                    })
                    return uuid
                end
                local mins = math.floor((os.clock() - startedAt) / 60)
                local secs = math.floor((os.clock() - startedAt) % 60)
                setDoorStatus(level.title, ("Menunggu <b>%s</b> di %s — %02d:%02d\n<i>Nyalakan auto fishing di tab Main.</i>")
                    :format(level.fish, level.spotName or "spot ikan", mins, secs))
                task.wait(1)
            end
            return nil
        end
        local function processDoor(data, level)
            if isDoorCompleted(data, level.completion) then
                setDoorStatus(level.title, "Pintu sudah terbuka, dilewati.")
                return true
            end
            local puzzle = getPuzzle(level.levelKey)
            local alreadyActivated = (puzzle and puzzle._isActivated) == true
            if not alreadyActivated then
                local uuid = findFishUUID(data, level.fish)
                if not uuid then
                    setDoorStatus(level.title, "Belum punya " .. level.fish .. ", teleport ke spot ikan...")
                    uuid = waitForFish(data, level)
                end
                if not uuid then
                    setDoorStatus(level.title, "Butuh <b>" .. level.fish .. "</b> - tidak ada di inventory.")
                    Library:MakeNotify({
                        Title       = "Elemental Door",
                        Description = level.title .. " butuh " .. level.fish .. ". Pancing dulu ikannya!",
                        Delay       = 5,
                    })
                    return false
                end
                setDoorStatus(level.title, "Pause auto fishing dulu...")
                pauseMainFishing()
                setDoorStatus(level.title, "Memegang " .. level.fish .. "...")
                if not holdFish(data, uuid) then
                    setDoorStatus(level.title, "Gagal memegang " .. level.fish .. ".")
                    resumeMainFishing()
                    return false
                end
                local emitterPos = resolveEmitterPos(level)
                setDoorStatus(level.title, "Teleport ke emitter " .. level.title .. "...")
                moveTo(emitterPos)
                local activateRemote = NetEvents.RF_LightCrystalActivate
                if not activateRemote then
                    setDoorStatus(level.title, "Remote Activate tidak ditemukan.")
                    resumeMainFishing()
                    return false
                end
                local activated = false
                for attempt = 1, 6 do
                    if not _elemDoor.enabled then resumeMainFishing(); return false end
                    local ok, res = pcall(function()
                        return activateRemote:InvokeServer({ CompletionId = level.completion })
                    end)
                    if ok and type(res) == "table" and res.Success then
                        activated = true
                        break
                    end
                    local reason = (ok and type(res) == "table" and res.Reason) or "Unknown"
                    setDoorStatus(level.title, "Offer gagal (" .. tostring(reason) .. "), retry " .. attempt .. "/6...")
                    if reason == "TooFar" then
                        moveTo(emitterPos)
                    elseif reason == "RequiredFishNotEquipped" then
                        holdFish(data, uuid)
                    elseif reason == "MissingFish" then
                        Library:MakeNotify({
                            Title       = "Elemental Door",
                            Description = level.title .. ": " .. level.fish .. " sudah habis.",
                            Delay       = 5,
                        })
                        resumeMainFishing()
                        return false
                    end
                    task.wait(1)
                end
                if not activated then
                    setDoorStatus(level.title, "Gagal offer ikan ke emitter.")
                    resumeMainFishing()
                    return false
                end
            else
                setDoorStatus(level.title, "Sudah teraktivasi, lanjut solve puzzle...")
            end
            setDoorStatus(level.title, "Menunggu puzzle aktif...")
            for _ = 1, 25 do
                if not _elemDoor.enabled then return false end
                task.wait(0.4)
                puzzle = getPuzzle(level.levelKey)
                if puzzle and puzzle._isActivated then break end
            end
            local solution = resolveSolution(level)
            local confirmed = false
            setDoorStatus(level.title, "Menyelesaikan puzzle laser " .. level.title .. "...")
            local deadline = os.clock() + 30
            while _elemDoor.enabled and os.clock() < deadline do
                if isDoorCompleted(data, level.completion) then confirmed = true; break end
                puzzle = getPuzzle(level.levelKey)
                if not (puzzle and puzzle._isSolved) then
                    solveWithPrompts(level, solution)
                else
                    setDoorStatus(level.title, "Puzzle solved, menunggu konfirmasi server...")
                end
                task.wait(0.4)
            end
            resumeMainFishing()
            if confirmed then
                setDoorStatus(level.title, "Pintu terbuka & tersimpan di server!")
                Library:MakeNotify({
                    Title       = "Elemental Door",
                    Description = level.title .. " terbuka!",
                    Delay       = 3,
                })
                return true
            end
            setDoorStatus(level.title, ("<b>%s GAGAL</b>\nServer belum konfirmasi hasil puzzle. Coba jalankan ulang toggle-nya."):format(level.title))
            Library:MakeNotify({
                Title       = "Elemental Door",
                Description = level.title .. " gagal disimpan server. Coba jalankan ulang.",
                Delay       = 6,
            })
            return false
        end
        DoorSection:AddDropdown({
            Title    = "Pilih Level Pintu",
            Options  = DOOR_OPTIONS,
            Default  = DOOR_OPTIONS,
            Multi    = true,
            Callback = function(list)
                selectedDoorLevels = (type(list) == "table") and list or {}
            end,
        })
        DoorSection:AddToggle({
            Title    = "Kembali ke Posisi Awal Setelah Selesai",
            Default  = false,
            Callback = function(on) _elemDoor.returnHome = on end,
        })
        DoorSection:AddToggle({
            Title    = "Enable Auto Open Elemental Door",
            Default  = false,
            Callback = function(on)
                _elemDoor.enabled = on
                if _elemDoor.thread then
                    pcall(task.cancel, _elemDoor.thread)
                    _elemDoor.thread = nil
                end
                if not on then
                    setDoorStatus("Status", "Idle")
                    resumeMainFishing()
                    return
                end
                local picked = {}
                for _, name in ipairs(selectedDoorLevels) do picked[name] = true end
                if not next(picked) then
                    _elemDoor.enabled = false
                    setDoorStatus("Status", "Pilih minimal 1 level dulu!")
                    Library:MakeNotify({ Title = "Elemental Door", Description = "Pilih minimal 1 level dulu!", Delay = 3 })
                    return
                end
                _elemDoor.thread = task.spawn(function()
                    local data = getCachedReplionData()
                    if not data then
                        setDoorStatus("Status", "Data player belum siap.")
                        _elemDoor.enabled = false
                        return
                    end
                    local char = LocalPlayer.Character
                    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
                    _elemDoor.homeCFrame = hrp and hrp.CFrame or nil
                    Library:MakeNotify({ Title = "Elemental Door", Description = "Active!", Delay = 2 })
                    local opened, failed = 0, 0
                    for _, level in ipairs(DOOR_LEVELS) do
                        if not _elemDoor.enabled then break end
                        if picked[level.title] then
                            if processDoor(data, level) then
                                opened = opened + 1
                            else
                                failed = failed + 1
                            end
                            task.wait(1)
                        end
                    end
                    restoreHotbar()
                    resumeMainFishing()
                    if _elemDoor.returnHome and _elemDoor.homeCFrame then
                        task.wait(1)
                        local char2 = LocalPlayer.Character
                        local hrp2  = char2 and char2:FindFirstChild("HumanoidRootPart")
                        if hrp2 then
                            pcall(function()
                                hrp2.CFrame = _elemDoor.homeCFrame
                                hrp2.AssemblyLinearVelocity  = Vector3.zero
                                hrp2.AssemblyAngularVelocity = Vector3.zero
                            end)
                        end
                    end
                    setDoorStatus("Selesai", opened .. " pintu beres, " .. failed .. " gagal/dilewati.")
                    Library:MakeNotify({
                        Title       = "Elemental Door",
                        Description = "Selesai - " .. opened .. " pintu terbuka, " .. failed .. " gagal.",
                        Delay       = 5,
                    })
                    _elemDoor.enabled = false
                end)
            end,
        })
    end
    do
        local _questTrigger = {
            enabled = false,
            thread  = nil,
            target  = nil,
        }
        local QUEST_DATA = cachedRequire(ReplicatedStorage.Shared.NPCQuestGivers) or {}
        local QUEST_NAMES = (function()
            local list = {}
            for name in pairs(QUEST_DATA) do
                table.insert(list, name)
            end
            table.sort(list)
            return list
        end)()
        local QuestSection = QuestTab:AddSection("Instant Trigger Quest", false)
        QuestSection:AddParagraph({
            Title   = "Info",
            Content = "Instantly triggers a quest dialogue without needing to physically visit the NPC. Select a quest from the dropdown and press Trigger Now.",
        })
        QuestSection:AddDropdown({
            Title    = "Select Quest",
            Options  = QUEST_NAMES,
            Default  = QUEST_NAMES[1],
            NoSave   = true,
            Callback = function(selected)
                _questTrigger.target = selected
            end,
        })
        QuestSection:AddButton({
            Title    = "Trigger Now",
            Callback = function()
                if _questTrigger.thread then
                    pcall(task.cancel, _questTrigger.thread)
                    _questTrigger.thread = nil
                end
                local questName = _questTrigger.target
                if not questName or questName == "" then
                    Library:MakeNotify({ Title = "Trigger Quest", Description = "Pilih quest dulu!", Delay = 2 })
                    return
                end
                local data = QUEST_DATA[questName]
                if not data then
                    Library:MakeNotify({ Title = "Trigger Quest", Description = "Data quest tidak ditemukan.", Delay = 2 })
                    return
                end
                _questTrigger.thread = task.spawn(function()
                    local replionData = getCachedReplionData()
                    if data.RequiredQuest then
                        local completed = false
                        pcall(function()
                            completed = replionData:Find("CompletedQuests", data.RequiredQuest) ~= nil
                        end)
                        if not completed then
                            Library:MakeNotify({
                                Title       = "Trigger Quest",
                                Description = "Selesaikan dulu: " .. data.RequiredQuest,
                                Delay       = 4,
                            })
                            _questTrigger.thread = nil
                            return
                        end
                    end
                    if data.RequiredItem then
                        local ItemUtility = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
                        local hasItem = false
                        pcall(function()
                            local items = replionData:GetExpect({"Inventory", "Items"})
                            for _, item in ipairs(items) do
                                local itemData = ItemUtility.GetItemDataFromItemType(data.RequiredItem.Type, item.Id)
                                if itemData and itemData.Data and itemData.Data.Id == data.RequiredItem.Id then
                                    hasItem = true
                                    break
                                end
                            end
                        end)
                        if not hasItem then
                            Library:MakeNotify({
                                Title       = "Trigger Quest",
                                Description = "Item dibutuhkan: " .. data.RequiredItem.Id,
                                Delay       = 4,
                            })
                            _questTrigger.thread = nil
                            return
                        end
                    end
                    local DialogueRemote = NetEvents.RE_DialogueEnded
                    if not DialogueRemote then
                        Library:MakeNotify({ Title = "Trigger Quest", Description = "Remote tidak ditemukan!", Delay = 3 })
                        _questTrigger.thread = nil
                        return
                    end
                    Library:MakeNotify({
                        Title       = "Trigger Quest",
                        Description = "Memulai: " .. questName,
                        Delay       = 2,
                    })
                    local success = true
                    for step = 1, data.Index do
                        local ok = pcall(function()
                            DialogueRemote:FireServer(data.NPC, data.Path, step)
                        end)
                        if not ok then
                            success = false
                            break
                        end
                        task.wait(0.1)
                    end
                    if success then
                        Library:MakeNotify({
                            Title       = "Trigger Quest",
                            Description = questName .. " berhasil!",
                            Delay       = 3,
                        })
                    else
                        Library:MakeNotify({
                            Title       = "Trigger Quest",
                            Description = "Gagal trigger " .. questName,
                            Delay       = 3,
                        })
                    end
                    _questTrigger.thread = nil
                end)
            end,
        })
    end
    local QuestDefs   = cachedRequire(ReplicatedStorage.Modules.Quests) or {}
    local QuestGivers = cachedRequire(ReplicatedStorage.Shared.NPCQuestGivers) or {}
