    local function notify(title, desc, delay)
        Library:MakeNotify({ Title = title, Description = desc, Delay = delay or 3 })
    end
    local function rootPart()
        local char = LocalPlayer.Character
        return char and char:FindFirstChild("HumanoidRootPart")
    end
    local function tp(target, minDist)
        local cf, hrp = typeof(target) == "CFrame" and target or SPOTS[target], rootPart()
        if not (cf and hrp) or (hrp.Position - cf.Position).Magnitude <= (minDist or 10) then return end
        pcall(function()
            hrp.CFrame = cf
            hrp.AssemblyLinearVelocity  = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    local function dialogue(npc, path, index)
        pcall(function() NetEvents.RE_DialogueEnded:FireServer(npc, path, index) end)
    end
    local function questDef(name)
        for cat, list in pairs(QuestDefs) do
            if type(list) == "table" and list[name] then return list[name], cat end
        end
    end
    local function questState(name)
        local def, cat = questDef(name)
        local data = getCachedReplionData()
        if not (def and data) then return nil end
        local entry = data:Get({ "Quests", cat, name })
        local done = data:Find("CompletedQuests", name) ~= nil or (entry ~= nil and entry.Claimed == true)
        return { name = name, def = def, cat = cat, entry = entry, done = done }
    end
    local function questDone(name)
        local q = questState(name)
        return q ~= nil and q.done
    end
    local function objDef(q, id)
        for i, o in ipairs(q.def.Objectives or {}) do
            if (o.Id or i) == id then return o end
        end
        return {}
    end
    local function objProgress(q, id)
        for i, o in ipairs(q.entry and q.entry.Objectives or {}) do
            if (o.Id or i) == id then return o.Progress or 0 end
        end
        return 0
    end
    local function objDone(q, id)
        return q.done or objProgress(q, id) >= (objDef(q, id).Goal or 1)
    end
    local function questLines(q, plain)
        if q.done then return (plain and "" or "✓ ") .. q.name .. " selesai" end
        local lines = { plain and q.name or ('<font color="rgb(255,200,80)">— ' .. q.name .. ' —</font>') }
        for i, o in ipairs(q.def.Objectives or {}) do
            local id, goal = o.Id or i, o.Goal or 1
            local prog = objProgress(q, id)
            lines[#lines + 1] = ("%s %s (%s/%s)"):format(prog >= goal and "✓" or "•", o.Name, prog, goal)
        end
        return table.concat(lines, "\n")
    end
    local function acceptQuest(name)
        local q = questState(name)
        if not q or q.done or q.entry then return q ~= nil end
        local giver = QuestGivers[name] or EXTRA_GIVERS[name]
        if not giver then return false end
        for _ = 1, 3 do
            dialogue(giver.NPC, giver.Path, giver.Index)
            for _ = 1, 8 do
                task.wait(0.5)
                local fresh = questState(name)
                if fresh and (fresh.entry or fresh.done) then return true end
            end
        end
        return false
    end
    local function itemTier(id)
        local ok, d = pcall(function() return ItemUtility:GetItemData(id) end)
        return ok and d and d.Data and d.Data.Tier or nil
    end
    local function findItem(req, bucket)
        local data = getCachedReplionData()
        local need = req.Metadata or {}
        for _, item in ipairs(data and data:Get({ "Inventory", bucket or "Items" }) or {}) do
            local variant = item.Metadata and item.Metadata.VariantId
            if (not req.Id or item.Id == req.Id)
                and (not need.Variant or variant == need.Variant)
                and (not need.Mutated or (variant ~= nil and variant ~= ""))
                and (not req.Tier or itemTier(item.Id) == req.Tier)
            then
                return item.UUID
            end
        end
        return nil
    end
    local function holdItem(uuid, category)
        local data = getCachedReplionData()
        if not data then return false end
        if data:Get("EquippedId") == uuid then return true end
        local function slotOf()
            for slot, id in pairs(data:Get("EquippedItems") or {}) do
                if id == uuid then return slot end
            end
        end
        _G.PauseAutoEquip = true
        local slot = slotOf()
        if not slot then
            local hotbar, used = data:Get("EquippedItems") or {}, 0
            for _ in pairs(hotbar) do used += 1 end
            if used >= 5 and hotbar[5] then
                pcall(function() NetEvents.RE_UnequipItem:FireServer(hotbar[5]) end)
                task.wait(0.5)
            end
            pcall(function() NetEvents.RE_EquipItem:FireServer(uuid, category or "Fish") end)
            for _ = 1, 20 do
                task.wait(0.25)
                slot = slotOf()
                if slot then break end
            end
        end
        local held = false
        if slot then
            pcall(function() NetEvents.RF_EquipToolFromHotbar:FireServer(tonumber(slot) or slot) end)
            for _ = 1, 20 do
                task.wait(0.25)
                if data:Get("EquippedId") == uuid then held = true; break end
            end
        end
        _G.PauseAutoEquip = false
        return held
    end
    local function withFishingPaused(fn)
        _G.SetOrbThrowing(true)
        pcall(function() NetEvents.RF_CancelFishingInputs:InvokeServer() end)
        pcall(function() cachedRequire(ReplicatedStorage.Controllers.FishingController):RequestClientStopFishing(true) end)
        pcall(function() LocalPlayer.Character.Humanoid:UnequipTools() end)
        task.wait(1.5)
        local ok, res = pcall(fn)
        _G.SetOrbThrowing(false)
        pcall(autoEquipRod)
        return ok and res
    end
    local function turnIn(q, objId)
        local route = TURN_INS[q.name]
        local d = route and route[objId]
        local uuid = d and findItem(objDef(q, objId).Requirements or {})
        if not uuid then return false end
        return withFishingPaused(function()
            if not holdItem(uuid, "Fish") then return false end
            task.wait(0.3)
            dialogue(route.npc, d[1], d[2])
            for _ = 1, 8 do
                task.wait(0.5)
                local fresh = questState(q.name)
                if fresh and objDone(fresh, objId) then return true end
            end
            return false
        end)
    end
    local function planStep(plan, setStatus)
        local q = questState(plan.quest)
        if not q then return false end
        if setStatus then setStatus(questLines(q)) end
        if q.done then return true end
        if not q.entry then
            if plan.trigger then
                if setStatus then setStatus(questLines(q) .. "\n\nTeleport ke " .. plan.trigger .. " untuk memulai quest...") end
                tp(plan.trigger, plan.minDist)
            else
                acceptQuest(plan.quest)
            end
            return false
        end
        for _, s in ipairs(plan.steps) do
            if s.turnIn and not objDone(q, s.obj) and turnIn(q, s.obj) then return false end
        end
        for _, s in ipairs(plan.steps) do
            if s.spot and not objDone(q, s.obj) and (not s.when or s.when()) then
                tp(s.spot, plan.minDist)
                return false
            end
        end
        return false
    end
    local function statusFor(section, title)
        local para, last = section:AddParagraph({ Title = title, Content = "Idle" }), nil
        return function(text)
            if text == last then return end
            last = text
            pcall(function() para:SetContent(text) end)
        end
    end
    local function loopToggle(section, opts)
        local state = { enabled = false, thread = nil }
        section:AddToggle({
            Title    = opts.title,
            Default  = false,
            NoSave   = not opts.save,
            Callback = function(on)
                state.enabled = on
                if state.thread then pcall(task.cancel, state.thread); state.thread = nil end
                if not on then
                    if opts.onStop then pcall(opts.onStop) end
                    if opts.setStatus then opts.setStatus("Idle") end
                    notify(opts.name, "Stopped.", 2)
                    return
                end
                notify(opts.name, "Active!", 2)
                state.thread = task.spawn(function()
                    local lastError
                    while state.enabled do
                        local ok, finished = pcall(opts.step, state)
                        if not ok and finished ~= lastError then
                            lastError = finished
                            warn("[" .. opts.name .. "]", finished)
                        end
                        if ok and finished then
                            state.enabled = false
                            if opts.onStop then pcall(opts.onStop) end
                            notify(opts.name, type(finished) == "string" and finished or "Selesai!", 5)
                            break
                        end
                        task.wait(opts.interval or 2)
                    end
                    state.thread = nil
                end)
            end,
        })
        return state
    end
    local ARTIFACTS = {
        { name = "Arrow Artifact",             id = 265 },
        { name = "Crescent Artifact",          id = 266 },
        { name = "Hourglass Diamond Artifact", id = 271 },
        { name = "Diamond Artifact",           id = 267 },
    }
    local function templeLever(name)
        local ji = workspace:FindFirstChild("JUNGLE INTERACTIONS")
        for _, v in ipairs(ji and ji:GetDescendants() or {}) do
            if v:IsA("Model") and v.Name == "TempleLever" and v:GetAttribute("Type") == name then return v end
        end
        return nil
    end
    local function artifactDone(name)
        local data = getCachedReplionData()
        local levers = data and data:Get("TempleLevers")
        if type(levers) == "table" and levers[name] then return true end
        local lever = templeLever(name)
        return lever ~= nil and not (lever:FindFirstChild("RootPart") and lever.RootPart:FindFirstChildWhichIsA("ProximityPrompt"))
    end
    local function artifactLines()
        local lines = { '<font color="rgb(255,200,80)">— Artifact Lever —</font>' }
        for _, a in ipairs(ARTIFACTS) do
            lines[#lines + 1] = (artifactDone(a.name) and "✓ " or "• ") .. a.name:gsub(" Artifact", "")
        end
        return table.concat(lines, "\n")
    end
    local function artifactStep(setStatus)
        if setStatus then setStatus(artifactLines()) end
        for _, a in ipairs(ARTIFACTS) do
            if not artifactDone(a.name) then
                tp(a.name, 15)
                if findItem({ Id = a.id }) then
                    task.wait(1.5)
                    if not pcall(function() NetEvents.RE_PlaceLeverItem:FireServer(a.name) end) then
                        local lever  = templeLever(a.name)
                        local prompt = lever and lever:FindFirstChild("RootPart") and lever.RootPart:FindFirstChildWhichIsA("ProximityPrompt")
                        if prompt then pcall(fireproximityprompt, prompt) end
                    end
                    local deadline = os.clock() + 10
                    repeat task.wait(0.5) until artifactDone(a.name) or os.clock() > deadline
                end
                return false
            end
        end
        return true
    end
    local function levelAtLeast(n)
        return function()
            local data = getCachedReplionData()
            return (data and data:Get("Level") or 0) >= n
        end
    end
    local DEEP_SEA = { quest = "Deep Sea Quest", trigger = "Sisyphus Statue", steps = {
        { obj = 2, spot = "Sisyphus Statue" },
        { obj = 3, spot = "Sisyphus Statue" },
        { obj = 1, spot = "Treasure Room" },
        { obj = 4, spot = "Sisyphus Statue" }, -- Earn 1M Coins: keep fishing there
    } }
    local ELEMENT = { quest = "Element Quest", steps = {
