    local DIAMOND = { quest = "Diamond Researcher", steps = {
        { obj = 4, turnIn = true, spot = "Treasure Room" },
        { obj = 5, turnIn = true, spot = "Kohana" },
        { obj = 2, spot = "Coral Reefs" },
