        { obj = 6, spot = "Coral Reefs" },
    } }
    local CRYSTALLINE = { quest = "Crystalline Secrets", steps = {
        { obj = 3, turnIn = true, spot = "Crystal Depths" },
        { obj = 4, turnIn = true, spot = "Crystal Depths" },
        { obj = 5, turnIn = true, spot = "Crystal Depths" },
    } }
    local function elementStep(setStatus)
        if not artifactStep(setStatus) then return false end
        return planStep(ELEMENT, setStatus)
    end
    local DIAMOND_ROD_ID, DIAMOND_KEY_ID = 559, 574
    local function diamondRodStep()
        if findItem({ Id = DIAMOND_ROD_ID }, "Fishing Rods") then return false end
        local key = findItem({ Id = DIAMOND_KEY_ID })
        if not key then return false end
        local data = getCachedReplionData()
        if data:Get("EquippedId") ~= key then
            pcall(function() NetEvents.RE_EquipItem:FireServer(key) end)
            task.wait(1.5)
        end
        tp("Treasure Room", 0)
        task.wait(2)
        local room, input
        pcall(function()
            room  = workspace.Islands["Mutation Cellar"]["! DIAMOND ROD ROOM"]
            input = room.InputPart
        end)
        if not input then
            local door = CollectionService:GetTagged("DiamondDoor")[1]
            input = door and door:FindFirstChild("InputPart")
            room  = door and door:FindFirstChild("Room")
        end
        if input then
            tp(input.CFrame, 0)
            task.wait(1)
            local prompt = input:FindFirstChildWhichIsA("ProximityPrompt")
            if prompt then pcall(fireproximityprompt, prompt); task.wait(3) end
        end
        local rodPrompt = room and room:FindFirstChildWhichIsA("ProximityPrompt", true)
        if rodPrompt then
            if rodPrompt.Parent and rodPrompt.Parent:IsA("BasePart") then tp(rodPrompt.Parent.CFrame, 0) end
            task.wait(0.5)
            pcall(fireproximityprompt, rodPrompt)
            task.wait(1)
        end
        return true
    end
    local PROGRESSION = {
        { name = "Steampunk Rod", id = 6,   price = 215000,  tier = 4, bag = "Fishing Rods", remote = "RF_PurchaseFishingRod" },
        { name = "Ares Rod",      id = 126, price = 3000000, tier = 6, bag = "Fishing Rods", remote = "RF_PurchaseFishingRod" },
        { name = "Aether Bait",   id = 16,  price = 3700000, tier = 6, bag = "Baits",        remote = "RF_PurchaseBait" },
    }
    local function ownsAtLeast(entry)
        local data = getCachedReplionData()
        for _, item in ipairs(data:Get({ "Inventory", entry.bag }) or {}) do
            if item.Id == entry.id then return true end
            local ok, d = pcall(function() return ItemUtility.GetItemDataFromItemType(entry.bag, item.Id) end)
            local tier, price = ok and d and d.Data and d.Data.Tier or 0, ok and d and d.Price or 0
            if tier > entry.tier or (tier == entry.tier and price > entry.price) then return true end
        end
        return false
    end
    local function autoBuyProgression()
        local data = getCachedReplionData()
        for _, entry in ipairs(PROGRESSION) do
            if not ownsAtLeast(entry) then
                if (data:Get("Coins") or 0) >= entry.price then
                    local ok, success = pcall(function() return NetEvents[entry.remote]:InvokeServer(entry.id) end)
                    if ok and success then notify("Kaitun Auto Buy", "Berhasil membeli " .. entry.name .. "!") end
                end
                return
            end
        end
    end
    local KAITUN_QUESTS = { "Deep Sea Quest", "Element Quest", "Diamond Researcher", "Crystalline Secrets" }
    do
        local RodQuestSection = QuestTab:AddSection("Kaitun Quest Rod", false)
        local setStatus = statusFor(RodQuestSection, "Status")
        loopToggle(RodQuestSection, {
            title = "Enable Auto Rod Quest", name = "Rod Quest", save = true, setStatus = setStatus,
            step = function()
                autoBuyProgression()
                if not questDone("Deep Sea Quest") then
                    planStep(DEEP_SEA, setStatus)
                elseif not questDone("Element Quest") then
                    elementStep(setStatus)
                elseif not questDone("Diamond Researcher") then
                    planStep(DIAMOND, setStatus)
                elseif not diamondRodStep() then
                    if questDone("Crystalline Secrets") then
                        setStatus('<font color="rgb(80,255,140)">✓ Semua Rod Quest selesai!</font>')
                        return "Semua quest rod selesai!"
                    end
                    planStep(CRYSTALLINE, setStatus)
                end
                return false
            end,
        })
        local function bestOwned(bag, itemType, luckOf)
            local data = getCachedReplionData()
            local best, bestScore, bestData = nil, -1, nil
            for _, item in ipairs(data and data:Get({ "Inventory", bag }) or {}) do
                local ok, d = pcall(function() return ItemUtility.GetItemDataFromItemType(itemType, item.Id) end)
                if ok and d and d.Data and not d.IsSkin then
                    local score = (d.Data.Tier or 0) * 1000 + (luckOf(d) or 0)
                    if score > bestScore then best, bestScore, bestData = item, score, d end
                end
            end
            return best, bestData
        end
        local function rodLuck(d) return d.RollData and d.RollData.BaseLuck end
        local function baitLuck(d) return d.Modifiers and d.Modifiers.BaseLuck end
        loopToggle(RodQuestSection, {
            title = "Auto Equip Best Rod/Bait", name = "Auto Equip", save = true, interval = 5,
            step = function()
                if _G.CosmicTrading or _G.AutoIndexActive then return false end
                local data = getCachedReplionData()
                if not data then return false end
                local rod, rodData = bestOwned("Fishing Rods", "Fishing Rods", rodLuck)
                local function rodSet() return (data:Get("EquippedItems") or {})[1] == rod.UUID end
                if rod and not rodSet() then
                    withFishingPaused(function()
                        for _ = 1, 3 do
                            pcall(function() NetEvents.RE_EquipItem:FireServer(rod.UUID, "Fishing Rods") end)
                            for _ = 1, 12 do if rodSet() then break end task.wait(0.25) end
                            if rodSet() then break end
                            pcall(function() NetEvents.RF_CancelFishingInputs:InvokeServer() end)
                            task.wait(0.5)
                        end
                    end)
                    notify("Auto Equip", rodSet() and ("Rod → " .. rodData.Data.Name) or "Gagal ganti rod, dicoba lagi...", 3)
                end
                local bait, baitData = bestOwned("Baits", "Baits", baitLuck)
                if bait and data:Get("EquippedBaitId") ~= bait.Id then
                    pcall(function() NetEvents.RE_EquipBait:FireServer(bait.Id) end)
                    notify("Auto Equip", "Bait → " .. baitData.Data.Name, 3)
                end
                return false
            end,
        })
        local formatPrice, cleanStr = Webhook.formatPrice, Webhook.cleanStr
        local TIER_NAMES, TIER_COLORS = Webhook.TierNames, Webhook.TierColors
        local KW_BOT, KW_ORANGE = "Lynxx | Kaitun", 0xFF8C00
        local KW_WATCH = { ["Fishing Rods"] = { [169] = true, [257] = true, [559] = true }, Baits = { [39] = true } }
        local _kw = { enabled = false, url = "", intervalMin = 5, thread = nil, conn = nil, sent = {} }
        local function kwPayload(opts)
            opts.botName, opts.authorName = KW_BOT, opts.authorName or KW_BOT
            opts.color = opts.color or KW_ORANGE
            return Webhook.payload(opts)
        end
        local function playerName() return LocalPlayer.DisplayName or LocalPlayer.Name end
        local function countTier(tier)
            local data, count = getCachedReplionData(), 0
            for _, item in ipairs(data:Get({ "Inventory", "Items" }) or {}) do
                local ok, d = pcall(function() return ItemUtility.GetItemDataFromItemType("Fish", item.Id) end)
                if ok and d and d.Data and d.Data.Type == "Fish" and d.Data.Tier == tier then count += 1 end
            end
            return count
        end
        local function avatarUrl()
            local url
            pcall(function()
                local res = getHTTP()({
                    Url    = ("https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=%d&size=420x420&format=Png&isCircular=false"):format(LocalPlayer.UserId),
                    Method = "GET",
                })
                local decoded = game:GetService("HttpService"):JSONDecode(res.Body)
                url = decoded.data[1].imageUrl
            end)
            return url
        end
        local function sendProgress()
            local data = getCachedReplionData()
            if not data then return end
            local rod, rodData   = bestOwned("Fishing Rods", "Fishing Rods", rodLuck)
            local bait, baitData = bestOwned("Baits", "Baits", baitLuck)
            local function label(item, d)
                if not (item and d) then return "None" end
                return ("**%s** `%s`"):format(d.Data.Name or tostring(item.Id), TIER_NAMES[d.Data.Tier] or tostring(d.Data.Tier or "?"))
            end
            local list, current = {}, nil
            for _, name in ipairs(KAITUN_QUESTS) do
                local q = questState(name)
                local done = q and q.done
                list[#list + 1] = (done and "**`✓`**" or "**`✗`**") .. "  " .. name
                if q and not done and not current then current = q end
            end
            Webhook.queue(_kw.url, kwPayload({
                authorName   = "Kaitun Quest Status",
                content      = playerName() .. " — Quest Progress Update",
                bodyText     = "Status akun **||" .. playerName() .. "||** — Kaitun Rod Quest",
                thumbnailUrl = avatarUrl(),
                fields = {
                    { name = "\227\128\162Best Rod :",        value = label(rod, rodData),                        inline = false },
                    { name = "\227\128\162Best Bait :",       value = label(bait, baitData),                      inline = false },
                    { name = "\227\128\162Coins :",           value = "`" .. formatPrice(data:Get("Coins") or 0) .. "`", inline = true },
                    { name = "\227\128\162SECRET Count :",    value = "`" .. countTier(7) .. "`",                 inline = true },
                    { name = "\227\128\162FORGOTTEN Count :", value = "`" .. countTier(8) .. "`",                 inline = true },
                    { name = "\227\128\162Current Quest :",   value = current and ("**" .. current.name .. "**\n```\n" .. questLines(current, true) .. "\n```") or "**All Done!**", inline = false },
                    { name = "\227\128\162Quest List :",      value = table.concat(list, "\n"),                  inline = false },
                },
            }))
        end
        local function sendObtained(itemType, id)
            local ok, d = pcall(function() return ItemUtility.GetItemDataFromItemType(itemType, id) end)
            if not (ok and d and d.Data) then return end
            local name, tier = d.Data.Name or tostring(id), d.Data.Tier or 1
            local fields = {
                { name = "\227\128\162Item", value = "**" .. name .. "**",                      inline = true },
                { name = "\227\128\162Tier", value = "**" .. (TIER_NAMES[tier] or "?") .. "**", inline = true },
            }
            local function add(label, value) fields[#fields + 1] = { name = "\227\128\162" .. label, value = tostring(value or "?"), inline = true } end
            if itemType == "Fishing Rods" then
                add("Base Luck",   d.RollData and d.RollData.BaseLuck)
                add("Click Power", d.ClickPower)
                add("Resilience",  d.Resilience)
                add("Max Weight",  d.MaxWeight and (formatPrice(d.MaxWeight) .. " kg"))
            else
                local m = d.Modifiers or {}
                add("Base Luck", m.BaseLuck); add("Shiny Mult", m.ShinyMultiplier)
                add("Mutation Mult", m.MutationMultiplier); add("Size Mult", m.SizeMultiplier)
            end
            add("Obtained by", "||" .. playerName() .. "||")
            add("Time", os.date("%m/%d/%Y at %I:%M %p"))
            local assetId = Webhook.assetId(d.Data.Icon)
            Webhook.queue(_kw.url, kwPayload({
                authorName = "Kaitun — " .. (itemType == "Fishing Rods" and "Rod" or "Bait") .. " Obtained!",
                content    = name .. " obtained by " .. playerName() .. "!",
                bodyText   = ("**||%s||** berhasil mendapatkan **%s**!"):format(playerName(), name),
                color      = TIER_COLORS[tier] or 3447003,
                imageUrl   = (assetId and Webhook.imageUrl(assetId)) or "https://i.imgur.com/UMWNYK7.png",
                fields     = fields,
            }))
        end
        local KwSection = QuestTab:AddSection("Kaitun Webhook", false)
        KwSection:AddParagraph({
            Title   = "Info",
            Content = "Kirim status akun ke Discord (Best Rod, Bait, Coins, Quest Progress)\ndan notifikasi otomatis saat dapat Ghostfinn/Element/Diamond Rod atau Aether Bait.",
        })
        KwSection:AddInput({ Title = "Webhook URL (Kaitun)", Default = "", Callback = function(v) _kw.url = cleanStr(v) end })
        KwSection:AddInput({
            Title = "Interval (menit)", Default = "5",
            Callback = function(v)
                local n = tonumber(v)
                if n and n >= 1 then _kw.intervalMin = n end
            end,
        })
        KwSection:AddButton({
            Title    = "Send Status Sekarang",
            Callback = function()
                if _kw.url == "" then notify("Kaitun Webhook", "Webhook URL belum diset!"); return end
                task.spawn(function()
                    sendProgress()
                    notify("Kaitun Webhook", "Status dikirim!", 2)
                end)
            end,
        })
        KwSection:AddToggle({
            Title    = "Enable Kaitun Progress Webhook",
            Default  = false,
            Callback = function(on)
                _kw.enabled = on
                if _kw.thread then pcall(task.cancel, _kw.thread); _kw.thread = nil end
                if _kw.conn then _kw.conn:Disconnect(); _kw.conn = nil end
                if not on then notify("Kaitun Webhook", "Stopped.", 2); return end
                if _kw.url == "" then notify("Kaitun Webhook", "Webhook URL belum diset!"); return end
                if not getHTTP() then notify("Kaitun Webhook", "Executor tidak support HTTP!"); return end
                _kw.conn = NetEvents.RE_TextNotification.OnClientEvent:Connect(function(p)
                    if type(p) ~= "table" or p.Type ~= "Item" then return end
                    local id = tonumber(p.ItemId)
                    if not (id and KW_WATCH[p.ItemType] and KW_WATCH[p.ItemType][id]) then return end
                    local key = p.ItemType .. "_" .. id
                    if _kw.sent[key] then return end
                    _kw.sent[key] = true
                    task.delay(10, function() _kw.sent[key] = nil end)
                    task.spawn(sendObtained, p.ItemType, id)
                end)
                notify("Kaitun Webhook", "Active! Interval: " .. _kw.intervalMin .. " menit")
                _kw.thread = task.spawn(function()
                    task.wait(2)
                    while _kw.enabled do
                        pcall(sendProgress)
                        task.wait(_kw.intervalMin * 60)
                    end
                end)
            end,
        })
    end
    do
        local OCULUS = { { id = 704, qty = 2, name = "Veilshard" }, { id = 20221, qty = 1, name = "Cave Crystal" },
                         { id = 700, qty = 1, name = "Embercrux" }, { id = 701, qty = 1, name = "Pyrafruit Relic" } }
        local FLAME_TYRANT_ID = 974
        local function countOwned(id)
            local data, count = getCachedReplionData(), 0
            for _, item in ipairs(data:Get({ "Inventory", "Items" }) or {}) do
                if item.Id == id then count += item.Quantity or 1 end
            end
            return count
        end
        local function oculusReady()
            for _, ing in ipairs(OCULUS) do
                if countOwned(ing.id) < ing.qty then return false end
            end
            return true
        end
        local function oculusLines()
            local lines = {}
            for _, ing in ipairs(OCULUS) do
                local have = countOwned(ing.id)
                lines[#lines + 1] = ("%s %s: %d/%d"):format(have >= ing.qty and "✓" or "✗", ing.name, have, ing.qty)
            end
            return table.concat(lines, "\n")
        end
        local WRSection = QuestTab:AddSection("Auto Withering Rod - Part 1", false)
        local setStatus = statusFor(WRSection, "Status")
        loopToggle(WRSection, {
            title = "Enable Auto Withering Rod", name = "Withering Rod", setStatus = setStatus, interval = 3,
            step = function()
                local q = questState("Withering Rod - Part 1")
                if not q then return false end
                if q.done then return "Withering Rod - Part 1 selesai!" end
                if not q.entry then acceptQuest(q.name); return false end
                local text = questLines(q)
                if not objDone(q, 3) and turnIn(q, 3) then return false end
                if not objDone(q, 5) then
                    text ..= "\n\nOculus Charm:\n" .. oculusLines()
                    if oculusReady() then
                        local okStart, started = pcall(function() return NetEvents.RF_StartCrafting:InvokeServer("Oculus Charm") end)
                        if okStart and started then
                            task.wait(0.5)
                            local okConfirm, confirmed = pcall(function() return NetEvents.RF_ConfirmCrafting:InvokeServer() end)
                            if not (okConfirm and confirmed) then
                                pcall(function() NetEvents.RF_CancelCrafting:InvokeServer() end)
                            end
                        end
                    end
                end
                if not objDone(q, 4) and not findItem({ Id = FLAME_TYRANT_ID }) then
                    text ..= "\n\nTangkap Flame Tyrant di Copper Canyon..."
                    tp("Copper Canyon")
                elseif not objDone(q, 2) then
                    text ..= "\n\nSelesaikan fish index (Auto Complete Fish Index)."
                elseif not objDone(q, 3) then
                    text ..= "\n\nMenunggu Megalodon yang bermutasi..."
                end
                setStatus(text)
                return false
            end,
        })
    end
    do
        local QuestSection = QuestTab:AddSection("Trigger Turn-in Quest", false)
        local setStatus = statusFor(QuestSection, "Status")
        local function handIn(name)
            local q = questState(name)
            for objId in pairs(TURN_INS[name]) do
                if type(objId) == "number" and not objDone(q, objId) then
                    setStatus("Turn in: " .. name)
                    if not turnIn(q, objId) then return false end
                    q = questState(name)
                end
            end
            return true
        end
        local function needsItem(name)
            local q = questState(name)
            for objId in pairs(TURN_INS[name]) do
                if type(objId) == "number" and not objDone(q, objId) and not findItem(objDef(q, objId).Requirements or {}) then return true end
            end
            return false
        end
        loopToggle(QuestSection, {
            title = "Run Quest Check", name = "Turn-in Quest", setStatus = setStatus,
            step = function(state)
                local done, skipped, failed, waiting = 0, 0, 0, {}
                for name, route in pairs(TURN_INS) do
                    if not state.enabled then return false end
                    if not questState(name) or questDone(name) then
                        skipped += 1
                    else
                        setStatus("Accept: " .. name)
                        acceptQuest(name)
                        if needsItem(name) then
                            if route.waitForItem then waiting[#waiting + 1] = name else skipped += 1 end
                        elseif handIn(name) then done += 1 else failed += 1 end
                    end
                end
                for _, name in ipairs(waiting) do
                    setStatus("Waiting item: " .. name .. "\nFishing dulu...")
                    while state.enabled and needsItem(name) do task.wait(2) end
                    if not state.enabled then return false end
                    if handIn(name) then done += 1 else failed += 1 end
                end
                local summary = ("Turned in: %d | Skipped: %d | Failed: %d"):format(done, skipped, failed)
                setStatus(summary)
                return summary
            end,
        })
    end
    do
        local RUNIC_OBJ = 2
        local DivineSection = QuestTab:AddSection("Auto Trigger Divine Power Quest", false)
        local setStatus = statusFor(DivineSection, "Status")
        local RUNIC_SPOTS = { "Sewers", "Underwater City" }
        local runicSpot = "Sewers"
        local home -- where we stood before going to the Runic Stone spot
        local atSpot -- the spot we teleported to, so a new dropdown pick moves us there
        local function goHome()
            atSpot = nil
            if home then tp(home, 0); home = nil; notify("Divine Power", "Kembali ke lokasi awal.") end
        end
        DivineSection:AddDropdown({
            Title    = "Runic Stone Location",
            Options  = RUNIC_SPOTS,
            Default  = runicSpot,
            Callback = function(value)
                if value == "Sewers" or value == "Underwater City" then runicSpot = value end
            end,
        })
        loopToggle(DivineSection, {
            title = "Auto Divine Power", name = "Divine Power", setStatus = setStatus, interval = 1, onStop = goHome,
            step = function()
                local q = questState("Divine Power")
                if not q then return false end
                local active = q.entry ~= nil and not q.entry.Claimed
                if not active then
                    goHome()
                    local claimedAt = q.entry and (q.entry.ClaimedAt or q.entry.Timestamp)
                    local remaining = claimedAt and ((q.def.RepeatCooldown or 28800) - (workspace:GetServerTimeNow() - claimedAt)) or 0
                    if remaining > 0 then
                        local s = math.floor(remaining)
                        setStatus(("Cooldown, bisa trigger lagi dalam %02dh %02dm %02ds"):format(s // 3600, s % 3600 // 60, s % 60))
                        return false
                    end
                    setStatus("Trigger quest ke Lucid...")
                    dialogue("Lucid", 1, 1)
                    task.wait(2)
                    return false
                end
                setStatus(questLines(q))
                if objDone(q, RUNIC_OBJ) then
                    goHome()
                elseif not home or atSpot ~= runicSpot then
                    if not home then
                        local hrp = rootPart()
                        home = hrp and hrp.CFrame
                    end
                    atSpot = runicSpot
                    tp(runicSpot, 0)
                    notify("Divine Power", ("Teleport ke %s untuk Runic Stone."):format(runicSpot))
                end
                return false
            end,
        })
    end
    do
        local SHARK = { quest = "A Grueling Shark Hunt", minDist = 20, steps = {
            { obj = 2, spot = "Ocean" },
            { obj = 3, spot = "Esoteric Depths" },
        } }
        local darkMega = false
        local function setDarkMega(on)
            if on == darkMega then return end
            darkMega = on
            local list = _ev.selectedEvents
            local idx = table.find(list, "Dark Megalodon")
            if on then
                if not idx then table.insert(list, "Dark Megalodon") end
                _ev.priorityEvent = "Dark Megalodon"
                if not _ev.active then _ev.start() end
                notify("Shark Hunt", "Auto teleport ke Dark Megalodon dimulai!")
            else
                _ev.priorityEvent = nil
                if idx then table.remove(list, idx) end
                if #list == 0 then _ev.stop() end
            end
        end
        local SharkSection = QuestTab:AddSection("Auto A Grueling Shark Hunt", false)
        local setStatus = statusFor(SharkSection, "Status")
        loopToggle(SharkSection, {
            title = "Auto Shark Hunt", name = "Shark Hunt", save = true, setStatus = setStatus, interval = 1,
            onStop = function() setDarkMega(false) end,
            step = function()
                local finished = planStep(SHARK, setStatus)
                local q = questState(SHARK.quest)
                setDarkMega(not finished and q ~= nil and q.entry ~= nil and objDone(q, 2) and objDone(q, 3) and not objDone(q, 4))
                return finished
            end,
        })
    end
    do
        local ArtSection = QuestTab:AddSection("Artifact Lever", false)
        local setStatus = statusFor(ArtSection, "Artifact Status")
        loopToggle(ArtSection, {
            title = "Auto Artifact Progress", name = "Artifact", save = true, setStatus = setStatus, interval = 1,
            step = function() return artifactStep(setStatus) and "Semua artifact selesai!" end,
        })
    end
    for _, entry in ipairs({
        { title = "Deep Sea Quest",           toggle = "Auto Deep Sea Quest",           step = function(set) return planStep(DEEP_SEA, set) end },
        { title = "Element Quest",            toggle = "Auto Element Quest",            step = elementStep },
        { title = "Diamond Researcher Quest", toggle = "Auto Diamond Researcher Quest", step = function(set) return planStep(DIAMOND, set) end },
        { title = "Crystalline Secret Quest", toggle = "Auto Crystalline Secret Quest", step = function(set) return planStep(CRYSTALLINE, set) end },
    }) do
        local section = QuestTab:AddSection(entry.title, false)
        local setStatus = statusFor(section, "Status")
        loopToggle(section, {
            title = entry.toggle, name = entry.title, setStatus = setStatus,
            step = function() return entry.step(setStatus) end,
        })
    end
    do
        local RUIN = { ["Freshwater Piranha"] = 284, ["Goliath Tiger"] = 270, ["Sacred Guardian Squid"] = 283, ["Crocodile"] = 263 }
        local RUIN_ORDER = { "Freshwater Piranha", "Goliath Tiger", "Sacred Guardian Squid", "Crocodile" }
        local function plateFor(tier)
            for _, part in ipairs(CollectionService:GetTagged("PressurePlate")) do
                if part.Parent and part.Parent:GetAttribute("Type") == tier then return part end
            end
            return nil
        end
        local RuinSection = QuestTab:AddSection("Auto Ancient Ruin", false)
        local setStatus = statusFor(RuinSection, "Ancient Ruin Status")
        loopToggle(RuinSection, {
            title = "Auto Ancient Ruin", name = "Ancient Ruin", setStatus = setStatus, interval = 1.5,
            step = function()
                local placed = getCachedReplionData():Get("RuinPressurePlates") or {}
                local lines, allDone = {}, true
                for _, tier in ipairs(RUIN_ORDER) do
                    lines[#lines + 1] = (placed[tier] and "✓ " or "• ") .. tier
                    if not placed[tier] then
                        allDone = false
                        if findItem({ Id = RUIN[tier] }) then
                            local plate = plateFor(tier)
                            if plate then tp(CFrame.new(plate.Position + Vector3.new(0, 3, 0)), 0); task.wait(0.6) end
                            pcall(function() NetEvents.RE_PlacePressureItem:FireServer(tier) end)
                            task.wait(0.5)
                        end
                    end
                end
                setStatus(table.concat(lines, "\n"))
                return allDone and "Semua pressure plate selesai!"
            end,
        })
    end
    do
        local SCALE = { quest = "Forgotten Scale", steps = {
            { obj = 1, spot = "Kohana" }, { obj = 2, spot = "Kohana" }, { obj = 3, spot = "Kohana" }, { obj = 4, spot = "Kohana" },
        } }
        local RELICS = {
            { index = 1, id = 578, name = "Sunken Eye Relic" },
            { index = 2, id = 577, name = "Blacktide Relic" },
            { index = 3, id = 579, name = "Burntflame Relic" },
        }
        local SCALE_ID = 576
        local function relicUUID(id) return findItem({ Id = id }) end
        local function plateActive(rep, index)
            local ok, plates = pcall(function() return rep:GetExpect("PressurePlates") end)
            return ok and plates and table.find(plates, index) ~= nil
        end
        local LeviSection = QuestTab:AddSection("Leviathan Hunt", false)
        local setStatus = statusFor(LeviSection, "Leviathan Status")
        loopToggle(LeviSection, {
            title = "Auto Leviathan Hunt", name = "Leviathan", setStatus = setStatus,
            step = function()
                if not questDone(SCALE.quest) then
                    planStep(SCALE, setStatus)
                    return false
                end
                local scale = findItem({ Id = SCALE_ID })
                if scale then
                    setStatus("Consume Leviathan Scale...")
                    tp("Archaeologist")
                    task.wait(1.5)
                    pcall(function() NetEvents.RF_ConsumeItem:InvokeServer(scale) end)
                    return false
                end
                local lines = { "Relic:" }
                local missing = false
                for _, r in ipairs(RELICS) do
                    local has = relicUUID(r.id) ~= nil
                    missing = missing or not has
                    lines[#lines + 1] = (has and "✓ " or "• ") .. r.name
                end
                setStatus(table.concat(lines, "\n"))
                if missing then tp("Kohana"); return false end
                local replion = getCachedReplion()
                local rep = replion and replion.Client:GetReplion("LeviathanEvent")
                if not (rep and rep:Get("Lobby")) then return false end
                local allPlaced = true
                for _, r in ipairs(RELICS) do
                    if not plateActive(rep, r.index) then
                        allPlaced = false
                        tp("Leviathan Plate " .. r.index, 0)
                        task.wait(1)
                        pcall(function() NetEvents.RE_PlaceLeviathanPressureItem:FireServer(relicUUID(r.id), r.index) end)
                        task.wait(1)
                    end
                end
                return allPlaced and "Semua relic terpasang! Leviathan Hunt dimulai!"
            end,
        })
    end
    do
        local names = {}
        for name in pairs(SPOTS) do names[#names + 1] = name end
        table.sort(names)
        local selected = names[1]
        local TpSection = QuestTab:AddSection("Quest Teleport", false)
        TpSection:AddDropdown({
            Title = "Lokasi", Options = names, Default = selected, NoSave = true,
            Callback = function(v) selected = type(v) == "string" and v or selected end,
        })
        TpSection:AddButton({ Title = "Teleport", Callback = function() tp(selected, 0) end })
    end
    do
        local _throne = { enabled = false, thread = nil }
        local function _throneReplion()
            local rep = cachedRequire(ReplicatedStorage.Packages.Replion)
            return rep and rep.Client:GetReplion("Data")
        end
        local function _thronePedestalMap()
            local ok, Map = pcall(function()
                return cachedRequire(ReplicatedStorage.Shared.Elemental.Map)
            end)
            if not ok or type(Map) ~= "table" then return nil end
            return Map
        end
        local function _thronePlacedSet(data)
            local placed = {}
            local ok, arr = pcall(function()
                return data:GetExpect({ "ThroneRoomProgress", "Placed" })
            end)
            if ok and arr then
                for _, name in ipairs(arr) do placed[name] = true end
            end
            return placed
        end
        local function _throneIsDone(data)
            local ok, progress = pcall(function() return data:GetExpect("ThroneRoomProgress") end)
            if not ok or not progress then return false end
            return (progress.Progress or 0) >= 3 or #(progress.Placed or {}) >= 3
        end
        local function _throneFindCrystalUUID(data, itemId)
            local ok, inv = pcall(function() return data:Get({ "Inventory", "Items" }) end)
            if not ok or not inv then return nil end
            for _, item in ipairs(inv) do
                if item.Id == itemId then return item.UUID end
            end
            return nil
        end
        local function _throneEquipCrystal(data, uuid)
            local slotKey = nil
            local deadline = tick() + 5
            while tick() < deadline and _throne.enabled do
                local equippedItems = data:Get("EquippedItems") or {}
                for key, u in pairs(equippedItems) do
                    if u == uuid then slotKey = key; break end
                end
                if slotKey then break end
                pcall(function() NetEvents.RE_EquipItem:FireServer(uuid, "Gears") end)
                task.wait(0.5)
            end
            if not slotKey then return false end
            pcall(function() NetEvents.RF_EquipToolFromHotbar:FireServer(slotKey) end)
            task.wait(0.4)
            local deadline2 = tick() + 3
            while tick() < deadline2 and _throne.enabled do
                if data:Get("EquippedId") == uuid and data:Get("EquippedType") == "Gears" then
                    return true
                end
                task.wait(0.2)
            end
            return false
        end
        local ThroneSection = QuestTab:AddSection("Auto Place Cystal Throne Room", false)
        ThroneSection:AddToggle({
            Title    = "Auto Open Throne Room",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                _throne.enabled = on
                if _throne.thread then
                    pcall(task.cancel, _throne.thread)
                    _throne.thread = nil
                end
                if not on then
                    Library:MakeNotify({ Title = "Throne Room", Description = "Stopped.", Delay = 2 })
                    return
                end
                local data = _throneReplion()
                if not data then
                    _throne.enabled = false
                    return
                end
                Library:MakeNotify({ Title = "Throne Room", Description = "Active!", Delay = 2 })
                _throne.thread = task.spawn(function()
                    while _throne.enabled do
                        if _throneIsDone(data) then
                            break
                        end
                        local map = _thronePedestalMap()
                        if not map then
                            task.wait(3)
                            continue
                        end
                        local placed  = _thronePlacedSet(data)
                        local didWork = false
                        for name, info in pairs(map) do
                            if not _throne.enabled then break end
                            if not placed[name] then
                                local itemId = type(info) == "table" and info.Id or nil
                                if itemId then
                                    local uuid = _throneFindCrystalUUID(data, itemId)
                                    if uuid then
                                        if _throneEquipCrystal(data, uuid) then
                                            local remote = NetEvents.RE_PlaceElementalCrystal
                                            if remote then
                                                pcall(function() remote:FireServer(name) end)
                                                task.wait(1.5)
                                                if _thronePlacedSet(data)[name] then
                                                    didWork = true
                                                    Library:MakeNotify({
                                                        Title = "Throne Room",
                                                        Description = name .. " Crystal berhasil ditaruh!",
                                                        Delay = 3,
                                                    })
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if not didWork then task.wait(3) end
                        task.wait(1)
                    end
                    if _throne.enabled then
                        _throne.enabled = false
                    end
                end)
            end,
        })
    end
end
-- [Plaza Tab]
task.wait()
local PlazzaTab = MainWindow:AddTab({ Name = "Plaza", Icon = "shop" })
do
    local TradeData   = cachedRequire(ReplicatedStorage.Shared.Trading.TradeData)
    local ItemUtility = cachedRequire(ReplicatedStorage.Shared.ItemUtility)
    local CONTAINER   = "Booth"
    local SLOT_COUNT  = math.max(tonumber(
        TradeData and TradeData.SaleContainers and TradeData.SaleContainers[CONTAINER]
            and TradeData.SaleContainers[CONTAINER].MaxItems) or 10, 1)
    local MAX_PRICE   = tonumber(TradeData and TradeData.MaxSaleListingPrice) or 1000000000
    local TRADABLE, SKIN_ONLY, EXCLUDE_PAID = {}, {}, {}
    for _, t in ipairs((TradeData and TradeData.TradableItemTypes) or {}) do TRADABLE[t] = true end
    for t in pairs((TradeData and TradeData.TradableItemsSkinOnly) or {}) do SKIN_ONLY[t] = true end
    for t in pairs((TradeData and TradeData.ExcludeCoinsItems) or {}) do EXCLUDE_PAID[t] = true end
    local GAP_MIN,  GAP_MAX  = 3.0, 6.5    -- between two CreateSaleListing calls
    local SOLD_MIN, SOLD_MAX = 6.0, 14.0   -- before refilling a slot that just sold
    local FAIL_MIN, FAIL_MAX = 15, 45      -- after the server refuses a listing
    local IDLE_POLL          = 8           -- nothing to do: how often to look again
    local PENDING_GRACE      = 4           -- Replion lags behind a successful listing
    local BAD_ITEM_TTL       = 120         -- park an item the server refused
    local function jitter(a, b) return a + math.random() * (b - a) end
    local _booth = {
        enabled = false, thread = nil, soldConn = nil,
        slots = {}, bad = {}, wake = false, lastError = "", listed = 0, sold = 0,
    }
    for i = 1, SLOT_COUNT do
        _booth.slots[i] = { itemName = nil, price = 100, mode = "Include", variants = {}, uuid = nil, grace = 0 }
    end
    local function replionData() return getCachedReplionData() end
    local function inventory()
        local rep = replionData()
        local ok, inv = pcall(function() return rep and rep:Get("Inventory") end)
        return (ok and type(inv) == "table") and inv or {}
    end
    local function listings()
        local rep = replionData()
        local ok, l = pcall(function() return rep and rep:Get({ "SaleListings", CONTAINER }) end)
        return (ok and type(l) == "table") and l or {}
    end
    local _dataCache = {}
    local function dataOf(bucket, id)
        local key = tostring(bucket) .. "\0" .. tostring(id)
        local hit = _dataCache[key]
        if hit ~= nil then return hit or nil end
        local ok, d = pcall(function() return ItemUtility.GetItemDataFromItemType(bucket, id) end)
        d = (ok and type(d) == "table" and d.Data) and d or nil
        _dataCache[key] = d or false
        return d
    end
    local function variantOf(item)
        local vid = item.Metadata and item.Metadata.VariantId
        if type(vid) ~= "string" or vid == "" then return nil end
        local ok, v = pcall(function() return ItemUtility:GetVariantData(vid) end)
        return (ok and v and v.Data and v.Data.Name) or vid
    end
    local function sellable(d, item)
        if not (d and d.Data) then return false end
        if TradeData and type(TradeData.FollowTradeRules) == "function" then
            local ok, res = pcall(TradeData.FollowTradeRules, d, item)
            if ok then return res == true end
        end
        local t = d.Data.Type
        return TRADABLE[t] == true
            and not (SKIN_ONLY[t] and not d.IsSkin)
            and not (EXCLUDE_PAID[t] and d.Price)
            and not (item.Metadata and item.Metadata.TradeLock)
            and not d.TradeLocked
    end
    local function scanInventory()
        local byName, counts, variants = {}, {}, {}
        for bucket, items in pairs(inventory()) do
            if type(items) == "table" then
                for _, item in ipairs(items) do
                    if type(item) == "table" and item.Id and item.UUID then
                        local d = dataOf(bucket, item.Id)
                        if d and sellable(d, item) then
                            local name = d.Data.Name or "?"
                            local v    = variantOf(item)
                            counts[name] = (counts[name] or 0) + 1
                            local pool = byName[name]
                            if not pool then pool = {}; byName[name] = pool end
                            pool[#pool + 1] = { uuid = item.UUID, itemType = d.Data.Type, variant = v }
                            if v then
                                local set = variants[name]
                                if not set then set = {}; variants[name] = set end
                                set[v] = true
                            end
                        end
                    end
                end
            end
        end
        return byName, counts, variants
    end
    local function sortedWithNone(set, counts)
        local out = { "None" }
        for k in pairs(set or {}) do
            out[#out + 1] = counts and (k .. " x" .. tostring(counts[k])) or k
        end
        table.sort(out, function(a, b)
            if a == "None" then return true end
            if b == "None" then return false end
            return a < b
        end)
        return out
    end
    local function stripCount(label)
        return type(label) == "string" and (label:match("^(.+) x%d+$") or label) or nil
    end
    local function slotAccepts(slot, entry)
        local v      = entry.variant or "None"
        local picked = next(slot.variants) ~= nil
        if slot.mode == "Exclude" then
            if not picked then return v ~= "None" end
            return slot.variants[v] ~= true
        end
        if not picked then return v == "None" end
        return slot.variants[v] == true
    end
    local function liveUUIDs()
        local set, n = {}, 0
        for _, listing in pairs(listings()) do
            if type(listing) == "table" and listing.ItemId then
                set[listing.ItemId] = true
                n += 1
            end
        end
        return set, n
    end
    local function slotHolds(slot, live)
        if not slot.uuid then return false end
        if live[slot.uuid] then slot.grace = 0; return true end
        if slot.grace > os.clock() then return true end
        slot.uuid = nil
        return false
    end
    local function slotLabel(slot)
        local label = slot.itemName or "?"
        if next(slot.variants) then
            local vars = {}
            for v in pairs(slot.variants) do vars[#vars + 1] = v end
            table.sort(vars)
            label = ("%s [%s: %s]"):format(label, slot.mode, table.concat(vars, ", "))
        end
        return label
    end
    local Section    = PlazzaTab:AddSection("Auto Restock Booth", false)
    local statusPara = Section:AddParagraph({ Title = "Status", Content = "Idle" })
    local function setStatus(title, content)
        pcall(function()
            statusPara:SetTitle(title)
            statusPara:SetContent(content)
        end)
    end
    Section:AddParagraph({
        Title   = "Info",
        Content = ("Booth muat <b>%d</b> listing (dibaca dari game, bukan ditebak).\n"):format(SLOT_COUNT)
            .. "Isi slot yang mau dijaga stoknya; yang kosong diabaikan.\n"
            .. "<b>Mode Include</b> = hanya variant yang dipilih. Kosong = hanya yang tanpa variant.\n"
            .. "<b>Mode Exclude</b> = selain variant yang dipilih. Kosong = semua yang ber-variant.\n"
            .. "Jeda antar listing diacak 3-6.5 detik dan slot yang laku baru diisi lagi "
            .. "setelah 6-14 detik, supaya polanya tidak seperti bot.",
    })
    local byNameCache, countsCache, variantsCache = scanInventory()
    local itemOptions = sortedWithNone(countsCache, countsCache)
    local itemDrops, variantDrops = {}, {}
    for i = 1, SLOT_COUNT do
        local slot = _booth.slots[i]
        itemDrops[i] = Section:AddDropdown({
            Title    = "Item Slot " .. i,
            Options  = itemOptions,
            Default  = "None",
            Callback = function(selected)
                slot.uuid = nil
                local name = stripCount(selected)
                if not name or name == "None" then
                    slot.itemName = nil
                    if variantDrops[i] then pcall(function() variantDrops[i]:SetOptions({ "None" }) end) end
                    return
                end
                slot.itemName = name
                slot.variants = {}
                if variantDrops[i] then
                    pcall(function() variantDrops[i]:SetOptions(sortedWithNone(variantsCache[name])) end)
                end
            end,
        })
        Section:AddDropdown({
            Title    = "Mode Slot " .. i,
            Options  = { "Include", "Exclude" },
            Default  = "Include",
            Callback = function(selected)
                slot.mode = selected == "Exclude" and "Exclude" or "Include"
                slot.uuid = nil
            end,
        })
        variantDrops[i] = Section:AddDropdown({
            Title    = "Variant Slot " .. i,
            Options  = { "None" },
            Default  = {},
            Multi    = true,
            Callback = function(selected)
                local set = {}
                if type(selected) == "table" then
                    for _, v in ipairs(selected) do set[v] = true end
                elseif type(selected) == "string" then
                    set[selected] = true
                end
                set["None"] = nil
                slot.variants = set
                slot.uuid     = nil
            end,
        })
        Section:AddInput({
            Title    = "Price Slot " .. i,
            Default  = "100",
            Callback = function(value)
                local n = tonumber(value)
                if n and n >= 1 then slot.price = math.floor(math.min(n, MAX_PRICE)) end
            end,
        })
    end
    Section:AddButton({
        Title    = "Refresh Item List",
        Callback = function()
            byNameCache, countsCache, variantsCache = scanInventory()
            itemOptions = sortedWithNone(countsCache, countsCache)
            for i = 1, SLOT_COUNT do
                pcall(function() itemDrops[i]:SetOptions(itemOptions) end)
                local name = _booth.slots[i].itemName
                if name and variantDrops[i] then
                    pcall(function() variantDrops[i]:SetOptions(sortedWithNone(variantsCache[name])) end)
                end
            end
            local kinds = 0
            for _ in pairs(countsCache) do kinds += 1 end
            setStatus("Status", ("List diperbarui: %d jenis item bisa dijual."):format(kinds))
        end,
    })
    local function pullSavedConfig()
        local flags = Library.flags
        if not flags then return end
        local function readFlag(key)
            local f = flags[key]
            if not f or type(f.GetValue) ~= "function" then return nil end
            local ok, v = pcall(function() return f:GetValue() end)
            return ok and v or nil
        end
        for i = 1, SLOT_COUNT do
            local slot = _booth.slots[i]
            if not slot.itemName then
                local name = stripCount(readFlag("Item_Slot_" .. i))
                if name and name ~= "" and name ~= "None" then slot.itemName = name end
            end
            if not next(slot.variants) then
                local v = readFlag("Variant_Slot_" .. i)
                if type(v) == "table" then
                    local set = {}
                    for _, name in ipairs(v) do set[name] = true end
                    set["None"] = nil
                    slot.variants = set
                end
            end
            local mode = readFlag("Mode_Slot_" .. i)
            if mode == "Include" or mode == "Exclude" then slot.mode = mode end
            local price = tonumber(readFlag("Price_Slot_" .. i))
            if price and price >= 1 then slot.price = math.floor(math.min(price, MAX_PRICE)) end
        end
    end
    local function listOne(slot, byName, live, taken)
        local pool = slot.itemName and byName[slot.itemName]
        if not pool then return "empty" end
        local remote = NetEvents.RF_CreateSaleListing
        if not remote then
            _booth.lastError = "remote CreateSaleListing tidak ketemu"
            return "failed"
        end
        local now = os.clock()
        for _, entry in ipairs(pool) do
            if not live[entry.uuid] and not taken[entry.uuid]
                and (_booth.bad[entry.uuid] or 0) <= now and slotAccepts(slot, entry)
            then
                local ok, success, info = pcall(function()
                    return remote:InvokeServer(CONTAINER, entry.itemType, entry.uuid, slot.price)
                end)
                if ok and success == true then
                    slot.uuid         = entry.uuid
                    slot.grace        = os.clock() + PENDING_GRACE
                    taken[entry.uuid] = true
                    _booth.listed    += 1
                    return "listed"
                end
                _booth.lastError       = tostring((ok and (info or success)) or success)
                _booth.bad[entry.uuid] = os.clock() + BAD_ITEM_TTL
                return "failed"
            end
        end
        return "empty"
    end
    local function sleepUntil(deadline)
        while _booth.enabled and not _booth.wake and os.clock() < deadline do
            task.wait(0.25)
        end
        _booth.wake = false
    end
    local function worker()
        while _booth.enabled do
            local live, used = liveUUIDs()
            local byName     = scanInventory()
            local taken      = {}
            for _, slot in ipairs(_booth.slots) do
                if slot.uuid then taken[slot.uuid] = true end
            end
            local wait, result, label, price = IDLE_POLL, nil, nil, 0
            if used >= SLOT_COUNT then
                setStatus("Penuh", ("Booth penuh (%d/%d listing). Nunggu ada yang laku."):format(used, SLOT_COUNT))
            else
                for _, slot in ipairs(_booth.slots) do
                    if not _booth.enabled then break end
                    if slot.itemName and not slotHolds(slot, live) then
                        label, price = slotLabel(slot), slot.price
                        result = listOne(slot, byName, live, taken)
                        if result ~= "empty" then break end
                    end
                end
                if result == "listed" then
                    wait = jitter(GAP_MIN, GAP_MAX)
                    setStatus("Listing", ("%s -> %d TT\nTerpasang: %d | Laku: %d | Isi booth: %d/%d")
                        :format(label, price, _booth.listed, _booth.sold, used + 1, SLOT_COUNT))
                elseif result == "failed" then
                    wait = jitter(FAIL_MIN, FAIL_MAX)
                    setStatus("Ditolak", ("%s ditolak server, item itu dilewati.\n%s\nCoba lagi %ds lagi.")
                        :format(tostring(label), tostring(_booth.lastError), math.floor(wait)))
                else
                    setStatus("Nunggu stok", ("Isi booth %d/%d. Stok untuk slot yang kosong belum ada.")
                        :format(used, SLOT_COUNT))
                end
            end
            sleepUntil(os.clock() + wait)
        end
    end
    Section:AddToggle({
        Title    = "Enable Auto Restock",
        Default  = false,
        NoSave   = true,
        Callback = function(on)
            if _booth.soldConn then pcall(function() _booth.soldConn:Disconnect() end); _booth.soldConn = nil end
            if _booth.thread   then pcall(task.cancel, _booth.thread); _booth.thread = nil end
            _booth.enabled = on
            if not on then
                for _, slot in ipairs(_booth.slots) do slot.uuid, slot.grace = nil, 0 end
                setStatus("Status", "Idle")
                Library:MakeNotify({ Title = "Booth Restock", Description = "Auto Restock dimatikan.", Delay = 2 })
                return
            end
            pullSavedConfig()
            local configured = 0
            for _, slot in ipairs(_booth.slots) do
                if slot.itemName then configured += 1 end
            end
            if configured == 0 then
                _booth.enabled = false
                setStatus("Status", "Pilih minimal 1 item di slot dulu.")
                Library:MakeNotify({ Title = "Booth Restock", Description = "Pilih minimal 1 item di slot dulu!", Delay = 3 })
                return
            end
            _booth.bad, _booth.wake, _booth.lastError = {}, false, ""
            _booth.listed, _booth.sold = 0, 0
            local sold = NetEvents.RE_SaleListingSold
            if sold then
                _booth.soldConn = sold.OnClientEvent:Connect(function(_, listingId, _, _, soldItem)
                    if not _booth.enabled then return end
                    local uuid = type(soldItem) == "table" and soldItem.UUID or nil
                    for _, slot in ipairs(_booth.slots) do
                        if uuid and slot.uuid == uuid then
                            slot.uuid, slot.grace = nil, 0
                            _booth.sold += 1
                        end
                    end
                    task.delay(jitter(SOLD_MIN, SOLD_MAX), function()
                        if _booth.enabled then _booth.wake = true end
                    end)
                end)
            end
            setStatus("Status", ("Aktif. %d slot diisi, booth muat %d."):format(configured, SLOT_COUNT))
            _booth.thread = task.spawn(worker)
            Library:MakeNotify({ Title = "Booth Restock", Description = "Auto Restock aktif.", Delay = 2 })
        end,
    })
    local _clearing = false
    Section:AddButton({
        Title    = "Clear Booth",
        Callback = function()
            if _clearing then return end
            if _booth.enabled then
                setStatus("Status", "Matikan Auto Restock dulu sebelum Clear Booth.")
                return
            end
            local remote = NetEvents.RF_DeleteSaleListing
            if not remote then
                setStatus("Status", "Remote DeleteSaleListing tidak ketemu.")
                return
            end
            local keys = {}
            for key in pairs(listings()) do keys[#keys + 1] = key end
            if #keys == 0 then
                setStatus("Status", "Booth sudah kosong.")
                return
            end
            _clearing = true
            task.spawn(function()
                local removed = 0
                for _, key in ipairs(keys) do
                    local ok, success = pcall(function() return remote:InvokeServer(CONTAINER, key) end)
                    if ok and success then removed += 1 end
                    setStatus("Clear Booth", ("Menghapus %d/%d listing..."):format(removed, #keys))
                    task.wait(jitter(1.2, 2.4))
                end
                for _, slot in ipairs(_booth.slots) do slot.uuid, slot.grace = nil, 0 end
                _clearing = false
                setStatus("Clear Booth", ("Selesai: %d dari %d listing dihapus."):format(removed, #keys))
            end)
        end,
    })
end
-- [Settings Tab]
task.wait()
do
    local SettingsTab = MainWindow:AddTab({ Name = "Settings", Icon = "settings" })
    do
        local ProtectionSection = SettingsTab:AddSection("Protection")
        local _stayActive       = { enabled = false, conns = {}, task = nil }
        local _antiStaff = { enabled = false, task = nil }
        local GROUP_ID = 35102746
        local STAFF_RANKS = {
            [2]=true,[3]=true,[4]=true,[30]=true,[35]=true,[55]=true,
            [75]=true,[76]=true,[79]=true,[100]=true,[145]=true,
            [250]=true,[252]=true,[254]=true,[255]=true,
        }
        local RANK_NAMES = {
            [2]   = "Trial Moderator",
            [3]   = "Moderator",
            [4]   = "Senior Moderator",
            [30]  = "Trial Administrator",
            [35]  = "Administrator",
            [55]  = "Senior Administrator",
            [75]  = "Trial Manager",
            [76]  = "Manager",
            [79]  = "Senior Manager",
            [100] = "Director",
            [145] = "Trial Developer",
            [250] = "Developer",
            [252] = "Senior Developer",
            [254] = "Co-Owner",
            [255] = "Owner",
        }
        local PRIORITY_NAMES = {
            [2] = "Junior Staff",
            [3] = "Staff",
            [4] = "Senior Staff",
            [5] = "Admin",
        }
        ProtectionSection:AddToggle({
            Title    = "Stay Active (Anti-AFK)",
            Default  = true,
            Callback = function(on)
                if on then
                    if _stayActive.enabled then return end
                    _stayActive.enabled = true
                    if type(getconnections) == "function" then
                        pcall(function()
                            for _, c in ipairs(getconnections(LocalPlayer.Idled)) do
                                if c and c.Disable then
                                    pcall(c.Disable, c)
                                    table.insert(_stayActive.conns, c)
                                end
                            end
                        end)
                    end
                else
                    _stayActive.enabled = false
                    pcall(function()
                        for _, c in ipairs(_stayActive.conns) do
                            if c and c.Enable then pcall(c.Enable, c) end
                        end
                        _stayActive.conns = {}
                    end)
                end
            end,
        }):SetValue(true)
        ProtectionSection:AddToggle({
            Title    = "Anti Staff (Auto Kick)",
            Default  = false,
            Callback = function(on)
                _antiStaff.enabled = on
                if on then
                    if _antiStaff.task then return end
                    _antiStaff.task = task.spawn(function()
                        local UserPriority = nil
                        pcall(function()
                            UserPriority = require(game:GetService("ReplicatedStorage").Shared.UserPriority)
                        end)
                        while _antiStaff.enabled do
                            for _, player in ipairs(Players:GetPlayers()) do
                                if player ~= LocalPlayer then
                                    local detected   = false
                                    local detectedBy = ""
                                    local roleName   = ""
                                    local rank = 0
                                    pcall(function() rank = player:GetRankInGroup(GROUP_ID) end)
                                    if STAFF_RANKS[rank] then
                                        detected   = true
                                        detectedBy = "Group Rank"
                                        roleName   = RANK_NAMES[rank] or ("Rank " .. rank)
                                    end
                                    if not detected and UserPriority then
                                        local priority = 0
                                        pcall(function()
                                            priority = UserPriority:GetPriorityLevel(player)
                                        end)
                                        if priority >= 2 then
                                            detected   = true
                                            detectedBy = "Priority Level"
                                            roleName   = PRIORITY_NAMES[priority] or ("Priority " .. priority)
                                        end
                                    end
                                    if detected then
                                        local kickMsg = string.format(
                                            "Staff Detected!\nNama: %s\nRole: %s\nDeteksi: %s\nAuto Kicked for Safety.",
                                            player.Name,
                                            roleName,
                                            detectedBy
                                        )
                                        LocalPlayer:Kick(kickMsg)
                                        return
                                    end
                                end
                            end
                            task.wait(1)
                        end
                    end)
                else
                    if _antiStaff.task then
                        task.cancel(_antiStaff.task)
                        _antiStaff.task = nil
                    end
                end
            end,
        })
    end
    do
        local CameraSection = SettingsTab:AddSection("Camera")
        local CAS = game:GetService("ContextActionService")
        local SINK_ACTION, RENDER_STEP = "LynxFreecamSink", "LynxFreecam"
        local SINK_INPUTS = {
            Enum.KeyCode.W, Enum.KeyCode.A, Enum.KeyCode.S, Enum.KeyCode.D, Enum.KeyCode.Space,
            Enum.KeyCode.Up, Enum.KeyCode.Down, Enum.KeyCode.Left, Enum.KeyCode.Right,
            Enum.KeyCode.LeftShift, Enum.KeyCode.RightShift,
            Enum.PlayerActions.CharacterForward, Enum.PlayerActions.CharacterBackward,
            Enum.PlayerActions.CharacterLeft, Enum.PlayerActions.CharacterRight, Enum.PlayerActions.CharacterJump,
        }
        local MOVE_KEYS = {
            [Enum.KeyCode.W] = Vector3.new(0, 0, 1),  [Enum.KeyCode.S] = Vector3.new(0, 0, -1),
            [Enum.KeyCode.A] = Vector3.new(-1, 0, 0), [Enum.KeyCode.D] = Vector3.new(1, 0, 0),
            [Enum.KeyCode.E] = Vector3.new(0, 1, 0),  [Enum.KeyCode.Space] = Vector3.new(0, 1, 0),
            [Enum.KeyCode.Q] = Vector3.new(0, -1, 0), [Enum.KeyCode.LeftShift] = Vector3.new(0, -1, 0),
        }
        local KEEP_GUIS = { LynxPanelMonitor = true, LynxStatsMonitor = true }
        local PITCH_LIMIT, DEADZONE, JOY_RADIUS = math.rad(85), 10, 80
        local isMobile = UIS.TouchEnabled and not UIS.KeyboardEnabled
        local fc = {
            enabled = false, speed = 50, sensitivity = 0.3,
            pos = Vector3.zero, pitch = 0, yaw = 0, joy = Vector3.zero,
            conns = {}, guis = {}, char = nil,
        }
        if _G._Freecam and _G._Freecam.stop then pcall(_G._Freecam.stop) end
        _G._Freecam = fc
        local function connect(signal, fn)
            fc.conns[#fc.conns + 1] = signal:Connect(fn)
        end
        local function look(dx, dy, scale)
            fc.yaw   = fc.yaw - dx * fc.sensitivity * scale
            fc.pitch = math.clamp(fc.pitch - dy * fc.sensitivity * scale, -PITCH_LIMIT, PITCH_LIMIT)
        end
        local function camCF()
            return CFrame.new(fc.pos) * CFrame.fromEulerAnglesYXZ(fc.pitch, fc.yaw, 0)
        end
        local function hideGui(gui)
            if not gui:IsA("ScreenGui") or KEEP_GUIS[gui.Name] or fc.guis[gui] ~= nil then return end
            fc.guis[gui] = gui.Enabled
            gui.Enabled = false
            connect(gui:GetPropertyChangedSignal("Enabled"), function()
                if fc.enabled and gui.Enabled then gui.Enabled = false end
            end)
        end
        local function hideEffect(obj)
            if obj:IsA("BillboardGui") then obj.Enabled = false end
        end
        local function freezeChar(char)
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not (hrp and hum) then return false end
            local boot = char:FindFirstChild("Core") and char.Core:FindFirstChild("BOOTSTRAPPER")
            if boot then boot.Disabled = true end
            fc.char = { model = char, hrp = hrp, hum = hum, boot = boot, pin = hrp.CFrame,
                        walk = hum.WalkSpeed, jump = hum.JumpPower }
            hrp.Anchored = true
            hum.WalkSpeed, hum.JumpPower, hum.AutoRotate = 0, 0, false
            return true
        end
        local function releaseChar()
            local c = fc.char
            fc.char = nil
            if not c then return end
            if c.boot then c.boot.Disabled = false end
            if c.hrp.Parent then
                c.hrp.Anchored = false
                c.hrp.CFrame = c.pin
                c.hrp.AssemblyLinearVelocity = Vector3.zero
            end
            if c.hum.Parent then
                c.hum.WalkSpeed, c.hum.JumpPower, c.hum.AutoRotate = c.walk, c.jump, true
            end
        end
        local function step(dt)
            local cam = workspace.CurrentCamera
            if cam.CameraType ~= Enum.CameraType.Scriptable then cam.CameraType = Enum.CameraType.Scriptable end
            local move = fc.joy
            if not isMobile then
                local rmb = UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
                UIS.MouseBehavior = rmb and Enum.MouseBehavior.LockCurrentPosition or Enum.MouseBehavior.Default
                if rmb then
                    local d = UIS:GetMouseDelta()
                    look(d.X, d.Y, 0.01)
                end
                move = Vector3.zero
                if not UIS:GetFocusedTextBox() then
                    for key, dir in pairs(MOVE_KEYS) do
                        if UIS:IsKeyDown(key) then move += dir end
                    end
                end
                if move.Magnitude > 0 then move = move.Unit end
            end
            if move.Magnitude > 0 then
                local cf = camCF()
                fc.pos += (cf.LookVector * move.Z + cf.RightVector * move.X + cf.UpVector * move.Y) * fc.speed * dt
            end
            cam.CFrame = camCF()
            local c = fc.char
            if c and c.hrp.Parent and c.hrp.CFrame ~= c.pin then
                c.hrp.CFrame = c.pin
                c.hrp.AssemblyLinearVelocity = Vector3.zero
            end
        end
        local function stopFreecam()
            if not fc.enabled then return end
            fc.enabled = false
            pcall(function() RunService:UnbindFromRenderStep(RENDER_STEP) end)
            CAS:UnbindAction(SINK_ACTION)
            for _, conn in ipairs(fc.conns) do pcall(function() conn:Disconnect() end) end
            table.clear(fc.conns)
            for gui, wasEnabled in pairs(fc.guis) do
                if gui.Parent then pcall(function() gui.Enabled = wasEnabled end) end
            end
            table.clear(fc.guis)
            _popCoreGuiHide(Enum.CoreGuiType.All)
            releaseChar()
            local cam = workspace.CurrentCamera
            local char = LocalPlayer.Character
            cam.CameraType    = Enum.CameraType.Custom
            cam.CameraSubject = char and char:FindFirstChildOfClass("Humanoid")
            UIS.MouseBehavior, UIS.MouseIconEnabled = Enum.MouseBehavior.Default, true
            fc.joy, fc.moveTouch, fc.lookTouch = Vector3.zero, nil, nil
        end
        fc.stop = stopFreecam
        local function startFreecam()
            if fc.enabled then return true end
            if not freezeChar(LocalPlayer.Character) then return false end
            fc.enabled = true
            local cam = workspace.CurrentCamera
            fc.pos = cam.CFrame.Position
            fc.pitch, fc.yaw = cam.CFrame:ToEulerAnglesYXZ()
            CAS:BindActionAtPriority(SINK_ACTION, function() return Enum.ContextActionResult.Sink end,
                false, 3000, table.unpack(SINK_INPUTS))
            local pg = LocalPlayer.PlayerGui
            for _, gui in ipairs(pg:GetChildren()) do hideGui(gui) end
            connect(pg.ChildAdded, hideGui)
            local effects = workspace:FindFirstChild("!!! EFFECTS")
            if effects then
                for _, obj in ipairs(effects:GetDescendants()) do hideEffect(obj) end
                connect(effects.DescendantAdded, hideEffect)
            end
            _pushCoreGuiHide(Enum.CoreGuiType.All)
            connect(LocalPlayer.CharacterAdded, function(char)
                char:WaitForChild("HumanoidRootPart", 10)
                if fc.enabled then freezeChar(char) end
            end)
            if isMobile then
                connect(UIS.InputBegan, function(input, gp)
                    if gp or input.UserInputType ~= Enum.UserInputType.Touch then return end
                    local p = Vector2.new(input.Position.X, input.Position.Y)
                    if p.X < workspace.CurrentCamera.ViewportSize.X / 2 then
                        if not fc.moveTouch then fc.moveTouch, fc.moveOrigin, fc.joy = input, p, Vector3.zero end
                    elseif not fc.lookTouch then
                        fc.lookTouch, fc.lookLast = input, p
                    end
                end)
                connect(UIS.InputChanged, function(input)
                    if input.UserInputType ~= Enum.UserInputType.Touch then return end
                    local p = Vector2.new(input.Position.X, input.Position.Y)
                    if input == fc.moveTouch then
                        local d = p - fc.moveOrigin
                        local dist = d.Magnitude
                        fc.joy = dist < DEADZONE and Vector3.zero
                            or Vector3.new(d.X / dist, 0, -d.Y / dist) * (math.min(dist, JOY_RADIUS) / JOY_RADIUS)
                    elseif input == fc.lookTouch then
                        look(p.X - fc.lookLast.X, p.Y - fc.lookLast.Y, 0.005)
                        fc.lookLast = p
                    end
                end)
                connect(UIS.InputEnded, function(input)
                    if input == fc.moveTouch then fc.moveTouch, fc.joy = nil, Vector3.zero end
                    if input == fc.lookTouch then fc.lookTouch = nil end
                end)
            end
            RunService:BindToRenderStep(RENDER_STEP, Enum.RenderPriority.Camera.Value + 1, step)
            return true
        end
        CameraSection:AddParagraph({
            Title   = "Freecam",
            Content = "Kamera bebas, karakter diam di tempat & semua UI game disembunyikan.\n"
                .. "• PC: [F3] on/off • WASD gerak • E/Space naik • Q/Shift turun • tahan klik kanan untuk menoleh\n"
                .. "• Mobile: jari kiri = gerak (arah kamera), jari kanan = menoleh",
        })
        local freecamToggle
        freecamToggle = CameraSection:AddToggle({
            Title    = "Freecam",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                if not on then stopFreecam(); return end
                if not startFreecam() then
                    freecamToggle:SetValue(false)
                    Library:MakeNotify({ Title = "Freecam", Description = "Character belum siap.", Delay = 2 })
                end
            end,
        })
        CameraSection:AddInput({
            Title    = "Freecam Speed",
            Default  = "50",
            Callback = function(value) fc.speed = math.max(1, tonumber(value) or 50) end,
        })
        CameraSection:AddInput({
            Title    = "Freecam Sensitivity",
            Default  = "0.3",
            Callback = function(value) fc.sensitivity = math.clamp(tonumber(value) or 0.3, 0.01, 5) end,
        })
        if not isMobile then
            if _G._FreecamHotkey then _G._FreecamHotkey:Disconnect() end
            _G._FreecamHotkey = UIS.InputBegan:Connect(function(input, gp)
                if not gp and input.KeyCode == Enum.KeyCode.F3 then freecamToggle:SetValue(not fc.enabled) end
            end)
        end
        local zoomMin, zoomMax = LocalPlayer.CameraMinZoomDistance, LocalPlayer.CameraMaxZoomDistance
        CameraSection:AddToggle({
            Title    = "Unlimited Zoom",
            Default  = false,
            Callback = function(on)
                LocalPlayer.CameraMinZoomDistance = on and 0.5 or zoomMin
                LocalPlayer.CameraMaxZoomDistance = on and 9999 or zoomMax
            end,
        })
    end
    do
        local PlayerSection = SettingsTab:AddSection("Player Features")
        local function getChar()
            return LocalPlayer.Character
