        local function getHumanoid()
            local char = getChar()
            return char and char:FindFirstChildOfClass("Humanoid")
        end
        local function getRootPart()
            local char = getChar()
            return char and char:FindFirstChild("HumanoidRootPart")
        end
        local sprintState = { enabled = false, value = 50, origSpeed = nil, conn = nil, charConn = nil }
        PlayerSection:AddToggle({
            Title    = "Enable Sprint",
            Default  = false,
            Callback = function(on)
                if sprintState.enabled == on then return end
                sprintState.enabled = on
                if sprintState.conn     then sprintState.conn:Disconnect();     sprintState.conn     = nil end
                if sprintState.charConn then sprintState.charConn:Disconnect(); sprintState.charConn = nil end
                local hum = getHumanoid()
                if not on then
                    if hum and sprintState.origSpeed then hum.WalkSpeed = sprintState.origSpeed end
                    sprintState.origSpeed = nil
                    return
                end
                if hum then
                    sprintState.origSpeed = hum.WalkSpeed
                    hum.WalkSpeed = sprintState.value
                end
                local timer = 0
                sprintState.conn = RunService.Heartbeat:Connect((function(dt)
                    if not sprintState.enabled then return end
                    timer += dt
                    if timer < 0.25 then return end
                    timer = 0
                    local h = getHumanoid()
                    if h and h.WalkSpeed ~= sprintState.value then h.WalkSpeed = sprintState.value end
                end))
                sprintState.charConn = LocalPlayer.CharacterAdded:Connect(function()
                    task.wait(0.5)
                    local h = getHumanoid()
                    if sprintState.enabled and h then
                        sprintState.origSpeed = sprintState.origSpeed or h.WalkSpeed
                        h.WalkSpeed = sprintState.value
                    end
                end)
            end,
        })
        PlayerSection:AddInput({
            Title    = "Sprint Speed",
            Default  = "50",
            Callback = function(value)
                local n = tonumber(value)
