        local flyState = {
            flying   = false,
            speed    = 50,
            isMobile = UIS.TouchEnabled and not UIS.KeyboardEnabled,
            conns    = {},
            charConn = nil,
            bg       = nil,
            bv       = nil,
        }
        local FLY_KEYS = {
            [Enum.KeyCode.W] = "F", [Enum.KeyCode.S] = "B",
            [Enum.KeyCode.A] = "L", [Enum.KeyCode.D] = "R",
            [Enum.KeyCode.Space] = "U", [Enum.KeyCode.E] = "U",
            [Enum.KeyCode.Q] = "D", [Enum.KeyCode.LeftControl] = "D",
        }
        PlayerSection:AddToggle({
            Title    = "Enable Fly",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                flyState.flying = on
                local function cleanup()
                    for _, c in ipairs(flyState.conns) do pcall(function() c:Disconnect() end) end
                    flyState.conns = {}
                    if flyState.bg then flyState.bg:Destroy(); flyState.bg = nil end
                    if flyState.bv then flyState.bv:Destroy(); flyState.bv = nil end
                    local hum = getHumanoid()
                    if hum then hum.PlatformStand = false end
                end
                if flyState.charConn then flyState.charConn:Disconnect(); flyState.charConn = nil end
                if not on then
                    cleanup()
                    return
                end
                local function attach()
                    local hum, root = getHumanoid(), getRootPart()
                    if not hum or not root then return false end
                    cleanup()
                    flyState.flying   = true
                    hum.PlatformStand = true
                    local bg = Instance.new("BodyGyro")
                    bg.P         = 9e4
                    bg.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
                    bg.CFrame    = root.CFrame
                    bg.Parent    = root
                    local bv = Instance.new("BodyVelocity")
                    bv.Velocity = Vector3.zero
                    bv.MaxForce = Vector3.new(9e9, 9e9, 9e9)
                    bv.Parent   = root
                    flyState.bg, flyState.bv = bg, bv
                    if not flyState.isMobile then
                        local CONTROL = { F = 0, B = 0, L = 0, R = 0, U = 0, D = 0 }
                        for signal, value in pairs({ [UIS.InputBegan] = 1, [UIS.InputEnded] = 0 }) do
                            table.insert(flyState.conns, signal:Connect(function(input, processed)
                                local dir = not processed and FLY_KEYS[input.KeyCode]
                                if dir then CONTROL[dir] = value end
                            end))
                        end
                        table.insert(flyState.conns, RunService.Heartbeat:Connect((function()
                            if not flyState.flying or not bv.Parent then return end
                            local cam     = workspace.CurrentCamera
                            local moveDir = cam.CFrame.LookVector  * (CONTROL.F - CONTROL.B)
                                          + cam.CFrame.RightVector * (CONTROL.R - CONTROL.L)
                                          + Vector3.new(0, 1, 0)   * (CONTROL.U - CONTROL.D)
                            bv.Velocity = if moveDir.Magnitude > 0 then moveDir.Unit * flyState.speed else Vector3.zero
                            bg.CFrame   = cam.CFrame
                        end)))
                    else
                        local ok, cm = pcall(function()
                            return require(LocalPlayer.PlayerScripts:WaitForChild("PlayerModule"):WaitForChild("ControlModule"))
                        end)
                        table.insert(flyState.conns, RunService.RenderStepped:Connect((function()
                            if not flyState.flying or not bv.Parent then return end
                            local h = getHumanoid()
                            if not h then return end
                            local cam = workspace.CurrentCamera
                            bg.CFrame = cam.CFrame
                            local dir = (ok and cm) and cm:GetMoveVector()
                                     or Vector3.new(h.MoveDirection.X, 0, -h.MoveDirection.Z)
                            local moveDir = Vector3.zero
                            if dir.Magnitude > 0 then
                                local flat  = Vector3.new(cam.CFrame.LookVector.X,  0, cam.CFrame.LookVector.Z).Unit
                                local rflat = Vector3.new(cam.CFrame.RightVector.X, 0, cam.CFrame.RightVector.Z).Unit
                                moveDir = rflat * dir.X - flat * dir.Z
                            end
                            bv.Velocity = if moveDir.Magnitude > 0 then moveDir.Unit * flyState.speed else Vector3.zero
                        end)))
                    end
                    return true
                end
                if not attach() then
                    flyState.flying = false
                    warn("[Fly] Character not ready")
                    return
                end
                flyState.charConn = LocalPlayer.CharacterAdded:Connect(function()
                    task.wait(1)
                    if flyState.flying then attach() end
                end)
            end,
        })
        PlayerSection:AddInput({
            Title    = "Fly Speed",
            Default  = "50",
            NoSave   = true,
            Callback = function(val)
                flyState.speed = math.clamp(tonumber(val) or 50, 1, 500)
            end,
        })
        local noclipState = { enabled = false, conns = {}, parts = {} }
        PlayerSection:AddToggle({
            Title    = "No Clip",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                noclipState.enabled = on
                for _, c in ipairs(noclipState.conns) do pcall(function() c:Disconnect() end) end
                noclipState.conns = {}
                if not on then
                    for _, part in ipairs(noclipState.parts) do
                        if part.Parent then pcall(function() part.CanCollide = true end) end
                    end
                    table.clear(noclipState.parts)
                    return
                end
                local function collect(char)
                    table.clear(noclipState.parts)
                    if not char then return end
                    for _, part in ipairs(char:GetDescendants()) do
                        if part:IsA("BasePart") then table.insert(noclipState.parts, part) end
                    end
                    table.insert(noclipState.conns, char.DescendantAdded:Connect(function(desc)
                        if desc:IsA("BasePart") then table.insert(noclipState.parts, desc) end
                    end))
                end
                collect(getChar())
                table.insert(noclipState.conns, LocalPlayer.CharacterAdded:Connect(function(char)
                    task.wait(0.5)
                    if noclipState.enabled then collect(char) end
                end))
                table.insert(noclipState.conns, RunService.Stepped:Connect((function()
                    if not noclipState.enabled then return end
                    local parts = noclipState.parts
                    for i = #parts, 1, -1 do
                        local part = parts[i]
                        if part.Parent then part.CanCollide = false else table.remove(parts, i) end
                    end
                end)))
            end,
        })
        local _antiLava = { conns = {}, guards = {} }
        local LavaCS = game:GetService("CollectionService")
        local function lavaDisable(part)
            if not part:IsA("BasePart") or _antiLava.guards[part] then return end
            part.CanTouch = false
            _antiLava.guards[part] = part:GetPropertyChangedSignal("CanTouch"):Connect(function()
                if part.CanTouch then part.CanTouch = false end
            end)
        end
        local function lavaForget(part)
            local guard = _antiLava.guards[part]
            if guard then
                guard:Disconnect()
                _antiLava.guards[part] = nil
            end
        end
        local antiLavaToggle = PlayerSection:AddToggle({
            Title    = "Anti Lava Kill",
            Default  = true,
            NoSave   = true,
            Callback = function(on)
                for _, conn in ipairs(_antiLava.conns) do conn:Disconnect() end
                table.clear(_antiLava.conns)
                for part, guard in pairs(_antiLava.guards) do
                    guard:Disconnect()
                    part.CanTouch = true
                end
                table.clear(_antiLava.guards)
                if not on then
                    Library:MakeNotify({ Title = "Anti Lava Kill", Description = "Disabled.", Delay = 2 })
                    return
                end
                table.insert(_antiLava.conns, LavaCS:GetInstanceAddedSignal("KillBrick"):Connect(lavaDisable))
                table.insert(_antiLava.conns, LavaCS:GetInstanceRemovedSignal("KillBrick"):Connect(lavaForget))
                for _, part in ipairs(LavaCS:GetTagged("KillBrick")) do lavaDisable(part) end
                Library:MakeNotify({ Title = "Anti Lava Kill", Description = "Active!", Delay = 2 })
            end,
        })
        antiLavaToggle:SetValue(true)
    end
