        local function _isExtreme()
            return _potato.style == "Extreme"
        end
        local function _tset(obj, prop, val)
            pcall(function() obj[prop] = val end)
        end
        local function _trackThread(th)
            local list = _potato.threads
            for i = #list, 1, -1 do
                local t = list[i]
                if not t or coroutine.status(t) == "dead" then table.remove(list, i) end
            end
            if th then list[#list + 1] = th end
            return th
        end
        local function _stopThreads()
            local list = _potato.threads
            for i = #list, 1, -1 do
                local th = list[i]
                list[i] = nil
                if th and coroutine.status(th) ~= "dead" then
                    pcall(task.cancel, th)
                end
            end
        end
        local function _budgetedEach(items, budget, fn)
            local t0 = os.clock()
            for _, item in ipairs(items) do
                if not _potato.enabled then return end
                pcall(fn, item)
                if (os.clock() - t0) >= budget then
                    RunService.Heartbeat:Wait()
                    if not _potato.enabled then return end
                    t0 = os.clock()
                end
            end
        end
        _potato.vfxFolder      = RS:FindFirstChild("VFX")
        _potato.cosmeticFolder = workspace:FindFirstChild("CosmeticFolder")
        local function hookTimeController()
            if _potato.timeController then return end
            local ok, tc = pcall(function()
                return cachedRequire(RS.Controllers.ClientTimeController)
            end)
            if not ok or not tc then return end
            _potato.timeController     = tc
            _potato.origUpdateLighting = rawget(tc, "_updateLighting")
            _potato.origTweenTime      = rawget(tc, "_tweenTime")
            pcall(function() _G._PotatoBlockUpdateLighting = true end)
            if _potato.origTweenTime then
                tc._tweenTime = function(self, p1)
                    if _potato.enabled then Lighting.ClockTime = 14; return end
                    return _potato.origTweenTime(self, p1)
                end
            end
            if tc.NightTimeChanged then
                pcall(function() tc.NightTimeChanged:DisconnectAll() end)
            end
        end
        local function unhookTimeController()
            if not _potato.timeController then return end
            pcall(function() _G._PotatoBlockUpdateLighting = nil end)
            if _potato.origTweenTime then
                _potato.timeController._tweenTime = _potato.origTweenTime
            end
            _potato.origUpdateLighting = nil
            _potato.origTweenTime      = nil
            _potato.timeController     = nil
        end
        local function hookAvatarController()
            if _potato.origBuildRig then return end
            local ok, ac = pcall(function()
                return cachedRequire(RS.Controllers.AvatarController)
            end)
            if not ok or not ac then return end
            _potato.avatarController = ac
            _potato.origBuildRig     = ac.BuildRig
            ac.BuildRig = function(self, p2, p3, p4)
                local cam  = Instance.new("Camera")
                cam.Parent = p3
                local stub      = Instance.new("Model")
                stub.Name       = "PotatoRigStub"
                stub.Parent     = p3
                return cam, stub
            end
            _potato.origAvatarRender = ac.Render
            ac.Render = function() return end
            pcall(function()
                local avatarGui = LocalPlayer.PlayerGui:FindFirstChild("Avatar")
                if not avatarGui then return end
                for _, vf in ipairs(avatarGui:GetDescendants()) do
                    if vf:IsA("ViewportFrame") then vf.Visible = false end
                end
            end)
        end
        local function unhookAvatarController()
            if not _potato.origBuildRig then return end
            if _potato.avatarController then
                if _potato.origBuildRig     then _potato.avatarController.BuildRig = _potato.origBuildRig     end
                if _potato.origAvatarRender then _potato.avatarController.Render   = _potato.origAvatarRender end
            end
            pcall(function()
                local avatarGui = LocalPlayer.PlayerGui:FindFirstChild("Avatar")
                if not avatarGui then return end
                for _, vf in ipairs(avatarGui:GetDescendants()) do
                    if vf:IsA("ViewportFrame") then vf.Visible = true end
                end
            end)
            _potato.avatarController = nil
            _potato.origBuildRig     = nil
            _potato.origAvatarRender = nil
        end
        local function hookHaloController()
            if _potato.origHaloRender then return end
            local ok, hc = pcall(function()
                return cachedRequire(RS.Controllers.HaloReplicationController)
            end)
            if not ok or not hc then return end
            _potato.haloController = hc
            _potato.origHaloRender = hc.Render
            hc.Render = function() return end
        end
        local function unhookHaloController()
            if not _potato.origHaloRender then return end
            if _potato.haloController then
                _potato.haloController.Render = _potato.origHaloRender
            end
            _potato.haloController = nil
            _potato.origHaloRender = nil
        end
        local function hookGooeyParticles()
            if _potato.origGooeyEmit then return end
            local RF = game:GetService("ReplicatedFirst")
            local ok, gp = pcall(function()
                return cachedRequire(RF.GAME.GooeyParticles)
            end)
            if not ok or not gp then return end
            _potato.gooey           = gp
            _potato.origGooeyEmit   = gp.Emit
            _potato.origGooeyCreate = gp.CreateEmitter
            gp.Emit = function() return end
            gp.CreateEmitter = function()
                local emitter = {
                    emitter = nil, container = Instance.new("Frame"), props = {},
                    SetEnabled = function() return end,
                }
                emitter.Destroy = function()
                    if emitter.container then
                        emitter.container:Destroy()
                        emitter.container = nil
                    end
                    table.clear(emitter.props)
                end
                return emitter
            end
        end
        local function unhookGooeyParticles()
            if not _potato.origGooeyEmit then return end
            if _potato.gooey then
                _potato.gooey.Emit          = _potato.origGooeyEmit
                _potato.gooey.CreateEmitter = _potato.origGooeyCreate
            end
            _potato.gooey = nil _potato.origGooeyEmit = nil _potato.origGooeyCreate = nil
        end
        local function hookParticleEmitter()
            if _potato.origEmitParticles then return end
            local ok, pm = pcall(function()
                return cachedRequire(RS.Modules.ParticleEmitter)
            end)
            if not ok or not pm then return end
            _potato.particleEmitterMod  = pm
            _potato.origEmitParticles   = pm.emitParticles
            _potato.origEmitParticlesAt = pm.emitParticlesAt
            _potato.origEmitContainer   = pm.emitContainer
            pm.emitParticles   = function() return nil end
            pm.emitParticlesAt = function() return nil end
            pm.emitContainer   = function() return 0 end
        end
        local function unhookParticleEmitter()
            if not _potato.origEmitParticles then return end
            if _potato.particleEmitterMod then
                _potato.particleEmitterMod.emitParticles   = _potato.origEmitParticles
                _potato.particleEmitterMod.emitParticlesAt = _potato.origEmitParticlesAt
                _potato.particleEmitterMod.emitContainer   = _potato.origEmitContainer
            end
            _potato.particleEmitterMod  = nil
            _potato.origEmitParticles   = nil
            _potato.origEmitParticlesAt = nil
            _potato.origEmitContainer   = nil
        end
        local function hookFireflyController()
            if _potato.fireflyHooked then return end
            local ok, fc = pcall(function()
                return cachedRequire(RS.Controllers.FireflyController)
            end)
            if not ok or not fc then return end
            _potato.fireflyMod       = fc
            _potato.origFireflyStart = fc.Start
            fc.Start = function() return end
            pcall(function() RunService:UnbindFromRenderStep("UpdateFireflies") end)
            _potato.fireflyHooked = true
        end
        local function unhookFireflyController()
            if not _potato.fireflyHooked then return end
            if _potato.fireflyMod and _potato.origFireflyStart then
                _potato.fireflyMod.Start = _potato.origFireflyStart
            end
            _potato.fireflyMod = nil _potato.origFireflyStart = nil _potato.fireflyHooked = false
        end
        local function _muteSound(obj)
            obj:Stop()
            obj.Volume             = 0
            obj.RollOffMaxDistance = 0
        end
        local function killSoundsInContainer(container)
            for _, obj in ipairs(container:GetDescendants()) do
                if obj:IsA("Sound") then pcall(_muteSound, obj) end
            end
        end
        local function startSoundKill()
            pcall(function() SoundService.AmbientReverb = E_NOREVRB end)
            pcall(function() SoundService.RespectFilteringEnabled = true end)
            pcall(killSoundsInContainer, SoundService)
            if LocalPlayer.Character then
                pcall(killSoundsInContainer, LocalPlayer.Character)
            end
        end
        local function stopSoundKill()
            for _, c in ipairs(_potato.soundConns) do
                pcall(function() c:Disconnect() end)
            end
            table.clear(_potato.soundConns)
        end
        local function getRoot(player)
            local char = player.Character
            if not char then return nil end
            return char:FindFirstChild("HumanoidRootPart")
        end
        local function getLocalRoot()
            local char = LocalPlayer.Character
            if not char then return nil end
            return char:FindFirstChild("HumanoidRootPart")
        end
        local function setDetail(player, level)
            if _potato.lodLevel[player] == level then return end
            local char = player.Character
            if not char then return end
            _potato.lodLevel[player] = level
            pcall(function()
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then
                    if level == "full" then
                        hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Subject
                        hum.HealthDisplayType   = Enum.HumanoidHealthDisplayType.DisplayWhenDamaged
                    else
                        hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                        hum.HealthDisplayType   = Enum.HumanoidHealthDisplayType.AlwaysHide
                    end
                end
                local t = level == "full" and 0 or level == "low" and 0.5 or 1
                for _, part in ipairs(char:GetChildren()) do
                    if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                        part.LocalTransparencyModifier = t
                    elseif part:IsA("Accessory") then
                        local handle = part:FindFirstChild("Handle")
                        if handle then handle.LocalTransparencyModifier = t end
                    end
                end
            end)
        end
        local function resetAllLOD()
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then
                    _potato.lodLevel[p] = nil
                    pcall(setDetail, p, "full")
                end
            end
            table.clear(_potato.lodLevel)
        end
        local function runLOD()
            local localRoot = getLocalRoot()
            if not localRoot then return end
            local lp     = localRoot.Position
            local lx, lz = lp.X, lp.Z
            for i = #_potato.playerCache, 1, -1 do
                local player = _potato.playerCache[i]
                if not player or player.Parent == nil then
                    table.remove(_potato.playerCache, i)
                    continue
                end
                local root = getRoot(player)
                if not root then
                    setDetail(player, "hidden")
                else
                    local rp     = root.Position
                    local dx     = rp.X - lx
                    local dz     = rp.Z - lz
                    local distSq = dx * dx + dz * dz
                    if distSq <= C.LOD_NEAR_SQ then
                        setDetail(player, "full")
                    elseif distSq <= C.LOD_FAR_SQ then
                        setDetail(player, "low")
                    else
                        setDetail(player, "hidden")
                    end
                end
            end
        end
        local function startLOD()
            if _potato.lodThread then
                pcall(task.cancel, _potato.lodThread)
                _potato.lodThread = nil
            end
            table.clear(_potato.playerCache)
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then table.insert(_potato.playerCache, p) end
            end
            local conns = _potato.conns
            conns[#conns + 1] = Players.PlayerAdded:Connect(function(player)
                if not _potato.enabled then return end
                table.insert(_potato.playerCache, player)
            end)
            conns[#conns + 1] = Players.PlayerRemoving:Connect(function(player)
                _potato.lodLevel[player] = nil
                for i, p in ipairs(_potato.playerCache) do
                    if p == player then table.remove(_potato.playerCache, i); break end
                end
            end)
            local myGen = _potato.gen
            _potato.lodThread = task.spawn(function()
                while _potato.enabled and _potato.gen == myGen do
                    task.wait(C.LOD_INTERVAL)
                    if not _potato.enabled or _potato.gen ~= myGen then break end
                    pcall(runLOD)
                end
            end)
        end
        local function stopLOD()
            if _potato.lodThread then
                pcall(task.cancel, _potato.lodThread)
                _potato.lodThread = nil
            end
            table.clear(_potato.playerCache)
            resetAllLOD()
        end
        local _destroyOne = function(inst) inst:Destroy() end
        local function purgeVFXFolder()
            if not _potato.vfxFolder then
                _potato.vfxFolder = RS:FindFirstChild("VFX")
                if not _potato.vfxFolder then return end
            end
            local folder = _potato.vfxFolder
            _trackThread(task.spawn(function()
                _budgetedEach(folder:GetChildren(), C.DRAIN_BUDGET, _destroyOne)
            end))
        end
        local function purgeWorkspaceVFX()
            local wVFX = workspace:FindFirstChild("VFX")
            if not wVFX then return end
            _trackThread(task.spawn(function()
                _budgetedEach(wVFX:GetChildren(), C.DRAIN_BUDGET, _destroyOne)
            end))
        end
        local function destroyWeather()
            for _, obj in ipairs(workspace:GetChildren()) do
                if C.WEATHER_NAMES[obj.Name] then pcall(function() obj:Destroy() end) end
            end
            local char = LocalPlayer.Character
            if char then
                for _, obj in ipairs(char:GetChildren()) do
                    if C.WEATHER_NAMES[obj.Name] then pcall(function() obj:Destroy() end) end
                end
            end
        end
        local function _hideTagged(obj)
            if not obj or not obj:IsDescendantOf(game) then return end
            pcall(function() obj:SetAttribute("ClientAnimationState", "Hide") end)
            if obj:IsA("BasePart") then
                pcall(function() obj.Transparency = 1 obj.CastShadow = false end)
                return
            end
            if obj:IsA("Model") then
                for _, d in ipairs(obj:GetDescendants()) do
                    if d:IsA("BasePart") then
                        pcall(function() d.Transparency = 1 d.CastShadow = false end)
                    end
                end
                return
            end
            if obj:IsA("GuiObject") then pcall(function() obj.Visible = false end) end
            for _, d in ipairs(obj:GetDescendants()) do
                if d:IsA("GuiObject") then pcall(function() d.Visible = false end) end
            end
        end
        local function refreshTagHiding()
            for _, tagName in ipairs(C.TAG_NAMES_TO_KILL) do
                local ok, tagged = pcall(function() return CS:GetTagged(tagName) end)
                if ok and tagged then
                    for _, obj in ipairs(tagged) do pcall(_hideTagged, obj) end
                end
            end
        end
        local function stopTagObservers()
            for _, c in ipairs(_potato.tagConns) do
                pcall(function() c:Disconnect() end)
            end
            table.clear(_potato.tagConns)
        end
        local function killTagObservers()
            stopTagObservers()
            refreshTagHiding()
            for _, tagName in ipairs(C.TAG_NAMES_TO_KILL) do
                local ok, sig = pcall(function() return CS:GetInstanceAddedSignal(tagName) end)
                if ok and sig then
                    _potato.tagConns[#_potato.tagConns + 1] = sig:Connect(function(obj)
                        if not _potato.enabled then return end
                        task.defer(function()
                            if _potato.enabled then pcall(_hideTagged, obj) end
                        end)
                    end)
                end
            end
        end
        local function _isVFXPart(obj)
            local p = obj.Parent
            if not p then return false end
            if C.VFX_PART_PARENTS[p.Name] then return true end
            local gp = p.Parent
            if gp and C.VFX_PART_PARENTS[gp.Name] then return true end
            return false
        end
        local function _hideMesh(obj)
            obj.Transparency              = 1
            obj.LocalTransparencyModifier = 1
            obj.CastShadow                = false
            obj.Reflectance               = 0
            if obj:IsA("MeshPart") then obj.TextureID = EMPTYTEX end
            pcall(function() obj.Size = ZERO_SIZE end)
            for _, child in ipairs(obj:GetChildren()) do
                local ccn = child.ClassName
                if ccn == "SpecialMesh" or ccn == "BlockMesh" or ccn == "CylinderMesh"
                    or ccn == "SurfaceAppearance" or ccn == "Decal" or ccn == "Texture" then
                    pcall(function() child:Destroy() end)
                end
            end
        end
        local function _flattenPart(obj)
            obj.Material    = E_PLASTIC
            obj.CastShadow  = false
            obj.Reflectance = 0
            for i = 1, 6 do obj[SURFACES[i]] = E_SMOOTH end
            if _isExtreme() then obj.Color = WHITE end
        end
        local function _isHeldCosmetic(obj, char)
            local node = obj
            while node and node ~= char do
                if node.Name:sub(1, 3) == "!!!" then return true end
                node = node.Parent
            end
            return false
        end
        local function _isFunctionalPart(obj)
            if obj:IsA("SpawnLocation") then return true end
            for _, ch in ipairs(obj:GetChildren()) do
                local ccn = ch.ClassName
                if C.KEEP_VISIBLE[ccn] then return true end
                if ccn == "Attachment" then
                    for _, sub in ipairs(ch:GetChildren()) do
                        if C.KEEP_VISIBLE[sub.ClassName] then return true end
                    end
                end
            end
            return false
        end
        local function _isLandscape(obj)
            local size = obj.Size
            local area = size.X * size.Z
            if area >= C.GROUND_FOOTPRINT then return true end
            if area >= C.GROUND_THICK_FOOTPRINT and size.Y >= C.GROUND_THICKNESS then return true end
            if size.Y >= C.GROUND_HEIGHT and area >= C.GROUND_TALL_FOOTPRINT then return true end
            local own = obj.Name:lower()
            for i = 1, #C.GROUND_NAMES do
                if own:find(C.GROUND_NAMES[i], 1, true) then return true end
            end
            return false
        end
        local function _hidePart(obj)
            _potato.hiddenParts[obj]      = obj.Transparency
            obj.Transparency              = 1
            obj.LocalTransparencyModifier = 1
            obj.CastShadow                = false
            obj.Reflectance               = 0
            obj.Material                  = E_PLASTIC
        end
        local function _optimizeObj(obj)
            if not obj or _potato.processed[obj] then return end
            local cn = obj.ClassName
            if C.DESTROY_ALWAYS[cn] then
                _potato.processed[obj] = true
                pcall(function() obj:Destroy() end)
                return
            end
            if C.DESTROY_HEAVY[cn] then
                _potato.processed[obj] = true
                pcall(function() obj:Destroy() end)
                return
            end
            if cn == "Sound" then
                _potato.processed[obj] = true
                pcall(_muteSound, obj)
                return
            end
            if not C.PART_CLASSES[cn] then return end
            local ownChar = LocalPlayer.Character
            if ownChar and obj:IsDescendantOf(ownChar)
                and not _isHeldCosmetic(obj, ownChar) then return end
            _potato.processed[obj] = true
            if _isVFXPart(obj) then
                pcall(function() obj:Destroy() end)
                return
            end
            if C.MESH_CLASSES[cn] then
                pcall(_hideMesh, obj)
                return
            end
            if not _potato.floorKeep[obj]
                and not _isFunctionalPart(obj) and not _isLandscape(obj) then
                pcall(_hidePart, obj)
                return
            end
            pcall(_flattenPart, obj)
        end
        local _anim = {
            owners = {}, conns = {}, detached = {}, watch = nil, locked = setmetatable({}, { __mode = "k" }),
            showcases = {}, showcaseConn = nil,
        }
        local function _animOn() return next(_anim.owners) ~= nil end
        local SHOWCASE_TAG = "EmoteCrateShowcase"
        local function _muteShowcase(obj)
            _anim.showcases[obj] = true
            CS:RemoveTag(obj, SHOWCASE_TAG)
        end
        local function _lockAnimator(an)
            if _anim.locked[an] then return end
            _anim.locked[an] = true
            local hum = an.Parent
            local rig = hum and hum.Parent
            if rig and rig == LocalPlayer.Character then
                for _, t in ipairs(an:GetPlayingAnimationTracks()) do pcall(function() t:Stop(0) end) end
                task.spawn(function()
                    local animate = rig:WaitForChild("Animate", 5)
                    if animate and _animOn() then animate.Disabled = true end
                end)
                return
            end
            if hum and hum:IsA("Humanoid") and rig and Players:GetPlayerFromCharacter(rig) then
                _anim.detached[#_anim.detached + 1] = { an, hum }
                an.Parent = nil
                return
            end
            for _, t in ipairs(an:GetPlayingAnimationTracks()) do pcall(function() t:Stop(0) end) end
            _anim.conns[#_anim.conns + 1] = an.AnimationPlayed:Connect(function(track)
                task.defer(function()
                    if _animOn() then pcall(function() track:Stop(0) end) end
                end)
            end)
        end
        local function _setAnimStop(owner, on)
            _anim.owners[owner] = on and true or nil
            _animationsOff = _animOn()
            if _animOn() then
                if _anim.watch then return end
                pcall(function()
                    local ac = cachedRequire(RS.Controllers.AnimationController)
                    local play = ac.PlayAnimation
                    _anim.ctrl, _anim.ctrlPlay = ac, play
                    ac.PlayAnimation = function(self, name, wait)
                        if wait then return play(self, name, wait) end -- the caller blocks until it ends
                    end
                end)
                for _, obj in ipairs(CS:GetTagged(SHOWCASE_TAG)) do pcall(_muteShowcase, obj) end
                _anim.showcaseConn = CS:GetInstanceAddedSignal(SHOWCASE_TAG):Connect(function(obj)
                    task.defer(function()
                        if _animOn() then pcall(_muteShowcase, obj) end
                    end)
                end)
                _anim.watch = workspace.DescendantAdded:Connect(function(obj)
                    if not obj:IsA("Animator") then return end
                    task.defer(function()
                        if _animOn() and obj.Parent then pcall(_lockAnimator, obj) end
                    end)
                end)
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if obj:IsA("Animator") then pcall(_lockAnimator, obj) end
                end
            elseif _anim.watch then
                _anim.watch:Disconnect()
                _anim.watch = nil
                if _anim.ctrl then _anim.ctrl.PlayAnimation = _anim.ctrlPlay end
                _anim.ctrl, _anim.ctrlPlay = nil, nil
                pcall(function() LocalPlayer.Character.Animate.Disabled = false end)
                for _, c in ipairs(_anim.conns) do pcall(function() c:Disconnect() end) end
                table.clear(_anim.conns)
                for _, d in ipairs(_anim.detached) do
                    pcall(function() if d[2].Parent then d[1].Parent = d[2] end end)
                end
                table.clear(_anim.detached)
                table.clear(_anim.locked)
                _anim.showcaseConn:Disconnect()
                _anim.showcaseConn = nil
                for obj in pairs(_anim.showcases) do
                    pcall(function() if obj.Parent then CS:AddTag(obj, SHOWCASE_TAG) end end)
                end
                table.clear(_anim.showcases)
            end
        end
        local function _freezeRigObj(obj)
            if obj:IsA("BasePart") then
                obj.LocalTransparencyModifier = 1
                obj.Transparency, obj.CastShadow = 1, false
            elseif obj:IsA("Decal") or obj:IsA("Texture") then
                obj.Transparency = 1
            elseif obj:IsA("BillboardGui") or obj:IsA("SurfaceGui") or obj:IsA("ParticleEmitter")
                or obj:IsA("Trail") or obj:IsA("Beam") or obj:IsA("Light") then
                obj.Enabled = false
            elseif obj:IsA("Humanoid") then
                obj.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
            end
        end
        local function _freezeRig(model)
            if not model or model == LocalPlayer.Character or _potato.rigDone[model] then return end
            if not model:IsDescendantOf(workspace) then return end
            _potato.rigDone[model] = true
            for _, obj in ipairs(model:GetDescendants()) do pcall(_freezeRigObj, obj) end
            local conns = _potato.rigConns
            conns[#conns + 1] = model.DescendantAdded:Connect(function(obj)
                if _potato.enabled then pcall(_freezeRigObj, obj) end
            end)
        end
        local function _freezeAllRigs()
            local rigs = {}
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("Humanoid") or obj:IsA("AnimationController") then rigs[#rigs + 1] = obj.Parent end
            end
            _budgetedEach(rigs, C.DRAIN_BUDGET, _freezeRig) -- ~150 rigs take ~40 ms; spread over frames
        end
        local function _unfreezeRigs()
            for _, c in ipairs(_potato.rigConns) do pcall(function() c:Disconnect() end) end
            table.clear(_potato.rigConns)
            _potato.rigDone = setmetatable({}, { __mode = "k" })
        end
        local function _optimizeChar(char)
            if not char then return end
            if char ~= LocalPlayer.Character then return _freezeRig(char) end
            local extreme = _isExtreme()
            pcall(function()
                for _, obj in ipairs(char:GetDescendants()) do
                    local cn = obj.ClassName
                    if C.DESTROY_ALWAYS[cn] or C.DESTROY_HEAVY[cn] then
                        pcall(function() obj:Destroy() end)
                    elseif cn == "Sound" then
                        pcall(_muteSound, obj)
                    elseif obj:IsA("BasePart") then
                        obj.CastShadow  = false
                        obj.Reflectance = 0
                        obj.Material    = E_PLASTIC
                        for s = 1, 6 do obj[SURFACES[s]] = E_SMOOTH end
                        if obj.Name == "Head" then obj.Transparency = 1 end
                        obj.CanCollide = (obj.Name == "HumanoidRootPart" or obj.Name == "Head")
                        if extreme then obj.Color = WHITE end
                    elseif obj:IsA("Humanoid") then
                        obj.HealthDisplayDistance = 0
                        obj.NameDisplayDistance   = 0
                        for _, t in ipairs(obj:GetPlayingAnimationTracks()) do t:Stop(0) end
                    end
                end
            end)
        end
        local function _drainQueue()
            local qn = _potato.qn
            if qn == 0 then return end
            local q  = _potato.queue
            local t0 = os.clock()
            local i  = 0
            while i < qn do
                i += 1
                local obj = q[i]
                q[i] = nil
                if obj then _optimizeObj(obj) end
                if (os.clock() - t0) >= C.DRAIN_BUDGET then break end
            end
            if i < qn then
                local w = 0
                for j = i + 1, qn do
                    w += 1
                    q[w] = q[j]
                    q[j] = nil
                end
                _potato.qn = w
            else
                _potato.qn = 0
            end
        end
        local INTERESTING_CLASS = { Sound = true }
        for cn in pairs(C.DESTROY_ALWAYS) do INTERESTING_CLASS[cn] = true end
        for cn in pairs(C.DESTROY_HEAVY)  do INTERESTING_CLASS[cn] = true end
        for cn in pairs(C.PART_CLASSES)   do INTERESTING_CLASS[cn] = true end
        local function _onDescendantAdded(obj)
            if obj:IsA("Humanoid") or obj:IsA("AnimationController") then
                task.defer(function() if _potato.enabled then pcall(_freezeRig, obj.Parent) end end)
                return
            end
            if not INTERESTING_CLASS[obj.ClassName] then return end
            if _potato.cosmeticFolder and obj:IsDescendantOf(_potato.cosmeticFolder) then
                return
            end
            local qn = _potato.qn
            if qn >= C.QUEUE_CAP then
                _potato.rescanWanted = true
                return
            end
            qn += 1
            _potato.qn        = qn
            _potato.queue[qn] = obj
        end
        local function _startDescendantWatcher()
            if _potato.descendantConn then return end
            _potato.qn = 0
            table.clear(_potato.queue)
            _potato.descendantConn = workspace.DescendantAdded:Connect(function(obj)
                if not _potato.enabled then return end
                pcall(_onDescendantAdded, obj)
            end)
            _potato.drainConn = RunService.Heartbeat:Connect(function()
                if not _potato.enabled then return end
                if _potato.qn == 0 then return end
                pcall(_drainQueue)
            end)
        end
        local function _stopDescendantWatcher()
            if _potato.descendantConn then
                _potato.descendantConn:Disconnect()
                _potato.descendantConn = nil
            end
            if _potato.drainConn then
                _potato.drainConn:Disconnect()
                _potato.drainConn = nil
            end
            _potato.qn = 0
            table.clear(_potato.queue)
        end
        local function _startScan(myGen, onDone)
            local myToken     = _potato.scanToken + 1
            _potato.scanToken = myToken
            _trackThread(task.spawn(function()
                local stack = { workspace }
                local sn    = 1
                while sn > 0 do
                    if not _potato.enabled or _potato.gen ~= myGen then break end
                    if _potato.scanToken ~= myToken then break end
                    local t0 = os.clock()
                    repeat
                        local node = stack[sn]
                        stack[sn] = nil
                        sn -= 1
                        if node then
                            local ok, kids = pcall(node.GetChildren, node)
                            if ok and kids then
                                for k = 1, #kids do
                                    sn += 1
                                    stack[sn] = kids[k]
                                end
                            end
                            _optimizeObj(node)
                        end
                    until sn == 0 or (os.clock() - t0) >= C.WALK_BUDGET
                    RunService.Heartbeat:Wait()
                end
                if onDone and _potato.enabled and _potato.gen == myGen
                    and _potato.scanToken == myToken then
                    pcall(onDone)
                end
            end))
        end
        local function _applyLighting()
            _tset(Lighting, "GlobalShadows", false)
            _tset(Lighting, "EnvironmentDiffuseScale", 0)
            _tset(Lighting, "EnvironmentSpecularScale", 0)
            _tset(Lighting, "ShadowSoftness", 0)
            _tset(Lighting, "Technology", E_LEGACY)
            _tset(Lighting, "FogEnd", 100000)
            _tset(Lighting, "FogStart", 0)
            _tset(Lighting, "ClockTime", 14)
            if _isExtreme() then
                _tset(Lighting, "Brightness", 2)
                _tset(Lighting, "OutdoorAmbient", WHITE)
                _tset(Lighting, "Ambient", WHITE)
                _tset(Lighting, "ExposureCompensation", 1)
            end
            for _, c in ipairs(Lighting:GetChildren()) do
                if C.POST_FX[c.ClassName] then
                    _tset(c, "Enabled", false)
                elseif c:IsA("Atmosphere") then
                    _tset(c, "Density", 0)
                    _tset(c, "Haze", 0)
                    _tset(c, "Glare", 0)
                elseif c:IsA("Sky") then
                    _tset(c, "StarCount", 0)
                    _tset(c, "SunAngularSize", 0)
                    _tset(c, "MoonAngularSize", 0)
                    _tset(c, "CelestialBodiesShown", false)
                end
            end
        end
        local function _applyWorldSettings()
            if Terrain then
                _tset(Terrain, "WaterWaveSize", 0)
                _tset(Terrain, "WaterWaveSpeed", 0)
                _tset(Terrain, "WaterReflectance", 0)
                _tset(Terrain, "WaterTransparency", 1)
                local clouds = Terrain:FindFirstChildOfClass("Clouds")
                if clouds then pcall(function() clouds:Destroy() end) end
            end
            _applyLighting()
            pcall(function()
                SoundService.AmbientReverb = E_NOREVRB
                SoundService:SetListener(E_LISTCAM)
            end)
            pcall(function()
                local rs = settings().Rendering
                rs.QualityLevel        = E_LVL1
                rs.MeshPartDetailLevel = E_MESH1
                rs.EditQualityLevel    = E_LVL1
            end)
            pcall(function()
                local ugs = UserSettings():GetService("UserGameSettings")
                ugs.SavedQualityLevel    = E_SAVEDQ1
                ugs.GraphicsQualityLevel = 1
            end)
            pcall(function()
                local cam = workspace.CurrentCamera
                if cam then cam.FieldOfView = 70 end
            end)
            _pushCoreGuiHide(Enum.CoreGuiType.PlayerList)
            _pushCoreGuiHide(Enum.CoreGuiType.EmotesMenu)
        end
        local function _disconnectCharConns()
            for _, c in ipairs(_potato.charConns) do
                pcall(function() c:Disconnect() end)
            end
            table.clear(_potato.charConns)
        end
        local function _attachCharConnections(char)
            _disconnectCharConns()
            table.insert(_potato.charConns, char.ChildAdded:Connect(function(child)
                if not _potato.enabled then return end
                if C.WEATHER_NAMES[child.Name] then
                    task.defer(function()
                        if child and child:IsDescendantOf(game) then
                            pcall(function() child:Destroy() end)
                        end
                    end)
                end
            end))
            task.delay(0.2, function()
                if not _potato.enabled then return end
                _optimizeChar(char)
                killTagObservers()
                destroyWeather()
                pcall(killSoundsInContainer, char)
            end)
        end
        local function _reoptimize(myGen)
            if not _potato.enabled or _potato.gen ~= myGen then return end
            pcall(_applyWorldSettings)
            pcall(destroyWeather)
            pcall(purgeVFXFolder)
            pcall(purgeWorkspaceVFX)
            pcall(refreshTagHiding)
            pcall(startSoundKill)
            if _potato.descendantConn == nil then _startDescendantWatcher() end
            _potato.processed = setmetatable({}, { __mode = "k" })
            _startScan(myGen, function()
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr.Character then task.defer(_optimizeChar, plr.Character) end
                end
            end)
        end
        local function _startScheduler()
            local myGen = _potato.gen
            _potato.schedThread = task.spawn(function()
                local tick = 0
                while _potato.enabled and _potato.gen == myGen do
                    task.wait(C.TICK_SECONDS)
                    if not _potato.enabled or _potato.gen ~= myGen then break end
                    tick += 1
                    if tick % C.REOPT_EVERY_TICKS == 0 then
                        _reoptimize(myGen)
                    elseif tick % C.PURGE_EVERY_TICKS == 0 then
                        pcall(purgeVFXFolder)
                        pcall(purgeWorkspaceVFX)
                        pcall(destroyWeather)
                    end
                end
                _potato.schedThread = nil
            end)
        end
        local function _potatoCleanup()
            for _, c in ipairs(_potato.conns) do pcall(function() c:Disconnect() end) end
            _potato.conns = {}
            _stopThreads()
            _disconnectCharConns()
            _unfreezeRigs()
            if _potato.schedThread then
                pcall(task.cancel, _potato.schedThread)
                _potato.schedThread = nil
            end
            _potato.processed   = setmetatable({}, { __mode = "k" })
            _potato.scanToken   = _potato.scanToken + 1
            _potato.qn          = 0
            table.clear(_potato.queue)
        end
        local function _setNativeLowPerformance(on)
            pcall(function()
                local data = getCachedReplionData()
                if data and data:Get({ "Settings", "Low Performance" }) == on then return end
                if not on and not _potato.nativeLowPerfByUs then return end
                local remote = NetEvents.RE_ChangeSetting
                if remote then
                    remote:FireServer("Low Performance", on)
                    _potato.nativeLowPerfByUs = on
                end
            end)
        end
        local function _potatoDisable()
            _setAnimStop("potato", false)
            _setNativeLowPerformance(false)
            stopLOD()
            stopTagObservers()
            stopSoundKill()
            unhookTimeController()
            unhookAvatarController()
            unhookGooeyParticles()
            unhookParticleEmitter()
            unhookFireflyController()
            unhookHaloController()
            _stopDescendantWatcher()
            _popCoreGuiHide(Enum.CoreGuiType.PlayerList)
            _popCoreGuiHide(Enum.CoreGuiType.EmotesMenu)
        end
        local _floorRayParams = RaycastParams.new()
        _floorRayParams.FilterType  = Enum.RaycastFilterType.Exclude
        _floorRayParams.IgnoreWater = true
        local _floorBoundsParams = OverlapParams.new()
        _floorBoundsParams.FilterType = Enum.RaycastFilterType.Exclude
        _floorBoundsParams.MaxParts   = 4000
        local function _unhideFloor(part)
            if not part or _potato.floorKeep[part] then return end
            _potato.floorKeep[part] = true
            local orig = _potato.hiddenParts[part]
            if orig then
                _potato.hiddenParts[part] = nil
                pcall(function()
                    part.Transparency              = orig
                    part.LocalTransparencyModifier = 0
                end)
            end
        end
        local function _guardFloor()
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            local pos = hrp.Position
            _floorRayParams.FilterDescendantsInstances = { char }
            local hit = workspace:Raycast(pos, FLOOR_RAY, _floorRayParams)
            if hit then _unhideFloor(hit.Instance) end
            local last = _potato.lastFloorPos
            if last and (pos - last).Magnitude < C.FLOOR_SWEEP_MOVE then return end
            _potato.lastFloorPos = pos
            _floorBoundsParams.FilterDescendantsInstances = { char }
            local footY  = pos.Y - 3
            local nearby = workspace:GetPartBoundsInRadius(pos, C.FLOOR_SWEEP_RADIUS, _floorBoundsParams)
            for i = 1, #nearby do
                local part = nearby[i]
                local top  = part.Position.Y + part.Size.Y * 0.5
                if top <= footY and (footY - top) <= C.FLOOR_SWEEP_MAX_DROP
                    and (part.Size.X * part.Size.Z) >= C.FLOOR_SWEEP_MIN_AREA then
                    _unhideFloor(part)
                end
            end
        end
        local function _startFloorGuard(myGen)
            _trackThread(task.spawn(function()
                while _potato.enabled and _potato.gen == myGen do
                    pcall(_guardFloor)
                    task.wait(C.FLOOR_GUARD_INTERVAL)
                end
            end))
        end
        local function _potatoEnable()
            local myGen = _potato.gen
            _startFloorGuard(myGen)
            _setNativeLowPerformance(true)
            hookTimeController()
            hookAvatarController()
            hookGooeyParticles()
            hookParticleEmitter()
            hookFireflyController()
            hookHaloController()
            _applyWorldSettings()
            startLOD()
            startSoundKill()
            destroyWeather()
            killTagObservers()
            _startDescendantWatcher()
            _startScheduler()
            _trackThread(task.spawn(_freezeAllRigs))
            _setAnimStop("potato", true)
            local conns = _potato.conns
            _potato.lastLocation = LocalPlayer:GetAttribute("LocationName")
            conns[#conns + 1] = LocalPlayer:GetAttributeChangedSignal("LocationName"):Connect(function()
                if not _potato.enabled or _potato.gen ~= myGen then return end
                local loc = LocalPlayer:GetAttribute("LocationName")
                if loc == _potato.lastLocation then return end
                _potato.lastLocation = loc
                _potato.rescanWanted = true
            end)
            _trackThread(task.spawn(function()
                while _potato.enabled and _potato.gen == myGen do
                    task.wait(3)
                    if not _potato.enabled or _potato.gen ~= myGen then break end
                    if _potato.rescanWanted then
                        _potato.rescanWanted = false
                        for _ = 1, 3 do
                            if not _potato.enabled or _potato.gen ~= myGen then break end
                            _potato.processed = setmetatable({}, { __mode = "k" })
                            _startScan(myGen)
                            task.wait(4)
                        end
                        pcall(destroyWeather)
                        pcall(refreshTagHiding)
                    end
                end
            end))
            conns[#conns + 1] = workspace.ChildAdded:Connect(function(child)
                if not _potato.enabled then return end
                if C.WEATHER_NAMES[child.Name] then
                    task.defer(function()
                        if child and child:IsDescendantOf(game) then
                            pcall(function() child:Destroy() end)
                        end
                    end)
                end
            end)
            conns[#conns + 1] = Players.PlayerAdded:Connect(function(plr)
                if not _potato.enabled then return end
                if plr.Character then task.defer(_optimizeChar, plr.Character) end
            end)
            conns[#conns + 1] = LocalPlayer.CharacterAdded:Connect(function(char)
                if not _potato.enabled then return end
                _attachCharConnections(char)
                if _potato.descendantConn == nil then _startDescendantWatcher() end
            end)
            if LocalPlayer.Character then
                _attachCharConnections(LocalPlayer.Character)
            end
            _trackThread(task.spawn(function()
                task.wait(1)
                if not _potato.enabled or _potato.gen ~= myGen then return end
                _startScan(myGen, function()
                    for _, plr in ipairs(Players:GetPlayers()) do
                        if plr.Character then task.defer(_optimizeChar, plr.Character) end
                    end
                end)
            end))
        end
        PerformanceSection:AddDropdown({
            Title    = "Potato Style",
            Options  = { "Balanced", "Extreme" },
            Default  = "Balanced",
            Callback = function(v)
                if v ~= "Balanced" and v ~= "Extreme" then return end
                if _potato.style == v then return end
                _potato.style = v
                if not _potato.enabled then return end
                _potato.gen = _potato.gen + 1
                local myGen = _potato.gen
                _potato.processed = setmetatable({}, { __mode = "k" })
                hookAvatarController()
                pcall(_applyWorldSettings)
                _startScan(myGen)
                Library:MakeNotify({
                    Title       = "FPS Booster",
                    Description = "Style: " .. v .. ". Turun dari Extreme butuh relog.",
                    Delay       = 3,
                })
            end,
        })
        PerformanceSection:AddToggle({
            Title    = "FPS Booster (Potato Mode)",
            Default  = false,
            Callback = function(on)
                _potato.enabled = on
                _potato.gen     = _potato.gen + 1
                _potatoCleanup()
                if not on then
                    _potatoDisable()
                    Library:MakeNotify({
                        Title       = "FPS Booster",
                        Description = "Dimatikan. Relog untuk kembalikan grafik.",
                        Delay       = 3,
                    })
                    return
                end
                _potatoEnable()
                Library:MakeNotify({
                    Title       = "FPS Booster",
                    Description = _potato.style == "Extreme"
                        and "Aktif (Extreme). Bangunan disembunyikan & sisanya diputihkan."
                        or  "Aktif (Balanced). Bangunan disembunyikan, warna dipertahankan.",
                    Delay       = 3,
                })
            end,
        })
        do
            local _potatoLite = {
                enabled     = false,
                gen         = 0,
                conns       = {},
                playerConns = {},
                processed   = setmetatable({}, { __mode = "k" }),
                queue       = table.create(C.QUEUE_CAP),
                qn          = 0,
                descConn    = nil,
                drainConn   = nil,
                scanToken   = 0,
                scanThread  = nil,
                loopThread  = nil,
            }
            local function _liteOptimizeObj(obj)
                if not obj then return end
                if _potato.processed[obj] then return end
                if _potatoLite.processed[obj] then return end
                local cn = obj.ClassName
                if C.DESTROY_ALWAYS[cn] then
                    _potatoLite.processed[obj] = true
                    pcall(function() obj:Destroy() end)
                    return
                end
                if not C.PART_CLASSES[cn] then return end
                _potatoLite.processed[obj] = true
                pcall(function()
                    obj.CastShadow  = false
                    obj.Reflectance = 0
                    if not C.MESH_CLASSES[cn] then
                        obj.Material = E_PLASTIC
                        for i = 1, 6 do obj[SURFACES[i]] = E_SMOOTH end
                    end
                end)
            end
            local function _liteOptimizeChar(char)
                if not char then return end
                pcall(function()
                    for _, obj in ipairs(char:GetDescendants()) do
                        if C.DESTROY_ALWAYS[obj.ClassName] then
                            pcall(function() obj:Destroy() end)
                        elseif obj:IsA("BasePart") then
                            obj.CastShadow  = false
                            obj.Reflectance = 0
                        elseif obj:IsA("Humanoid") then
                            obj.HealthDisplayDistance = 0
                            obj.NameDisplayDistance   = 0
                        end
                    end
                end)
            end
            local function _liteDrain()
                local qn = _potatoLite.qn
                if qn == 0 then return end
                local q  = _potatoLite.queue
                local t0 = os.clock()
                local i  = 0
                while i < qn do
                    i += 1
                    local obj = q[i]
                    q[i] = nil
                    if obj then _liteOptimizeObj(obj) end
                    if (os.clock() - t0) >= C.DRAIN_BUDGET then break end
                end
                if i < qn then
                    local w = 0
                    for j = i + 1, qn do
                        w += 1
                        q[w] = q[j]
                        q[j] = nil
                    end
                    _potatoLite.qn = w
                else
                    _potatoLite.qn = 0
                end
            end
            local function _liteCleanup()
                for _, c in ipairs(_potatoLite.conns) do
                    pcall(function() c:Disconnect() end)
                end
                _potatoLite.conns = {}
                for _, c in pairs(_potatoLite.playerConns) do
                    pcall(function() c:Disconnect() end)
                end
                _potatoLite.playerConns = {}
                if _potatoLite.descConn then
                    _potatoLite.descConn:Disconnect()
                    _potatoLite.descConn = nil
                end
                if _potatoLite.drainConn then
                    _potatoLite.drainConn:Disconnect()
                    _potatoLite.drainConn = nil
                end
                if _potatoLite.scanThread then
                    pcall(task.cancel, _potatoLite.scanThread)
                    _potatoLite.scanThread = nil
                end
                if _potatoLite.loopThread then
                    pcall(task.cancel, _potatoLite.loopThread)
                    _potatoLite.loopThread = nil
                end
                _potatoLite.processed   = setmetatable({}, { __mode = "k" })
                _potatoLite.scanToken   = _potatoLite.scanToken + 1
                _potatoLite.qn          = 0
                table.clear(_potatoLite.queue)
            end
            local function _liteApplyWorld()
                if _potato.enabled then return end
                if Terrain then
                    _tset(Terrain, "WaterWaveSize", 0)
                    _tset(Terrain, "WaterWaveSpeed", 0)
                    _tset(Terrain, "WaterReflectance", 0)
                    local clouds = Terrain:FindFirstChildOfClass("Clouds")
                    if clouds then pcall(function() clouds:Destroy() end) end
                end
                _tset(Lighting, "GlobalShadows", false)
                _tset(Lighting, "EnvironmentDiffuseScale", 0)
                _tset(Lighting, "EnvironmentSpecularScale", 0)
                _tset(Lighting, "ShadowSoftness", 0)
                _tset(Lighting, "Technology", E_LEGACY)
                _tset(Lighting, "FogEnd", 100000)
                for _, c in ipairs(Lighting:GetChildren()) do
                    if C.POST_FX[c.ClassName] then
                        _tset(c, "Enabled", false)
                    elseif c:IsA("Atmosphere") then
                        _tset(c, "Density", 0)
                        _tset(c, "Haze", 0)
                        _tset(c, "Glare", 0)
                    elseif c:IsA("Sky") then
                        _tset(c, "StarCount", 0)
                        _tset(c, "CelestialBodiesShown", false)
                    end
                end
                pcall(function()
                    SoundService.AmbientReverb = E_NOREVRB
                    SoundService:SetListener(E_LISTCAM)
                end)
                pcall(function()
                    local rs = settings().Rendering
                    rs.QualityLevel        = E_LVL1
                    rs.MeshPartDetailLevel = E_MESH1
                    rs.EditQualityLevel    = E_LVL1
                end)
                pcall(function()
                    local ugs = UserSettings():GetService("UserGameSettings")
                    ugs.SavedQualityLevel    = E_SAVEDQ1
                    ugs.GraphicsQualityLevel = 1
                end)
                pcall(function()
                    local cam = workspace.CurrentCamera
                    if cam then cam.FieldOfView = 70 end
                end)
                _pushCoreGuiHide(Enum.CoreGuiType.PlayerList)
                _pushCoreGuiHide(Enum.CoreGuiType.EmotesMenu)
            end
            local function _liteRunScan(myGen)
                local myToken         = _potatoLite.scanToken + 1
                _potatoLite.scanToken = myToken
                _potatoLite.processed = setmetatable({}, { __mode = "k" })
                _potatoLite.scanThread = task.spawn(function()
                    local stack = { workspace }
                    local sn    = 1
                    while sn > 0 do
                        if not _potatoLite.enabled or _potatoLite.gen ~= myGen then break end
                        if _potatoLite.scanToken ~= myToken then break end
                        local t0 = os.clock()
                        repeat
                            local node = stack[sn]
                            stack[sn] = nil
                            sn -= 1
                            if node then
                                local ok, kids = pcall(node.GetChildren, node)
                                if ok and kids then
                                    for k = 1, #kids do
                                        sn += 1
                                        stack[sn] = kids[k]
                                    end
                                end
                                _liteOptimizeObj(node)
                            end
                        until sn == 0 or (os.clock() - t0) >= C.WALK_BUDGET
                        RunService.Heartbeat:Wait()
                    end
                    _potatoLite.scanThread = nil
                    if not _potatoLite.enabled or _potatoLite.gen ~= myGen then return end
                    if _potatoLite.scanToken ~= myToken then return end
                    for _, plr in ipairs(Players:GetPlayers()) do
                        if plr.Character then task.defer(_liteOptimizeChar, plr.Character) end
                    end
                end)
            end
            PerformanceSection:AddToggle({
                Title    = "FPS Booster Lite (Scan Loop)",
                Default  = false,
                Callback = function(on)
                    _potatoLite.enabled = on
                    _potatoLite.gen     = _potatoLite.gen + 1
                    _liteCleanup()
                    _setAnimStop("lite", on)
                    if not on then
                        _popCoreGuiHide(Enum.CoreGuiType.PlayerList)
                        _popCoreGuiHide(Enum.CoreGuiType.EmotesMenu)
                        Library:MakeNotify({
                            Title       = "FPS Booster Lite",
                            Description = "Dimatikan. Relog untuk kembalikan grafik.",
                            Delay       = 3,
                        })
                        return
                    end
                    local myGen = _potatoLite.gen
                    _liteApplyWorld()
                    _potatoLite.descConn = workspace.DescendantAdded:Connect(function(obj)
                        if not _potatoLite.enabled or _potato.enabled then return end
                        local cn = obj.ClassName
                        if C.DESTROY_ALWAYS[cn] then
                            pcall(function() obj:Destroy() end)
                            return
                        end
                        if not C.PART_CLASSES[cn] then return end
                        local qn = _potatoLite.qn
                        if qn >= C.QUEUE_CAP then return end
                        qn += 1
                        _potatoLite.qn        = qn
                        _potatoLite.queue[qn] = obj
                    end)
                    _potatoLite.drainConn = RunService.Heartbeat:Connect(function()
                        if not _potatoLite.enabled or _potato.enabled then return end
                        if _potatoLite.qn == 0 then return end
                        pcall(_liteDrain)
                    end)
                    _potatoLite.loopThread = task.spawn(function()
                        task.wait(1)
                        while _potatoLite.enabled and _potatoLite.gen == myGen do
                            if not _potato.enabled then
                                pcall(_liteApplyWorld)
                                _liteRunScan(myGen)
                            end
                            task.wait(600)
                        end
                        _potatoLite.loopThread = nil
                    end)
                    local function watchPlayer(plr)
                        if _potatoLite.playerConns[plr] then return end
                        _potatoLite.playerConns[plr] = plr.CharacterAdded:Connect(function(char)
                            if not _potatoLite.enabled or _potato.enabled then return end
                            task.delay(0.2, function()
                                if _potatoLite.enabled and not _potato.enabled then
                                    _liteOptimizeChar(char)
                                end
                            end)
                        end)
                        if plr.Character and not _potato.enabled then
                            task.defer(_liteOptimizeChar, plr.Character)
                        end
                    end
                    for _, plr in ipairs(Players:GetPlayers()) do watchPlayer(plr) end
                    local conns = _potatoLite.conns
                    conns[#conns + 1] = Players.PlayerAdded:Connect(function(plr)
                        if not _potatoLite.enabled then return end
                        watchPlayer(plr)
                    end)
                    conns[#conns + 1] = Players.PlayerRemoving:Connect(function(plr)
                        local c = _potatoLite.playerConns[plr]
                        if c then
                            pcall(function() c:Disconnect() end)
                            _potatoLite.playerConns[plr] = nil
                        end
                    end)
                    local msg = _potato.enabled
                        and "Aktif! (Potato Mode aktif, scan tetap jalan.)"
                        or  "Aktif! Grafik diringankan."
                    Library:MakeNotify({ Title = "FPS Booster Lite", Description = msg, Delay = 3 })
                end,
            })
        end
        local BRIGHT_LIGHTING = {
