            Ambient                 = Color3.new(1, 1, 1),
            FogEnd                  = 9e9,
            ExposureCompensation    = 1,
            EnvironmentDiffuseScale = 1,
        }
        local BRIGHT_ATMOSPHERE = { Density = 0, Haze = 0, Glare = 0 }
        local function _brightWrite(obj, vals)
            if not obj or not vals then return end
            for k, v in pairs(vals) do pcall(function() obj[k] = v end) end
        end
        local function _brightRead(obj, vals)
            if not obj then return nil end
            local out = {}
            for k in pairs(vals) do pcall(function() out[k] = obj[k] end) end
            return out
        end
