        end
        local function _gameSettings()
            local ok, ugs = pcall(function() return UserSettings():GetService("UserGameSettings") end)
            if not ok or not ugs then return nil end
            if not pcall(function() return ugs.FramerateCap end) then return nil end
            return ugs
