        local function _setEngineCap(value)
            local ugs = _gameSettings()
            if not ugs then return false end
            return (pcall(function() ugs.FramerateCap = value end))
        end
        local function _applyFPSCap()
            if not _unlockFPS.enabled then return end
            local cap = _unlockFPS.cap
            if setfpscap then pcall(setfpscap, cap) end
            _setEngineCap(cap > 0 and cap or UNCAPPED)
        end
        PerformanceSection:AddToggle({
