        local _invLagFix = { enabled = false }
        local function setAbilityRefreshGate(shared, on)
            local gate = shared.ability
            if not on then
                if gate then
                    if gate.handler._fn == gate.wrapper then gate.handler._fn = gate.orig end
                    if gate.conn then pcall(function() gate.conn:Disconnect() end) end
                    shared.ability = nil
                end
                return true
            end
            if gate and gate.handler._fn == gate.wrapper then return true end
            local data = getCachedReplionData()
            local node = data and data._signals and data._signals._containers
            node = node and node.onChange and node.onChange.Inventory
            node = node and node.Items and node.Items.__signal
            local h = node and node._handlerListHead
            while h do
                local ok, src = pcall(debug.info, h._fn, "s")
                if ok and type(src) == "string" and src:find("AbilityUIController$") then break end
                h = h._next
            end
            if not h then return false end
            gate = { handler = h, orig = h._fn, dirty = false }
            gate.wrapper = function(...)
                local gui = LocalPlayer.PlayerGui:FindFirstChild("!!!! AbilityUI")
                if not gui or gui.Enabled then return gate.orig(...) end
                gate.dirty = true
                if gate.connGui ~= gui then
                    if gate.conn then pcall(function() gate.conn:Disconnect() end) end
                    gate.connGui = gui
                    gate.conn = gui:GetPropertyChangedSignal("Enabled"):Connect(function()
                        if gui.Enabled and gate.dirty then
                            gate.dirty = false
                            task.defer(gate.orig)
                        end
                    end)
                end
                return
            end
            h._fn = gate.wrapper
            shared.ability = gate
            return true
        end
        PerformanceSection:AddToggle({
            Title    = "Enhanced Lag Fix",
            Default  = false,
            Callback = function(on)
                if _invLagFix.enabled == on then return end
                local IU = nil
                pcall(function() IU = cachedRequire(ReplicatedStorage.Shared.ItemUtility) end)
                if type(IU) ~= "table" or type(IU.GetItemData) ~= "function" then
                    if on then
                        Library:MakeNotify({ Title = "Enhanced Lag Fix", Description = "ItemUtility tidak ditemukan.", Delay = 3 })
                    end
                    return
                end
                local shared = _G.__LynxInvLagFix
                if shared and not shared.patches then
                    if IU.GetItemData == shared.patched then IU.GetItemData = shared.orig end
                    shared = nil
                end
                if not shared then
                    local ID_GETTERS = {
                        "GetItemData", "GetBaitData", "GetPotionData", "GetVariantData", "GetEnchantData",
                        "GetFinisherData", "GetPetData", "GetPetEggData", "GetBoothData", "GetHaloData",
                        "GetCharmData", "GetEmoteData", "GetLanternData", "GetBoatData", "GetTotemData",
                    }
                    local LIST_GETTERS = {
                        "GetFish", "GetEnchantStones", "GetFishingRods", "GetGears", "GetTrophies", "GetEquipments",
                        "GetTotems", "GetCharms", "GetEmotes", "GetPets", "GetPetEggs", "GetLanterns", "GetBaits",
                        "GetBooths", "GetBoats", "GetVariants", "GetPotions", "GetHalos", "GetFinishers",
                    }
                    shared = { patches = {}, ability = nil }
                    for _, name in ipairs(ID_GETTERS) do
                        local orig = IU[name]
                        if type(orig) == "function" then
                            local cache = {}
                            shared.patches[name] = { orig = orig, patched = function(self, id)
                                local key = tonumber(id)
                                if type(id) ~= "string" and key then
                                    local hit = cache[key]
                                    if hit then return table.unpack(hit, 1, hit.n) end
                                    local res = table.pack(orig(self, id))
                                    if res[1] ~= nil then cache[key] = res end
                                    return table.unpack(res, 1, res.n)
                                end
                                return orig(self, id)
                            end }
                        end
                    end
                    for _, name in ipairs(LIST_GETTERS) do
                        local orig = IU[name]
                        if type(orig) == "function" then
                            local list
                            shared.patches[name] = { orig = orig, patched = function(self, ...)
                                if select("#", ...) > 0 then return orig(self, ...) end
                                if not list then
                                    local res = orig(self)
                                    if type(res) ~= "table" then return res end
                                    list = res
                                end
                                return table.clone(list) -- callers sort / trim their copy
                            end }
                        end
                    end
                    local origByType = IU.GetItemDataFromItemType
                    if type(origByType) == "function" then
                        local cache = {}
                        shared.patches.GetItemDataFromItemType = { orig = origByType, patched = function(itemType, id)
                            if type(id) ~= "number" then return origByType(itemType, id) end
                            local key = tostring(itemType) .. "\0" .. id
                            local hit = cache[key]
                            if hit then return hit end
                            hit = origByType(itemType, id)
                            if hit ~= nil then cache[key] = hit end
                            return hit
                        end }
                    end
                    _G.__LynxInvLagFix = shared
                end
                _invLagFix.enabled = on
                for name, p in pairs(shared.patches) do
                    if on then
                        IU[name] = p.patched
                    elseif IU[name] == p.patched then
                        IU[name] = p.orig
                    end
                end
                local abilityOk = false
                pcall(function() abilityOk = setAbilityRefreshGate(shared, on) end)
                local desc
                if not on then
                    desc = "Dimatikan, fungsi game dikembalikan."
                elseif abilityOk then
                    desc = "Aktif! Cache data item, rod, bait, potion, dll + refresh UI Ability dilewati saat tertutup."
                else
                    desc = "Aktif! Cache data item, rod, bait, potion, dll (hook UI Ability tidak ditemukan)."
                end
                Library:MakeNotify({ Title = "Enhanced Lag Fix", Description = desc, Delay = 2 })
            end,
        })
        do
            local GATED = { BagSize = true, LanternShopController = true, AbilityUIController = true }
            local PATHS = {
                { "onChange", "Inventory" }, { "onChange", "Inventory", "Items" },
                { "onArrayInsert", "Inventory", "Items" }, { "onArrayRemove", "Inventory", "Items" },
            }
            local FLUSH_EVERY = 10 -- keeps the bag counter (read by Auto Sell By Count) at most 10 s stale
            local HIDDEN_GUIS = { Inventory = true, Backpack = true } -- bag + hotbar; equips go through remotes
            local _hideInv = { enabled = false, gates = {}, dirty = {}, conns = {}, guis = {}, thread = nil }
            local function lockGui(gui)
                if not (HIDDEN_GUIS[gui.Name] and gui:IsA("ScreenGui")) or _hideInv.guis[gui] ~= nil then return end
                _hideInv.guis[gui] = gui.Enabled
                gui.Enabled = false
                _hideInv.conns[#_hideInv.conns + 1] = gui:GetPropertyChangedSignal("Enabled"):Connect(function()
                    if _hideInv.enabled and gui.Enabled then gui.Enabled = false end
                end)
            end
            local function flush()
                local pending = _hideInv.dirty
                _hideInv.dirty = {}
                for gate in pairs(pending) do task.spawn(pcall, gate.orig) end
            end
            local function release()
                for _, gate in ipairs(_hideInv.gates) do
                    if gate.handler._fn == gate.wrapper then gate.handler._fn = gate.orig end
                end
                table.clear(_hideInv.gates)
                for _, c in ipairs(_hideInv.conns) do pcall(function() c:Disconnect() end) end
                table.clear(_hideInv.conns)
                for gui, was in pairs(_hideInv.guis) do
                    if gui.Parent then gui.Enabled = was end
                end
                table.clear(_hideInv.guis)
                if _hideInv.thread then pcall(task.cancel, _hideInv.thread); _hideInv.thread = nil end
                flush()
            end
            local function hold()
                local pg = LocalPlayer.PlayerGui
                for _, gui in ipairs(pg:GetChildren()) do lockGui(gui) end
                _hideInv.conns[#_hideInv.conns + 1] = pg.ChildAdded:Connect(lockGui) -- respawn rebuilds
                local data = getCachedReplionData()
                local containers = data and data._signals and data._signals._containers
                if not containers then return 0 end
                for _, path in ipairs(PATHS) do
                    local node = containers
                    for _, key in ipairs(path) do node = node and node[key] end
                    local h = node and node.__signal and node.__signal._handlerListHead
                    while h do
                        local ok, src = pcall(debug.info, h._fn, "s")
                        local owner = ok and type(src) == "string" and src:match("([%w_]+)$")
                        if owner and GATED[owner] then
                            local gate = { handler = h, orig = h._fn }
                            gate.wrapper = function() _hideInv.dirty[gate] = true end -- bag is locked shut
                            h._fn = gate.wrapper
                            _hideInv.gates[#_hideInv.gates + 1] = gate
                        end
                        h = h._next
                    end
                end
                _hideInv.thread = task.spawn(function()
                    while _hideInv.enabled do
                        task.wait(FLUSH_EVERY)
                        if next(_hideInv.dirty) then flush() end
                    end
                end)
                return #_hideInv.gates
            end
            PerformanceSection:AddToggle({
                Title    = "Hide Inventory",
                Default  = false,
                Callback = function(on)
                    if _hideInv.enabled == on then return end
                    _hideInv.enabled = on
                    release()
                    if not on then
                        Library:MakeNotify({ Title = "Hide Inventory", Description = "Dimatikan, tas & hotbar kembali normal.", Delay = 2 })
                        return
                    end
                    local n = hold()
                    Library:MakeNotify({
                        Title       = "Hide Inventory",
                        Description = ("Aktif! Tas & hotbar disembunyikan, %d listener inventory ditunda."):format(n),
                        Delay       = 3,
                    })
                end,
            })
        end
        do
            local LISTENERS = { -- by source module, so the script's own listeners stay connected
                BaitCastVisual = "FishBaitVisual", BaitDestroyed = "FishBaitVisual", BaitSpawned = "WorldVisuals",
                CaughtFishVisual = "FishCaughtVisual", ["Pets/CaughtFishVisual"] = "FishCaughtVisual",
                PlayFishingEffect = "Effects", ReplicateTextEffect = "Effects",
            }
            local TEXTURE_PROP = { MeshPart = "TextureID", SpecialMesh = "TextureId", Decal = "Texture", Texture = "Texture" }
            local FX = { ParticleEmitter = true, Trail = true, Beam = true }
            local INVISIBLE = NumberSequence.new(1)
            local _ultra = { enabled = false, listeners = {} }
            local function cutCosmetics()
                for name, owner in pairs(LISTENERS) do
                    pcall(function()
                        for _, c in ipairs(getconnections(_G.EventResolver:GetRemoteEvent(name).OnClientEvent)) do
                            local ok, src = pcall(debug.info, c.Function, "s")
                            if ok and type(src) == "string" and src:match("([%w_]+)$") == owner then
                                c:Disable()
                                _ultra.listeners[#_ultra.listeners + 1] = c
                            end
                        end
                    end)
                end
                pcall(function()
                    local caught = cachedRequire(ReplicatedStorage.Controllers.FishingController.FishCaughtVisual)
                    _ultra.caught, _ultra.origCaught = caught, caught.playCaughtFishVisual
                    caught.playCaughtFishVisual = function() end
                end)
                local folder = workspace:FindFirstChild("CosmeticFolder")
                if folder then
                    folder.Parent = ReplicatedStorage
                    local standIn = Instance.new("Folder")
                    standIn.Name, standIn.Parent = "CosmeticFolder", workspace
                    _ultra.folder, _ultra.standIn = folder, standIn
                end
            end
            local function stripTexture(obj)
                local cn, prop = obj.ClassName, TEXTURE_PROP[obj.ClassName]
                if prop then
                    obj[prop] = ""
                elseif FX[cn] then
                    obj.Texture, obj.Transparency = "", INVISIBLE -- a bare particle would draw a white square
                elseif cn == "SurfaceAppearance" then
                    obj:Destroy()
                end
            end
            local function cutTextures()
                _worldStripped = true
                _ultra.watcher = workspace.DescendantAdded:Connect(function(obj)
                    local cn = obj.ClassName
                    if TEXTURE_PROP[cn] or FX[cn] or cn == "SurfaceAppearance" then
                        task.defer(function()
                            if _ultra.enabled then pcall(stripTexture, obj) end
                        end)
                    end
                end)
                _ultra.thread = task.spawn(function()
                    for _, root in ipairs({ workspace, ReplicatedStorage }) do
                        for i, obj in ipairs(root:GetDescendants()) do
                            pcall(stripTexture, obj)
                            if i % 2000 == 0 then task.wait() end
                        end
                    end
                    _ultra.thread = nil
                end)
            end
            local function freezeLighting()
                pcall(function()
                    local tc = cachedRequire(ReplicatedStorage.Controllers.ClientTimeController)
                    _ultra.time, _ultra.origProfile, _ultra.origLabels = tc, tc._getLightingProfile, tc._updateTextLabels
                    tc._getLightingProfile = function() end
                    tc._updateTextLabels = function() end -- the UI clock stops at its last value
                end)
                pcall(function()
                    local data = getCachedReplion().Client:GetReplion("Time")
                    local h = data._signals._containers.onChange.Time.__signal._handlerListHead
                    while h do
                        local ok, src = pcall(debug.info, h._fn, "s")
                        if ok and type(src) == "string" and src:find("ClientTimeController$") then
                            _ultra.handler, _ultra.origHandler = h, h._fn
                            h._fn = function() end
                            break
                        end
                        h = h._next
                    end
                end)
                local L = game:GetService("Lighting")
                pcall(function()
                    L.ClockTime, L.GlobalShadows, L.ShadowSoftness = 14, false, 0
                    L.EnvironmentDiffuseScale, L.EnvironmentSpecularScale = 0, 0
                    L.FogStart, L.FogEnd = 0, 100000
                end)
                for _, c in ipairs(L:GetChildren()) do
                    pcall(function()
                        if c:IsA("PostEffect") then
                            c.Enabled = false
                        elseif c:IsA("Atmosphere") then
                            c.Density, c.Haze, c.Glare, c.Offset = 0, 0, 0, 0
                        elseif c:IsA("Sky") then
                            c.StarCount, c.CelestialBodiesShown = 0, false
                        end
                    end)
                end
                pcall(function() workspace.Terrain:FindFirstChildOfClass("Clouds").Enabled = false end)
            end
            local function restore() -- textures and Lighting values stay as they are until a rejoin
                for _, c in ipairs(_ultra.listeners) do pcall(function() c:Enable() end) end
                table.clear(_ultra.listeners)
                if _ultra.caught then _ultra.caught.playCaughtFishVisual = _ultra.origCaught end
                if _ultra.standIn then _ultra.standIn:Destroy() end
                if _ultra.folder then _ultra.folder.Parent = workspace end
                if _ultra.watcher then _ultra.watcher:Disconnect() end
                if _ultra.thread then pcall(task.cancel, _ultra.thread) end
                if _ultra.time then
                    _ultra.time._getLightingProfile, _ultra.time._updateTextLabels = _ultra.origProfile, _ultra.origLabels
                end
                if _ultra.handler then _ultra.handler._fn = _ultra.origHandler end
                _ultra = { enabled = false, listeners = _ultra.listeners }
            end
            PerformanceSection:AddToggle({
                Title    = "Remove All Texture & Effect",
                Default  = false,
                Callback = function(on)
                    if _ultra.enabled == on then return end
                    if not on then
                        restore()
                        Library:MakeNotify({ Title = "Remove All Texture & Effect", Description = "Dimatikan. Rejoin untuk kembalikan tekstur & pencahayaan.", Delay = 3 })
                        return
                    end
                    _ultra.enabled = true
                    cutCosmetics()
                    cutTextures()
                    freezeLighting()
                    Library:MakeNotify({ Title = "Remove All Texture & Effect", Description = "Aktif! Efek, tekstur, waktu & langit dimatikan.", Delay = 3 })
                end,
            })
        end
        do
            local _ui = { enabled = false, conn = nil }
            local function strip(obj)
                if (obj:IsA("ImageLabel") or obj:IsA("ImageButton")) and obj.Image ~= "" then obj.Image = "" end
            end
            PerformanceSection:AddToggle({
                Title    = "Remove UI Icons",
                Default  = false,
                Callback = function(on)
                    if _ui.enabled == on then return end
                    _ui.enabled = on
                    local pg = LocalPlayer.PlayerGui
                    if not on then
                        if _ui.conn then _ui.conn:Disconnect(); _ui.conn = nil end
                        Library:MakeNotify({ Title = "Remove UI Icons", Description = "Dimatikan. Rejoin untuk kembalikan icon.", Delay = 3 })
                        return
                    end
                    for _, root in ipairs({ pg, workspace }) do
                        for _, obj in ipairs(root:GetDescendants()) do pcall(strip, obj) end
                    end
                    _ui.conn = pg.DescendantAdded:Connect(function(obj)
                        task.defer(function()
                            if _ui.enabled then pcall(strip, obj) end
                        end)
                    end)
                    Library:MakeNotify({ Title = "Remove UI Icons", Description = "Aktif! Semua icon UI game dihapus.", Delay = 3 })
                end,
            })
        end
    end
    do
        local NotificationSection = SettingsTab:AddSection("Notification Position")
        local customPosEnabled = false
        local currentAlign = "Tengah"
        local origState = nil
        local function updatePosition()
            local pg = LocalPlayer:FindFirstChild("PlayerGui")
            if not pg then return end
            local tn = pg:FindFirstChild("Text Notifications")
            if not tn then return end
            local frame = tn:FindFirstChild("Frame")
            if not frame then return end
            local layout = frame:FindFirstChildOfClass("UIListLayout")
            if not origState then
                origState = {
                    AnchorPoint = frame.AnchorPoint,
                    Position = frame.Position,
                    HorizontalAlignment = layout and layout.HorizontalAlignment or Enum.HorizontalAlignment.Center
                }
            end
            if not customPosEnabled then
                if origState then
                    frame.AnchorPoint = origState.AnchorPoint
                    frame.Position = origState.Position
                    if layout then layout.HorizontalAlignment = origState.HorizontalAlignment end
                end
                return
            end
            if currentAlign == "Kiri" then
                frame.AnchorPoint = Vector2.new(0, 0)
                frame.Position = UDim2.new(0, 5, 0, 110)
                if layout then layout.HorizontalAlignment = Enum.HorizontalAlignment.Left end
            elseif currentAlign == "Tengah" then
                frame.AnchorPoint = Vector2.new(0.5, 0)
                frame.Position = UDim2.new(0.5, 0, 0, 110)
                if layout then layout.HorizontalAlignment = Enum.HorizontalAlignment.Center end
            elseif currentAlign == "Kanan" then
                frame.AnchorPoint = Vector2.new(1, 0)
                frame.Position = UDim2.new(1, -5, 0, 110)
                if layout then layout.HorizontalAlignment = Enum.HorizontalAlignment.Right end
            end
        end
        NotificationSection:AddToggle({
            Title    = "Enable Custom Notification Position",
            Default  = false,
            Callback = function(v)
                customPosEnabled = v
                updatePosition()
            end,
        })
        NotificationSection:AddDropdown({
            Title    = "Select Position",
            Options  = {"Kiri", "Tengah", "Kanan"},
            Default  = "Tengah",
            Callback = function(v)
                currentAlign = v
                updatePosition()
            end,
        })
    end
    do
        local HideStatsSection = SettingsTab:AddSection("Hide Stats")
        local PREMIUM_CHAR = ""
        local VERIFY_CHAR  = ""
        local _hideStats = {
            enabled             = false,
            premiumLogo         = false,
            verifyLogo          = false,
            fakeName            = "LynX",
            fakeLevel           = "501",
            charConn            = nil,
            sysMsgHooked        = false,
            origSysMsg          = nil,
            otherFakeNames      = setmetatable({}, { __mode = "k" }),
            otherState          = setmetatable({}, { __mode = "k" }),
            playerAddedConn     = nil,
            playerRemovingConn  = nil,
        }
        local _localState = {
            origTexts = {},
            textConns = setmetatable({}, { __mode = "k" }),
            descConn  = nil,
        }
        local function _getBuiltName()
            local name = _hideStats.fakeName
            if _hideStats.premiumLogo then name = name .. PREMIUM_CHAR end
            if _hideStats.verifyLogo  then name = name .. VERIFY_CHAR  end
            return name
        end
        local function _escapePat(s)
            return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%1"))
        end
        local function _fakeNameForPlayer(player)
            if player == LocalPlayer then return _getBuiltName() end
            local cached = _hideStats.otherFakeNames[player]
            if cached then return cached end
            local fake = "Player" .. tostring(1000 + (player.UserId % 9000))
            _hideStats.otherFakeNames[player] = fake
            return fake
        end
        local function _hookSystemMessage()
            if _hideStats.sysMsgHooked then return end
            pcall(function()
                for _, obj in ipairs(game:GetService("ReplicatedStorage"):GetDescendants()) do
                    if obj:IsA("ModuleScript") and obj.Name == "SystemMessage" then
                        local sysMsg = require(obj)
                        if sysMsg and sysMsg._displaySystemMessage then
                            _hideStats.origSysMsg = sysMsg._displaySystemMessage
                            sysMsg._displaySystemMessage = function(self, message, ...)
                                if _hideStats.enabled and type(message) == "string" then
                                    for _, p in ipairs(Players:GetPlayers()) do
                                        local fake = _fakeNameForPlayer(p)
                                        for _, n in ipairs({ p.Name, p.DisplayName }) do
                                            if type(n) == "string" and #n > 2 then
                                                message = string.gsub(message, _escapePat(n), fake)
                                            end
                                        end
                                    end
                                end
                                return _hideStats.origSysMsg(self, message, ...)
                            end
                            _hideStats.sysMsgHooked = true
                        end
                        break
                    end
                end
            end)
        end
        local function _unhookSystemMessage()
            if not _hideStats.sysMsgHooked then return end
            pcall(function()
                for _, obj in ipairs(game:GetService("ReplicatedStorage"):GetDescendants()) do
                    if obj:IsA("ModuleScript") and obj.Name == "SystemMessage" then
                        local sysMsg = require(obj)
                        if sysMsg and _hideStats.origSysMsg then
                            sysMsg._displaySystemMessage = _hideStats.origSysMsg
                        end
                        break
                    end
                end
            end)
            _hideStats.sysMsgHooked = false
            _hideStats.origSysMsg = nil
        end
        local function _findOverhead(char)
            if not char then return nil end
            for _, partName in ipairs({ "Head", "HumanoidRootPart" }) do
                local part = char:FindFirstChild(partName)
                local overhead = part and part:FindFirstChild("Overhead")
                if overhead then return overhead end
            end
            return nil
        end
        local function _waitOverhead(char)
            local deadline = os.clock() + 10
            repeat
                local overhead = _findOverhead(char)
                if overhead then return overhead end
                task.wait(0.25)
            until os.clock() > deadline or not char.Parent
            return nil
        end
        local function _getOverheadFor(player)
            return _findOverhead(player.Character)
        end
        local function _applyLabelGeneric(obj, state, fakeNameFn, maskLevel)
            if not obj:IsA("TextLabel") then return end
            local path = obj:GetFullName()
            if not state.origTexts[path] then
                state.origTexts[path] = obj.Text
            end
            local orig = state.origTexts[path]
            if not orig or orig == "" then return end
            if obj.Name == "Header" then
                obj.Text = fakeNameFn()
            elseif maskLevel and string.find(string.lower(orig), "lvl") then
                obj.Text = string.gsub(orig, "[%d,]+", _hideStats.fakeLevel)
            end
        end
        local function _armLabelGeneric(obj, state, fakeNameFn, maskLevel)
            if not obj:IsA("TextLabel") then return end
            _applyLabelGeneric(obj, state, fakeNameFn, maskLevel)
            if state.textConns[obj] then return end
            state.textConns[obj] = obj:GetPropertyChangedSignal("Text"):Connect(function()
                if not _hideStats.enabled then return end
                local path    = obj:GetFullName()
                local current = obj.Text
                local fake    = fakeNameFn()
                if current ~= fake and not (maskLevel and string.find(current, _hideStats.fakeLevel)) then
                    state.origTexts[path] = current
                end
                _applyLabelGeneric(obj, state, fakeNameFn, maskLevel)
            end)
        end
        local function _watchOverheadGeneric(overhead, state, fakeNameFn, maskLevel)
            for _, conn in pairs(state.textConns) do pcall(function() conn:Disconnect() end) end
            state.textConns = setmetatable({}, { __mode = "k" })
            if state.descConn then
                pcall(function() state.descConn:Disconnect() end)
                state.descConn = nil
            end
            if not overhead then return end
            for _, obj in ipairs(overhead:GetDescendants()) do
                _armLabelGeneric(obj, state, fakeNameFn, maskLevel)
            end
            state.descConn = overhead.DescendantAdded:Connect(function(obj)
                task.defer(function()
                    if _hideStats.enabled and obj and obj.Parent then
                        _armLabelGeneric(obj, state, fakeNameFn, maskLevel)
                    end
                end)
            end)
        end
        local function _watchOverhead()
            if not _hideStats.enabled then return end
            _watchOverheadGeneric(_getOverheadFor(LocalPlayer), _localState, _getBuiltName, true)
        end
        local function _restoreOverhead()
            for path, origText in pairs(_localState.origTexts) do
                pcall(function()
                    local obj = game
                    for part in string.gmatch(path, "[^.]+") do
                        obj = obj and obj:FindFirstChild(part)
                    end
                    if obj and obj:IsA("TextLabel") then
                        obj.Text = origText
                    end
                end)
            end
            _localState.origTexts = {}
            for _, conn in pairs(_localState.textConns) do pcall(function() conn:Disconnect() end) end
            _localState.textConns = setmetatable({}, { __mode = "k" })
            if _localState.descConn then
                pcall(function() _localState.descConn:Disconnect() end)
                _localState.descConn = nil
            end
        end
        local function _stopWatchingPlayer(player)
            local state = _hideStats.otherState[player]
            if not state then return end
            for _, conn in pairs(state.textConns) do pcall(function() conn:Disconnect() end) end
            if state.descConn then pcall(function() state.descConn:Disconnect() end) end
            if state.charConn then pcall(function() state.charConn:Disconnect() end) end
            _hideStats.otherState[player] = nil
        end
        local function _watchOtherPlayer(player)
            if not _hideStats.enabled or player == LocalPlayer then return end
            local state = _hideStats.otherState[player]
            if not state then
                state = { origTexts = {}, textConns = setmetatable({}, { __mode = "k" }), descConn = nil, charConn = nil }
                _hideStats.otherState[player] = state
            end
            local fakeNameFn = function() return _fakeNameForPlayer(player) end
            if state.charConn then pcall(function() state.charConn:Disconnect() end) end
            state.charConn = player.CharacterAdded:Connect(function(char)
                if not _hideStats.enabled then return end
                state.origTexts = {}
                local overhead = _waitOverhead(char)
                if overhead and _hideStats.enabled then
                    _watchOverheadGeneric(overhead, state, fakeNameFn, false)
                end
            end)
            _watchOverheadGeneric(_getOverheadFor(player), state, fakeNameFn, false)
        end
        local function _watchAllOtherPlayers()
            for _, p in ipairs(Players:GetPlayers()) do
                _watchOtherPlayer(p)
            end
        end
        local function _stopWatchingAllOthers()
            for player in pairs(_hideStats.otherState) do
                _stopWatchingPlayer(player)
            end
        end
        local function _startPlayerTracking()
            _hideStats.playerAddedConn = Players.PlayerAdded:Connect(function(p)
                if _hideStats.enabled then _watchOtherPlayer(p) end
            end)
            _hideStats.playerRemovingConn = Players.PlayerRemoving:Connect(function(p)
                _stopWatchingPlayer(p)
                _hideStats.otherFakeNames[p] = nil
            end)
        end
        local function _stopPlayerTracking()
            if _hideStats.playerAddedConn then
                _hideStats.playerAddedConn:Disconnect()
                _hideStats.playerAddedConn = nil
            end
            if _hideStats.playerRemovingConn then
                _hideStats.playerRemovingConn:Disconnect()
                _hideStats.playerRemovingConn = nil
            end
        end
        local _chatHide = { conn = nil, playerConns = {}, nameMap = {}, sortedNames = {}, textConns = setmetatable({}, { __mode = "k" }) }
        local function _buildChatNames()
            local map, seen, list = {}, {}, {}
            for _, p in ipairs(Players:GetPlayers()) do
                local fake = _fakeNameForPlayer(p)
                for _, n in ipairs({ p.Name, p.DisplayName }) do
                    if type(n) == "string" and #n > 2 and not seen[n] then
                        seen[n] = true
                        map[n]  = fake
                        list[#list + 1] = n
                    end
                end
            end
            table.sort(list, function(a, b) return #a > #b end)
            _chatHide.nameMap     = map
            _chatHide.sortedNames = list
        end
        local _maskChatLabel
        _maskChatLabel = function(d)
            if not (d:IsA("TextLabel") or d:IsA("TextButton")) then return end
            local t = d.Text
            if type(t) ~= "string" or #t == 0 then return end
            local out = t
            for _, n in ipairs(_chatHide.sortedNames) do
                out = out:gsub(_escapePat(n), _chatHide.nameMap[n])
            end
            if out ~= t then d.Text = out end
            if not _chatHide.textConns[d] then
                _chatHide.textConns[d] = d:GetPropertyChangedSignal("Text"):Connect(function()
                    if not _hideStats.enabled then return end
                    _maskChatLabel(d)
                end)
            end
        end
        local function _stopChatMask()
            if _chatHide.conn then
                _chatHide.conn:Disconnect()
                _chatHide.conn = nil
            end
            for _, c in ipairs(_chatHide.playerConns) do
                pcall(function() c:Disconnect() end)
            end
            _chatHide.playerConns = {}
            for obj, c in pairs(_chatHide.textConns) do
                pcall(function() c:Disconnect() end)
                _chatHide.textConns[obj] = nil
            end
        end
        local function _startChatMask()
            if not _hideStats.enabled then return end
            _stopChatMask()
            _buildChatNames()
            local ec = game:GetService("CoreGui"):FindFirstChild("ExperienceChat")
            if not ec then return end
            for _, d in ipairs(ec:GetDescendants()) do pcall(_maskChatLabel, d) end
            _chatHide.conn = ec.DescendantAdded:Connect(function(d)
                if not _hideStats.enabled then return end
                if d:IsA("TextLabel") or d:IsA("TextButton") then
                    task.defer(function()
                        if _hideStats.enabled then pcall(_maskChatLabel, d) end
                    end)
                end
            end)
            local pa = Players.PlayerAdded:Connect(function() _buildChatNames() end)
            local pr = Players.PlayerRemoving:Connect(function() _buildChatNames() end)
            table.insert(_chatHide.playerConns, pa)
            table.insert(_chatHide.playerConns, pr)
        end
        local LEADERBOARD_GUI_NAMES = {
            RarestFish = true, MonthlyCaughtFish = true, GalaxyVariantsCaught = true,
        }
        local _lbHide = { conns = {}, guiWatchConn = nil }
        local function _isUsernameLabel(obj)
            if obj.Name == "DisplayName" or obj.Name == "Username" then return true end
            local t = obj.Text
            return type(t) == "string" and t:find("@[%w_]+") ~= nil
        end
        local function _maskLeaderboardLabel(obj)
            if not obj:IsA("TextLabel") then return end
            if not _isUsernameLabel(obj) then return end
            local t = obj.Text
            if type(t) ~= "string" or t == "" then return end
            local out = t
            out = out:gsub("%S+%s*%(@[%w_]+%)", "Hidden (@Hidden)")
            out = out:gsub("@[%w_]+", "@Hidden")
            if out == t and obj.Name == "DisplayName" then
                out = "Hidden"
            end
            if out ~= t then obj.Text = out end
        end
        local function _watchLeaderboardGui(gui)
            for _, d in ipairs(gui:GetDescendants()) do pcall(_maskLeaderboardLabel, d) end
            table.insert(_lbHide.conns, gui.DescendantAdded:Connect(function(d)
                if not _hideStats.enabled then return end
                task.defer(function()
                    if d and d.Parent then pcall(_maskLeaderboardLabel, d) end
                end)
            end))
        end
        local function _stopLeaderboardMask()
            for _, c in ipairs(_lbHide.conns) do pcall(function() c:Disconnect() end) end
            _lbHide.conns = {}
            if _lbHide.guiWatchConn then
                pcall(function() _lbHide.guiWatchConn:Disconnect() end)
                _lbHide.guiWatchConn = nil
            end
        end
        local function _startLeaderboardMask()
            if not _hideStats.enabled then return end
            _stopLeaderboardMask()
            local pgui = LocalPlayer:FindFirstChild("PlayerGui")
            if not pgui then return end
            for name in pairs(LEADERBOARD_GUI_NAMES) do
                local gui = pgui:FindFirstChild(name)
                if gui then _watchLeaderboardGui(gui) end
            end
            _lbHide.guiWatchConn = pgui.ChildAdded:Connect(function(child)
                if not _hideStats.enabled then return end
                if LEADERBOARD_GUI_NAMES[child.Name] then
                    task.defer(function()
                        if _hideStats.enabled then _watchLeaderboardGui(child) end
                    end)
                end
            end)
        end
        local _plList = { conns = setmetatable({}, { __mode = "k" }), panelConn = nil }
        local function _maskPlayerListLabel(obj)
            if not obj:IsA("TextLabel") then return end
            local nameFrame = obj:FindFirstAncestor("NameFrame")
            if not nameFrame then return end
            local userId, cur = nil, nameFrame.Parent
            while cur do
                local id = cur.Name:match("^PlayerEntry_(%d+)$")
                if id then userId = tonumber(id); break end
                cur = cur.Parent
            end
            if not userId then return end
            local function apply()
                local player = Players:GetPlayerByUserId(userId)
                local fake = player and _fakeNameForPlayer(player)
                    or ("Player" .. tostring(1000 + (userId % 9000)))
                if obj.Text ~= fake then obj.Text = fake end
            end
            apply()
            if not _plList.conns[obj] then
                _plList.conns[obj] = obj:GetPropertyChangedSignal("Text"):Connect(function()
                    if _hideStats.enabled then apply() end
                end)
            end
        end
        local function _stopPlayerListMask()
            for _, conn in pairs(_plList.conns) do pcall(function() conn:Disconnect() end) end
            _plList.conns = setmetatable({}, { __mode = "k" })
            if _plList.panelConn then
                pcall(function() _plList.panelConn:Disconnect() end)
                _plList.panelConn = nil
            end
        end
        local function _startPlayerListMask()
            if not _hideStats.enabled then return end
            _stopPlayerListMask()
            local pl = game:GetService("CoreGui"):FindFirstChild("PlayerList")
            if not pl then return end
            for _, d in ipairs(pl:GetDescendants()) do pcall(_maskPlayerListLabel, d) end
            _plList.panelConn = pl.DescendantAdded:Connect(function(d)
                if not _hideStats.enabled then return end
                task.defer(function()
                    if d and d.Parent then pcall(_maskPlayerListLabel, d) end
                end)
            end)
        end
        local function _cleanupAll()
            _stopChatMask()
            _stopLeaderboardMask()
            _stopPlayerListMask()
            _stopWatchingAllOthers()
            _stopPlayerTracking()
            if _hideStats.charConn then
                _hideStats.charConn:Disconnect()
                _hideStats.charConn = nil
            end
            _restoreOverhead()
            _unhookSystemMessage()
        end
        HideStatsSection:AddToggle({
            Title    = "Enable Hide Stats",
            Default  = false,
            Callback = function(on)
                _hideStats.enabled = on
                if not on then
                    _cleanupAll()
                    return
                end
                _watchOverhead()
                _hookSystemMessage()
                _startChatMask()
                _startLeaderboardMask()
                _startPlayerListMask()
                _watchAllOtherPlayers()
                _startPlayerTracking()
                if _hideStats.charConn then
                    _hideStats.charConn:Disconnect()
                    _hideStats.charConn = nil
                end
                _hideStats.charConn = LocalPlayer.CharacterAdded:Connect(function(char)
                    if not _hideStats.enabled then return end
                    _localState.origTexts = {}
                    local overhead = _waitOverhead(char)
                    if overhead and _hideStats.enabled then
                        _watchOverheadGeneric(overhead, _localState, _getBuiltName, true)
                    end
                end)
            end,
        })
        HideStatsSection:AddToggle({
            Title    = "Enable Premium Logo",
            Default  = false,
            Callback = function(on)
                _hideStats.premiumLogo = on
                if not _hideStats.enabled then return end
                _watchOverhead()
            end,
        })
        HideStatsSection:AddToggle({
            Title    = "Enable Verification Logo",
            Default  = false,
            Callback = function(on)
                _hideStats.verifyLogo = on
                if not _hideStats.enabled then return end
                _watchOverhead()
            end,
        })
        HideStatsSection:AddInput({
            Title    = "Fake Name",
            Default  = "LynX",
            Callback = function(value)
                _hideStats.fakeName = value or "LynX"
                if not _hideStats.enabled then return end
                _watchOverhead()
            end,
        })
        HideStatsSection:AddInput({
            Title    = "Fake Level",
            Default  = "501",
            Callback = function(value)
                _hideStats.fakeLevel = tostring(value or "501")
                if not _hideStats.enabled then return end
                _watchOverhead()
            end,
        })
    end
    do
        local ServerSection = SettingsTab:AddSection("Server")
        ServerSection:AddButton({
            Title    = "Rejoin Server",
            Callback = function()
                pcall(function()
                    game:GetService("TeleportService"):Teleport(game.PlaceId, LocalPlayer)
                end)
            end,
        })
        ServerSection:AddButton({
            Title    = "Serverhop",
            Callback = function()
                task.spawn(function()
                    local TeleportService = game:GetService("TeleportService")
                    local HttpService     = game:GetService("HttpService")
                    local placeId         = game.PlaceId
                    local currentJobId    = game.JobId
                    local foundJobId      = nil
                    local cursor          = nil
                    repeat
                        local ok, result = pcall(function()
                            local httpFn = getHTTP()
                            if not httpFn then return nil end
                            local url = string.format(
                                "https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100%s",
                                placeId,
                                cursor and ("&cursor=" .. cursor) or ""
                            )
                            local res = httpFn({ Url = url, Method = "GET" })
                            if not res or not res.Body then return nil end
                            return HttpService:JSONDecode(res.Body)
                        end)
                        if not ok or not result or not result.data then break end
                        for _, server in ipairs(result.data) do
                            if server.id ~= currentJobId and (server.maxPlayers - server.playing) > 0 then
                                foundJobId = server.id
                                break
                            end
                        end
                        cursor = result.nextPageCursor
                    until foundJobId or not cursor
                    pcall(function()
                        if foundJobId then
                            TeleportService:TeleportToPlaceInstance(placeId, foundJobId, LocalPlayer)
                        else
                            TeleportService:Teleport(placeId, LocalPlayer)
                        end
                    end)
                end)
            end,
        })
    end
    do
        local ReconnectSection = SettingsTab:AddSection("Reconnect & Execute")
        local _reconnect = {
            enabled        = false,
            autoExec       = false,
            setup          = false,
            fired          = false,
            errorConn      = nil,
            overlayConn    = nil,
        }
        local function _disconnectListeners()
            if _reconnect.errorConn then
                pcall(function() _reconnect.errorConn:Disconnect() end)
                _reconnect.errorConn = nil
            end
            if _reconnect.overlayConn then
                pcall(function() _reconnect.overlayConn:Disconnect() end)
                _reconnect.overlayConn = nil
            end
            _reconnect.setup = false
        end
        local function _setupListeners()
            _disconnectListeners()
            _reconnect.setup = true
            _reconnect.fired = false
            local function handleReconnect()
                if not _reconnect.enabled or _reconnect.fired then return end
                _reconnect.fired = true
                if _reconnect.autoExec then
                    sharedQueueAutoExecute()
                end
                task.wait(2)
                pcall(function()
                    game:GetService("TeleportService"):Teleport(game.PlaceId, LocalPlayer)
                end)
            end
            pcall(function()
                local GuiService = game:GetService("GuiService")
                _reconnect.errorConn = GuiService.ErrorMessageChanged:Connect(function(msg)
                    if msg and msg ~= "" then handleReconnect() end
                end)
            end)
            pcall(function()
                local overlay = game:GetService("CoreGui"):FindFirstChild("RobloxPromptGui")
                    and game:GetService("CoreGui").RobloxPromptGui:FindFirstChild("promptOverlay")
                if overlay then
                    _reconnect.overlayConn = overlay.ChildAdded:Connect(function(child)
                        if child.Name == "ErrorPrompt" then
                            task.wait(0.5)
                            handleReconnect()
                        end
                    end)
                end
            end)
        end
        ReconnectSection:AddParagraph({
            Title   = "Info",
            Content = "Auto rejoin server on disconnect.\nUses Roblox ErrorPrompt detection.\nScript will auto execute after reconnect.",
        })
        ReconnectSection:AddToggle({
            Title    = "Enable Auto Reconnect",
            Default  = false,
            Callback = function(on)
                _reconnect.enabled = on
                if on then
                    _setupListeners()
                    Library:MakeNotify({ Title = "Auto Reconnect", Description = "Aktif.", Delay = 2 })
                else
                    _disconnectListeners()
                    Library:MakeNotify({ Title = "Auto Reconnect", Description = "Dimatikan.", Delay = 2 })
                end
            end,
        })
        ReconnectSection:AddToggle({
            Title    = "Enable Auto Execute",
            Default  = false,
            Callback = function(on)
                _reconnect.autoExec = on
                Library:MakeNotify({
                    Title       = "Auto Execute",
                    Description = on and "Aktif — script akan auto execute setelah reconnect." or "Dimatikan.",
                    Delay       = 2,
                })
            end,
        })
    end
    do
        local ShaderSection = SettingsTab:AddSection("Shader")
        local Lighting = game:GetService("Lighting")
        local PRESETS = { -- layered on the game's own color and bloom, so light and color stay rich; only its blur goes
            Realistic = {
