                Water      = { WaterColor = Color3.fromRGB(24, 118, 150), WaterReflectance = 1, WaterTransparency = 0.65, WaterWaveSize = 0.16, WaterWaveSpeed = 14 },
                Fog        = { Density = 1, Haze = 1.1, Glare = 0.25 },
                BloomEffect           = { Intensity = 0.08, Size = 16, Threshold = 2 },
                SunRaysEffect         = { Intensity = 0.16, Spread = 0.75 },
                DepthOfFieldEffect    = { FarIntensity = 0, FocusDistance = 200, InFocusRadius = 100, NearIntensity = 0 },
                ColorCorrectionEffect = { Brightness = 0.01, Contrast = 0.12, Saturation = 0.14, TintColor = Color3.fromRGB(255, 255, 255) },
