                DepthOfFieldEffect    = { FarIntensity = 0, FocusDistance = 200, InFocusRadius = 100, NearIntensity = 0 },
                ColorCorrectionEffect = { Brightness = 0.01, Contrast = 0.1, Saturation = 0.12, TintColor = Color3.fromRGB(255, 238, 215) },
            },
            Sunset = {
                Lighting   = { Brightness = 2.8, ExposureCompensation = 0, ShadowSoftness = 0.1, ClockTime = 17.8, GeographicLatitude = 25, EnvironmentDiffuseScale = 0.75, Ambient = Color3.fromRGB(120, 90, 88), OutdoorAmbient = Color3.fromRGB(165, 110, 90) },
                Water      = { WaterColor = Color3.fromRGB(74, 62, 72), WaterReflectance = 1, WaterTransparency = 0.35, WaterWaveSize = 0.2, WaterWaveSpeed = 9 },
                Fog        = { Density = 1.25, Haze = 1.5, Glare = 0.7, Color = Color3.fromRGB(255, 170, 120), Decay = Color3.fromRGB(170, 80, 70) },
                BloomEffect           = { Intensity = 0.28, Size = 24, Threshold = 1.3 },
                SunRaysEffect         = { Intensity = 0.42, Spread = 1 },
                DepthOfFieldEffect    = { FarIntensity = 0.02, FocusDistance = 180, InFocusRadius = 90, NearIntensity = 0 },
                ColorCorrectionEffect = { Brightness = 0, Contrast = 0.14, Saturation = 0.24, TintColor = Color3.fromRGB(255, 205, 165) },
            },
            Moonlight = {
                Lighting   = { Brightness = 1.4, ExposureCompensation = -0.1, ShadowSoftness = 0.15, ClockTime = 0.5, GeographicLatitude = 25, EnvironmentDiffuseScale = 0.6, Ambient = Color3.fromRGB(50, 62, 95), OutdoorAmbient = Color3.fromRGB(60, 80, 130) },
                Water      = { WaterColor = Color3.fromRGB(8, 26, 54), WaterReflectance = 1, WaterTransparency = 0.3, WaterWaveSize = 0.18, WaterWaveSpeed = 8 },
                Fog        = { Density = 1.3, Haze = 1.3, Glare = 0.1, Color = Color3.fromRGB(110, 140, 190), Decay = Color3.fromRGB(30, 45, 85) },
                BloomEffect           = { Intensity = 0.3, Size = 26, Threshold = 1.1 },
                SunRaysEffect         = { Intensity = 0, Spread = 0.5 },
                DepthOfFieldEffect    = { FarIntensity = 0.02, FocusDistance = 150, InFocusRadius = 80, NearIntensity = 0 },
                ColorCorrectionEffect = { Brightness = -0.01, Contrast = 0.14, Saturation = -0.1, TintColor = Color3.fromRGB(190, 210, 255) },
            },
            Tropical = {
                Lighting   = { Brightness = 3.6, ExposureCompensation = 0.05, ShadowSoftness = 0.04, ClockTime = 12.5, GeographicLatitude = 25, EnvironmentDiffuseScale = 1, Ambient = Color3.fromRGB(120, 130, 120), OutdoorAmbient = Color3.fromRGB(150, 170, 160) },
                Water      = { WaterColor = Color3.fromRGB(16, 168, 178), WaterReflectance = 0.9, WaterTransparency = 0.75, WaterWaveSize = 0.14, WaterWaveSpeed = 13 },
                Fog        = { Density = 0.85, Haze = 0.8, Glare = 0.2, Color = Color3.fromRGB(200, 240, 250), Decay = Color3.fromRGB(120, 200, 220) },
                BloomEffect           = { Intensity = 0.14, Size = 16, Threshold = 1.8 },
                SunRaysEffect         = { Intensity = 0.16, Spread = 0.7 },
                DepthOfFieldEffect    = { FarIntensity = 0, FocusDistance = 200, InFocusRadius = 100, NearIntensity = 0 },
                ColorCorrectionEffect = { Brightness = 0.01, Contrast = 0.12, Saturation = 0.32, TintColor = Color3.fromRGB(250, 255, 240) },
            },
            Misty = {
                Lighting   = { Brightness = 2.5, ExposureCompensation = 0, ShadowSoftness = 0.2, ClockTime = 9.5, GeographicLatitude = 25, EnvironmentDiffuseScale = 0.85, Ambient = Color3.fromRGB(105, 112, 118), OutdoorAmbient = Color3.fromRGB(130, 140, 148) },
                Water      = { WaterColor = Color3.fromRGB(46, 76, 86), WaterReflectance = 0.9, WaterTransparency = 0.3, WaterWaveSize = 0.1, WaterWaveSpeed = 7 },
                Fog        = { Density = 1.9, Haze = 2.2, Glare = 0.15, Color = Color3.fromRGB(215, 225, 232), Decay = Color3.fromRGB(160, 172, 185) },
                BloomEffect           = { Intensity = 0.16, Size = 26, Threshold = 1.5 },
                SunRaysEffect         = { Intensity = 0.14, Spread = 0.95 },
                DepthOfFieldEffect    = { FarIntensity = 0.08, FocusDistance = 120, InFocusRadius = 70, NearIntensity = 0 },
                ColorCorrectionEffect = { Brightness = 0, Contrast = 0.02, Saturation = -0.12, TintColor = Color3.fromRGB(232, 240, 246) },
            },
            Vivid = {
                Lighting   = { Brightness = 3.6, ExposureCompensation = 0.05, ShadowSoftness = 0.05, ClockTime = 14, GeographicLatitude = 25, EnvironmentDiffuseScale = 0.95, Ambient = Color3.fromRGB(115, 105, 125), OutdoorAmbient = Color3.fromRGB(145, 125, 140) },
                Water      = { WaterColor = Color3.fromRGB(10, 104, 160), WaterReflectance = 1, WaterTransparency = 0.5, WaterWaveSize = 0.2, WaterWaveSpeed = 14 },
                Fog        = { Density = 1, Haze = 1, Glare = 0.25, Color = Color3.fromRGB(190, 225, 255), Decay = Color3.fromRGB(150, 150, 220) },
                BloomEffect           = { Intensity = 0.16, Size = 18, Threshold = 1.6 },
                SunRaysEffect         = { Intensity = 0.2, Spread = 0.8 },
                DepthOfFieldEffect    = { FarIntensity = 0, FocusDistance = 200, InFocusRadius = 100, NearIntensity = 0 },
                ColorCorrectionEffect = { Brightness = 0.01, Contrast = 0.16, Saturation = 0.38, TintColor = Color3.fromRGB(255, 255, 255) },
            },
        }
        local SAVED_PROPS = {
            "Technology", "Brightness", "ExposureCompensation", "ShadowSoftness", "GlobalShadows",
            "EnvironmentDiffuseScale", "EnvironmentSpecularScale", "ClockTime", "GeographicLatitude", "Ambient", "OutdoorAmbient",
        }
        local WATER_PROPS = { "WaterColor", "WaterReflectance", "WaterTransparency", "WaterWaveSize", "WaterWaveSpeed" }
        local MaterialService = game:GetService("MaterialService")
        local TILE_SCALE = 0.45 -- tighter tiling packs more of the same texture detail into each stud
        local M = Enum.Material
        local PART_UPGRADES = {
            [M.Wood] = { M.Wood, "Wood - 1" }, [M.WoodPlanks] = { M.Wood, "Wood Planks" }, [M.Grass] = { M.Grass, "Grass" },
            [M.Ground] = { M.Rock, "Rock - 1" }, [M.Mud] = { M.Rock, "Rock - 1" },
            [M.Concrete] = { M.Rock, "Rock - 2" }, [M.Limestone] = { M.Rock, "Rock - 2" }, [M.Slate] = { M.Rock, "Rock -  3" },
            [M.Basalt] = { M.Rock, "Rock -  3" }, [M.Rock] = { M.Rock, "Rock -  3" }, [M.Brick] = { M.Brick, "Brick 2016" },
            [M.Cobblestone] = { M.Cobblestone, "GroundCobblestone" },
        }
        local _shader = { enabled = false, preset = "Realistic", effects = {} }
        local WOOD_VARIANTS = { ["Wood - 1"] = true, ["Wood - 2"] = true, ["Wood Planks"] = true }
        local GLOSS = { -- no real ray tracing exists, but these reflect the sky
            [M.Metal] = 0.25, [M.DiamondPlate] = 0.2, [M.Foil] = 0.3, [M.Glass] = 0.35, [M.Ice] = 0.2, [M.Marble] = 0.15,
        }
        local function upgradePart(part)
            local gloss = GLOSS[part.Material]
            if gloss and part.Reflectance < gloss then part.Reflectance = gloss end
            if part:IsA("MeshPart") and part.Material == M.Grass and not part.Name:lower():find("terrain") then
                local size = part.Size
                if math.max(size.X, size.Y, size.Z) <= 40 then
                    part.Material, part.MaterialVariant = M.LeafyGrass, ""
                    return
                end
            end
            local upgrade = PART_UPGRADES[part.Material]
            if upgrade and part.MaterialVariant == "" then part.Material, part.MaterialVariant = upgrade[1], upgrade[2] end
            if part.Material == M.Wood and WOOD_VARIANTS[part.MaterialVariant] and not part:GetAttribute("LynxWood") then
                local size = part.Size
                if size.Y < math.min(size.X, size.Z) * 0.25 then part.MaterialVariant = "Wood Planks" end -- floors, decks
                part.Color = part.Color:Lerp(Color3.new(1, 1, 1), 0.18)
                part:SetAttribute("LynxWood", true)
            end
        end
        local function upgradeLight(light) -- Future lighting's dynamic light; few of the game's lamps cast shadows
            if light:GetAttribute("LynxLight") then return end
            light.Shadows, light.Brightness, light.Range = true, light.Brightness * 1.4, math.min(light.Range * 1.3, 60)
            light:SetAttribute("LynxLight", true)
        end
        local function isAura(obj)
            local char = LocalPlayer.Character
            return (obj:IsA("ParticleEmitter") or obj:IsA("Beam") or obj:IsA("Trail")) and char and obj:IsDescendantOf(char)
        end
        local function upgradeAura(fx) -- your own rod and aura effects run thin and unlit by default
            if fx:GetAttribute("LynxAura") then return end
            fx.LightEmission = math.max(fx.LightEmission, 0.7)
            if fx:IsA("ParticleEmitter") then fx.Rate *= 2.5 end
            fx:SetAttribute("LynxAura", true)
        end
        local function upgradeParts() -- one finite pass, then one look at each part, light and aura that appears
            _shader.watcher = workspace.DescendantAdded:Connect(function(obj)
                local upgrade = obj:IsA("Light") and upgradeLight
                    or obj:IsA("BasePart") and (PART_UPGRADES[obj.Material] or GLOSS[obj.Material]) and upgradePart
                    or isAura(obj) and upgradeAura
                if upgrade then
                    task.defer(function()
                        if _shader.enabled then pcall(upgrade, obj) end
                    end)
                end
            end)
            _shader.thread = task.spawn(function()
                for i, obj in ipairs(workspace:GetDescendants()) do
                    if obj:IsA("BasePart") then
                        pcall(upgradePart, obj)
                    elseif obj:IsA("Light") then
                        pcall(upgradeLight, obj)
                    elseif isAura(obj) then
                        pcall(upgradeAura, obj)
                    end
                    if i % 3000 == 0 then task.wait() end
                end
                _shader.thread = nil
            end)
        end
        local function applyPreset(name)
            local preset = PRESETS[name]
            local base = _shader.saved and _shader.saved.lighting
            if base then Lighting.Ambient, Lighting.OutdoorAmbient = base.Ambient, base.OutdoorAmbient end -- only some presets set these
            for prop, value in pairs(preset.Lighting) do pcall(function() Lighting[prop] = value end) end
            for prop, value in pairs(preset.Water) do pcall(function() workspace.Terrain[prop] = value end) end
            local fog = _shader.saved and _shader.saved.fog
            if fog then -- scaled from the game's own fog, whose colors stay untouched; Density and Haze are multipliers
                fog.atmosphere.Density = fog.Density * preset.Fog.Density
                fog.atmosphere.Haze = fog.Haze * preset.Fog.Haze
                fog.atmosphere.Glare = math.max(fog.Glare, preset.Fog.Glare)
                fog.atmosphere.Color, fog.atmosphere.Decay = preset.Fog.Color or fog.Color, preset.Fog.Decay or fog.Decay
            end
            for class, props in pairs(preset) do
                if class ~= "Lighting" and class ~= "Water" and class ~= "Fog" then
                    local effect = _shader.effects[class]
                    if not effect then
                        effect = Instance.new(class)
                        effect.Name, effect.Parent = "LynxShader", Lighting
                        _shader.effects[class] = effect
                    end
                    for prop, value in pairs(props) do pcall(function() effect[prop] = value end) end
                end
            end
        end
        local function startShader()
            local rendering = settings().Rendering
            local graphics = UserSettings():GetService("UserGameSettings")
            local saved = {
                lighting = {}, water = {}, tiling = {}, gameEffects = {},
                quality = rendering.QualityLevel, mesh = rendering.MeshPartDetailLevel,
                savedLevel = graphics.SavedQualityLevel, graphicsLevel = graphics.GraphicsQualityLevel,
            }
            pcall(function()
                graphics.SavedQualityLevel, graphics.GraphicsQualityLevel = Enum.SavedQualitySetting.QualityLevel10, 21
            end)
            for _, variant in ipairs(MaterialService:GetChildren()) do
                if variant:IsA("MaterialVariant") then
                    saved.tiling[variant] = variant.StudsPerTile
                    variant.StudsPerTile *= TILE_SCALE
                end
            end
            for _, prop in ipairs(SAVED_PROPS) do saved.lighting[prop] = Lighting[prop] end
            for _, prop in ipairs(WATER_PROPS) do saved.water[prop] = workspace.Terrain[prop] end
            upgradeParts()
            for _, child in ipairs(Lighting:GetChildren()) do
                if child:IsA("BlurEffect") then
                    saved.gameEffects[child] = child.Enabled
                    child.Enabled = false
                elseif child:IsA("Sky") then -- other features hide the sun, and sun rays need one
                    saved.sky, saved.skyStars, saved.skyBodies, saved.skySun = child, child.StarCount, child.CelestialBodiesShown, child.SunAngularSize
                    child.StarCount, child.CelestialBodiesShown, child.SunAngularSize = 3000, true, 18 -- a bigger sun throws fuller rays
                end
            end
            local atmosphere = Lighting:FindFirstChildOfClass("Atmosphere")
            if atmosphere then
                saved.fog = {
                    atmosphere = atmosphere, Density = atmosphere.Density, Haze = atmosphere.Haze, Glare = atmosphere.Glare,
                    Color = atmosphere.Color, Decay = atmosphere.Decay,
                }
            end
            _shader.saved = saved
            pcall(function()
                local tc = cachedRequire(ReplicatedStorage.Controllers.ClientTimeController)
                _shader.time, _shader.origProfile = tc, tc._getLightingProfile
                tc._getLightingProfile = function() end
            end)
            pcall(function()
                local data = getCachedReplion().Client:GetReplion("Time")
                local h = data._signals._containers.onChange.Time.__signal._handlerListHead
                while h do
                    local ok, src = pcall(debug.info, h._fn, "s")
                    if ok and type(src) == "string" and src:find("ClientTimeController$") then
                        _shader.handler, _shader.origHandler = h, h._fn
                        h._fn = function() end
                        break
                    end
                    h = h._next
                end
            end)
            pcall(function()
                rendering.QualityLevel, rendering.MeshPartDetailLevel = Enum.QualityLevel.Level21, Enum.MeshPartDetailLevel.Level04
            end)
            pcall(function()
                Lighting.Technology, Lighting.GlobalShadows = Enum.Technology.Future, true
                Lighting.EnvironmentDiffuseScale, Lighting.EnvironmentSpecularScale = 1, 1
            end)
            applyPreset(_shader.preset)
        end
        local function stopShader() -- part materials stay upgraded until a rejoin; undoing them would mean remembering every part
            if _shader.watcher then _shader.watcher:Disconnect(); _shader.watcher = nil end
            if _shader.thread then pcall(task.cancel, _shader.thread); _shader.thread = nil end
            for _, effect in pairs(_shader.effects) do effect:Destroy() end
            table.clear(_shader.effects)
            if _shader.time then _shader.time._getLightingProfile = _shader.origProfile end
            if _shader.handler then _shader.handler._fn = _shader.origHandler end
            _shader.handler, _shader.origHandler = nil, nil
            local saved = _shader.saved
            if not saved then return end
            for prop, value in pairs(saved.lighting) do pcall(function() Lighting[prop] = value end) end
            for prop, value in pairs(saved.water) do pcall(function() workspace.Terrain[prop] = value end) end
            for variant, tile in pairs(saved.tiling) do pcall(function() variant.StudsPerTile = tile end) end
            for effect, wasOn in pairs(saved.gameEffects) do pcall(function() effect.Enabled = wasOn end) end
            if saved.fog then
                saved.fog.atmosphere.Density, saved.fog.atmosphere.Haze = saved.fog.Density, saved.fog.Haze
                saved.fog.atmosphere.Glare, saved.fog.atmosphere.Color = saved.fog.Glare, saved.fog.Color
                saved.fog.atmosphere.Decay = saved.fog.Decay
            end
            if saved.sky then
                saved.sky.StarCount, saved.sky.CelestialBodiesShown, saved.sky.SunAngularSize = saved.skyStars, saved.skyBodies, saved.skySun
            end
            pcall(function()
                local graphics = UserSettings():GetService("UserGameSettings")
                graphics.SavedQualityLevel, graphics.GraphicsQualityLevel = saved.savedLevel, saved.graphicsLevel
            end)
            pcall(function()
                local rendering = settings().Rendering
                rendering.QualityLevel, rendering.MeshPartDetailLevel = saved.quality, saved.mesh
            end)
            _shader.time, _shader.origProfile, _shader.saved = nil, nil, nil
        end
        ShaderSection:AddDropdown({
            Title    = "Shader Preset",
            Options  = { "Realistic", "Cinematic", "Bright HD", "Golden Hour", "Soft Morning", "Sunset", "Moonlight", "Tropical", "Misty", "Vivid" },
            Default  = "Realistic",
            Callback = function(selected)
                if not PRESETS[selected] then return end
                _shader.preset = selected
                if _shader.enabled then applyPreset(selected) end
            end,
        })
        local shaderToggle
        shaderToggle = ShaderSection:AddToggle({
            Title    = "Enable Shader",
            Default  = false,
            NoSave   = true,
            Callback = function(on)
                if _shader.enabled == on then return end
                if on and (_animationsOff or _worldStripped) then
                    Library:MakeNotify({ Title = "Shader", Description = "Matikan FPS Booster & Remove All Texture & Effect, lalu rejoin dulu.", Delay = 4 })
                    task.defer(function() shaderToggle:SetValue(false) end)
                    return
                end
                _shader.enabled = on
                if on then startShader() else stopShader() end
                Library:MakeNotify({ Title = "Shader", Description = on and ("Aktif: " .. _shader.preset) or "Dimatikan. Rejoin untuk kembalikan material.", Delay = 3 })
            end,
        })
        local TimeSection = SettingsTab:AddSection("Change Time")
        local TimeController = nil
        pcall(function()
            TimeController = require(game:GetService("ReplicatedStorage"):WaitForChild("Controllers", 3):WaitForChild("ClientTimeController", 3))
        end)
        local _changeTime = {
            enabled = false,
            profile = "Night",
        }
        TimeSection:AddToggle({
            Title    = "Change Time",
            Default  = false,
            Callback = function(on)
                _changeTime.enabled = on
                if on then
                    if TimeController then TimeController:_forceUpdateAndOverride(_changeTime.profile) end
                else
                    if TimeController then TimeController:_removeOverride() end
                end
            end,
        })
        TimeSection:AddDropdown({
            Title    = "Time Profile",
            Options  = { "Night", "Day", "Bloodmoon", "Purple Bloodmoon", "Galaxy" },
            Default  = "Night",
            Callback = function(selected)
                _changeTime.profile = selected
                if _changeTime.enabled and TimeController then
                    TimeController:_forceUpdateAndOverride(selected)
                end
            end,
        })
    end
end
task.wait(2)
Library:Init()
